window.CHEESES_DATA = JSON.parse('[{"name":"Gailtaler Almkäse","lat":46.62,"lon":13.18,"country":"Austria","where":"Carinthia — Gailtal Alps","hint":"Carinthia, on the Italian border","desc":"Hard summer-only cow\'s-milk Alpine cheese from huts on the Gailtal high pastures.","image":"gailtaler_almkaese.jpg","name_protections":["PDO"],"milk_types":["cow","goat"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":49,"format":"wheel, ~5–35 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Gailtaler Almkäse is the summer-pasture cheese of the Gail valley in Carinthia, southern Austria — a tradition that documentary records trace back to the fourteenth century. The PDO requires raw cow\'s milk, with up to ten per cent goat\'s milk permitted, all drawn from cattle pastured on the thirteen registered alpine pastures of the Gailtal Alps during the summer grazing season. The milk is set in a copper vessel with natural rennet at low alpine-dairy temperatures, the curd is cut with the harp and scalded to about 50 °C with constant stirring, then pressed into wheels of up to thirty-five kilograms, salted, and matured in cool mountain cellars for at least seven weeks; many wheels rest considerably longer. EU PDO came in 1997. The cheese has an ivory to straw-yellow paste sparsely scattered with small eyes, a thin tan rind, and a flavour that carries the herbal lift of the Gailtal alpine flora — spicy, grassy, with a long savoury finish that pairs traditionally with Carinthian Speck and sourdough rye.","sources":[{"label":"Slow Food Presidia: Gailtaler Almkäse","url":"https://www.fondazioneslowfood.com/en/slow-food-presidia/gailtaler-almkase-gail-valley-mountain-pasture-cheese/"}],"pronunciation":{"ipa":"/ˈɡaɪltaːlɐ ˈalmˌkɛːzə/","respelling":"GYL-tah-ler AHLM-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[12.85,46.7],[13.3,46.75],[13.75,46.65],[13.75,46.5],[13.3,46.5],[12.85,46.55],[12.85,46.7]]]}},{"name":"Tiroler Almkäse / Tiroler Alpkäse","lat":47.27,"lon":11.51,"country":"Austria","where":"Tyrolean Alps","hint":"Tyrol","desc":"Hard cow\'s-milk wheel made on Tyrolean mountain pastures from raw morning and evening milk.","image":"tiroler_almkase.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":120,"format":"wheel, ~30–60 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Tiroler Almkäse — also called Tiroler Alpkäse — is the summer-only alpine cheese of North and East Tyrol, made on the high pastures during the ninety-to-one-hundred-twenty-day vegetation window of the Tyrolean alpages. The PDO requires raw cow\'s milk drawn exclusively from cattle grazing those pastures; the evening milking is set in shallow pans and skimmed by hand the next morning before being blended with the morning milk for the make. The combined milk is warmed to 31–32 °C, set only with calf rennet (no industrial coagulant), the curd cut to pea-sized grains, then cooked to 50–54 °C with constant stirring. Wheels are pressed, brined, and matured at least four to six months. The PDO forbids antioxidants, preservatives, emulsifiers and stabilisers of any kind. EU PDO came in 1997. The paste is firm, ivory to straw-yellow with sparse small eyes; the flavour is markedly herbaceous, full and faintly piquant — a high-pasture expression as honest as any in the Alps.","sources":[{"label":"Qualigeo: Tiroler Almkäse / Tiroler Alpkäse PDO","url":"https://www.qualigeo.eu/en/product/tiroler-almkase-tiroler-alpkase-pdo/"},{"label":"Austrian Federal Ministry (BMLRT): Tiroler Almkäse / Alpkäse g.U.","url":"https://www.bmlrt.gv.at/land/lebensmittel/trad-lebensmittel/kaese/tiroler_almk_alpk.html"},{"label":"Wikipedia: Bergkäse","url":"https://en.wikipedia.org/wiki/Bergkäse"}],"pronunciation":{"ipa":"/tiˈroːlɐ ˈalmˌkɛːzə/","respelling":"tee-ROH-ler AHLM-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[10.15,47.55],[11.3,47.65],[12.4,47.55],[12.8,47.05],[11.85,46.85],[10.65,46.95],[10.2,47.2],[10.15,47.55]]]}},{"name":"Tiroler Bergkäse","lat":47.27,"lon":11.51,"country":"Austria","where":"Tyrol","hint":"Tyrol, year-round mountain dairies","desc":"Hard raw cow\'s-milk mountain cheese, aged 4–6 months; subtly fruity.","image":"tiroler_bergkase.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed","smear-ripened"],"ageing_min_days":98,"format":"wheel, ~10–35 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Tiroler Bergkäse is the year-round alpine cheese of the Tyrolean valleys, the Bergkäse counterpart to the summer-only Almkäse — produced in the northern and eastern Tyrolean valleys from raw cow\'s milk drawn from herds whose feed must be hay-milk grass and which forbids any silage, fermented fodder, GMOs or transport before processing. The partially-skimmed milk is heated to roughly 52 °C, set with calf rennet only, cut, scalded and pressed; wheels are matured in cool moist cellars for at least fourteen weeks, salt-brined twice a week to develop a smear of natural surface flora that gives the cheese its characteristic warm, spicy aroma. EU PDO came in 1997. The wheels are dense ivory-yellow, scattered with small to medium eyes, and the flavour runs full and savoury — close in profile to Vorarlberger Bergkäse but generally a touch milder, with a clean tyrosine snap in well-aged lots.","sources":[{"label":"Qualigeo: Tiroler Bergkäse PDO","url":"https://www.qualigeo.eu/en/product/tiroler-bergkase-pdo/"},{"label":"Wikipedia: Bergkäse","url":"https://en.wikipedia.org/wiki/Bergkäse"}],"pronunciation":{"ipa":"/tiˈroːlɐ ˈbɛʁkˌkɛːzə/","respelling":"tee-ROH-ler BAIRK-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[10.1,47.6],[11.3,47.7],[12.45,47.65],[12.85,47.05],[11.85,46.8],[10.7,46.9],[10.15,47.25],[10.1,47.6]]]}},{"name":"Tiroler Graukäse","lat":47.18,"lon":11.85,"country":"Austria","where":"Tyrol — Zillertal","hint":"Zillertal valley, Tyrol","desc":"Acid-curdled, very low-fat sour-milk \'grey\' cheese with sharp, ammoniacal bite.","image":"tiroler_graukäse.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","sour-curd","low-fat","blue-grey rind"],"ageing_min_days":14,"format":"small block, ~1–2 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Tiroler Graukäse is the famously austere sour-milk cheese of Tyrol, traditionally made from the skimmed milk left over after the day\'s butter had been pulled and named for the blue-grey moulds that bloom across the rind during maturation. The PDO permits fresh or pasteurised cow\'s milk, almost always skimmed, and forbids the use of rennet entirely — the curd sets by lactic-acid acidification alone over several hours at room temperature. The acid curd is broken, gently warmed, drained in cloth or moulds, salted, and dried in a warm chamber where the surface flora — Mucor and Penicillium species — colonises the rind and creeps inward to give the cheese its marbled greyish appearance. EU PDO came in 1997. Production runs across the whole federal state of Tyrol. Fat sits between half a per cent and ten per cent in dry matter — among the leanest of all named cheeses — and the flavour is pronounced: sour, ammoniated, intensely savoury, often eaten with vinegar, oil and onion as the classic Tyrolean Saurer Käse meal.","sources":[{"label":"Qualigeo: Tiroler Graukäse PDO","url":"https://www.qualigeo.eu/en/product/tiroler-graukase-pdo/"},{"label":"Wikipedia: Tyrolean grey cheese","url":"https://en.wikipedia.org/wiki/Tyrolean_grey_cheese"}],"pronunciation":{"ipa":"/tiˈroːlɐ ˈɡʁaʊˌkɛːzə/","respelling":"tee-ROH-ler GROW-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[10.1,47.7],[11.5,47.75],[12.5,47.65],[12.85,47.05],[11.85,46.8],[10.7,46.9],[10.15,47.25],[10.1,47.7]]]}},{"name":"Vorarlberger Alpkäse","lat":47.27,"lon":9.97,"country":"Austria","where":"Vorarlberg Alps","hint":"Vorarlberg, summer pastures only","desc":"Raw cow\'s-milk Alpine cheese, summer-only production from herd-on-pasture.","image":"vorarlberger_alpkase.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":90,"format":"wheel, ~25–40 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Vorarlberger Alpkäse is the summer-only alpine cheese of westernmost Austria, produced on alpine pastures between one thousand and one thousand-eight-hundred metres in the Bregenzerwald, Großwalsertal, Kleinwalsertal and adjacent districts from May to September. The PDO requires fresh raw cow\'s milk — no tank milk — from cattle grazing exclusively on alpine grasses with no silage allowed; up to twenty per cent supplementary grain meal is permitted on an annual basis. The milk is set with natural rennet, the curd cut and scalded, pressed into large wheels of up to forty kilograms and aged a minimum of three months. EU PDO came in 1997. The rind is dried golden-brown and slightly granular; the paste is firm and ivory-yellow with sparse pea-sized eyes; the flavour carries the high-alpine herb signature — gentian, alpine clover, mountain hay — and gains complexity as wheels rest for six, nine or twelve months in the cooperative cellars.","sources":[{"label":"Frontiers in Microbiology: Vorarlberger Alpkäse ripening study","url":"https://www.frontiersin.org/journals/microbiology/articles/10.3389/fmicb.2025.1617995/full"},{"label":"Austrian Federal Ministry (BMLRT): Vorarlberger Alpkäse g.U.","url":"https://www.bmlrt.gv.at/land/lebensmittel/trad-lebensmittel/kaese/vorarlb_alpkaese.html"},{"label":"Wikipedia: Alpkäse","url":"https://en.wikipedia.org/wiki/Alpkäse"}],"pronunciation":{"ipa":"/ˈfoːɐ̯ʔaʁlˌbɛʁɡɐ ˈalpˌkɛːzə/","respelling":"FOR-arl-bair-ger AHLP-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.6,47.55],[10.0,47.55],[10.2,47.3],[10.1,47.05],[9.65,47.05],[9.5,47.3],[9.6,47.55]]]}},{"name":"Vorarlberger Bergkäse","lat":47.27,"lon":9.97,"country":"Austria","where":"Vorarlberg","hint":"Vorarlberg, hard mountain wheel","desc":"Raw cow\'s-milk mountain cheese aged 3–6 months; fruity, nutty, year-round.","image":"vorarlberger_bergkäse.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed","smear-ripened"],"ageing_min_days":90,"format":"wheel, ~8–35 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Vorarlberger Bergkäse is the year-round mountain cheese of Vorarlberg, the western tip of Austria where dairy farming traditions overlap with neighbouring Switzerland\'s. The PDO restricts production to dairies in the Bregenzerwald, Großwalsertal, Kleinwalsertal, Leiblachtal and Rhine Valley, and the milk to hay-milk from grassland farms that exclude silage entirely. The milk must reach the dairy at least once a day and be processed immediately — no intermediate storage and no transport between dairies. Only natural rennet is permitted; production must be by manual methods. Wheels mature at least three months in moist cellars, washed regularly with brine to develop a smear rind and full savoury character. EU PDO came in 1997. The cheese has a warm tan rind, firm ivory-to-golden paste with small to medium eyes, and a markedly aromatic flavour — spicy, almost meaty with age — that puts it alongside the great alpine cheeses of the Allgäu and the Berner Oberland.","sources":[{"label":"Wikipedia: Vorarlberger Bergkäse","url":"https://en.wikipedia.org/wiki/Vorarlberger_Bergk%C3%A4se"},{"label":"Qualigeo: Vorarlberger Bergkäse PDO","url":"https://www.qualigeo.eu/en/product/vorarlberger-bergkase-pdo/"}],"pronunciation":{"ipa":"/ˈfoːɐ̯ʔaʁlˌbɛʁɡɐ ˈbɛʁkˌkɛːzə/","respelling":"FOR-arl-bair-ger BAIRK-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.55,47.6],[10.15,47.6],[10.25,47.2],[10.05,47.0],[9.55,47.0],[9.45,47.3],[9.55,47.6]]]}},{"name":"Fromage de Herve","lat":50.64,"lon":5.79,"country":"Belgium","where":"Pays de Herve, Liège","hint":"East Belgium, near the German border","desc":"Soft washed-rind cow\'s-milk cube with pungent aroma; the only Belgian PDO cheese.","image":"fromage_de_herve.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind","smear-rind"],"ageing_min_days":21,"format":"small cube, 6 × 6 × 6 cm, 50–400 g","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Fromage de Herve is the great washed-rind cheese of Belgium, made in the Pays de Herve — the hilly bocage country east of Liège between the Vesdre and the Meuse — from local cow\'s milk. The PDO requires that all milk come from herds raised in the Pays de Herve and that production and ripening also take place there. The milk is warmed to 32 °C, coagulated within forty-eight hours of milking (lactic enzymes added if required), the curd cut and placed in moulds to drain slowly without pressing. Each piece is salted by hand or brine-dipped, then matured at high humidity with regular turning and brine-and-Brevibacterium washing — three to four weeks for a young, mild grade, five to six for a stronger, sharper one. EU PDO came in 1996. The cheese is unmistakable in form: a small uniform cube, six centimetres on a side and fifty to four hundred grams in weight, with a damp orange-tan rind and a creamy ivory paste. Its flavour ranges from buttery and milky to overtly barnyard, and it is the canonical pairing for local Liège syrup and a glass of strong Trappist beer.","sources":[{"label":"Qualigeo: Fromage de Herve PDO","url":"https://www.qualigeo.eu/en/product/fromage-de-herve-pdo/"},{"label":"EU DOOR document: Fromage de Herve PDO application (archived)","url":"https://web.archive.org/web/20160404150610/http://ec.europa.eu/agriculture/quality/door/documentDisplay.html?chkDocument=1435_1_en"},{"label":"Wikipedia: Limburger","url":"https://en.wikipedia.org/wiki/Limburger"}],"pronunciation":{"ipa":"/fʁɔ.maʒ də ɛʁv/","respelling":"froh-MAHZH duh ERV"},"region_polygon":{"type":"Polygon","coordinates":[[[5.55,50.75],[5.85,50.75],[6.05,50.65],[6.05,50.5],[5.8,50.4],[5.55,50.5],[5.45,50.65],[5.55,50.75]]]}},{"name":"Bulgarsko byalo salamureno sirene","lat":42.7,"lon":25.5,"country":"Bulgaria","where":"Throughout Bulgaria","hint":"Bulgaria","desc":"White brined cheese from sheep, cow, goat or buffalo milk; the Bulgarian feta-cousin.","image":"bulgarsko_byalo_salamureno_sirene.jpg","name_protections":["PDO"],"milk_types":["sheep","goat","cow","buffalo"],"pasteurization":"any","style":["semi-soft","brined","white"],"ageing_min_days":45,"format":"blocks in brine, ~1 kg pieces","year_recognized":2023,"animal_breed":null,"vegetarian":null,"desc_long":"Bulgarsko byalo salamureno sirene — \\"Bulgarian white brined cheese\\" — is the cornerstone cheese of the Bulgarian table, finally protected at EU level as a PDO in 2023. The spec permits sheep\'s, goat\'s, cow\'s or buffalo\'s milk, or any mixture of those, and ties production to Bulgaria. The recipe builds on the country\'s signature lactic bacterium Lactobacillus delbrueckii subsp. bulgaricus: after heating and cooling, the milk is inoculated with LAB cultures and rennet, the curd cut and drained, lightly pressed, salted, and matured in brine at controlled temperature. Finished cheese carries 46–48 % dry matter and 44–48 % fat in dry matter. The cheese is firm but lightly crumbly, with a bright clean white paste, and a markedly briny, lactic, sharp tang — a richer, more lactic-forward profile than Greek feta from which the recipe is historically distinguished. It anchors the national salad shopska, melts into banitsa pastry, and is grilled in the classic sirene po shopski casserole.","sources":[{"label":"Wikipedia: Sirene","url":"https://en.wikipedia.org/wiki/Sirene"},{"label":"eAmbrosia (EU GI register): Bulgarsko byalo salamureno sirene","url":"https://ec.europa.eu/info/food-farming-fisheries/food-safety-and-quality/certification/quality-labels/geographical-indications-register/details/EUGI00000017826"}],"pronunciation":{"ipa":"/ˈbɤɫɡarsko ˈbʲaɫo saɫamuˈrɛno siˈrɛnɛ/","respelling":"BUL-gar-skoh BYAH-loh sah-lah-moo-REH-noh see-REH-neh"},"region_polygon":{"type":"Polygon","coordinates":[[[22.4,44.2],[23.5,44.2],[25.1,43.95],[26.55,44.1],[27.95,43.8],[28.6,43.4],[28.1,42.1],[27.55,41.95],[26.3,41.7],[24.8,41.55],[23.2,41.4],[22.5,41.85],[22.35,42.85],[22.4,43.6],[22.4,44.2]]]}},{"name":"Halloumi / Χαλλούμι / Hellim","lat":35.1,"lon":33.3,"country":"Cyprus","where":"Cyprus","hint":"Eastern Mediterranean island","desc":"Brined sheep/goat (sometimes cow) curd folded in half; famously grills without melting.","image":"halloumi.jpeg","name_protections":["PDO"],"milk_types":["sheep","goat","cow"],"pasteurization":"any","style":["semi-hard","brined","fresh","scalded-curd"],"ageing_min_days":null,"format":"hemispherical block, ~220–270 g","year_recognized":2021,"animal_breed":null,"vegetarian":true,"desc_long":"Halloumi is a semi-hard brined cheese from Cyprus, traditionally made from a blend of sheep and goat milk, though modern industrial production often includes a significant proportion of cow\'s milk. The signature step is scalding the pressed curds in hot whey for at least thirty minutes — a process that knits the proteins into a structure stable enough to grill or fry without melting, even at high heat. After scalding, the curds are salted, folded around sprigs of spearmint and stored in salted whey; fresh halloumi can be eaten within days, while mature versions cure in brine for forty days or more. Cyprus secured EU PDO protection in 2021 after a long negotiation that fixed milk composition and tied the name to production on the island. Squeaky against the teeth and gently minty with a salt-forward profile, halloumi is central to Cypriot meze and has become the workhorse grilling cheese of the eastern Mediterranean.","sources":[{"label":"Wikipedia: Halloumi","url":"https://en.wikipedia.org/wiki/Halloumi"},{"label":"European Commission press: Halloumi registered as PDO","url":"https://ec.europa.eu/commission/presscorner/detail/en/ip_21_1623"}],"pronunciation":{"ipa":"/xaˈlumi/","respelling":"hah-LOO-mee"},"region_polygon":{"type":"Polygon","coordinates":[[[32.3,35.1],[33.2,35.45],[34.05,35.55],[34.6,35.55],[34.55,35.1],[33.85,34.75],[33.1,34.65],[32.45,34.8],[32.3,34.95],[32.3,35.1]]]}},{"name":"Jihočeská Niva","lat":48.97,"lon":14.47,"country":"Czech Republic","where":"South Bohemia","hint":"Southern Czechia, around České Budějovice","desc":"Cow\'s-milk blue cheese; soft, creamy paste with Penicillium roqueforti veining.","image":"jihoceska_niva.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","blue"],"ageing_min_days":28,"format":"wheel, ~2.8 kg, 18–20 cm dia × 10 cm tall","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Jihočeská Niva is the South Bohemian blue cheese — a pasteurised cow\'s-milk wheel made in the South Bohemia region since 1951, drawing its milk from the pastures of the Šumava foothills, the Novohradské Hory and the Blanský les. The PGI requires production, ripening and packaging within the protected geographical area. The milk is set with rennet, the curd cut and inoculated with Penicillium roqueforti, drained, moulded into a flat cylinder of about 2.8 kg, salted, and pierced with needles to admit oxygen; wheels then mature at least four weeks at controlled temperature and humidity. EU PGI came in 2010. Each wheel runs eighteen to twenty centimetres across and ten centimetres tall. The paste is cream-white to butter-white shot through with bright blue-green veining and visible needle tracks; the flavour is salty, aromatic and assertively blue, in the rich Central European tradition of Roquefort-styled blues from cow\'s milk.","sources":[{"label":"Qualigeo: Jihočeská Niva PGI","url":"https://www.qualigeo.eu/en/product/jihoceska-niva-pgi/"}],"pronunciation":{"ipa":"/ˈjɪɦotʃɛskaː ˈɲɪva/","respelling":"YIH-hoh-ches-kah NYEE-vah"},"region_polygon":{"type":"Polygon","coordinates":[[[13.5,49.4],[14.2,49.5],[14.95,49.3],[15.3,49.05],[15.1,48.65],[14.3,48.55],[13.7,48.65],[13.5,49.05],[13.5,49.4]]]}},{"name":"Jihočeská Zlatá Niva","lat":48.97,"lon":14.47,"country":"Czech Republic","where":"South Bohemia","hint":"Southern Czechia","desc":"\'Golden Niva\' — a milder, richer cow\'s-milk blue from the same Bohemian dairy tradition.","image":"jihoceskazlata_niva.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","blue","washed-rind"],"ageing_min_days":28,"format":"wheel, ~2.8 kg, 18–20 cm dia × 10 cm tall","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Jihočeská Zlatá Niva — \\"Golden Niva\\" — is the washed-rind cousin of Jihočeská Niva, produced in the same South Bohemian PGI zone (the pastures of Novohradské Hory, Blanský les and Šumava) and registered under PGI alongside it in 2010. The processed cow\'s milk is pasteurised and inoculated with Penicillium roqueforti, moulded into the same flat 2.8 kg cylinder as its sibling, pierced with needles, and then matured with a wash that builds up a semi-waxy, creamy to light-brown smear on the rind alongside the blue and green moulds. Wheels rest at least four weeks. EU PGI came in 2010. The paste is creamy white to pale yellow with the blue-to-green mould well distributed; the texture is appreciably softer and pastier than Jihočeská Niva, the flavour saltier and more intense, with the wash adding a yeasty, barnyard note that lingers past the blue tang. The two cheeses are sometimes sold side by side as a study in how a single base recipe responds to different rind treatments.","sources":[{"label":"TasteAtlas: Jihočeská Zlatá Niva","url":"https://www.tasteatlas.com/jihoceska-zlata-niva"}],"pronunciation":{"ipa":"/ˈjɪɦotʃɛskaː ˈzlataː ˈɲɪva/","respelling":"YIH-hoh-ches-kah ZLAH-tah NYEE-vah"},"region_polygon":{"type":"Polygon","coordinates":[[[13.5,49.4],[14.2,49.5],[14.95,49.3],[15.3,49.05],[15.1,48.65],[14.3,48.55],[13.7,48.65],[13.5,49.05],[13.5,49.4]]]}},{"name":"Olomoucké tvarůžky","lat":49.59,"lon":17.25,"country":"Czech Republic","where":"Loštice, Moravia","hint":"Central Moravia","desc":"Pungent ripened sour-milk cheese in tiny rings; one of the strongest-smelling cheeses in Europe.","image":"olomoucke_tvaruzky.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["soft","sour-curd","smear-rind","low-fat"],"ageing_min_days":7,"format":"small disc or ring, ~20 g","year_recognized":2010,"animal_breed":null,"vegetarian":true,"desc_long":"Olomoucké tvarůžky is the famously pungent low-fat cheese of Loštice in the Haná region of Moravia, central Czech Republic — a sour-milk specialty whose production traces back over four hundred years in the surrounding countryside and to 1876 in commercial form at Loštice itself. The PGI restricts production to the protected area and the recipe to skimmed cow\'s-milk sour curd to which only salt is added; no rennet, colourings, flavourings or stabilisers are permitted. Fat in the finished cheese is around half a per cent, making this one of the leanest named cheeses in the world. The curd is salted and rested in silos, blended with ripening agents and acidity regulators, moulded into small discs or rings of around twenty grams, ripened briefly in temperature-and-humidity-controlled chambers to start the surface flora, washed to remove excess yeast, then aged a second phase for the rind to develop its waxy yellow colour and the cheese its unmistakable sharp ammoniated character. EU PGI came in 2010. Annual production exceeds two thousand tonnes — eaten with rye bread, beer and raw onion.","sources":[{"label":"Qualigeo: Olomoucké tvarůžky PGI","url":"https://www.qualigeo.eu/en/product/olomoucke-tvaruzky-pgi/"},{"label":"Wikipedia: Olomoucké tvarůžky","url":"https://en.wikipedia.org/wiki/Olomouck%C3%A9_tvar%C5%AF%C5%BEky"},{"label":"EUR-Lex: PDO/PGI application — Olomoucké tvarůžky (OJ C 182/2007, PDF)","url":"https://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:C:2007:182:0020:0022:EN:PDF"}],"pronunciation":{"ipa":"/ˈolomoutskɛː tvaˈruːʃkɪ/","respelling":"OH-loh-moh-tskay tvah-ROO-shkee"},"region_polygon":{"type":"Polygon","coordinates":[[[16.75,49.95],[17.2,50.0],[17.6,49.85],[17.65,49.55],[17.3,49.45],[16.8,49.55],[16.65,49.8],[16.75,49.95]]]}},{"name":"Danbo","lat":55.95,"lon":10.2,"country":"Denmark","where":"Throughout Denmark","hint":"Denmark","desc":"Mild semi-hard cow\'s-milk loaf with a thin rind; often spiced with caraway.","image":"danbo.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","washed-curd","smear-rind"],"ageing_min_days":21,"format":"loaf or rectangular block, ~6 kg","year_recognized":2017,"animal_breed":null,"vegetarian":null,"desc_long":"Danbo is the Danish national table cheese — a semi-hard washed-curd loaf invented in the late nineteenth century by Rasmus Marius Bøggild and now produced industrially across the country. The PGI restricts production to Denmark and the milk to pasteurised Danish cow\'s milk. The recipe is built on a generous water-addition stage at low scalding temperatures, which gives Danbo its characteristic high moisture, supple paste and mild profile. After moulding and brining, wheels are smear-ripened at 18–20 °C for seven to ten days to develop a thin Brevibacterium linens rind, then matured a minimum of three weeks; younger grades run six weeks for full mildness, while aged versions run six to twelve months for a sharper, more savoury finish. EU PGI came in 2017. The paste is ivory-yellow, marked by small irregular eyes, sometimes additionally spiced with caraway; the flavour is mild, milky and gently smear-aromatic, the Danish answer to Dutch Edam.","sources":[{"label":"Wikipedia: Danbo","url":"https://en.wikipedia.org/wiki/Danbo"}],"pronunciation":{"ipa":"/ˈtænpo/","respelling":"DAN-boh"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[8.05,57.5],[9.45,57.65],[10.65,57.45],[10.85,56.65],[12.05,56.2],[12.65,56.05],[12.35,55.3],[11.3,55.05],[10.3,54.85],[9.2,54.85],[8.3,55.35],[8.05,56.65],[8.05,57.5]]],[[[14.65,55.35],[15.2,55.3],[15.2,54.95],[14.65,54.95],[14.65,55.35]]]]}},{"name":"Havarti","lat":55.79,"lon":12.51,"country":"Denmark","where":"Throughout Denmark","hint":"Denmark","desc":"Semi-soft buttery cow\'s-milk cheese with small irregular eyes; the Danish picnic standard.","image":"havarti.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","washed-curd"],"ageing_min_days":21,"format":"loaf or rectangular block, ~1–4 kg","year_recognized":2019,"animal_breed":null,"vegetarian":null,"desc_long":"Havarti is Denmark\'s most-exported table cheese, developed in the mid-nineteenth century by Hanne Nielsen on her Havarthigaard farm north of Copenhagen, where she experimented with washed-curd cheese-making after travels through the dairying regions of central Europe. The PGI restricts production to Denmark and to approved dairies using Danish milk. After pasteurisation, the milk is set with rennet and acid cultures, the curd is repeatedly washed with hot water to lower its acidity and produce the cheese\'s signature mild profile, then drained, salted and pressed. Rinded Havarti is smear-ripened a week or two at 14–18 °C and finished at 8–12 °C; rindless Havarti ripens about three weeks at 12–20 °C. EU PGI came in 2019. The paste is supple, ivory-yellow and shot through with countless small irregular eyes; the flavour is mild, milky-sweet and gently buttery, with extended ageing producing a more pronounced sharpness in the Aged and Vintage grades.","sources":[{"label":"Wikipedia: Havarti","url":"https://en.wikipedia.org/wiki/Havarti"},{"label":"Danish Dairy Board: PGI cheeses","url":"https://danishdairyboard.dk/products/danish-pgi-cheeses/"},{"label":"Fødevarestyrelsen: Varespecifikation Havarti (PDF)","url":"https://www.foedevarestyrelsen.dk/Media/638206919135372279/Varespecifikation%20Havarti.pdf"}],"pronunciation":{"ipa":"/haˈvɑːti/","respelling":"hah-VAR-tee"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[8.05,57.5],[9.45,57.65],[10.65,57.45],[10.85,56.65],[12.05,56.2],[12.65,56.05],[12.35,55.3],[11.3,55.05],[10.3,54.85],[9.2,54.85],[8.3,55.35],[8.05,56.65],[8.05,57.5]]],[[[14.65,55.35],[15.2,55.3],[15.2,54.95],[14.65,54.95],[14.65,55.35]]]]}},{"name":"Danablu","lat":55.95,"lon":10.2,"country":"Denmark","where":"Throughout Denmark","hint":"Denmark","desc":"Creamy, strongly sharp cow\'s-milk blue developed in the 1920s as a Roquefort substitute.","image":"danablu.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","blue"],"ageing_min_days":56,"format":"cylinder, ~3 kg","year_recognized":2003,"animal_breed":null,"vegetarian":null,"desc_long":"Danablu — Danish Blue — is Denmark\'s interpretation of the European blue cheese tradition, developed in the early twentieth century by cheesemaker Marius Boel as a Roquefort-style cheese made from cow\'s milk. The PGI restricts production to Denmark and to approved dairies using Danish milk. The milk is homogenised and pasteurised — uniquely among European blues, the homogenisation step is part of the spec — and lightly inoculated with Penicillium roqueforti. After moulding, salting and a short rest, the wheels are pierced with steel needles to admit oxygen and trigger the moulds to bloom outward, then matured eight to twelve weeks at controlled temperature. EU PGI came in 2003. Two fat grades are permitted: Danablu 50+ with fifty per cent fat in dry matter and Danablu 60+ at sixty per cent. The paste is moist, creamy and densely veined with blue-grey threads; the flavour is famously pungent — sharper, saltier and more piquant than Roquefort, with a long ammoniated finish.","sources":[{"label":"Qualigeo: Danablu PGI","url":"https://www.qualigeo.eu/en/product/danablu-pgi/"},{"label":"Wikipedia: Danish Blue Cheese","url":"https://en.wikipedia.org/wiki/Danish_Blue_Cheese"},{"label":"EU GI application: Danablu (archived PDF)","url":"https://web.archive.org/web/20190830152913/https://ecta.org/IMG/pdf/gi_application_danablu.pdf"}],"pronunciation":{"ipa":"/ˈtænæblu/","respelling":"DAN-uh-bloo"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[8.05,57.5],[9.45,57.65],[10.65,57.45],[10.85,56.65],[12.05,56.2],[12.65,56.05],[12.35,55.3],[11.3,55.05],[10.3,54.85],[9.2,54.85],[8.3,55.35],[8.05,56.65],[8.05,57.5]]],[[[14.65,55.35],[15.2,55.3],[15.2,54.95],[14.65,54.95],[14.65,55.35]]]]}},{"name":"Esrom","lat":56.04,"lon":12.39,"country":"Denmark","where":"Esrum, North Zealand","hint":"Zealand, north of Copenhagen","desc":"Semi-soft washed-rind cow\'s-milk loaf revived from a recipe of the Cistercian Esrum Abbey.","image":"esrom.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","washed-rind","smear-rind"],"ageing_min_days":14,"format":"rectangular block, ~250 g – 2 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Esrom is the smear-ripened, Tilsit-influenced semi-soft cheese of Denmark, named for the Esrum Monastery in North Zealand where Cistercian monks made an early version centuries ago. The recipe was re-developed in the 1930s by the Danish Dairy Research Institute and is today produced industrially across the country under PGI. The spec restricts production to Denmark and the milk to lightly pasteurised Danish cow\'s milk: rennet and lactic acid bacteria are added, the curd cut and stirred, drained, lightly pressed and salted, then wheels are rubbed with a smear of Brevibacterium linens and aged in a well-ventilated chamber for at least two weeks, typically running ten to twelve. EU PGI came in 1996. The cheese has a thin tan-orange washed rind and a supple ivory-to-yellow paste shot through with small irregular eyes; the flavour is mild and milky in young wheels, developing a strong barnyard pungency and yeasty depth as it ages.","sources":[{"label":"Wikipedia: Esrom","url":"https://en.wikipedia.org/wiki/Esrom"},{"label":"Qualigeo: Esrom PGI","url":"https://www.qualigeo.eu/en/product/esrom-pgi/"}],"pronunciation":{"ipa":"/ˈesʁʌm/","respelling":"ESS-rom"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[8.05,57.5],[9.45,57.65],[10.65,57.45],[10.85,56.65],[12.05,56.2],[12.65,56.05],[12.35,55.3],[11.3,55.05],[10.3,54.85],[9.2,54.85],[8.3,55.35],[8.05,56.65],[8.05,57.5]]],[[[14.65,55.35],[15.2,55.3],[15.2,54.95],[14.65,54.95],[14.65,55.35]]]]}},{"name":"Abondance","lat":46.28,"lon":6.72,"country":"France","where":"Vallée d\'Abondance, Haute-Savoie","hint":"Savoyard Alps, near Lake Geneva","desc":"Hard pressed cow\'s-milk wheel with concave heel, made from Abondance-breed milk.","image":"abondance.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","pressed","cooked-curd","alpine"],"ageing_min_days":100,"format":"wheel, ~10 kg, concave heel","year_recognized":1990,"animal_breed":["Abondance","Montbéliarde","Tarine"],"vegetarian":null,"desc_long":"Abondance is a semi-hard cow\'s-milk cheese from the Val d\'Abondance in the Haute-Savoie, named both for the valley and for the small auburn-and-white cattle breed that supplies most of the milk. The AOC requires raw milk drawn predominantly from Abondance cows (at least fifty-five percent), with the rest permitted from Montbéliarde and Tarine animals — all three suited to the high alpine summer pastures around the village. The curd is gently cooked and pressed into wheels weighing about ten kilograms, whose distinctive concave heel marks the cheese unmistakably on a shop counter. Maturation runs a minimum of three months on spruce boards in cool cellars, frequently extending to six or more, with the rind brushed and turned regularly. French AOC came in 1990 and EU PDO followed in 1996. The flavour is firm and fruity with a hazelnut sweetness that lengthens into a long savoury finish — recognisably related to its grander Savoyard cousin Beaufort, but smaller, simpler and quietly fond.","sources":[{"label":"INAO product page: Abondance","url":"https://www.inao.gouv.fr/produit/abondance-17637"},{"label":"Wikipedia: Abondance cheese","url":"https://en.wikipedia.org/wiki/Abondance_cheese"}],"pronunciation":{"ipa":"/a.bɔ̃.dɑ̃s/","respelling":"ah-bohn-DAHNSS"},"region_polygon":{"type":"Polygon","coordinates":[[[6.55,46.4],[6.8,46.45],[7.0,46.4],[7.05,46.2],[6.85,46.15],[6.6,46.2],[6.55,46.4]]]}},{"name":"Banon","lat":44.04,"lon":5.63,"country":"France","where":"Haute-Provence","hint":"Provence highlands","desc":"Soft goat\'s-milk disc wrapped in chestnut leaves tied with raffia; ages under foliage.","image":"banon.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","leaf-wrapped"],"ageing_min_days":15,"format":"small disc, ~100 g, 8 cm diameter","year_recognized":2003,"animal_breed":null,"vegetarian":null,"desc_long":"Banon is a small soft goat\'s-milk cheese from the limestone uplands of Haute-Provence, named for the village of Banon where the local farmers traditionally wrapped their summer cheese in chestnut leaves for storage. The AOC requires raw goat\'s milk drawn from local breeds, set with rennet and lightly drained into the characteristic eight-centimetre disc; after a short initial affinage the wheels are dipped in eau de vie and wrapped in pre-soaked chestnut leaves tied with raffia, then aged a further few weeks under cover. The leaf wrapping is more than decorative — it slows the cheese\'s drying, contributes tannic notes and houses a wild flora that ripens the rind into a creamy, slightly nutty paste. French AOC came in 2003 and EU PDO followed; Banon was the first Provençal cheese formally protected. Eaten with the leaves peeled back at table, it pairs naturally with the herbal whites of the southern Rhône and a crust of country bread.","sources":[{"label":"INAO product page: Banon","url":"https://www.inao.gouv.fr/produit/banon-15965"},{"label":"Wikipedia: Banon cheese","url":"https://en.wikipedia.org/wiki/Banon_cheese"}],"pronunciation":{"ipa":"/ba.nɔ̃/","respelling":"bah-NOHN"},"region_polygon":{"type":"Polygon","coordinates":[[[5.0,44.8],[5.7,44.7],[6.4,44.4],[6.5,44.0],[6.3,43.6],[5.8,43.5],[5.2,43.7],[4.8,44.0],[4.7,44.5],[5.0,44.8]]]}},{"name":"Beaufort","lat":45.72,"lon":6.57,"country":"France","where":"Beaufortain, Savoie","hint":"Northern French Alps","desc":"Hard cow\'s-milk Alpine wheel called \'prince of gruyères\'; Tarine & Abondance breeds, concave sides.","image":"beaufort.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","cooked-curd","pressed","alpine"],"ageing_min_days":150,"format":"wheel, 20–70 kg, concave-sided","year_recognized":1968,"animal_breed":["Tarine","Abondance"],"vegetarian":null,"desc_long":"Beaufort is a cooked-curd cow\'s-milk cheese from the Beaufortain, Tarentaise and Maurienne valleys of the Savoie, often described as the prince of Gruyère for the dignity of its long-aged wheels. The AOC requires raw milk from Tarine and Abondance cattle, set in copper cauldrons, cooked, and pressed into the unmistakable concave-sided wheels that weigh between twenty and seventy kilograms. Three classes are recognised: standard Beaufort, Beaufort d\'Été made between June and October when cattle are on summer pasture, and Beaufort Chalet d\'Alpage produced entirely on the high alpages from single-herd milk twice daily. Maturation runs a minimum of five months on spruce boards in cool cellars; chalet wheels often age much longer. French AOC came in 1968 and EU PDO followed. The paste is pale yellow, smooth and supple, with a flavour that begins fruity and sweet and lengthens into the deep buttery savour for which Beaufort is celebrated — and which, melted, defines a great Savoyard fondue.","sources":[{"label":"INAO product page: Beaufort","url":"https://www.inao.gouv.fr/produit/beaufort-22661"},{"label":"Wikipedia: Beaufort cheese","url":"https://en.wikipedia.org/wiki/Beaufort_cheese"}],"pronunciation":{"ipa":"/bo.fɔʁ/","respelling":"boh-FOR"},"region_polygon":{"type":"Polygon","coordinates":[[[6.4,45.95],[6.85,45.85],[7.1,45.55],[6.8,45.2],[6.3,45.2],[6.1,45.55],[6.15,45.8],[6.4,45.95]]]}},{"name":"Bleu d\'Auvergne","lat":45.5,"lon":2.93,"country":"France","where":"Auvergne (Massif Central)","hint":"Auvergne volcanoes, central France","desc":"Creamy, pungent cow\'s-milk blue with broad blue-green veining; piqué (needled) like Roquefort.","image":"bleu_dauvergne.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft","blue","natural-rind"],"ageing_min_days":28,"format":"cylinder, ~2.5 kg","year_recognized":1975,"animal_breed":null,"vegetarian":null,"desc_long":"Bleu d\'Auvergne is a cow\'s-milk blue cheese from the Auvergne in central France, born in the mid-nineteenth century when a local farmer-experimenter is said to have intentionally seeded his curd with the mould from rye bread crusts to coax a moist, blue-veined paste closer in character to Roquefort. Today the AOC covers a defined production zone across the Massif Central, with raw or pasteurised cow\'s milk set with rennet, drained, salted, then pierced with long needles to admit the air on which Penicillium roqueforti depends. Cylindrical wheels of about two and a half kilograms age a minimum of four weeks in cool, humid cellars where the moulds spread through the paste in broad blue-green strokes. French AOC came in 1975 and EU PDO followed. Compared to Roquefort, Bleu d\'Auvergne is less salty, milder and softer — a creamy, buttery, gently pungent blue at home crumbled over walnut salads or melted into the regional pork dishes of the Massif.","sources":[{"label":"INAO product page: Bleu d\'Auvergne","url":"https://www.inao.gouv.fr/produit/bleu-dauvergne-4562"},{"label":"Wikipedia: Bleu d\'Auvergne","url":"https://en.wikipedia.org/wiki/Bleu_d%27Auvergne"}],"pronunciation":{"ipa":"/blø d‿o.vɛʁɲ/","respelling":"bluh doh-VAIRN-yuh"},"region_polygon":{"type":"Polygon","coordinates":[[[2.0,46.0],[3.5,46.3],[4.3,45.8],[4.4,45.0],[4.0,44.4],[3.3,44.1],[2.5,44.2],[1.8,44.5],[1.5,45.2],[1.7,45.7],[2.0,46.0]]]}},{"name":"Bleu de Gex Haut-Jura / Bleu de Septmoncel","lat":46.32,"lon":6.05,"country":"France","where":"Haut-Jura plateau","hint":"Jura mountains","desc":"Mild ivory cow\'s-milk blue marbled with Penicillium glaucum; from high pastures of the Jura.","image":"bleu_de_gex_haut-jura_bleu_de_septmoncel.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-soft","blue","natural-rind"],"ageing_min_days":21,"format":"wheel, 6–9 kg, 31–35 cm × 10 cm","year_recognized":1977,"animal_breed":["Montbéliarde"],"vegetarian":null,"desc_long":"Bleu de Gex is a high-altitude cow\'s-milk blue cheese from the upper Jura mountains, made entirely from the raw milk of Montbéliarde cattle pastured between the Lac de Joux country and the Ain plateau. The AOC takes its full name from the two villages most associated with the recipe, Gex and Septmoncel. After setting, draining and salting, wheels of seven and a half kilograms are pierced to admit air to the seeded Penicillium and aged a minimum of three weeks — though most of the cheese sold reaches markets after a month or two, when the green-blue marbling has spread evenly through an ivory paste. French AOC was confirmed in 1977 and EU PDO followed in 1996. Bleu de Gex is markedly milder than the major French blues, with a creamy, almost nutty character and a gentle bittersweet finish that has long made it the everyday blue of mountain farmhouse cooking.","sources":[{"label":"Wikipedia: Bleu de Gex","url":"https://en.wikipedia.org/wiki/Bleu_de_Gex"}],"pronunciation":{"ipa":"/blø də ʒɛks o ʒy.ʁa/","respelling":"bluh duh ZHEKS oh zhoo-RAH"},"region_polygon":{"type":"Polygon","coordinates":[[[5.7,46.55],[6.05,46.55],[6.2,46.3],[6.05,46.0],[5.65,45.95],[5.5,46.15],[5.55,46.45],[5.7,46.55]]]}},{"name":"Bleu des Causses","lat":44.1,"lon":3.1,"country":"France","where":"Causses plateau (Aveyron, Lozère)","hint":"Limestone causses south of Massif Central","desc":"Cow\'s-milk version of Roquefort, aged in the same kind of natural fleurines (cave drafts).","image":"bleu_des_causses.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-soft","blue","natural-rind"],"ageing_min_days":70,"format":"cylinder, ~2.3–3 kg","year_recognized":1953,"animal_breed":null,"vegetarian":null,"desc_long":"Bleu des Causses is a raw cow\'s-milk blue cheese from the limestone causses of the Aveyron and Lozère, made on the very same plateau as Roquefort and aged in the same kind of natural limestone caves whose ventilation cracks — the fleurines — propagate Penicillium roqueforti through the paste. Whole milk is set, drained, pierced and matured for at least seventy days in cellar conditions that approximate the cool damp of the caves of Combalou. Wheels weigh around two and a half kilograms with a moist, faintly sticky ivory paste broken by broad green-blue veining. French AOC came in 1953, and EU PDO followed in 1996. The cheese is sometimes called the cow\'s-milk Roquefort — bigger-flavoured, creamier, less salty than the sheep original, with the same mineral character that comes from the same caves.","sources":[{"label":"INAO product page: Bleu des Causses","url":"https://www.inao.gouv.fr/produit/bleu-des-causses-14230"},{"label":"Wikipedia: Bleu des Causses","url":"https://en.wikipedia.org/wiki/Bleu_des_Causses"}],"pronunciation":{"ipa":"/blø de kos/","respelling":"bluh day KOHSS"},"region_polygon":{"type":"Polygon","coordinates":[[[2.4,44.4],[3.0,44.5],[3.5,44.4],[3.5,44.0],[3.0,43.8],[2.4,43.9],[2.2,44.1],[2.4,44.4]]]}},{"name":"Bleu du Vercors-Sassenage","lat":45.05,"lon":5.4,"country":"France","where":"Vercors massif (Isère, Drôme)","hint":"Northern Pre-Alps","desc":"Soft cow\'s-milk blue from alpine pastures of the Vercors limestone massif; gentle bite.","image":"bleu_du_vercors_sassenage.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","blue"],"ageing_min_days":21,"format":"wheel, ~4–4.5 kg, 27–30 cm × 7–9 cm","year_recognized":1998,"animal_breed":null,"vegetarian":null,"desc_long":"Bleu du Vercors-Sassenage is a soft cow\'s-milk blue cheese from the limestone Vercors massif on the western edge of the French Alps, produced across roughly thirty municipalities of the Drôme and Isère. Cattle are pastured on the dry herbal alpages of the Vercors, and their milk is set, drained and seeded with Penicillium roqueforti before being moulded into wheels of about four kilograms and pierced to develop the blue marbling. Maturation runs at least three weeks in cool humid cellars. French AOC came in 1998 and EU PDO followed. The cheese is one of the gentler French blues — a sweet, almost milky paste broken by light blue-grey veining, with a moist supple texture and a finish that tilts more toward butter than salt. It is at home crumbled into the local ravioles or melted into walnut-flecked salads of the surrounding hills.","sources":[{"label":"Wikipedia: Bleu du Vercors-Sassenage","url":"https://en.wikipedia.org/wiki/Bleu_du_Vercors-Sassenage"}],"pronunciation":{"ipa":"/blø dy vɛʁ.kɔʁ sas.naʒ/","respelling":"bluh doo vair-KOR sass-NAHZH"},"region_polygon":{"type":"Polygon","coordinates":[[[5.2,45.3],[5.5,45.3],[5.65,45.15],[5.7,44.85],[5.5,44.7],[5.2,44.8],[5.1,45.05],[5.2,45.3]]]}},{"name":"Brie de Meaux","lat":48.96,"lon":2.88,"country":"France","where":"Île-de-France — around Meaux","hint":"East of Paris","desc":"Large soft cow\'s-milk wheel with bloomy white rind; the \'king of cheeses\' since the Congress of Vienna.","image":"brie_de_meaux.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","bloomy-rind"],"ageing_min_days":28,"format":"wheel, ~2.8 kg, 36–37 cm diameter","year_recognized":1980,"animal_breed":null,"vegetarian":null,"desc_long":"Brie de Meaux is the larger and historically older of the two Bries protected by appellation in the Île-de-France, made from raw cow\'s milk in a defined zone around the town of Meaux that today reaches into half a dozen surrounding departments. After setting and draining, the curd is hand-ladled into the mould in thin layers with a flat scoop called a pelle à brie, salted by hand and aged on rye straw for a minimum of four weeks under a developing bloom of Penicillium camemberti. Mature wheels are about thirty-seven centimetres across and just under three kilograms, with a thin white rind streaked rose-red and an ivory paste that turns golden and softly oozing at the peak of ripeness. French AOC came in 1980 and EU PDO followed in 1996. At the Congress of Vienna in 1815 Talleyrand is said to have presented Brie de Meaux at a contest of European cheeses and to have walked away with its enduring sobriquet, the king of cheeses.","sources":[{"label":"INAO product page: Brie de Meaux","url":"https://www.inao.gouv.fr/produit/brie-de-meaux-16167"},{"label":"Wikipedia: Brie de Meaux","url":"https://en.wikipedia.org/wiki/Brie_de_Meaux"},{"label":"EU PDO application: Brie de Meaux (eAmbrosia, archived)","url":"https://web.archive.org/web/20251220044536/https://ec.europa.eu/geographical-indications-register/eambrosia-public-api/api/v1/attachments/71328"}],"pronunciation":{"ipa":"/bʁi də mo/","respelling":"bree duh MOH"},"region_polygon":{"type":"Polygon","coordinates":[[[2.4,49.0],[3.0,49.2],[3.7,49.1],[4.2,48.8],[4.0,48.3],[3.4,48.2],[2.7,48.4],[2.4,48.7],[2.4,49.0]]]}},{"name":"Brie de Melun","lat":48.54,"lon":2.66,"country":"France","where":"Île-de-France — around Melun","hint":"South of Paris","desc":"Smaller, more rustic, more pungent Brie than its Meaux cousin; longer-aged.","image":"brie_de_melun.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","bloomy-rind"],"ageing_min_days":28,"format":"wheel, ~1.5 kg, 27 cm diameter","year_recognized":1980,"animal_breed":null,"vegetarian":null,"desc_long":"Brie de Melun is the smaller and the more pungent of the two AOC Bries of the Île-de-France, produced around the town of Melun south of Paris from raw cow\'s milk. The cheese is matured at least four weeks under a thin bloom of Penicillium camemberti, but mature wheels are typically taken longer than that and develop a stronger personality than their Meaux counterpart. A finished wheel is about a kilo and a half and twenty-seven centimetres across, with a pale wrinkled rind streaked rose-red and an ivory paste that turns more pronouncedly sharp and ammoniacal at the peak of ripeness. French AOC recognition came in 1980 alongside Brie de Meaux. Where Brie de Meaux is the gracious king of cheeses, Brie de Melun is the more rustic, more uncompromising version — coarser, deeper, frankly stronger — and a connoisseur\'s choice on a French cheese course.","sources":[{"label":"INAO product page: Brie de Melun","url":"https://www.inao.gouv.fr/produit/brie-de-melun-16351"},{"label":"Wikipedia: Brie de Melun","url":"https://en.wikipedia.org/wiki/Brie_de_Melun"}],"pronunciation":{"ipa":"/bʁi də mə.lœ̃/","respelling":"bree duh muh-LUHN"},"region_polygon":{"type":"Polygon","coordinates":[[[2.5,48.7],[3.1,48.7],[3.7,48.5],[3.7,48.0],[3.3,47.7],[2.7,47.9],[2.5,48.3],[2.5,48.7]]]}},{"name":"Brocciu (Corse)","lat":42.15,"lon":9.08,"country":"France","where":"Corsica","hint":"Corsica","desc":"Fresh whey cheese (sheep or goat) eaten warm; the basis of every Corsican filling, sweet or savoury.","image":"brocciu_corse.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["fresh","whey cheese"],"ageing_min_days":1,"format":"tronco-conical mould, ~250 g – 1 kg","year_recognized":1983,"animal_breed":null,"vegetarian":null,"desc_long":"Brocciu is a fresh whey cheese from Corsica, the only French AOC cheese in this family and the cornerstone of the island\'s culinary identity. Production begins with the whey left over from making a firm sheep\'s- or goat\'s-milk cheese: the whey is heated gently, fresh whole milk is added back in to lift the protein content, and the mixture is brought close to the boil so that the residual proteins coagulate and rise as soft white curds. The curds are skimmed into perforated tronco-conical moulds and drained briefly; brocciu is then ready to eat warm, within a day, or salted and air-dried for keeping. French AOC came in 1983 and EU PDO followed in 1998. The flavour is delicately milky and faintly sweet, and the cheese is woven through the whole Corsican cooking calendar — folded into fiadone cheesecakes and migliacci, stuffed into ravioli or into roast kid, eaten with figs in summer, and spread on toast with chestnut honey.","sources":[{"label":"INAO product page: Brocciu (Corse)","url":"https://www.inao.gouv.fr/produit/brocciu-16325"},{"label":"Wikipedia: Brocciu","url":"https://en.wikipedia.org/wiki/Brocciu"}],"pronunciation":{"ipa":"/ˈbrɔt.tʃu/","respelling":"BROH-choo"},"region_polygon":{"type":"Polygon","coordinates":[[[8.55,43.0],[9.0,42.95],[9.5,42.85],[9.55,42.3],[9.4,41.6],[9.0,41.4],[8.65,41.55],[8.55,42.0],[8.55,42.5],[8.55,43.0]]]}},{"name":"Camembert de Normandie","lat":48.87,"lon":0.18,"country":"France","where":"Normandy","hint":"Normandy, west of Paris","desc":"Raw cow\'s-milk bloomy-rind disc, ladled by hand in five passes — the only legal Camembert.","image":"camembert_de_normandie.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","bloomy-rind"],"ageing_min_days":21,"format":"small disc, ~250 g, 10.2 cm × 3.2 cm","year_recognized":1983,"animal_breed":null,"vegetarian":null,"desc_long":"Camembert de Normandie is the legally protected version of one of the world\'s most copied cheeses, requiring by AOC rule that it be made only from raw cow\'s milk in a defined zone of Normandy. Curd is ladled by hand into the moulds in five successive passes — the moulage à la louche that distinguishes the AOC cheese from its industrial cousins — and the small flat discs are then drained, salted and aged at least three weeks under a developing bloom of Penicillium camemberti. A finished wheel is about a quarter kilogram, ten centimetres across, with a thin chalky-white rind sometimes streaked rose-red and an ivory paste that softens to almost spoonable at ripeness. French AOC came in 1983 and EU PDO followed in 1992. Tradition assigns the invention of Camembert to Marie Harel, a Norman farmer who in 1791 is said to have refined an earlier soft-cheese recipe with advice from a priest fleeing Revolutionary France; her descendants later presented the cheese to Napoleon III, sealing its national reputation.","sources":[{"label":"INAO product page: Camembert de Normandie","url":"https://www.inao.gouv.fr/produit/camembert-de-normandie-21884"},{"label":"Wikipedia: Camembert de Normandie","url":"https://en.wikipedia.org/wiki/Camembert_de_Normandie"}],"pronunciation":{"ipa":"/ka.mɑ̃.bɛʁ də nɔʁ.mɑ̃.di/","respelling":"kam-em-BAIR duh nor-mahn-DEE"},"region_polygon":{"type":"Polygon","coordinates":[[[-1.9,49.7],[-0.5,49.9],[0.5,49.8],[1.7,50.1],[1.5,49.4],[1.0,48.9],[-0.5,48.5],[-1.2,48.5],[-1.95,49.0],[-1.9,49.7]]]}},{"name":"Cantal / Fourme de Cantal / Cantalet","lat":45.05,"lon":2.66,"country":"France","where":"Cantal, Auvergne","hint":"Auvergne plateau","desc":"Tall pressed cow\'s-milk cylinder, twice-pressed (cantal-style); aged jeune, entre-deux, vieux.","image":"cantal.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":30,"format":"tall cylinder, 35–45 kg","year_recognized":1956,"animal_breed":["Salers","Montbéliarde"],"vegetarian":null,"desc_long":"Cantal is one of the oldest cheeses of France, a tall pressed cow\'s-milk cylinder from the volcanic uplands of the Auvergne that takes its name from the département of Cantal. The defining production trick, often called pressage en deux temps, is a double pressing: the curd is salted and pressed once, then broken up after a rest of roughly a day, salted again, and pressed a second time into the final cylindrical wheel. Three age classes are recognised by the AOC: Cantal Jeune is taken at one to two months and is gentle, milky and faintly tangy; Cantal Entre-deux runs from three to six months and balances buttery sweetness with the first hints of a sharper finish; Cantal Vieux is aged eight months or more and dries into a firm amber paste with a vigorous nutty, tangy character sometimes compared to mature English Cheddar. French AOC was granted in 1956 and EU PDO followed in 1996. Cantal is the indispensable base of the regional aligot and an enduring everyday cheese on Auvergnat tables.","sources":[{"label":"INAO product page: Cantal","url":"https://www.inao.gouv.fr/produit/cantal-ou-fourme-de-cantal-15010"},{"label":"Wikipedia: Cantal cheese","url":"https://en.wikipedia.org/wiki/Cantal_cheese"}],"pronunciation":{"ipa":"/kɑ̃.tal/","respelling":"kahn-TAHL"},"region_polygon":{"type":"Polygon","coordinates":[[[2.0,45.5],[3.0,45.5],[3.5,45.2],[3.3,44.7],[2.7,44.5],[2.0,44.6],[1.8,45.0],[2.0,45.5]]]}},{"name":"Chabichou du Poitou","lat":46.58,"lon":0.34,"country":"France","where":"Haut-Poitou plateau","hint":"West-central France","desc":"Small truncated cylinder of goat\'s milk; firm white paste with delicate goaty tang.","image":"chabichou_du_poitou.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"any","style":["soft","bloomy-rind"],"ageing_min_days":10,"format":"truncated cylinder (\'bonde\'), ~120 g","year_recognized":1990,"animal_breed":null,"vegetarian":null,"desc_long":"Chabichou du Poitou is a small soft goat\'s-milk cheese from the Haut-Poitou — the chalky farmland north of Poitiers shared across the Vienne, Deux-Sèvres and northern Charente — where goats have been the working dairy animal for centuries. The cheese takes its distinctive shape from the bonde, the wooden bung used in old wine barrels: a stubby truncated cylinder of about a hundred and twenty grams. Curd is gently set, ladled into individual moulds, salted and ripened a minimum of ten days under a developing bloom that turns from chalky-white to lightly ivory and crinkled. French AOC came in 1990 and EU PDO followed. Chabichou is unusual within the family of French AOC chèvres for permitting pasteurised milk under the spec — most others require raw — but the artisanal cheese is still made with whole raw milk wherever it can be. The flavour is gently caprine with a clean nutty tang under a moist, smooth paste.","sources":[{"label":"INAO product page: Chabichou du Poitou","url":"https://www.inao.gouv.fr/produit/chabichou-du-poitou-16081"},{"label":"Wikipedia: Chabichou","url":"https://en.wikipedia.org/wiki/Chabichou"}],"pronunciation":{"ipa":"/ʃa.bi.ʃu dy pwa.tu/","respelling":"shah-bee-SHOO doo pwah-TOO"},"region_polygon":{"type":"Polygon","coordinates":[[[-0.7,47.0],[-0.1,47.0],[0.6,46.8],[0.7,46.3],[0.0,46.0],[-0.7,46.1],[-0.9,46.6],[-0.7,47.0]]]}},{"name":"Chaource","lat":48.06,"lon":4.13,"country":"France","where":"Aube/Yonne, Champagne","hint":"Champagne hinterland","desc":"Soft cow\'s-milk cylinder with bloomy rind; lactic, mushroomy, almost cake-like inside.","image":"chaource.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","bloomy-rind"],"ageing_min_days":14,"format":"cylinder, 250 g or 450 g, ~10 cm × 6 cm","year_recognized":1970,"animal_breed":null,"vegetarian":null,"desc_long":"Chaource is a soft cow\'s-milk cheese from the Pays d\'Othe between the Aube and the Yonne, in the hill country east of Troyes that produces a great deal of the milder Champagne. The cheese is set very slowly — coagulation typically takes longer than half a day — then ladled gently into the perforated moulds so the curd retains its lactic, almost cream-like character. After draining and salting, wheels of about a quarter or a half kilogram ripen at least two weeks under a developing white Penicillium bloom; mature wheels are taken three to four weeks. French AOC came in 1970 and EU PDO followed in 1996. Chaource has the soft melting paste of a fresh-cheese, lightly salted and faintly mushroomy at the rind, with a flavour that turns slightly bitter and nutty as the cheese ages. It is the classic cheese-board partner for sparkling and still wines of the Côte des Bar Champagne.","sources":[{"label":"Wikipedia: Chaource cheese","url":"https://en.wikipedia.org/wiki/Chaource_cheese"}],"pronunciation":{"ipa":"/ʃa.uʁs/","respelling":"shah-OORSS"},"region_polygon":{"type":"Polygon","coordinates":[[[3.7,48.2],[4.2,48.2],[4.4,48.0],[4.3,47.7],[3.9,47.7],[3.7,47.9],[3.7,48.2]]]}},{"name":"Chevrotin","lat":45.93,"lon":6.42,"country":"France","where":"Aravis & Bauges, Haute-Savoie/Savoie","hint":"Savoyard Alps","desc":"Washed-rind raw goat\'s-milk Alpine cheese — the Reblochon\'s goat counterpart.","image":"chevrotin.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","washed-rind"],"ageing_min_days":21,"format":"small flat cylinder, 250–350 g, 9–12 cm × 3–4.5 cm","year_recognized":2002,"animal_breed":null,"vegetarian":null,"desc_long":"Chevrotin is the goat-milk counterpart to Reblochon, made in the same Aravis, Chablais and Bauges country of Haute-Savoie and Savoie from raw whole milk drawn off small farmstead herds. The cheese takes Reblochon\'s recognisable shape — a flat cylinder of about three hundred grams — and the same intervention during ageing: each wheel is turned and washed with brine three times a week, so the rind develops a pale orange-pink coating tacky to the touch. Ripening runs at least three weeks in cool damp cellars. French AOC came in 2002 and EU PDO followed. Inside the rind sits a supple ivory paste that combines the mushroomy character of a washed-rind cheese with the herbal, faintly nutty tang of pasture-fed goat milk. Chevrotin is at its best from late spring through early autumn when the goats are on the alpages, and pairs well with the dry whites of Apremont and Roussette de Savoie.","sources":[{"label":"INAO product page: Chevrotin","url":"https://www.inao.gouv.fr/produit/chevrotin-13476"},{"label":"Wikipedia: Chevrotin","url":"https://en.wikipedia.org/wiki/Chevrotin"},{"label":"French Ministry of Agriculture: Cahier des charges (PDO spec): Chevrotin","url":"https://info.agriculture.gouv.fr/gedei/site/bo-agri/document_administratif-c3b143d1-4c22-49f2-9ff9-1def3bcba296/telechargement"}],"pronunciation":{"ipa":"/ʃə.vʁɔ.tɛ̃/","respelling":"shuh-vroh-TAN"},"region_polygon":{"type":"Polygon","coordinates":[[[6.3,46.0],[6.55,46.05],[6.7,45.9],[6.65,45.7],[6.4,45.65],[6.25,45.85],[6.3,46.0]]]}},{"name":"Comté","lat":46.8,"lon":6.4,"country":"France","where":"Massif du Jura","hint":"Jura mountains, eastern France","desc":"Hard cooked-curd cow\'s-milk wheel from Montbéliarde milk, aged in mountain fruitières.","image":"comté.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","cooked-curd","pressed","alpine"],"ageing_min_days":120,"format":"wheel, 32–45 kg, 40–70 cm × 9–13 cm","year_recognized":1958,"animal_breed":["Montbéliarde","French Simmental"],"vegetarian":null,"desc_long":"Comté is the great cooked-curd cow\'s-milk cheese of the Jura mountains of eastern France, made under one of the most carefully organised dairy systems anywhere in Europe: roughly 160 village-level fruitières each collect milk from neighbouring farmers and turn it into cheese the same day. The AOC requires raw milk from Montbéliarde and French Simmental cattle that have grazed pastures within a defined Franche-Comté zone, set with rennet, cooked to about fifty-five degrees and pressed into substantial wheels of forty kilograms or more. Maturation runs a minimum of four months and frequently extends to twelve, eighteen or even thirty-six, on spruce boards in cool affineur cellars where the wheels are brushed and turned weekly. French AOC came in 1958 and EU PDO followed in 1996. Each finished wheel carries a coloured band that grades it by ageing and flavour panel — a green band for the higher-scoring examples and brown for the more modest. The flavour vocabulary used to describe Comté is famously broad: hazelnut, brown butter, toasted bread, dried fruit, leather. It is at the centre of Jura cooking and arguably the most beloved cheese in France.","sources":[{"label":"INAO product page: Comté","url":"https://www.inao.gouv.fr/produit/comte-21935"},{"label":"Légifrance: Décret AOC Comté (2007)","url":"https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000000618053"},{"label":"Wikipedia: Comté cheese","url":"https://en.wikipedia.org/wiki/Comt%C3%A9_cheese"}],"pronunciation":{"ipa":"/kɔ̃.te/","respelling":"kohn-TAY"},"region_polygon":{"type":"Polygon","coordinates":[[[5.3,47.2],[5.8,47.45],[6.5,47.5],[7.0,47.1],[6.8,46.5],[6.2,46.05],[5.65,46.15],[5.4,46.65],[5.3,47.2]]]}},{"name":"Crottin de Chavignol","lat":47.31,"lon":2.83,"country":"France","where":"Sancerre region, Loire","hint":"Upper Loire, paired with Sancerre wine","desc":"Small dense goat\'s-milk disc that ripens from chalky white to grey-blue and almost black.","image":"crottin_de_chavignol.jpeg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["semi-hard","natural-rind"],"ageing_min_days":11,"format":"small disc, ~60–90 g","year_recognized":1976,"animal_breed":null,"vegetarian":null,"desc_long":"Crottin de Chavignol is a small raw goat\'s-milk cheese from the hills around the village of Chavignol, just across the river from Sancerre in the Cher department of central France. The cheese is set with a long slow lactic acidification, ladled into perforated cylindrical moulds and dry-salted, then ripened a minimum of about ten days in cool caves. What makes Crottin distinctive is that the producers and the AOC permit a wide ageing spectrum: a young cheese is chalk-white, supple and gently milky; bleuté shows a thickening blue-grey bloom and a firmer, more aromatic interior; affiné continues into a dry, shrunken, brown-rinded, almost crumbly disc with concentrated goat tang. French AOC came in 1976 and EU PDO followed. The cheese is the canonical partner for Sancerre Blanc, melted under the broiler on toast as crottin sur toast, or grated over a green salad with walnut oil.","sources":[{"label":"INAO product page: Crottin de Chavignol","url":"https://www.inao.gouv.fr/produit/chavignol-16448"},{"label":"Wikipedia: Crottin de Chavignol","url":"https://en.wikipedia.org/wiki/Crottin_de_Chavignol"}],"pronunciation":{"ipa":"/kʁɔ.tɛ̃ də ʃa.vi.ɲɔl/","respelling":"kroh-TAN duh shah-vee-NYOHL"},"region_polygon":{"type":"Polygon","coordinates":[[[2.5,47.4],[2.8,47.4],[3.05,47.3],[3.0,47.1],[2.6,47.1],[2.5,47.25],[2.5,47.4]]]}},{"name":"Emmental de Savoie","lat":45.57,"lon":6.2,"country":"France","where":"Savoie","hint":"Savoyard Alps","desc":"Large-eyed cooked-curd cow\'s-milk wheel from Savoie raw milk; sweet and nutty.","image":"emmental-de-savoie.png","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","cooked-curd","pressed","alpine"],"ageing_min_days":75,"format":"wheel, 60–130 kg, ~75 cm diameter","year_recognized":1996,"animal_breed":["Abondance","Montbéliarde","Tarine"],"vegetarian":null,"desc_long":"Emmental de Savoie is the Savoyard version of the great large-eyed alpine grana cheese, distinguished from its Swiss cousin by being a PGI rather than an AOP and by being produced from the raw milk of specifically French breeds — Abondance, Montbéliarde and Tarine — grazed in the Savoie and Haute-Savoie. Production follows the classic Emmental method: milk is set with rennet and a culture of propionic bacteria, the curd is heated and pressed into wheels of sixty to one hundred and thirty kilograms, then aged for two and a half months or more on spruce boards. As the wheels mature in the warm phase of ripening, the propionic bacteria release carbon dioxide that forms the characteristic large eyes through the pale yellow paste. EU PGI recognition came in 1996. The flavour is sweet, gently nutty and grass-fed, with a clean cooked-milk core that makes it both a household table cheese and a workhorse in Savoyard cooking — gratins, tarts, raclette-style melting and the famous tartiflette.","sources":[{"label":"Wikipedia: Emmental cheese","url":"https://en.wikipedia.org/wiki/Emmental_cheese"},{"label":"EU PGI specification: Emmental de Savoie","url":"https://www.gob.mx/cms/uploads/attachment/file/245503/FR_Emmental_de_Savoie.pdf"}],"pronunciation":{"ipa":"/e.mɛn.tal də sa.vwa/","respelling":"em-en-TAHL duh sah-VWAH"},"region_polygon":{"type":"Polygon","coordinates":[[[5.7,46.2],[6.3,46.4],[7.0,46.4],[7.1,45.85],[6.8,45.2],[6.1,45.3],[5.7,45.65],[5.7,46.2]]]}},{"name":"Emmental français est-central","lat":46.5,"lon":5.85,"country":"France","where":"Eastern central France","hint":"Franche-Comté & east-central France","desc":"Big-wheeled Emmental with hazelnut-sized eyes; gateway cheese to Comté country.","image":"emmental_français_est_central.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","cooked-curd","pressed"],"ageing_min_days":84,"format":"wheel, ~70–80 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Emmental français est-central is the broader east-central French expression of the great large-eyed grana cheese, produced under PGI rule across the Doubs, Jura, Haute-Saône, Haute-Marne, Territoire de Belfort and Vosges. The cheese is made from raw cow\'s milk set with rennet and a propionic culture, the curd cooked and pressed into substantial wheels of around seventy kilograms and aged at least twelve weeks in cool cellars. As the cheese ripens, the propionic bacteria release carbon dioxide that opens the characteristic eyes through the pale yellow paste — anything from cherry-sized to walnut-sized under the spec. EU PGI recognition came in 1996. The flavour is the gently nutty, mildly sweet, cooked-milk profile of the wider Emmental family, less terroir-specific than the Savoie version and produced at significantly larger volumes for the everyday French market.","sources":[{"label":"TasteFrance / EU PGI register on Emmental français est-central","url":"https://www.tastefrance.com/french-products/cheese-dairy-products/emmental-de-savoie-pgi"},{"label":"EU DOOR registry: Emmental français est-central (archived)","url":"https://web.archive.org/web/20160604192517/http://ec.europa.eu/agriculture/quality/door/registeredName.html?denominationId=291"},{"label":"Wikipedia: Emmental cheese","url":"https://en.wikipedia.org/wiki/Emmental_cheese"}],"pronunciation":{"ipa":"/e.mɛn.tal fʁɑ̃.sɛ ɛst sɑ̃.tʁal/","respelling":"em-en-TAHL frahn-SAY est sahn-TRAHL"},"region_polygon":{"type":"Polygon","coordinates":[[[4.5,48.5],[6.0,48.5],[7.2,47.4],[7.1,46.45],[6.0,46.0],[5.0,46.3],[4.4,46.8],[4.3,47.5],[4.5,48.5]]]}},{"name":"Époisses","lat":47.51,"lon":4.18,"country":"France","where":"Côte-d\'Or, Burgundy","hint":"Burgundy, near Dijon","desc":"Soft cow\'s-milk cheese washed with Marc de Bourgogne; deep orange rind and famously potent aroma.","image":"époisses.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind"],"ageing_min_days":28,"format":"small disc, ~250 g or ~700 g, sold in a wooden box","year_recognized":1991,"animal_breed":null,"vegetarian":null,"desc_long":"Époisses is a soft cow\'s-milk cheese from the Côte-d\'Or in Burgundy, named for the village halfway between Dijon and Auxerre where Cistercian monks of nearby Cîteaux are said to have first made it in the sixteenth century. Curd is set, drained and salted, then aged at least four weeks in a cool damp cellar where each disc is washed two or three times a week with a brine increasingly cut with Marc de Bourgogne, the regional pomace brandy. The yeasts and bacteria that proliferate under that wash produce the cheese\'s brilliant red-orange rind and its uncompromising aroma, and inside the rind sits a pale gold paste that turns spoonable at peak ripeness. French AOC came in 1991 and EU PDO followed in 1996. The flavour is intensely savoury, vinous and gently spicy — Brillat-Savarin called Époisses the king of cheeses, and its long monastic recipe nearly vanished in the 1950s before being revived by a single family who put the cheese back on French tables.","sources":[{"label":"Wikipedia: Époisses cheese","url":"https://en.wikipedia.org/wiki/%C3%89poisses_cheese"},{"label":"INAO AOC text: Époisses (archived)","url":"https://web.archive.org/web/20170314084646/http://www2.inao.gouv.fr/public/produits/showTexte.php?ID_TEXTE_CONSOLIDE=1534"}],"pronunciation":{"ipa":"/e.pwas/","respelling":"ay-PWAHSS"},"region_polygon":{"type":"Polygon","coordinates":[[[4.05,47.95],[4.6,47.95],[4.95,47.75],[4.8,47.35],[4.3,47.3],[3.95,47.5],[3.9,47.8],[4.05,47.95]]]}},{"name":"French Gruyère","lat":46.2,"lon":6.1,"country":"France","where":"Savoie & Franche-Comté","hint":"French Alps & Jura","desc":"Cooked-curd cow\'s-milk wheel — French gruyère must have small eyes, unlike its Swiss namesake.","image":"french_gruyère.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["hard","cooked-curd","pressed"],"ageing_min_days":120,"format":"wheel, ~40 kg","year_recognized":2013,"animal_breed":null,"vegetarian":null,"desc_long":"French Gruyère is the EU PGI version of a cheese far better known in its Swiss form, distinguished above all by a small but legally significant detail: the French spec requires that the cheese have holes between the size of a pea and a cherry, whereas Swiss Gruyère AOP is essentially eyeless. Production zones cover parts of Franche-Comté and Savoie that share an alpine dairying tradition with the Swiss side of the Jura. The curd is cooked and pressed in the classic gruyère style and aged a minimum of four months on spruce boards in cool cellars. EU PGI recognition came in 2013, granted after a long dispute between French producers and the Swiss consortium that had registered Le Gruyère AOP. The flavour is gently nutty and mildly sweet, with the smoother, somewhat softer character of a cheese produced under less restrictive farm-level rules than its Swiss cousin.","sources":[{"label":"Wikipedia: Gruyère","url":"https://en.wikipedia.org/wiki/Gruy%C3%A8re"}],"pronunciation":{"ipa":"/ɡʁy.jɛʁ/","respelling":"groo-YAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[5.5,47.2],[6.5,47.4],[7.0,47.0],[7.1,45.7],[6.2,45.3],[5.6,45.8],[5.45,46.7],[5.5,47.2]]]}},{"name":"Fourme d\'Ambert","lat":45.55,"lon":3.74,"country":"France","where":"Forez & Livradois, Auvergne","hint":"Eastern Auvergne","desc":"Tall cylindrical cow\'s-milk blue with mild, creamy character; one of France\'s oldest cheeses.","image":"fourme_dambert.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft","blue","natural-rind"],"ageing_min_days":28,"format":"tall cylinder, ~1.9–2.5 kg, ~13 cm diameter × 19 cm tall","year_recognized":1972,"animal_breed":null,"vegetarian":null,"desc_long":"Fourme d\'Ambert is a tall cylindrical cow\'s-milk blue cheese from the Livradois and Forez ranges of the Auvergne, one of the oldest documented French cheeses — there are records of Fourme being paid as tithe in the early Middle Ages. The cheese is set, drained, pierced to admit air, and inoculated with Penicillium roqueforti, then aged for at least twenty-eight days in cool damp cellars. The cylinder format is distinctive — taller than it is wide, around two kilograms — and the paste is comparatively pale and fine-veined, with a mild bluing rather than the dense streaking of Roquefort. French AOC came in 1972 jointly with Fourme de Montbrison, and the two were separated into distinct AOCs in 2002. The flavour of Fourme d\'Ambert is among the most approachable of the French blues: creamy, gently nutty, almost honeyed near the rind, with the blue tang appearing only as an undertone.","sources":[{"label":"INAO product page: Fourme d\'Ambert","url":"https://www.inao.gouv.fr/produit/fourme-dambert-13163"},{"label":"Wikipedia: Fourme d\'Ambert","url":"https://en.wikipedia.org/wiki/Fourme_d%27Ambert"},{"label":"Syndicat: AOC Fourme d\'Ambert et de Montbrison (archived)","url":"https://web.archive.org/web/20070211095606/http://www.fourme-ambert.com/htm/aoc.htm"}],"pronunciation":{"ipa":"/fuʁm dɑ̃.bɛʁ/","respelling":"FOORM dahn-BAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[3.0,45.95],[3.6,46.0],[4.1,45.8],[4.2,45.4],[3.8,45.2],[3.2,45.3],[2.95,45.6],[3.0,45.95]]]}},{"name":"Fourme de Montbrison","lat":45.6,"lon":3.97,"country":"France","where":"Monts du Forez, Loire/Puy-de-Dôme","hint":"Forez highlands","desc":"Tall cow\'s-milk blue cylinder turned on rye-straw chéneaux during draining; slightly drier than Ambert.","image":"fourme_de_montbrison.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft","blue","natural-rind"],"ageing_min_days":32,"format":"tall cylinder, 1.5–2 kg, 13 cm × 19 cm","year_recognized":2002,"animal_breed":null,"vegetarian":null,"desc_long":"Fourme de Montbrison is the smaller, drier and faintly fruitier of the two PDO Fourme cheeses, named for the market town of Montbrison on the eastern slope of the Monts du Forez. Until 2002 it shared an AOC with its near-identical neighbour Fourme d\'Ambert; the two were then formally separated and Montbrison received a distinct designation that codifies the small but real differences in technique. Above all the wheels of Montbrison are drained on grooved wooden rye-straw cradles known as chéneaux, which leave a characteristic orange-tinted rind that the producers cultivate carefully through brushing. The cheese is aged a minimum of thirty-two days, with most wheels released a little later. EU PDO followed the French separation in 2010. The flavour is gently aromatic, drier and a touch more savoury than Ambert, with the blue presence in the paste announced by fine streaks rather than broad veining.","sources":[{"label":"INAO product page: Fourme de Montbrison","url":"https://www.inao.gouv.fr/produit/fourme-de-montbrison-22287"},{"label":"Wikipedia: Fourme de Montbrison","url":"https://en.wikipedia.org/wiki/Fourme_de_Montbrison"},{"label":"INAO AOC text: Fourme de Montbrison (archived)","url":"https://web.archive.org/web/20151104145000/http://www2.inao.gouv.fr/public/produits/showTexte.php?ID_TEXTE_CONSOLIDE=376"},{"label":"Syndicat: AOC Fourme d\'Ambert et de Montbrison (archived)","url":"https://web.archive.org/web/20070211095606/http://www.fourme-ambert.com/htm/aoc.htm"}],"pronunciation":{"ipa":"/fuʁm də mɔ̃.bʁi.zɔ̃/","respelling":"FOORM duh mohn-bree-ZOHN"},"region_polygon":{"type":"Polygon","coordinates":[[[3.3,45.95],[3.8,45.9],[4.2,45.7],[4.0,45.4],[3.5,45.5],[3.25,45.7],[3.3,45.95]]]}},{"name":"Laguiole","lat":44.69,"lon":2.86,"country":"France","where":"Aubrac plateau","hint":"Aubrac, Massif Central","desc":"Large pressed raw cow\'s-milk wheel from Aubrac and Simmental herds; the curd of aligot.","image":"laguiole_cheese.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","pressed"],"ageing_min_days":120,"format":"tall cylinder, 40–50 kg","year_recognized":1961,"animal_breed":["Aubrac","French Simmental"],"vegetarian":null,"desc_long":"Laguiole is a cousin of Cantal made on the high Aubrac plateau where Aveyron, Cantal and Lozère meet at eight hundred to fourteen hundred metres of altitude. The AOC requires raw milk from Aubrac and French Simmental cattle grazed on the herbal pastures of the plateau, set with rennet and pressed in the same two-stage technique that defines Cantal — pressed once, broken up after a rest, salted and pressed a second time into massive cylinders of forty to fifty kilograms. Maturation runs a minimum of four months in cool damp cellars and frequently extends to a year. French AOC came in 1961 and EU PDO followed in 1996. The flavour begins butter-sweet and mild and lengthens into a deep, lightly tangy, sometimes pleasantly bitter finish as the cheese ages. Laguiole is the cheese behind aligot, the famous stretchy potato-and-cheese dish of the high country, and the cooperative that protects it is also a local economic anchor.","sources":[{"label":"INAO product page: Laguiole","url":"https://www.inao.gouv.fr/produit/laguiole-16326"},{"label":"Wikipedia: Laguiole cheese","url":"https://en.wikipedia.org/wiki/Laguiole_cheese"}],"pronunciation":{"ipa":"/la.jɔl/","respelling":"lah-YOHL"},"region_polygon":{"type":"Polygon","coordinates":[[[2.4,44.95],[2.9,44.95],[3.3,44.85],[3.3,44.55],[2.9,44.35],[2.4,44.45],[2.25,44.7],[2.4,44.95]]]}},{"name":"Langres","lat":47.86,"lon":5.33,"country":"France","where":"Plateau de Langres, Champagne","hint":"Haute-Marne, Champagne","desc":"Washed-rind cow\'s-milk cylinder with a sunken top — the \'fontaine\' meant to be filled with Champagne.","image":"langres.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","washed-rind"],"ageing_min_days":35,"format":"small cylinder, ~180 g, concave top","year_recognized":1991,"animal_breed":null,"vegetarian":null,"desc_long":"Langres is a small washed-rind cow\'s-milk cheese from the Haute-Marne plateau in southern Champagne, immediately recognisable by the deliberate dent in its upper face — the fontaine — that producers leave by never turning the wheel during ripening. Local custom is to pour a little Marc de Champagne or eau de vie into the fontaine before serving. The cheese is made from raw milk, set, drained, and ripened a minimum of five weeks under a regimen of rind washing that brings the surface to its characteristic vivid orange-red. French AOC came in 1991 and EU PDO followed in 1996. Inside the rind sits a moist, slightly crumbly ivory paste with a softer flavour than the similar but more emphatic Époisses: forward and tangy without becoming heavy, with a lactic, lightly herbal core. Langres is one of the great everyday washed-rind cheeses of eastern France.","sources":[{"label":"INAO product page: Langres","url":"https://www.inao.gouv.fr/produit/langres-4202"},{"label":"Wikipedia: Langres cheese","url":"https://en.wikipedia.org/wiki/Langres_cheese"},{"label":"Légifrance: Décret n° 2009-112 (AOC Langres)","url":"https://www.legifrance.gouv.fr/loda/id/JORFTEXT000020094297"}],"pronunciation":{"ipa":"/lɑ̃ɡʁ/","respelling":"LAHN-gruh"},"region_polygon":{"type":"Polygon","coordinates":[[[5.0,48.3],[5.5,48.3],[5.7,48.1],[5.7,47.7],[5.3,47.6],[4.95,47.8],[4.9,48.1],[5.0,48.3]]]}},{"name":"Livarot","lat":48.94,"lon":0.09,"country":"France","where":"Pays d\'Auge, Normandy","hint":"Normandy, Pays d\'Auge","desc":"Pungent washed-rind cow\'s-milk cheese banded with five reed strips — nicknamed \'le colonel\'.","image":"livarot.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind"],"ageing_min_days":21,"format":"small cylinder, ~450 g, bound with reed strips","year_recognized":1975,"animal_breed":["Normande"],"vegetarian":null,"desc_long":"Livarot is one of the great washed-rind cheeses of the Pays d\'Auge in Normandy, named for a small town between Lisieux and Vimoutiers and traditionally made from the milk of Normande cattle whose lush pasture flavours come through in the paste. After moulding and salting, each wheel is wound about with three to five thin rings of dried reedmace — the laîches that visually echo the stripes on a French officer\'s uniform and give Livarot its nickname, le colonel. Maturation runs at least three weeks under repeated washings that flush the rind with a bacterial flora and turn it a rich orange-brown. French AOC came in 1975 and EU PDO followed in 1996. The cheese smells assertively of damp cellar and barnyard, but the paste is supple, creamy and surprisingly soft on the palate, with a peppery, lingering finish — at home with the cider and Calvados the region also produces in quantity.","sources":[{"label":"INAO product page: Livarot","url":"https://www.inao.gouv.fr/produit/livarot-4593"},{"label":"Wikipedia: Livarot cheese","url":"https://en.wikipedia.org/wiki/Livarot_cheese"}],"pronunciation":{"ipa":"/li.va.ʁo/","respelling":"lee-vah-ROH"},"region_polygon":{"type":"Polygon","coordinates":[[[-0.3,49.3],[0.0,49.3],[0.3,49.2],[0.3,48.95],[0.05,48.9],[-0.3,48.95],[-0.4,49.1],[-0.3,49.3]]]}},{"name":"Mâconnais","lat":46.3,"lon":4.83,"country":"France","where":"Mâconnais hills, Burgundy","hint":"Southern Burgundy","desc":"Tiny truncated-cone goat cheese ages from soft and white to firm and bluish-grey.","image":"maconnais.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["semi-hard","natural-rind"],"ageing_min_days":10,"format":"small truncated cone, 50–65 g, 4–5 cm × 3–4 cm","year_recognized":2005,"animal_breed":null,"vegetarian":null,"desc_long":"Mâconnais is a small raw goat\'s-milk cheese from the limestone-and-clay vine country of southern Burgundy, formed in a distinctive squat truncated cone that fits in the palm. The AOC requires raw whole milk drawn from local farmstead herds, set with rennet and a long lactic acidification, then ladled into small individual moulds. Each cheese weighs only about sixty grams and ripens at least ten days, sometimes much longer; the rind passes through chalk-white youth into a wrinkled grey-blue affiné and finally into a hard, dark brown finish that concentrates the goat character. French AOC came in 2005 and EU PDO followed in 2010. The cheese sits naturally next to the Chardonnay whites of the Mâconnais — Pouilly-Fuissé, Saint-Véran, Viré-Clessé — and is a familiar sight on Burgundian cheese plates and at the local Mâconnais markets that have sold it for generations.","sources":[{"label":"Wikipedia: Mâconnais cheese","url":"https://en.wikipedia.org/wiki/M%C3%A2connais_cheese"}],"pronunciation":{"ipa":"/ma.kɔ.nɛ/","respelling":"mah-koh-NAY"},"region_polygon":{"type":"Polygon","coordinates":[[[4.5,46.55],[4.95,46.55],[5.1,46.3],[4.95,46.0],[4.5,46.05],[4.4,46.3],[4.5,46.55]]]}},{"name":"Maroilles / Marolles","lat":50.04,"lon":3.96,"country":"France","where":"Thiérache (Aisne & Nord)","hint":"Northern France, near the Belgian border","desc":"Square washed-rind cow\'s-milk brick with brick-orange crust and ripe, robust aroma.","image":"maroilles.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind"],"ageing_min_days":35,"format":"square block; standard ~700 g; smaller Sorbais, Mignon and Quart sizes","year_recognized":1976,"animal_breed":null,"vegetarian":null,"desc_long":"Maroilles is one of the oldest and frankly most aromatic washed-rind cheeses of northern France, named for an abbey in the Thiérache where, according to tradition, monks first made the cheese around the year 962. The AOC covers the Aisne and Nord departments and recognises four wheel sizes — Standard, Sorbais, Mignon and Quart — that differ only in scale and minimum ageing, all sharing the recipe\'s defining square cornered profile. After moulding and salting, wheels are washed regularly with brine over a minimum five-week affinage; the rind turns first yellow and then a bright moist red-orange, while the paste inside softens to a pale ivory. French AOC came in 1976 and EU PDO followed in 1996. The aroma is famously powerful but the flavour is softer than the smell suggests — milky, savoury and warmly spiced. Maroilles is also the cheese behind two great northern French dishes: flamiche au maroilles, a hot tart on the cheese board, and rabbit braised in beer with the cheese melted in at the finish.","sources":[{"label":"INAO product page: Maroilles","url":"https://www.inao.gouv.fr/produit/maroilles-ou-marolles-13200"},{"label":"Wikipedia: Maroilles cheese","url":"https://en.wikipedia.org/wiki/Maroilles_cheese"},{"label":"INAO AOC text: Maroilles ou Marolles (archived)","url":"https://web.archive.org/web/20151104153241/http://www2.inao.gouv.fr/public/produits/showTexte.php?ID_TEXTE_CONSOLIDE=447"}],"pronunciation":{"ipa":"/ma.ʁwal/","respelling":"mah-RWAHL"},"region_polygon":{"type":"Polygon","coordinates":[[[3.5,50.4],[4.0,50.3],[4.2,50.0],[4.3,49.75],[3.95,49.65],[3.5,49.7],[3.4,50.05],[3.5,50.4]]]}},{"name":"Mont d\'Or / Vacherin du Haut-Doubs","lat":46.78,"lon":6.31,"country":"France","where":"Haut-Doubs, Jura","hint":"Jura, on the Swiss border","desc":"Winter-only soft washed-rind cow\'s-milk cheese ringed by a spruce-bark belt; spoonably ripe.","image":"mont_dor_vacherin_du_haut_doubs.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","washed-rind"],"ageing_min_days":21,"format":"round box in spruce wood, ~450 g – 3 kg","year_recognized":1981,"animal_breed":["Montbéliarde"],"vegetarian":null,"desc_long":"Mont d\'Or, also known under the AOC name Vacherin du Haut-Doubs, is a winter-only soft cow\'s-milk cheese from the upper Doubs valleys on the French side of the Jura, made between mid-August and mid-March from the raw milk of Montbéliarde cattle. The defining feature is the ribbon of Norway spruce cambium that girdles each wheel, lending the cheese both structural support and a distinct resinous fragrance. After moulding the wheels are washed regularly, aged a minimum of three weeks in cool damp cellars and packaged in their own spruce-wood box. French AOC came in 1981 and EU PDO followed in 1996. At peak ripeness the rind is supple and faintly tacky and the paste turns runny enough to scoop with a spoon; warmed in its box with a splash of white wine and a clove of garlic it becomes the traditional Boîte chaude, served like a fondue with potatoes and cured meats through the cold months of the upper Jura.","sources":[{"label":"Wikipedia: Vacherin Mont d\'Or","url":"https://en.wikipedia.org/wiki/Vacherin_Mont_d%27Or"},{"label":"INAO product page: Mont d\'Or / Vacherin du Haut-Doubs (archived)","url":"https://web.archive.org/web/20200821000924/https://www.inao.gouv.fr/produit/10687"}],"pronunciation":{"ipa":"/mɔ̃ dɔʁ/","respelling":"mohn DOR"},"region_polygon":{"type":"Polygon","coordinates":[[[5.95,46.95],[6.3,47.0],[6.55,46.85],[6.55,46.55],[6.2,46.5],[5.95,46.65],[5.95,46.95]]]}},{"name":"Morbier","lat":46.54,"lon":6.04,"country":"France","where":"Jura & Doubs","hint":"Jura mountains","desc":"Semi-soft cow\'s-milk cheese with a horizontal line of vegetable ash through the middle.","image":"morbier.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft","washed-rind"],"ageing_min_days":45,"format":"wheel, ~5–8 kg, 30–40 cm × 6–8 cm","year_recognized":2000,"animal_breed":["Montbéliarde","French Simmental"],"vegetarian":null,"desc_long":"Morbier is a semi-soft cow\'s-milk cheese from the Franche-Comté, immediately recognisable for the thin horizontal black line that runs through the middle of every wheel. The line is traditionally explained as a relic of farmhouse practice: cheesemakers who had only enough morning milk for half a wheel would coat that lower curd with a thin layer of soot to protect it overnight before laying the evening\'s curd on top — a memory that the modern PDO preserves as a layer of vegetable charcoal. The recipe uses raw or pasteurised cow\'s milk, set with rennet and aged a minimum of forty-five days on spruce boards, during which the rind is washed and turned regularly. French AOC came in 2000 and EU PDO followed in 2002. The paste is supple and ivory, with a mild aroma and a creamy, gently fruity flavour that hints at the makers\' shared origins with Comté — the two cheeses are often produced in the same fruitières.","sources":[{"label":"Wikipedia: Morbier","url":"https://en.wikipedia.org/wiki/Morbier_(cheese)"}],"pronunciation":{"ipa":"/mɔʁ.bje/","respelling":"mor-BYAY"},"region_polygon":{"type":"Polygon","coordinates":[[[5.4,47.4],[6.2,47.4],[6.95,47.0],[6.95,46.4],[6.1,46.05],[5.5,46.3],[5.3,47.0],[5.4,47.4]]]}},{"name":"Munster / Munster-Géromé","lat":48.04,"lon":7.13,"country":"France","where":"Vosges, between Alsace and Lorraine","hint":"Vosges mountains","desc":"Washed-rind cow\'s-milk cheese with brick-orange rind, often eaten with cumin and warm potatoes.","image":"munster.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","washed-rind"],"ageing_min_days":21,"format":"small cylinder 7–12 cm or large 13–19 cm, 150 g – 1.5 kg","year_recognized":1969,"animal_breed":["Vosgienne"],"vegetarian":null,"desc_long":"Munster — known as Munster-Géromé on the Lorraine side of the Vosges — is one of the great washed-rind cheeses of eastern France, produced in the high pastures of the Vosges from raw milk that long flowed in equal measure from the Alsace and the Lorraine sides of the mountains. The recipe is monastic: tradition assigns it to Irish-Scottish monks who settled in the Vosges valleys in the seventh century and called their cheese after their abbey, Münster. The recipe sets cow\'s milk with rennet, drains and salts the curd, and ages the wheels a minimum of three weeks under repeated washings of brine that turn the rind a sticky orange-red. French AOC came in 1969 and EU PDO followed in 1996. The smell is forthright, the paste creamy and gently spicy. Munster is traditionally served with whole cumin seeds scattered over the rind — a pairing the Alsatians take seriously enough that the cumin appears at the table in its own small bowl — and partnered with a glass of dry Gewürztraminer.","sources":[{"label":"INAO product page: Munster","url":"https://www.inao.gouv.fr/produit/munster-16348"},{"label":"Wikipedia: Munster cheese","url":"https://en.wikipedia.org/wiki/Munster_cheese"}],"pronunciation":{"ipa":"/mœ̃s.tɛʁ/","respelling":"MUN-stair"},"region_polygon":{"type":"Polygon","coordinates":[[[5.5,48.8],[6.5,49.2],[7.4,49.05],[7.65,48.2],[7.1,47.4],[6.4,47.4],[5.85,47.8],[5.6,48.5],[5.5,48.8]]]}},{"name":"Neufchâtel","lat":49.74,"lon":1.44,"country":"France","where":"Pays de Bray, Normandy","hint":"Upper Normandy","desc":"Soft cow\'s-milk cheese famously moulded into a heart; bloomy rind, mushroomy paste.","image":"neufchatel.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","bloomy-rind"],"ageing_min_days":10,"format":"heart, square, brick, plug or double-plug; 100–600 g","year_recognized":1969,"animal_breed":null,"vegetarian":null,"desc_long":"Neufchâtel is one of the oldest soft cheeses of France, made for centuries in the Pays de Bray on the Normandy-Picardy border and protected since 1969 under the AOC that bears the name of the town of Neufchâtel-en-Bray. The AOC recognises a range of formats — square, brick, plug, double-plug and famously the heart — all from the same recipe of cow\'s milk gently set, drained and ladled into the small moulds before ripening at least ten days under a Penicillium camemberti bloom. The local heart shape is no recent flourish: tradition holds that local women shaped the cheese into hearts and gave them to English soldiers during the Hundred Years\' War, an origin story that the village happily nurtures. Finished wheels carry a thin chalky-white rind over a moist, slightly grainy paste with a saltier, sharper character than Camembert. EU PDO recognition followed the French AOC in 1996.","sources":[{"label":"INAO product page: Neufchâtel","url":"https://www.inao.gouv.fr/produit/neufchatel-13169"},{"label":"Wikipedia: Neufchâtel cheese","url":"https://en.wikipedia.org/wiki/Neufch%C3%A2tel_cheese"}],"pronunciation":{"ipa":"/nø.ʃɑ.tɛl/","respelling":"nuh-shah-TEL"},"region_polygon":{"type":"Polygon","coordinates":[[[1.3,49.8],[1.75,49.85],[1.95,49.65],[1.8,49.35],[1.4,49.4],[1.2,49.6],[1.3,49.8]]]}},{"name":"Ossau-Iraty","lat":43.1,"lon":-0.6,"country":"France","where":"Béarn (Ossau valley) & French Basque Country","hint":"French Pyrenees","desc":"Hard sheep\'s-milk wheel from Manech and Basco-Béarnaise ewes; long-aged, nutty, faintly sweet.","image":"ossau_iraty.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","pressed","uncooked"],"ageing_min_days":80,"format":"wheel, 2–3 kg or 4–7 kg","year_recognized":1980,"animal_breed":["Manech à tête rousse","Manech à tête noire","Basco-Béarnaise"],"vegetarian":null,"desc_long":"Ossau-Iraty is the sheep\'s-milk cheese of the western French Pyrenees, jointly named for the Ossau valley in Béarn and the Iraty beech forest of the Basque side of the range. The AOC requires milk drawn from three traditional ewe breeds — Manech à tête rousse, Manech à tête noire and Basco-Béarnaise — set with rennet, gently heated and pressed into firm wheels in two formats: smaller wheels of two to three kilograms and the larger four to seven kilo Ossau format. Maturation runs a minimum of eighty days for the smaller wheels and four months for the larger. French AOC came in 1980 and EU PDO followed in 1996. The paste is ivory to pale gold and faintly dotted with eyes; the flavour is at once nutty and gently sweet with the warm savouriness of a long-aged sheep\'s-milk cheese. Pyrenean tradition serves Ossau-Iraty with cherry preserves (confiture de cerises noires) — a pairing borrowed from the Basque cherry-growing villages around Itxassou.","sources":[{"label":"INAO product page: Ossau-Iraty","url":"https://www.inao.gouv.fr/produit/ossau-iraty-13705"},{"label":"French Ministry of Agriculture: Cahier des charges AOC Ossau-Iraty (archived PDF)","url":"https://web.archive.org/web/20140630102436/http://agriculture.gouv.fr/IMG/pdf/CDC_AOC_Ossau-iraty.pdf"},{"label":"Wikipedia: Ossau-Iraty","url":"https://en.wikipedia.org/wiki/Ossau-Iraty"}],"pronunciation":{"ipa":"/o.so i.ʁa.ti/","respelling":"oh-SOH ee-rah-TEE"},"region_polygon":{"type":"Polygon","coordinates":[[[-1.85,43.35],[-1.45,43.35],[-0.75,43.2],[-0.45,42.95],[-0.55,42.8],[-1.1,42.85],[-1.55,42.95],[-1.85,43.15],[-1.85,43.35]]]}},{"name":"Pélardon","lat":44.1,"lon":3.7,"country":"France","where":"Cévennes, Languedoc","hint":"Cévennes mountains","desc":"Tiny raw goat\'s-milk disc with delicate nutty flavor and a fine bloomy rind.","image":"pélardon.jpeg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","bloomy-rind"],"ageing_min_days":11,"format":"small disc, ~60 g, 60–70 mm × 22–27 mm","year_recognized":2000,"animal_breed":null,"vegetarian":null,"desc_long":"Pélardon is a small goat\'s-milk cheese from the Cévennes, the limestone-and-schist ranges that rise sharply above Languedoc-Roussillon. The AOC covers a defined zone across the Gard, the Hérault, the Aude and parts of the Tarn and the Ardèche where small goat herds graze the herb-rich shrubland — the famous garrigue. Milk is set with rennet and a long lactic acidification, then ladled into individual moulds and ripened a minimum of eleven days under a developing Penicillium bloom. The finished disc is barely sixty grams and a thumb high; the rind is wrinkled chalky-white in young cheeses and turns ivory and faintly grey with longer maturation. French AOC came in 2000 and EU PDO followed in 2001. Pélardon\'s character is concentrated and gently goaty, with the warm herbal notes of the garrigue lingering through the finish — at home with the Languedoc reds and whites of the surrounding hills.","sources":[{"label":"INAO product page: Pélardon","url":"https://www.inao.gouv.fr/produit/pelardon-4532"},{"label":"Wikipedia: Pélardon","url":"https://en.wikipedia.org/wiki/P%C3%A9lardon"}],"pronunciation":{"ipa":"/pe.laʁ.dɔ̃/","respelling":"pay-lar-DOHN"},"region_polygon":{"type":"Polygon","coordinates":[[[2.2,44.6],[3.1,44.8],[3.95,44.65],[4.4,44.25],[4.2,43.65],[3.5,43.45],[2.7,43.55],[2.2,43.8],[2.15,44.2],[2.2,44.6]]]}},{"name":"Picodon","lat":44.5,"lon":4.6,"country":"France","where":"Drôme & Ardèche","hint":"Rhône valley uplands","desc":"Small goat\'s-milk disc that develops a wrinkled white rind and concentrated pepper bite with age.","image":"picodon.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["semi-hard","natural-rind"],"ageing_min_days":14,"format":"small disc, 40–100 g, 5–8 cm diameter","year_recognized":1983,"animal_breed":null,"vegetarian":null,"desc_long":"Picodon is a small flat raw goat\'s-milk cheese from the Drôme and the Ardèche, regions of southeast France whose sun-warmed hillsides and herb-thick vegetation support small farmstead goat herds. The AOC requires raw milk and at least fourteen days of drying in cool cellars; the finished disc is barely a hundred grams and recognisable at a glance from the wrinkled, almost bony rind that develops as the cheese loses moisture. A traditional variant, méthode Dieulefit, ages the wheels further by washing each one in water and then maturing them in earthenware jars for a month or more, drying them to compact little pucks of concentrated flavour. French AOC came in 1983 and EU PDO followed in 1996. Picodon\'s flavour is forthright and characterful — gently nutty when young, frankly peppery and goaty in the older wheels, with the warm herbal echoes that the local Côtes du Rhône whites and rosés naturally meet.","sources":[{"label":"Wikipedia: Picodon","url":"https://en.wikipedia.org/wiki/Picodon"}],"pronunciation":{"ipa":"/pi.kɔ.dɔ̃/","respelling":"pee-koh-DOHN"},"region_polygon":{"type":"Polygon","coordinates":[[[4.3,45.1],[4.85,45.1],[5.4,44.95],[5.5,44.35],[5.15,44.1],[4.55,44.2],[4.2,44.5],[4.15,44.85],[4.3,45.1]]]}},{"name":"Pont-l\'Évêque","lat":49.3,"lon":0.19,"country":"France","where":"Pays d\'Auge, Normandy","hint":"Normandy","desc":"Square washed-rind cow\'s-milk cheese — one of the oldest French cheeses still made, monastic origins.","image":"pont_leveque.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind"],"ageing_min_days":14,"format":"square, ~400 g, ~10 cm side","year_recognized":1972,"animal_breed":["Normande"],"vegetarian":null,"desc_long":"Pont-l\'Évêque is one of the oldest cheeses of Normandy and arguably the oldest still in production, attributed to Cistercian monks who settled west of Caen in the medieval Pays d\'Auge and protected today by AOC across that same green coastal hinterland. The cheese is moulded as a small square wheel and ripened a minimum of two weeks (most reach the market at six or more) under a regimen of washing that produces a thin coppery-orange to brown rind. The recipe uses cow\'s milk — pasteurised or raw, with the best wheels still made from Normande raw milk — set, drained, gently pressed and salted before ageing. French AOC came in 1972 and EU PDO followed in 1996. At ripeness the paste is the colour of straw butter and just supple enough to give under a knife, with a fragrant but mild flavour that is more cured-milk than barnyard, finished with a peppery cellar note — a cheese best served alongside cider, calvados and the apples the region also turns into all of those.","sources":[{"label":"INAO product page: Pont-l\'Évêque","url":"https://www.inao.gouv.fr/produit/pont-leveque-13477"},{"label":"Wikipedia: Pont-l\'Évêque cheese","url":"https://en.wikipedia.org/wiki/Pont-l%27%C3%89v%C3%AAque_cheese"}],"pronunciation":{"ipa":"/pɔ̃ le.vɛk/","respelling":"pohn lay-VEK"},"region_polygon":{"type":"Polygon","coordinates":[[[-0.4,49.45],[0.2,49.5],[0.4,49.3],[0.4,49.0],[0.0,48.9],[-0.4,49.0],[-0.4,49.45]]]}},{"name":"Pouligny-Saint-Pierre","lat":46.66,"lon":1.1,"country":"France","where":"Berry, Indre","hint":"Berry, central France","desc":"Pyramid-shaped goat\'s-milk cheese nicknamed the \'Eiffel Tower\' for its tall, square profile.","image":"pouligny_saint_pierre.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","natural-rind"],"ageing_min_days":14,"format":"tall truncated pyramid, ~250 g","year_recognized":1976,"animal_breed":null,"vegetarian":null,"desc_long":"Pouligny-Saint-Pierre is a small raw goat\'s-milk cheese from the Brenne country of the Indre, in central France, shaped into a striking tall pyramid that locals affectionately call the Eiffel Tower. The AOC requires raw whole milk from local goat herds, set with rennet and a long lactic acidification before ladling carefully into the pyramid moulds — a shape that drains slowly and concentrates the cheese\'s character toward the apex. Ripening runs a minimum of two weeks in cool damp cellars, with the rind passing through chalk-white youth into a dappled ivory and finally into a wrinkled grey-blue affiné. French AOC came in 1976 and EU PDO followed in 1996. The paste underneath is bright white and crumbles with the touch of a knife, balancing a clean lactic sourness against a salt-and-cream sweetness; the rind brings a soft hay-and-mushroom note that grows more emphatic with age. Pouligny-Saint-Pierre is one of the great French chèvres and pairs naturally with the Sancerre and Quincy whites of the upper Loire.","sources":[{"label":"INAO product page: Pouligny-Saint-Pierre","url":"https://www.inao.gouv.fr/produit/pouligny-saint-pierre-4583"},{"label":"Wikipedia: Pouligny-Saint-Pierre cheese","url":"https://en.wikipedia.org/wiki/Pouligny-Saint-Pierre_cheese"}],"pronunciation":{"ipa":"/pu.li.ɲi sɛ̃ pjɛʁ/","respelling":"poo-lee-NYEE san PYAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[0.8,46.85],[1.2,46.85],[1.55,46.7],[1.5,46.4],[1.1,46.3],[0.8,46.5],[0.8,46.85]]]}},{"name":"Reblochon / Reblochon de Savoie","lat":45.93,"lon":6.42,"country":"France","where":"Massif des Aravis, Haute-Savoie","hint":"Savoyard Alps","desc":"Soft washed-rind cow\'s-milk Alpine cheese — from the \'second milking\' farmers hid from the lord.","image":"reblochon_reblochon_de_savoie.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","washed-rind"],"ageing_min_days":21,"format":"small disc, ~450 g, 14 cm × 3–4 cm","year_recognized":1958,"animal_breed":["Abondance","Montbéliarde","Tarine"],"vegetarian":null,"desc_long":"Reblochon is the great washed-rind cow\'s-milk cheese of the Aravis mountains in Haute-Savoie, made from the raw milk of Abondance, Montbéliarde and Tarine cattle grazing high alpine pastures. The cheese\'s name preserves a medieval tax-dodge: the Savoyard verb reblocher meant to pinch a cow\'s udder a second time once the landowner\'s milk-counter had moved on, freeing up a richer, creamier remainder that farmers turned into a cheese kept off the books. The recipe sets whole milk with rennet, drains and salts the curd, and ages small flat discs of about four hundred and fifty grams under repeated washings of brine for a minimum of three weeks. French AOC came in 1958 and EU PDO followed in 1996. The rind ripens to a pale ivory-orange and the paste turns soft and almost spoonable at peak ripeness, with a nutty cooked-milk flavour that finishes with a gentle, even fruity sweetness. Reblochon is also the cheese behind tartiflette, the gratin of potatoes, lardons and onions that has become a winter staple across the French Alps.","sources":[{"label":"INAO product page: Reblochon","url":"https://www.inao.gouv.fr/produit/reblochon-ou-reblochon-de-savoie-16291"},{"label":"Wikipedia: Reblochon","url":"https://en.wikipedia.org/wiki/Reblochon"}],"pronunciation":{"ipa":"/ʁə.blɔ.ʃɔ̃/","respelling":"ruh-bloh-SHOHN"},"region_polygon":{"type":"Polygon","coordinates":[[[6.05,46.1],[6.5,46.15],[6.85,46.0],[6.9,45.75],[6.65,45.55],[6.2,45.55],[5.95,45.8],[6.05,46.1]]]}},{"name":"Rigotte de Condrieu","lat":45.46,"lon":4.77,"country":"France","where":"Pilat plateau, Rhône","hint":"South of Lyon, Pilat hills","desc":"Tiny raw goat\'s-milk button that dries to a wrinkled ivory crust; floral, slightly fruity.","image":"rigotte_de_condrieu.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","natural-rind"],"ageing_min_days":8,"format":"tiny button, ~30–45 g, ~4–4.5 cm diameter","year_recognized":2008,"animal_breed":null,"vegetarian":null,"desc_long":"Rigotte de Condrieu is a small raw goat\'s-milk cheese from the Pilat massif, the granite-and-schist plateau south of Lyon that has lent its name to Saint-Joseph red wine and the famous Condrieu Viognier. The AOC requires whole raw milk from local farmstead herds, lactic-set and ladled carefully into tiny moulds; the finished button weighs barely thirty grams and is a few centimetres across. Ripening runs at least eight days in cool cellars and frequently longer, with the rind moving from chalk-white through ivory to a wrinkled grey-blue. French AOC came in 2008 and EU PDO followed in 2013, late acknowledgement for a cheese already much sought after by Lyonnais bouchons and cheese shops. The paste is moist and bright and turns concentrated and lightly nutty with age, fitted naturally next to a glass of dry Viognier on a Rhône-valley table.","sources":[{"label":"Wikipedia: Rigotte de Condrieu","url":"https://en.wikipedia.org/wiki/Rigotte_de_Condrieu"},{"label":"Syndicat: Rigotte de Condrieu AOP (archived)","url":"https://web.archive.org/web/20141010014641/http://www.rigottedecondrieu.fr/aop/l-aop-un-gage-de-qualite.html"}],"pronunciation":{"ipa":"/ʁi.ɡɔt də kɔ̃.dʁi.jø/","respelling":"ree-GOT duh kohn-dree-UH"},"region_polygon":{"type":"Polygon","coordinates":[[[4.45,45.55],[4.8,45.55],[4.95,45.4],[4.85,45.2],[4.55,45.2],[4.4,45.4],[4.45,45.55]]]}},{"name":"Rocamadour","lat":44.8,"lon":1.62,"country":"France","where":"Quercy, Lot","hint":"Quercy, Lot valley","desc":"Small flat raw goat\'s-milk disc with delicate cream-and-hazelnut flavor.","image":"rocamadour.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","bloomy-rind"],"ageing_min_days":12,"format":"tiny disc, ~35 g, 4–5 cm × 1–1.5 cm","year_recognized":1996,"animal_breed":["Alpine","Saanen"],"vegetarian":null,"desc_long":"Rocamadour is a tiny raw goat\'s-milk cheese from the limestone Quercy and Périgord, named for the cliff-clinging village in the Lot whose pilgrimage church has drawn visitors since the Middle Ages. The AOC requires whole raw milk from Alpine and Saanen goats grazed on the local causse, set with rennet, drained carefully into shallow moulds and ripened a minimum of twelve days. Each finished disc weighs barely thirty-five grams — a single bite — with a thin pale rind that turns gently ivory and gently wrinkled with longer ageing. French AOC came in 1996 and EU PDO followed. Rocamadour is sold young, when its character is delicately milky and softly hazelnut-sweet, or briefly aged into a firmer, faintly piquant disc; older wheels turn assertive and concentrated. The cheese partners naturally with the Cahors reds of the lower Lot and with summer fruit on a Quercy table.","sources":[{"label":"INAO product page: Rocamadour","url":"https://www.inao.gouv.fr/produit/rocamadour-13352"},{"label":"Wikipedia: Rocamadour (cheese)","url":"https://en.wikipedia.org/wiki/Rocamadour_(cheese)"}],"pronunciation":{"ipa":"/ʁɔ.ka.ma.duʁ/","respelling":"roh-kah-mah-DOOR"},"region_polygon":{"type":"Polygon","coordinates":[[[0.8,45.1],[1.6,45.2],[2.1,45.1],[2.2,44.5],[1.9,44.1],[1.1,44.2],[0.65,44.4],[0.7,44.85],[0.8,45.1]]]}},{"name":"Roquefort","lat":43.98,"lon":2.98,"country":"France","where":"Aveyron — Combalou caves","hint":"Aveyron, southern Massif Central","desc":"Sheep\'s-milk blue aged in the natural limestone caves of Combalou where Penicillium roqueforti grows on the walls.","image":"roquefort.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-soft","blue","natural-rind"],"ageing_min_days":90,"format":"cylinder, ~2.5–3 kg, ~10 cm thick","year_recognized":1925,"animal_breed":["Lacaune"],"vegetarian":null,"desc_long":"Roquefort is a raw sheep\'s-milk blue cheese, made only from the milk of Lacaune ewes and aged exclusively in the limestone caves of Combalou at Roquefort-sur-Soulzon. The defining feature of the production is the network of natural fissures called fleurines, cool damp drafts that ventilate the caves and propagate Penicillium roqueforti throughout the paste. After curd-setting and seeding with the mould, wheels are pierced with needles to admit air and develop the characteristic blue marbling against a moist, crumbly ivory paste. France granted the cheese its first appellation d\'origine in 1925, building on a royal monopoly Charles VI had recognised for the village as early as 1411. The flavour is pungent and salty with a sharp, mineral finish, and Roquefort is regarded as the senior member of France\'s blue cheese tradition.","sources":[{"label":"INAO product page: Roquefort","url":"https://www.inao.gouv.fr/produit/roquefort-24302"},{"label":"Wikipedia: Roquefort","url":"https://en.wikipedia.org/wiki/Roquefort"},{"label":"INAO AOC text: Roquefort (archived)","url":"https://web.archive.org/web/20170306193150/http://www2.inao.gouv.fr/public/produits/showTexte.php?ID_TEXTE_CONSOLIDE=791"}],"pronunciation":{"ipa":"/ʁɔk.fɔʁ/","respelling":"rohk-FOR"},"region_polygon":{"type":"Polygon","coordinates":[[[2.4,44.4],[3.2,44.4],[3.5,44.1],[3.4,43.7],[2.8,43.6],[2.4,43.8],[2.2,44.1],[2.4,44.4]]]}},{"name":"Sainte-Maure de Touraine","lat":47.11,"lon":0.62,"country":"France","where":"Touraine, Loire","hint":"Loire valley","desc":"Goat\'s-milk log dusted with ash and pierced lengthwise by a piece of rye straw for structure.","image":"sainte_maure_de_touraine.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","ash-coated","natural-rind"],"ageing_min_days":10,"format":"log, ~250 g, 16–17 cm long","year_recognized":1990,"animal_breed":null,"vegetarian":null,"desc_long":"Sainte-Maure de Touraine is a small raw goat\'s-milk log from the Loire valley, made across the Indre-et-Loire and parts of three neighbouring departments and named for the village of Sainte-Maure where the cheese has been produced since the early Middle Ages. The AOC mandates whole raw milk, set with a long lactic acidification and ladled into the elongated log mould; the surface is dusted with charcoal that gives the rind its characteristic grey-blue colour, and a length of rye straw is pushed through the centre, lending structure to the soft paste and carrying the AOC stamp. Ripening runs a minimum of ten days; older wheels lose moisture and dry into a denser, more concentrated cheese. French AOC came in 1990 and EU PDO followed in 1996. The cheese has a moist, faintly chalky paste under the ash, and a clean lactic goat flavour that lengthens into something deeper and nuttier with longer maturation — the everyday chèvre of the Loire\'s white wines.","sources":[{"label":"INAO product page: Sainte-Maure de Touraine","url":"https://www.inao.gouv.fr/produit/sainte-maure-de-touraine-16988"},{"label":"Wikipedia: Sainte-Maure de Touraine","url":"https://en.wikipedia.org/wiki/Sainte-Maure_de_Touraine"},{"label":"CNIEL: AOC Sainte-Maure de Touraine (archived)","url":"https://web.archive.org/web/20020220125844/http://www.cniel.com/Prodlait/AOC/Tourai.html"}],"pronunciation":{"ipa":"/sɛ̃t moʁ də tu.ʁɛn/","respelling":"sant MOR duh too-REN"},"region_polygon":{"type":"Polygon","coordinates":[[[0.1,47.55],[1.0,47.7],[1.85,47.5],[1.75,47.0],[1.3,46.65],[0.55,46.65],[0.05,47.0],[0.1,47.55]]]}},{"name":"Saint-Marcellin","lat":45.16,"lon":5.32,"country":"France","where":"Dauphiné — Isère/Drôme","hint":"Northern Dauphiné","desc":"Small soft cow\'s-milk button that runs at peak ripeness; sold in tiny ceramic crocks.","image":"saint_marcellin.webp","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["soft","natural-rind"],"ageing_min_days":10,"format":"small disc, ~80 g, ~7 cm diameter","year_recognized":2013,"animal_breed":null,"vegetarian":null,"desc_long":"Saint-Marcellin is a small soft cow\'s-milk cheese from the Dauphiné country south of Lyon, named for a market town in the Isère and historically a mixed goat-and-cow cheese before settling into its modern all-cow form in the late twentieth century. The PGI covers the Isère and parts of the Drôme and the Savoie. Curd is gently set, ladled into small individual moulds and ripened at least ten days, with the rind passing through chalk-white youth into a wrinkled grey-blue affiné. EU PGI recognition came in 2013, late for a cheese already firmly established in Lyon\'s bouchons. Saint-Marcellin is at its best when it has begun to turn — the paste soft and almost spoonable, the flavour lactic, faintly mushroomy, and gently piquant. Many cheese shops sell the ripest examples in small ceramic crocks so the cheese can be eaten with a spoon, often warmed briefly in the oven and partnered with a glass of Côtes du Rhône.","sources":[{"label":"Wikipedia: Saint-Marcellin","url":"https://en.wikipedia.org/wiki/Saint-Marcellin"},{"label":"French Ministry of Agriculture: Le Saint-Marcellin IGP","url":"https://agriculture.gouv.fr/le-saint-marcellin-igp-fromage-cremeux-du-dauphine"}],"pronunciation":{"ipa":"/sɛ̃ maʁ.sɛ.lɛ̃/","respelling":"san mar-suh-LAN"},"region_polygon":{"type":"Polygon","coordinates":[[[4.95,45.5],[5.45,45.55],[5.85,45.45],[5.95,45.1],[5.65,44.85],[5.2,44.9],[4.95,45.25],[4.95,45.5]]]}},{"name":"Saint-Nectaire","lat":45.5,"lon":2.95,"country":"France","where":"Mont-Dore, Auvergne","hint":"Auvergne, volcanic uplands","desc":"Pressed cow\'s-milk cheese aged on rye straw; supple, beige-grey rind with mushroomy notes.","image":"saint_nectaire.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft","washed-rind"],"ageing_min_days":28,"format":"flat wheel, ~1.7 kg, 20–24 cm × 3–5 cm","year_recognized":1955,"animal_breed":["Salers","Holstein","Montbéliarde"],"vegetarian":null,"desc_long":"Saint-Nectaire is a soft pressed cow\'s-milk cheese from the volcanic Mont-Dore country of the Auvergne, named for the village of Saint-Nectaire and produced across some seventy villages of the Puy-de-Dôme and Cantal. The cheese is moulded as a relatively flat wheel of about a kilogram and a half, pressed lightly and aged a minimum of twenty-eight days on traditional rye-straw mats in cool damp cellars. As the rind ripens, regular brushing and turning encourage a layered grey-pink-orange surface that develops yeasts, moulds and bacteria together — the cellar microflora that give Saint-Nectaire its character. French AOC came in 1955, among the very first French PDOs, and EU PDO followed in 1996. Under the rind sits a supple, cream-coloured paste with a hazelnut sweetness and a long savoury finish that hints at mushroom, hay and the volcanic uplands the cheese comes from. Saint-Nectaire is a fixture of Auvergnat cheese boards and an excellent melting cheese in winter cooking.","sources":[{"label":"INAO product page: Saint-Nectaire","url":"https://www.inao.gouv.fr/produit/saint-nectaire-24296"},{"label":"Wikipedia: Saint-Nectaire","url":"https://en.wikipedia.org/wiki/Saint-Nectaire"}],"pronunciation":{"ipa":"/sɛ̃ nɛk.tɛʁ/","respelling":"san nek-TAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[2.6,45.8],[3.1,45.85],[3.35,45.7],[3.3,45.3],[2.9,45.2],[2.55,45.4],[2.45,45.65],[2.6,45.8]]]}},{"name":"Salers","lat":45.13,"lon":2.49,"country":"France","where":"Cantal — high pastures","hint":"Cantal, summer-only mountain cheese","desc":"Large summer-only cow\'s-milk wheel made in wooden gerle from Salers-breed milk on alpine pasture.","image":"salers.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","pressed"],"ageing_min_days":90,"format":"tall cylinder, ~40 kg","year_recognized":1961,"animal_breed":["Salers"],"vegetarian":null,"desc_long":"Salers is the high-summer pasture cheese of the Cantal, made only between mid-April and mid-November when the herds are on the alpine pastures of the Massif Central and produced by farmer-cheesemakers in stone burons rather than in dairy cooperatives. The AOC requires raw milk from Salers cattle — the rust-red mountain breed that gives the cheese its name — set in the traditional wooden gerle whose ambient flora seed the curd with a uniquely place-bound microbiome. The curd is twice-pressed in the cantal style, salted in stages and aged a minimum of three months on wooden boards in cool cellars; many wheels go much longer, sometimes to three years or more. French AOC came in 1961 and EU PDO followed in 1996. The forty-kilogram wheels are the most farmstead of any AOC French cheese — fewer than a hundred farmers still make it under the strict spec — and the flavour rewards the rigour: dense and savoury, complex, with floral and grassy notes lifted out of the high herbal pasture.","sources":[{"label":"INAO product page: Salers","url":"https://www.inao.gouv.fr/produit/salers-16449"},{"label":"Wikipedia: Salers cheese","url":"https://en.wikipedia.org/wiki/Salers_cheese"}],"pronunciation":{"ipa":"/sa.lɛʁ/","respelling":"sah-LAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[2.0,45.4],[2.7,45.6],[3.3,45.5],[3.4,45.1],[3.05,44.85],[2.5,44.85],[2.05,45.0],[2.0,45.4]]]}},{"name":"Selles-sur-Cher","lat":47.34,"lon":1.55,"country":"France","where":"Loire — Sologne","hint":"Berry-Loire borderland","desc":"Goat\'s-milk disc dusted with salted ash; firm chalky paste with mild nutty tang.","image":"selles_sur_cher.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","ash-coated","natural-rind"],"ageing_min_days":10,"format":"truncated cone, ~150 g, 8 cm base × 7 cm top × 2–3 cm tall","year_recognized":1975,"animal_breed":null,"vegetarian":null,"desc_long":"Selles-sur-Cher is a small raw goat\'s-milk cheese from the Sologne and the southern Cher valley in central France, named for the market town where the cheeses were once sold along the river. The AOC requires whole raw milk and a long lactic acidification, ladled gently into the characteristic truncated-cone moulds. As the wheels drain they are dusted with vegetable charcoal that gives the rind its dark grey-blue colour and slows the growth of unwanted moulds; after a minimum of ten days of ripening the rind has firmed into a fine wrinkled crust over a moist, white, faintly chalky paste. French AOC came in 1975 and EU PDO followed in 1996. Selles-sur-Cher has a clean lactic flavour with a salt-and-nut sweetness underneath, and the ash-coated rind adds a moss-and-mushroom note that grows more emphatic with age. The cheese pairs naturally with the dry whites of the upper Loire, especially Sauvignon Blanc from Quincy and Reuilly.","sources":[{"label":"Wikipedia: Selles-sur-Cher cheese","url":"https://en.wikipedia.org/wiki/Selles-sur-Cher_cheese"}],"pronunciation":{"ipa":"/sɛl syʁ ʃɛʁ/","respelling":"sel soor SHAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[1.1,47.5],[1.85,47.55],[2.3,47.4],[2.3,46.95],[1.8,46.85],[1.2,47.0],[1.05,47.2],[1.1,47.5]]]}},{"name":"Soumaintrain","lat":47.92,"lon":3.86,"country":"France","where":"Yonne & Aube, Burgundy","hint":"Northern Burgundy","desc":"Soft washed-rind cow\'s-milk cheese with orange crust and milder character than Époisses.","image":"soumaintrain.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind"],"ageing_min_days":21,"format":"small disc, ~180–600 g","year_recognized":2016,"animal_breed":null,"vegetarian":null,"desc_long":"Soumaintrain is a small washed-rind cow\'s-milk cheese from the Pays d\'Othe and the Tonnerrois, in the northern Burgundian countryside of the Yonne and the Aube. The cheese is a close relative of Époisses — they share the same lineage of Burgundian monastic recipes — but Soumaintrain has remained the smaller, gentler cousin: discs of two or three hundred grams whose pale yellow paste sits under a sticky orange rind built up through weekly brine washings. The recipe sets cow\'s milk with rennet, drains and lightly salts the curd, and ripens the wheels at least three weeks in cool damp cellars. EU PGI recognition came in 2016. The aroma is unmistakably washed-rind — warm, ripe, lightly farmyardy — but the flavour is softer than Époisses: a creamy, lactic core with a savoury edge near the rind, suited to a glass of dry Chablis or the unaoaked Aligotés of the surrounding country.","sources":[{"label":"Wikipedia: Soumaintrain region article","url":"https://en.wikipedia.org/wiki/Soumaintrain"}],"pronunciation":{"ipa":"/su.mɛ̃.tʁɛ̃/","respelling":"soo-man-TRAN"},"region_polygon":{"type":"Polygon","coordinates":[[[3.2,48.3],[3.8,48.3],[4.3,48.1],[4.3,47.6],[3.65,47.55],[3.1,47.8],[3.0,48.1],[3.2,48.3]]]}},{"name":"Tome des Bauges","lat":45.66,"lon":6.2,"country":"France","where":"Massif des Bauges, Savoie","hint":"Bauges massif, Savoyard pre-Alps","desc":"Semi-firm cow\'s-milk wheel with grey-pink rind; rustic Alpine table cheese.","image":"tome_des_bauges.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","pressed","alpine"],"ageing_min_days":35,"format":"wheel, ~1.2 kg, ~17 cm × 5 cm","year_recognized":2002,"animal_breed":["Abondance","Montbéliarde","Tarine"],"vegetarian":null,"desc_long":"Tome des Bauges is a semi-hard cow\'s-milk cheese from the Bauges massif, the limestone prealpine block tucked between Annecy, Aix-les-Bains and Chambéry. The AOC requires raw milk from Abondance, Montbéliarde and Tarine cattle grazed within the massif, set with rennet and lightly pressed into modest wheels of just over a kilogram. Maturation runs at least five weeks in cool cellars, where the wheels develop a thick grey-brown rind and a pale ivory paste shot with small irregular eyes. French AOC came in 2002 and EU PDO followed in 2007. The aroma carries the warm hazelnut-and-hay character of long-aged farmstead milk, and the flavour balances a clean lactic core against a faintly bitter herbal finish — recognisably a cousin of the larger and longer-aged Beaufort, but smaller, plainer and more everyday, the way Bauges farmers have made it for generations.","sources":[{"label":"Wikipedia: Tome des Bauges","url":"https://en.wikipedia.org/wiki/Tome_des_Bauges"}],"pronunciation":{"ipa":"/tɔm de boʒ/","respelling":"tohm day BOHZH"},"region_polygon":{"type":"Polygon","coordinates":[[[5.95,45.9],[6.3,45.95],[6.45,45.85],[6.4,45.6],[6.1,45.55],[5.9,45.7],[5.95,45.9]]]}},{"name":"Tomme de Savoie","lat":45.5,"lon":6.4,"country":"France","where":"Savoie","hint":"Savoyard Alps","desc":"Pressed semi-firm cow\'s-milk Alpine cheese with mottled grey rind; low-fat, mild.","image":"tomme_de_savoie.webp","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed","alpine"],"ageing_min_days":30,"format":"wheel, 1–2 kg, ~18 cm diameter × 5–8 cm","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Tomme de Savoie is the everyday alpine pressed cow\'s-milk cheese of the French Alps, made historically from the milk left over after the cream was lifted off for butter or richer cheeses — which is why its fat content sits at the low end of the alpine range. The PGI covers production across the Savoie and Haute-Savoie and accepts both raw and pasteurised milk, gently set, drained, pressed and aged on wooden boards for at least a month. The rind ripens to a mottled grey-brown crust streaked with white and golden moulds; underneath sits a pale, supple paste with small irregular eyes. EU PGI recognition came in 1996. The flavour is the quiet, faintly milky-grassy character of an honest alpine table cheese, with the rind adding a mushroomy depth as the cheese ages — at home next to charcuterie and dark bread on a Savoyard sandwich, or melted onto baked potatoes.","sources":[{"label":"INAO product page: Tomme de Savoie","url":"https://www.inao.gouv.fr/produit/tomme-de-savoie-16327"},{"label":"Wikipedia: Tomme de Savoie","url":"https://en.wikipedia.org/wiki/Tomme_de_Savoie"}],"pronunciation":{"ipa":"/tɔm də sa.vwa/","respelling":"TOHM duh sah-VWAH"},"region_polygon":{"type":"Polygon","coordinates":[[[5.7,46.3],[6.4,46.4],[7.05,46.3],[7.1,45.5],[6.4,45.1],[5.85,45.2],[5.65,45.8],[5.7,46.3]]]}},{"name":"Tomme des Pyrénées","lat":43.0,"lon":0.5,"country":"France","where":"French Pyrenees","hint":"French Pyrenees","desc":"Pressed cow\'s-milk wheel with characteristic black wax rind; mild, supple paste.","image":"tomme_des_pyrenees.jpg","name_protections":["PGI"],"milk_types":["cow","sheep","goat"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":21,"format":"wheel, 450 g – 5.5 kg, black or gold wax rind","year_recognized":2021,"animal_breed":null,"vegetarian":null,"desc_long":"Tomme des Pyrénées is the broader French Pyrenean pressed cheese, made variously from cow, sheep or goat milk and produced across what was historically Aquitaine and Midi-Pyrénées. The PGI distinguishes two principal types: a black-waxed cheese ripened a minimum of three weeks, the most familiar everyday Pyrenean tomme on supermarket and épicerie shelves; and a gold-coated longer-aged variant matured at least six weeks. Both share the same general profile — a supple, slightly elastic paste that is faintly straw-yellow and gently salty under a thin wax rind. EU PGI recognition came in 2021 after a long campaign by producers on the French side of the range. Tomme des Pyrénées is mild, milky and approachable, an honest table cheese rather than an affineur\'s masterpiece — at home in sandwiches, melted on raclette nights or grated into the local garbure soups of Béarn and the Pays Basque.","sources":[{"label":"Wikipedia: Tomme des Pyrénées","url":"https://en.wikipedia.org/wiki/Tomme_des_Pyr%C3%A9n%C3%A9es"}],"pronunciation":{"ipa":"/tɔm de pi.ʁe.ne/","respelling":"TOHM day pee-ray-NAY"},"region_polygon":{"type":"Polygon","coordinates":[[[-1.85,43.3],[-0.5,43.2],[1.0,43.1],[2.2,42.85],[2.0,42.6],[0.5,42.7],[-0.8,42.85],[-1.85,43.05],[-1.85,43.3]]]}},{"name":"Valençay","lat":47.16,"lon":1.56,"country":"France","where":"Berry — Indre/Loir-et-Cher","hint":"Berry, central France","desc":"Goat\'s-milk truncated pyramid dusted with ash — legend says Napoléon sliced its top after Marengo.","image":"valencay.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","ash-coated","natural-rind"],"ageing_min_days":11,"format":"truncated pyramid, ~200–250 g, ~7 cm tall","year_recognized":1998,"animal_breed":null,"vegetarian":null,"desc_long":"Valençay is one of the great raw goat\'s-milk cheeses of the Berry, recognisable at any cheese counter for the truncated pyramid shape that distinguishes it from the cones, logs and discs of its Loire neighbours. Local legend attributes the flat top to Napoleon, said to have angrily struck the apex off a pyramid Valençay on his return from the failed Egyptian campaign; in fact the shape is older. The AOC requires whole raw milk from local farmstead herds, lactic-set, ladled into the pyramid moulds and dusted with vegetable charcoal that gives the rind its dark grey-blue colour. Ripening runs a minimum of eleven days in cool cellars. French AOC came in 1998 and EU PDO followed in 2004. A young Valençay shows a clean lactic citrus tang under a chalk-white paste; a more aged wheel turns nuttier, with the wrinkled ashed rind contributing a moss-and-mushroom depth. Valençay is also unusual in sharing its AOC name with the local Loire wine of the same village — the rare French pair of cheese and wine both protected under the same designation.","sources":[{"label":"INAO product page: Valençay","url":"https://www.inao.gouv.fr/produit/valencay-13170"},{"label":"Wikipedia: Valençay cheese","url":"https://en.wikipedia.org/wiki/Valen%C3%A7ay_cheese"}],"pronunciation":{"ipa":"/va.lɑ̃.sɛ/","respelling":"vah-lahn-SAY"},"region_polygon":{"type":"Polygon","coordinates":[[[1.0,47.45],[1.7,47.5],[2.2,47.35],[2.1,46.85],[1.5,46.75],[1.0,47.0],[1.0,47.45]]]}},{"name":"Allgäuer Bergkäse","lat":47.55,"lon":10.3,"country":"Germany","where":"Allgäu Alps, Bavaria","hint":"Bavarian Alps","desc":"Hard cooked-curd cow\'s-milk wheel made in mountain dairies; nutty and lightly fruity.","image":"allgäuer_bergkase.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":120,"format":"wheel, ~15–50 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Allgäuer Bergkäse is the Bavarian Alpine cheese made from raw cow\'s milk in the Allgäu, the western corner of Bavaria where the foothills rise toward the Austrian and Swiss border. The PDO requires untreated silage-free milk, brought to no more than 40 °C before renneting, then cooked and pressed into large wheel-shaped rounds of fifteen to fifty kilograms that are matured rind-down on wooden boards for a minimum of four months. The dry matter content is at least 62 % and the fat-in-dry-matter rests between 45 % and 49 %. EU PDO came in 1997, formalising a mountain dairy tradition that for centuries was practiced in seasonal alpine huts (Sennereien) and now persists in small village cheesemakers across the Allgäu valleys. Long ageing produces a firm, ivory paste with sparse small eyes, an aroma of warm hay and roast hazelnut, and a flavour that is full, savoury, and gently spicy — closer in spirit to a young Comté than to industrial Emmentaler.","sources":[{"label":"EU Agri: Allgäuer Bergkäse PDO","url":"https://agriculture.ec.europa.eu/farming/geographical-indications-and-quality-schemes/geographical-indications-food-and-drink/allgauer-bergkase-pdo_en"},{"label":"Qualigeo: Allgäuer Bergkäse PDO","url":"https://www.qualigeo.eu/en/product/allgauer-bergkase-pdo/"},{"label":"Wikipedia: Bergkäse","url":"https://en.wikipedia.org/wiki/Bergkäse"}],"pronunciation":{"ipa":"/ˈalɡɔɪɐ ˈbɛʁkˌkɛːzə/","respelling":"AHL-goy-er BAIRK-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.85,47.9],[10.3,47.95],[10.7,47.85],[10.75,47.55],[10.45,47.4],[10.0,47.45],[9.85,47.65],[9.85,47.9]]]}},{"name":"Allgäuer Emmentaler","lat":47.55,"lon":10.3,"country":"Germany","where":"Allgäu, Bavaria","hint":"Bavarian Alps","desc":"German Emmental with hazelnut-to-cherry-sized eyes; sweet, mild cow\'s-milk classic.","image":"allgäuer_emmentaler.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed","eyed"],"ageing_min_days":90,"format":"wheel, ~75–100 kg","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Allgäuer Emmentaler is the German counterpart of Swiss Emmental, produced from raw cow\'s milk in the Bavarian Allgäu and protected under PDO since 1997. The spec restricts production to milk from the defined area, requires a maximum heating of about 40 °C before adding natural rennet, and calls for the giant wheels of up to roughly a hundred kilograms to mature at least three months — including a warm phase at around 20 °C, which encourages the propionic-acid bacteria responsible for Emmental\'s characteristic walnut-sized eyes and faintly sweet, nutty flavour. The PDO is administered alongside Allgäuer Bergkäse by the same producer dairies, and reflects the introduction of Swiss-style cheesemaking into the Allgäu in the nineteenth century. Wheels show the deep golden rind and propionic-eyed paste of the classic Emmental family; the flavour is mellow, faintly sweet with mature pasture and hazelnut notes, and the cheese melts beautifully into fondue or onto pretzels.","sources":[{"label":"Qualigeo: Allgäuer Emmentaler PDO","url":"https://www.qualigeo.eu/en/product/allgauer-emmentaler-pdo/"},{"label":"EU DOOR registry: Allgäuer Emmentaler (archived)","url":"https://web.archive.org/web/20160604190409/http://ec.europa.eu/agriculture/quality/door/registeredName.html?denominationId=80"},{"label":"Wikipedia: Emmental cheese","url":"https://en.wikipedia.org/wiki/Emmental_cheese"}],"pronunciation":{"ipa":"/ˈalɡɔɪɐ ˈɛmənˌtaːlɐ/","respelling":"AHL-goy-er EM-en-tah-ler"},"region_polygon":{"type":"Polygon","coordinates":[[[9.85,47.9],[10.3,47.95],[10.7,47.85],[10.75,47.55],[10.45,47.4],[10.0,47.45],[9.85,47.65],[9.85,47.9]]]}},{"name":"Altenburger Ziegenkäse","lat":50.99,"lon":12.43,"country":"Germany","where":"Thuringia & Saxony","hint":"Central Germany","desc":"Soft cheese from cow & goat milk with caraway seed; small wheels with bloomy rind.","image":"altenburger_ziegenkase.jpg","name_protections":["PDO"],"milk_types":["cow","goat"],"pasteurization":"raw","style":["soft","bloomy-rind","caraway"],"ageing_min_days":14,"format":"small cylinder or half-cylinder, ~250 g","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Altenburger Ziegenkäse is the small soft-ripened goat cheese of the Altenburg region in eastern Thuringia. Despite its name, the PDO does not require pure goat\'s milk: the spec specifies cow\'s milk to which at least fifteen per cent goat\'s milk is added, with cumin (caraway) blended into the curd and rennet used to set it. The mixed milk is warmed to 32–40 °C, cut, drained and salted, then moulded into a small 250 g cylinder (or a half-cylinder) and ripened with a bloomy white rind for at least two weeks. Fat content runs at least 30 % in dry matter. EU PDO came in 1997. The flavour is light and lactic with the warm seed-spice of the caraway threading through, the goat\'s-milk fraction supplying a quiet tang that lifts the cheese above straight cow\'s-milk Camembert without dominating. Altenburger is one of the few cheeses in the EU GI register based on a deliberately mixed cow-and-goat milk recipe.","sources":[{"label":"Qualigeo: Altenburger Ziegenkäse PDO","url":"https://www.qualigeo.eu/en/product/altenburger-ziegenkase-pdo/"}],"pronunciation":{"ipa":"/ˈaltn̩ˌbʊʁɡɐ ˈtsiːɡn̩ˌkɛːzə/","respelling":"AHL-ten-boor-ger TSEE-gen-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[12.1,51.15],[12.65,51.15],[12.85,51.0],[12.85,50.75],[12.55,50.6],[12.1,50.75],[12.0,50.95],[12.1,51.15]]]}},{"name":"Hessischer Handkäse","lat":50.11,"lon":8.68,"country":"Germany","where":"Hesse","hint":"Hesse, around Frankfurt","desc":"Hand-shaped sour-milk cheese, low fat, served \'mit Musik\' — onions and vinegar.","image":"hessischer_handkase.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["sour-curd","hand-formed","smear-rind"],"ageing_min_days":2,"format":"small disc, 20–125 g","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Hessischer Handkäse is the sour-milk cheese of Hesse, named for the traditional practice of shaping the small wheels by hand from acid-coagulated quark rather than rennet-set curd. The PGI restricts production and packaging to the federal state of Hesse and requires the raw material to be sour-milk quark of skimmed cow\'s milk: the quark is blended with table salt and ripening salts, sometimes caraway, then formed into small discs of twenty to one-hundred-twenty grams and ripened two to three days in chambers that step from 18 °C to 30 °C. Red-smear variants are seeded with Brevibacterium linens to develop the orange surface and pungent aroma; mould variants run a Camembert-style white rind. EU PGI came in 2010. The cheese must be packaged at the producing dairy because its character degrades quickly in transport. Eaten with onions and a glass of apple wine (Apfelwein) — \\"Handkäs mit Musik\\" — it is the regional staple of the Hessian table.","sources":[{"label":"Qualigeo: Hessischer Handkäse / Handkäs PGI","url":"https://www.qualigeo.eu/en/product/hessischer-handkase-hessischer-handkas-pgi/"},{"label":"EUR-Lex: Hessischer Handkäse application","url":"https://eur-lex.europa.eu/legal-content/EN/ALL/?uri=CELEX:52009XC1224(12)"},{"label":"Wikipedia: Handkäse","url":"https://en.wikipedia.org/wiki/Handkäse"}],"pronunciation":{"ipa":"/ˈhɛsɪʃɐ ˈhantˌkɛːzə/","respelling":"HES-ish-er HAHNT-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[7.85,51.65],[8.85,51.65],[9.75,51.55],[10.2,51.3],[10.2,50.5],[9.9,50.15],[9.2,49.85],[8.3,49.65],[7.8,50.05],[7.8,51.05],[7.85,51.65]]]}},{"name":"Holsteiner Tilsiter","lat":54.2,"lon":9.5,"country":"Germany","where":"Schleswig-Holstein","hint":"North Germany, near Denmark","desc":"Semi-hard washed-rind cow\'s-milk loaf with small irregular cracks; aromatic, mildly tangy.","image":"holsteiner_tilsiter.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","washed-rind"],"ageing_min_days":35,"format":"wheel or loaf, ~3–5 kg","year_recognized":2013,"animal_breed":null,"vegetarian":null,"desc_long":"Holsteiner Tilsiter is the protected form of Germany\'s classic Tilsit cheese, produced in Schleswig-Holstein on the country\'s northern plain and named for the East Prussian town of Tilsit where the recipe was first developed in the nineteenth century. The PGI covers a semi-hard wheel or loaf made from cow\'s milk — raw or pasteurised — with the rind continuously rubbed with brine and Brevibacterium linens through a minimum five-week ripening. Fat-in-dry-matter ranges from 30 % to 60 % depending on style, and the recipe may be augmented with caraway. EU PGI came in 2013. Mature wheels carry a thin yellow-brown washed rind and a light-yellow paste shot through with small irregular cracks and eyes; the flavour is full, gently piquant, and earthier than the supermarket Tilsiter sold across central Europe, with the Schleswig-Holstein dairy heritage clearly audible behind the smear.","sources":[{"label":"GOV.UK: Holsteiner Tilsiter PGI","url":"https://www.gov.uk/protected-food-drink-names/holsteiner-tilsiter"},{"label":"Wikipedia: Tilsit cheese","url":"https://en.wikipedia.org/wiki/Tilsit_cheese"}],"pronunciation":{"ipa":"/ˈhɔlʃtaɪnɐ ˈtɪlzɪtɐ/","respelling":"HOHL-shty-ner TIL-zit-er"},"region_polygon":{"type":"Polygon","coordinates":[[[8.0,55.05],[9.0,55.05],[10.1,54.95],[11.2,54.45],[11.3,53.95],[10.6,53.55],[9.6,53.55],[8.45,53.65],[7.95,54.4],[8.0,55.05]]]}},{"name":"Nieheimer Käse","lat":51.79,"lon":9.1,"country":"Germany","where":"Nieheim, North Rhine-Westphalia","hint":"Westphalia","desc":"Sour-milk cheese rolled with caraway and traditionally aged wrapped in hop leaves.","image":"nieheimer_kase.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["sour-curd","small-format","caraway"],"ageing_min_days":14,"format":"small cylinder, 32–37 g (~4 cm dia × 2 cm)","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Nieheimer Käse is a tiny sour-curd cheese from the East Westphalian town of Nieheim, made entirely from skimmed cow\'s-milk quark that meets a defined specification — at least 33 % dry matter, pH 3.9–4.3, and less than 1 % fat in the fresh mass. The PGI requires production within the municipal boundaries of Nieheim and forbids the addition of any external ripening culture: the cheese matures solely on the bacterial and yeast flora carried in by the sour quark itself, a feature that distinguishes it from other German sour-milk cheeses. Quark is blended with salt — and caraway, depending on the recipe — then pressed into small cylinders four centimetres across and roughly two centimetres tall, weighing thirty-two to thirty-seven grams each. EU PGI came in 2010. The flavour is sharp, spicy and pure, with the caraway adding a warm seed-spice lift, traditionally enjoyed with rye bread and beer.","sources":[{"label":"EUR-Lex: Nieheimer Käse PGI application","url":"https://eur-lex.europa.eu/legal-content/EN/ALL/?uri=CELEX:52009XC0929(04)&from=BG"},{"label":"GOV.UK: Nieheimer Käse PGI","url":"https://www.gov.uk/protected-food-drink-names/nieheimer-kase"}],"pronunciation":{"ipa":"/ˈniːhaɪmɐ ˈkɛːzə/","respelling":"NEE-hy-mer KAY-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.0,51.85],[9.2,51.9],[9.35,51.85],[9.35,51.75],[9.2,51.7],[9.0,51.75],[9.0,51.85]]]}},{"name":"Odenwälder Frühstückskäse","lat":49.6,"lon":8.9,"country":"Germany","where":"Odenwald, Hesse","hint":"Odenwald hills, southern Hesse","desc":"Round soft cow\'s-milk \'breakfast cheese\' with bloomy rind and caraway-tinged tang.","image":"odenwalder_fruhstuckskase.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["soft","bloomy-rind","small-format"],"ageing_min_days":10,"format":"small round, ~100–400 g","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Odenwälder Frühstückskäse — the \\"Odenwald breakfast cheese\\" — is a small soft-ripened cheese made in the southern Odenwald, the wooded uplands where Hesse, Bavaria and Baden-Württemberg meet. The PDO requires pasteurised cow\'s milk from the defined area and calf rennet only; the milk is skimmed and pasteurised at 72 °C, cooled to 34 °C, set with rennet for about an hour, then cut into 1.5–2 cm cubes, drained into pre-warmed moulds turned at thirty-minute intervals, and finished with a two-hour brine bath at 18 °C. The wheels then ripen with a bloomy or lightly smeared rind. EU PDO came in 1997. The cheese is intentionally small and quick-ripening — built for a breakfast plate, not a banquet — with a soft, supple paste, mild lactic flavour, and a faint mushroom note from the surface flora that develops over the short ripening.","sources":[{"label":"Qualigeo: Odenwälder Frühstückskäse PDO","url":"https://www.qualigeo.eu/en/product/odenwalder-fruhstuckskase-pdo/"}],"pronunciation":{"ipa":"/ˈoːdn̩ˌvɛldɐ ˈfʁyːʃtʏksˌkɛːzə/","respelling":"OH-den-vel-der FRYU-shtuks-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.5,49.85],[9.2,49.85],[9.5,49.7],[9.45,49.4],[9.0,49.3],[8.55,49.4],[8.45,49.65],[8.5,49.85]]]}},{"name":"Anevato","lat":40.08,"lon":21.43,"country":"Greece","where":"Grevena, Western Macedonia","hint":"Pindus mountains, NW Greece","desc":"Soft fresh sheep/goat-milk spread, slightly tart, eaten with bread or in pita.","image":"anevato.jpg","name_protections":["PDO"],"milk_types":["goat","sheep"],"pasteurization":"raw","style":["soft","fresh","acid-curd"],"ageing_min_days":60,"format":"soft mass, no rind, sold in tubs","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Anevato is a fresh white soft cheese from the mountains of Western Macedonia and is the only Greek PDO that may be made from one hundred per cent goat\'s milk — though sheep\'s milk or a sheep-and-goat blend is also permitted. The PDO confines production to the prefecture of Grevena and the Voio district of Kozani, drawing milk from animals raised in those highland pastures. The name itself, from the Greek anevainei (\\"rising\\"), refers to the way the curd rises in the vessel during the long, gentle acid coagulation: the raw milk is left at 18–22 °C until the desired acidity develops, briefly chilled, then set with a touch of rennet and salt before maturing for about two months at a final pH of 4.0–4.3. EU PDO came in 1996. Anevato has no rind, no eyes, and no colour beyond an even bright white; the flavour is gently salty with a clear fresh-goat tang and an underlying lactic sweetness — eaten by the spoonful or spread on rusks with olive oil.","sources":[{"label":"Wikipedia: List of Greek PDO cheeses","url":"https://en.wikipedia.org/wiki/List_of_Greek_Protected_Designations_of_Origin_cheeses"},{"label":"TheCheeseAtlas: Anevato","url":"https://thecheeseatlas.com/cheese-profiles/anevato/"}],"pronunciation":{"ipa":"/aneˈvato/","respelling":"ah-neh-VAH-toh"},"region_polygon":{"type":"Polygon","coordinates":[[[21.1,40.3],[21.4,40.4],[21.7,40.3],[21.8,40.1],[21.65,39.95],[21.3,39.95],[21.1,40.15],[21.1,40.3]]]}},{"name":"Batzos","lat":40.3,"lon":22.0,"country":"Greece","where":"Western & Central Macedonia, Thessaly","hint":"Northern mainland Greece","desc":"Hard, very salty sheep/goat curd cheese with little holes; grilled or fried in tiganitós.","image":"batzos.webp","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["semi-hard","brined"],"ageing_min_days":60,"format":"square blocks in brine, ~1 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Batzos is a brine-matured, low-fat semi-hard cheese from Thessaly and Western and Central Macedonia, with deep roots in the transhumant sheep- and goat-herding traditions of Northern Pindos. The PDO permits sheep\'s milk, goat\'s milk or a blend, and is unusual for an EU GI cheese in calling for the raw milk to be vigorously stirred during coagulation so that most of the milk fat is driven into the whey — that whey is then used to make either anthotyro or, where goat milk dominates, manouri-style cream cheeses. The defatted curd is moulded into square blocks, salted, and matured in brine for at least two months. EU PDO came in 1996. The finished cheese is white-to-pale-yellow, rindless, lightly punctuated with small eyes, with a sharp, piquant, sour-and-spicy flavour and a remarkably low fat content of around twenty per cent. Batzos is typically grilled, fried (it withstands high heat very well) or grated over pasta and pulses.","sources":[{"label":"Wikipedia: List of Greek PDO cheeses","url":"https://en.wikipedia.org/wiki/List_of_Greek_Protected_Designations_of_Origin_cheeses"}],"pronunciation":{"ipa":"/ˈbadzos/","respelling":"BAH-dzohs"},"region_polygon":{"type":"Polygon","coordinates":[[[21.3,40.8],[22.2,40.95],[23.0,40.8],[23.2,40.3],[23.1,39.8],[22.6,39.3],[21.8,39.3],[21.3,39.6],[21.1,40.3],[21.3,40.8]]]}},{"name":"Feta","lat":39.5,"lon":22.0,"country":"Greece","where":"Mainland Greece + Lesvos","hint":"Mainland Greece","desc":"Brined sheep-milk cheese (up to 30% goat); PDO since 2002 — only Greek-made cheese can be feta in the EU.","image":"feta.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"any","style":["semi-soft","brined","white"],"ageing_min_days":60,"format":"blocks in brine, ~1 kg pieces","year_recognized":2002,"animal_breed":null,"vegetarian":null,"desc_long":"Feta is the brined white cheese of Greece, made from sheep\'s milk or a blend of sheep\'s milk with up to thirty per cent goat\'s milk, and protected as Greek-only since the European Court of Justice settled the long-running PDO dispute in 2002. The spec restricts production to mainland Greece and the island of Lesbos, and forbids cow\'s milk, colourants, preservatives, casein salts and reconstituted milk. Curds are set with rennet, drained in cloth, salted heavily and packed into wooden barrels or tins to ripen — about ten to fifteen days at 16–18 °C, then at least another six weeks in cold brine at 2–4 °C. Total ageing is no less than two months. The result is a firm but crumbly white cheese with a clean, briny tang and the unmistakable lanolin-rich character of Greek sheep\'s milk. Feta anchors the Greek table — central to horiatiki, baked into spanakopita, dressed with olive oil and rigani — and is the single most widely exported Greek food product.","sources":[{"label":"EU Agri: Feta PDO","url":"https://agriculture.ec.europa.eu/farming/geographical-indications-and-quality-schemes/geographical-indications-food-and-drink/feta-pdo_en"},{"label":"Academy of Cheese: Feta PDO","url":"https://academyofcheese.org/feta-pdo/"},{"label":"EUR-Lex: Commission Regulation (EC) No 1107/96 (PDO registration, PDF)","url":"https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:31996R1107"},{"label":"Wikipedia: Feta","url":"https://en.wikipedia.org/wiki/Feta"}],"pronunciation":{"ipa":"/ˈfeta/","respelling":"FEH-tah"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[20.1,41.4],[22.0,41.7],[24.5,41.55],[26.55,41.3],[26.5,40.7],[25.7,40.2],[24.5,39.85],[23.4,38.95],[23.1,38.3],[22.85,37.5],[22.65,36.8],[21.75,36.55],[21.0,37.0],[20.5,37.8],[20.2,38.8],[19.75,39.85],[19.85,40.9],[20.1,41.4]]],[[[25.85,39.45],[26.3,39.45],[26.6,39.3],[26.55,39.0],[26.2,38.95],[25.85,39.15],[25.85,39.45]]]]}},{"name":"Formaella Arachovas Parnassou","lat":38.48,"lon":22.6,"country":"Greece","where":"Arachova, Mt. Parnassus","hint":"Slopes of Mt. Parnassus","desc":"Small hard sheep/goat-milk cheese aged in wicker baskets; pan-fried like saganaki.","image":"formaella_arachovas_parnassou.webp","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["semi-hard","basket-formed","scalded"],"ageing_min_days":90,"format":"small cylinder, basket-imprinted","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Formaella Arachovas Parnassou is the small reed-basket cheese of Arachova, the mountain village on the south slopes of Parnassus in Boeotia. The PDO restricts production to the boundaries of Arachova and the milk to sheep\'s, goat\'s, or a blend of the two, drawn from native mountain breeds grazed on the Parnassus flora. Milk is curdled at 32 °C over about two hours; the curd is heated to 40 °C, cut, packed into the eponymous reed baskets (formes), and given a remarkable double-bath treatment: an hour in 60 °C whey, then a flip-and-soak hour in 75–80 °C milk. After salting and a day of drying, wheels are aged at least three months. EU PDO came in 1996. The cheese carries the distinctive vertical striations of the reed basket on its surface; the paste is firm but elastic with a pale yellow colour, and the flavour is full and sheep-fatted, with a long savoury finish. It is the canonical cheese for saganaki at the foot of Parnassus.","sources":[{"label":"Qualigeo: Formaella Arachovas Parnassou PDO","url":"https://www.qualigeo.eu/en/product/formaella-arachovas-parnassou-pdo/"},{"label":"Wikipedia: Formaela","url":"https://en.wikipedia.org/wiki/Formaela"}],"pronunciation":{"ipa":"/forˈmaela araˈxovas parnaˈsu/","respelling":"for-MY-lah ah-RAH-khoh-vas par-nah-SOO"},"region_polygon":{"type":"Polygon","coordinates":[[[22.45,38.65],[22.7,38.65],[22.8,38.5],[22.75,38.35],[22.5,38.3],[22.4,38.45],[22.45,38.65]]]}},{"name":"Galotyri","lat":39.66,"lon":20.85,"country":"Greece","where":"Epirus & Thessaly","hint":"Epirus, NW Greece","desc":"Soft creamy spreadable sheep/goat-milk cheese with slight sour tang; the original Greek cream-cheese.","image":"galotyri.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["soft","fresh","acid-curd","spreadable"],"ageing_min_days":60,"format":"soft paste in tubs or wooden barrels","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Galotyri is the soft, tangy, spreadable cheese of Epirus and Thessaly — one of the oldest cheeses in the eastern Mediterranean and protected as a PDO since 1996. The spec permits raw sheep\'s milk, goat\'s milk, or a blend of the two. Production begins by bringing the fresh milk briefly to a boil, then leaving it at room temperature for about a day, salting it at three to four per cent, and stirring it over two more days to build the strongly lactic acidity that defines the cheese. The acid-set curd is packed into wooden barrels or leather bags and rested at no more than 8 °C for a minimum of two months. The result is a brilliant-white, intensely yogurty paste shot through with small curd pieces — moisture up to seventy-five per cent, fat in dry matter at least forty per cent — sharper and more tangy than yogurt itself, served on bread with olive oil, swirled into eggs, or paired with bitter greens.","sources":[{"label":"Qualigeo: Galotyri PDO","url":"https://www.qualigeo.eu/en/product/galotyri-pdo/"}],"pronunciation":{"ipa":"/ɣaloˈtiri/","respelling":"ghah-loh-TEE-ree"},"region_polygon":{"type":"Polygon","coordinates":[[[20.5,40.4],[21.3,40.5],[22.3,40.3],[22.85,40.0],[23.1,39.5],[22.8,39.1],[22.0,38.95],[21.2,39.05],[20.45,39.3],[20.2,39.85],[20.5,40.4]]]}},{"name":"Graviera Agrafon","lat":39.27,"lon":21.65,"country":"Greece","where":"Agrafa mountains, Central Greece","hint":"Pindus highlands","desc":"Hard sheep/goat-milk cheese from remote \'unwritten\' mountain villages; sweet, nutty.","image":"graviera_agrafon.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["hard","cooked","pressed","gruyère-style"],"ageing_min_days":90,"format":"wheel, ~10–25 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Graviera Agrafon is produced in the Agrafa range that straddles Karditsa in Thessaly and Evrytania in Central Greece. The PDO restricts production to that mountain zone and the milk to sheep\'s, with up to thirty per cent goat\'s milk permitted, drawn exclusively from free-range animals grazing the herb-rich Agrafa flora. The cheese follows the classic Greek graviera method — milk coagulated at 34–36 °C, curd cut and cooked to about 50 °C with constant stirring, then pressed into wheel-shaped rounds, rested two days on wooden racks, salted in brine for two to four days, and matured at least three months. EU PDO came in 1996. Production is famously tiny — for years only a single dairy worked the wheels — and most of the annual output is exported to France, Switzerland and Germany. The paste is firm, eyed, deep yellow, and the flavour is the most concentrated of the graviera family, with sheep-milk sweetness, alpine herbs, and a long, savoury finish.","sources":[{"label":"TheCheeseAtlas: Graviera Agrafon","url":"https://thecheeseatlas.com/cheese-profiles/graviera-agrafon/"}],"pronunciation":{"ipa":"/ɣraviˈera aˈɣrafon/","respelling":"ghrah-vee-EH-rah AH-ghrah-fohn"},"region_polygon":{"type":"Polygon","coordinates":[[[21.3,39.4],[21.55,39.4],[21.75,39.3],[21.8,39.05],[21.55,38.9],[21.3,39.0],[21.2,39.25],[21.3,39.4]]]}},{"name":"Graviera Kritis","lat":35.3,"lon":24.8,"country":"Greece","where":"Crete","hint":"Crete","desc":"Hard sheep/goat-milk Cretan cheese; sweet, with light caramel notes.","image":"graviera_kritis.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["hard","cooked","pressed","gruyère-style"],"ageing_min_days":90,"format":"wheel, ~5–25 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Graviera Kritis is the Cretan member of Greece\'s graviera family — hard, cooked-curd, gruyère-inflected cheeses developed when Greek dairying took inspiration from the Swiss tradition in the early twentieth century. The PDO restricts production to Crete and to raw sheep\'s milk or a blend in which sheep predominates, with goat\'s milk capped at twenty per cent of the total mix. The milk is curdled at 34–36 °C, the curd cut and cooked to 50–52 °C with continuous stirring before being pressed into wheel-shaped rounds, salted and matured in cellars at 14–18 °C for a minimum of three months; on Crete itself wheels routinely ripen for five months or longer. EU PDO came in 1996. The paste is firm, ivory-yellow and gently eyed; the flavour balances a clean nutty sweetness against the lanolin warmth of Cretan sheep milk and the herbal grazing of the island\'s mountains, finishing with the gentle caramel depth that the cooked curd contributes.","sources":[{"label":"Qualigeo: Graviera Kritis PDO","url":"https://www.qualigeo.eu/en/product/graviera-kritis-pdo/"}],"pronunciation":{"ipa":"/ɣraviˈera ˈkritis/","respelling":"ghrah-vee-EH-rah KREE-tees"},"region_polygon":{"type":"Polygon","coordinates":[[[23.45,35.65],[24.2,35.7],[25.2,35.45],[26.2,35.3],[26.3,34.95],[25.45,34.85],[24.2,34.95],[23.55,35.2],[23.45,35.45],[23.45,35.65]]]}},{"name":"Graviera Naxou","lat":37.1,"lon":25.38,"country":"Greece","where":"Naxos, Cyclades","hint":"Naxos, central Cyclades","desc":"Hard cow-dominant (with sheep/goat) cheese with small eyes; mellow and butter-soft.","image":"graviera_naxou.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"any","style":["hard","cooked","pressed","gruyère-style"],"ageing_min_days":90,"format":"wheel, ~8–20 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Graviera Naxou is the Cycladic member of the graviera family, made on the island of Naxos and the only Greek graviera built primarily on cow\'s milk. The PDO calls for at least eighty per cent cow\'s milk with the remainder drawn from sheep and goats also raised on the island. The milk is curdled at 36–37 °C for half an hour, the curd cut, cooked to 50 °C with continuous mixing, then pressed in cloth-lined moulds for three to four hours and salted in brine for two to five days. Wheels mature at least three months. EU PDO came in 1996. The cheese has a thin natural rind and a firm, elastic paste shot through with small irregular eyes; the flavour is the mildest, sweetest and most milk-forward of the Greek gravieras — close in spirit to a young Swiss Gruyère, with a clean lactic finish and the green-pasture lift that Naxos\'s cow herds give it.","sources":[{"label":"Qualigeo: Graviera Naxou PDO","url":"https://www.qualigeo.eu/en/product/graviera-naxou-pdo/"}],"pronunciation":{"ipa":"/ɣraviˈera ˈnaksu/","respelling":"ghrah-vee-EH-rah NAHK-soo"},"region_polygon":{"type":"Polygon","coordinates":[[[25.3,37.2],[25.5,37.2],[25.65,37.05],[25.55,36.9],[25.35,36.9],[25.25,37.05],[25.3,37.2]]]}},{"name":"Kalathaki Limnou","lat":39.92,"lon":25.23,"country":"Greece","where":"Lemnos","hint":"Lemnos, north Aegean","desc":"White brined sheep/goat cheese pressed in \'kalathi\' baskets that leave reed marks on its rind.","image":"kalathaki_limnou.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"any","style":["semi-soft","brined","basket-formed"],"ageing_min_days":60,"format":"small cylinder, basket-imprinted, ~1 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Kalathaki Limnou is the basket-shaped brined cheese of Lemnos, the windswept Aegean island where the recipe is a close cousin of feta. The name kalathaki means \\"little basket\\": after the milk is set at about 35 °C, the curd is ladled into small woven baskets, drained without pressing, salted, and ripened in brine for at least two months. The baskets leave a distinct vertical-banded pattern on the rind. The PDO permits sheep\'s milk or a sheep-and-goat blend with goat\'s milk capped at thirty per cent, drawn from animals grazed freely on the wild grass and aromatic herbs of Lemnos. EU PDO came in 1996. The paste is bright white and slightly firmer than Feta, with moisture around fifty-six per cent and fat in dry matter at forty-three per cent; the flavour is briny, lanolin-rich, and gently spicy — the salt and pasture of the Aegean made cheese.","sources":[{"label":"Qualigeo: Kalathaki Limnou PDO","url":"https://www.qualigeo.eu/en/product/kalathaki-limnou-pdo/"},{"label":"Wikipedia: Baklava","url":"https://en.wikipedia.org/wiki/Baklava"}],"pronunciation":{"ipa":"/kalaˈθaki ˈlimnu/","respelling":"kah-lah-THAH-kee LEEM-noo"},"region_polygon":{"type":"Polygon","coordinates":[[[25.0,40.0],[25.3,40.05],[25.55,39.95],[25.55,39.85],[25.25,39.8],[25.0,39.9],[25.0,40.0]]]}},{"name":"Kasseri","lat":40.0,"lon":22.5,"country":"Greece","where":"Macedonia, Thessaly, Lesvos","hint":"Northern Greece","desc":"Pasta-filata sheep/goat-milk cheese, semi-hard and golden; melts beautifully (saganaki).","image":"kasseri.jpeg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"any","style":["semi-hard","pasta-filata","pressed"],"ageing_min_days":90,"format":"wheel, ~1–9 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Kasseri is a semi-hard pasta-filata cheese produced in Thessaly, Macedonia, Lesbos, and the Xanthi region of Thrace, made from sheep\'s milk or a blend of at least eighty per cent sheep with up to twenty per cent goat\'s milk. Cow\'s milk is forbidden. The PDO requires the milk to be set with rennet at 32–35 °C, the curds drained and acidified, then plunged into hot water and stretched in the pasta-filata fashion before being moulded and pressed; ageing runs at least three months. EU PDO came in 1996. The cheese has a slightly elastic, fibrous paste with a pale ivory colour, a mild milky-tangy flavour and a faint sheep-fat richness. Kasseri melts beautifully, and is the canonical Greek cheese for the flame-finished saganaki — pan-seared, flamed with brandy, and served at the table.","sources":[{"label":"MyCheese: Kasseri","url":"https://mycheese.org/kasseri-cheese-greek-varieties-and-taste/"},{"label":"Wikipedia: Kasseri","url":"https://en.wikipedia.org/wiki/Kasseri"}],"pronunciation":{"ipa":"/kaˈseri/","respelling":"kah-SEH-ree"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[20.8,41.2],[22.5,41.3],[24.5,41.1],[25.3,41.1],[25.2,40.55],[24.0,40.3],[23.1,40.1],[22.0,39.4],[21.4,39.0],[20.8,39.3],[20.6,40.2],[20.8,41.2]]],[[[25.85,39.45],[26.3,39.45],[26.6,39.3],[26.55,39.0],[26.2,38.95],[25.85,39.15],[25.85,39.45]]]]}},{"name":"Katiki Domokou","lat":38.99,"lon":22.3,"country":"Greece","where":"Domokos, Thessaly","hint":"Central Greece","desc":"Soft, fluffy fresh sheep/goat cheese — like a more delicate Greek cream cheese.","image":"katiki_domokou.jpg","name_protections":["PDO"],"milk_types":["goat","sheep"],"pasteurization":"pasteurized","style":["fresh","spreadable","acid-curd"],"ageing_min_days":0,"format":"soft paste in tubs","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Katiki Domokou is the spreadable fresh white cheese of Domokos, on the Othrys plateau of Thessaly. The PDO restricts production to the Domokos region and the milk to free-range goat\'s milk — most often blended with sheep\'s milk in roughly a 70/30 ratio — from animals feeding on the wild flora of the plateau. After pasteurisation the milk is held at 25 °C for about twenty-four hours until natural acidification builds the curd; the soft curd, with or without a touch of rennet, is then ladled into cloth bags and allowed to drain at controlled temperature until moisture sits between seventy and eighty per cent of total weight. No preservatives or colourants are permitted. EU PDO came in 1996. The cheese is brilliant white, creamy and homogeneous, with a low fat content of around forty per cent in dry matter and a clean, tangy, lactic flavour that lifts off grilled bread or paired with honey and walnuts.","sources":[{"label":"Qualigeo: Katiki Domokou PDO","url":"https://www.qualigeo.eu/en/product/katiki-domokou-pdo/"},{"label":"Wikipedia: Katiki Domokou","url":"https://en.wikipedia.org/wiki/Katiki_Domokou"}],"pronunciation":{"ipa":"/kaˈtiki doˈmoku/","respelling":"kah-TEE-kee doh-MOH-koo"},"region_polygon":{"type":"Polygon","coordinates":[[[22.1,39.1],[22.35,39.1],[22.55,39.0],[22.55,38.8],[22.35,38.75],[22.1,38.85],[22.1,39.1]]]}},{"name":"Kefalograviera","lat":39.3,"lon":21.3,"country":"Greece","where":"Western Macedonia, Epirus, Aetolia-Acarnania","hint":"Western mainland Greece","desc":"Hard salty sheep/goat-milk grating cheese; a graviera-kefalotyri hybrid.","image":"kefalograviera.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"any","style":["hard","pressed","salted"],"ageing_min_days":90,"format":"wheel, ~6–10 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Kefalograviera is a hard table cheese developed in the mid-twentieth century as a hybrid of two older Greek styles — kefalotyri\'s salt-and-grate character and graviera\'s cooked-curd discipline — and is made today in Western Greece, Epirus and parts of Western Macedonia. The PDO permits sheep\'s milk or a sheep-and-goat blend with goat\'s milk capped at ten per cent, and confines production to a defined arc of prefectures including Ioannina, Thesprotia, Arta, Preveza, Florina, Kozani, Kastoria, Grevena, Aetolia-Acarnania and Evrytania. The milk is curdled at 32–34 °C, the curd cut and cooked to 48 °C before being moulded and pressed; wheels brine at 18–20 °Bé for two days, then mature at 14–16 °C for at least three months. EU PDO came in 1996. Fat in dry matter sits at no less than forty per cent; the paste is firm and golden, scattered with small irregular eyes, and the flavour is intensely salty-savoury with a sharp finish — superb fried for saganaki or grated over baked pasta.","sources":[{"label":"Qualigeo: Kefalograviera PDO","url":"https://www.qualigeo.eu/en/product/kefalograviera-pdo/"},{"label":"Wikipedia: Kefalograviera","url":"https://en.wikipedia.org/wiki/Kefalograviera"}],"pronunciation":{"ipa":"/kefaloɣraviˈera/","respelling":"keh-fah-loh-ghrah-vee-EH-rah"},"region_polygon":{"type":"Polygon","coordinates":[[[20.2,40.5],[21.3,40.55],[22.2,40.3],[22.15,39.8],[21.7,39.1],[21.3,38.4],[20.8,38.4],[20.2,38.9],[20.05,39.8],[20.2,40.5]]]}},{"name":"Kopanisti","lat":37.45,"lon":25.33,"country":"Greece","where":"Cyclades — Mykonos & neighbours","hint":"Cyclades islands","desc":"Pungent semi-soft cheese fermented and \'beaten\' (kopanizo) until creamy and sharp.","image":"kopanisti.jpeg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"raw","style":["soft","fermented","spreadable","blue-adjacent"],"ageing_min_days":30,"format":"soft paste in tubs","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Kopanisti is the famously pungent fermented cheese of the Cyclades — Mykonos, Tinos, Andros, Syros and Naxos — with documented production on Mykonos for well over three hundred years. The PDO permits cow\'s, sheep\'s, or goat\'s milk, or any mixture thereof. The process is distinctive: the milk is set with a starter at 28–30 °C until thick (twenty to twenty-four hours), the drained curd is then salted heavily and worked by hand in the producer\'s wooden bowl, with fresh portions added daily and the whole mass kneaded over the course of weeks. The repeated kneading, called the kopanisma, both inoculates the cheese with surface flora — including Penicillium and lactobacilli — and accelerates lipolysis and proteolysis to produce the cheese\'s characteristic peppery, intensely savoury bite. EU PDO came in 1996. Locals compare its sharpness to Roquefort, though Kopanisti carries no visible blue veining; it is a paste, not a wheel, and is eaten by the spoonful with raki and crusty bread.","sources":[{"label":"Wikipedia: Kopanisti","url":"https://en.wikipedia.org/wiki/Kopanisti"},{"label":"Slow Food Ark of Taste: Kopanisti","url":"https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/kopanisti-2/"},{"label":"EUR-Lex: PDO amendment publication — Kopanisti (OJ C 186/2012, PDF)","url":"http://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:C:2012:186:0011:0017:EN:PDF"}],"pronunciation":{"ipa":"/kopaˈnisti/","respelling":"koh-pah-NEES-tee"},"region_polygon":{"type":"Polygon","coordinates":[[[24.65,38.05],[25.3,38.05],[25.65,37.45],[25.55,36.9],[25.05,36.9],[24.75,37.35],[24.55,37.7],[24.65,38.05]]]}},{"name":"Ladotyri Mytilinis","lat":39.1,"lon":26.55,"country":"Greece","where":"Lesvos","hint":"Lesvos","desc":"Hard sheep/goat-milk cheese aged submerged in olive oil; the name means \'oil cheese\'.","image":"ladotyri_mytilinis.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"any","style":["hard","pressed","oil-preserved"],"ageing_min_days":90,"format":"small cylinder, ~1 kg, in olive oil or paraffin","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Ladotyri Mytilinis — literally \\"oil cheese of Mytilene\\" — is the traditional hard cheese of Lesbos, named for its centuries-old method of preservation under the island\'s prized olive oil. The PDO restricts production to Lesbos and the milk to sheep\'s, with goat\'s milk allowed up to thirty per cent. The milk is curdled at 32–34 °C, the curd separated and heated to 45 °C, then hand-pressed into small cylindrical moulds. The young wheels are salted once a day for three days, then turned daily for ten to twenty days, and ripened for at least three months. When mature, the wheels are either submerged in olive oil — roughly one and a half litres per kilo of cheese — or sealed with paraffin wax. The technique was a domestic necessity before refrigeration reached the island in the 1960s and 1970s, and it remains the signature preservation method today. EU PDO came in 1996. The paste is firm, golden, and lightly piquant, with the lanolin warmth of sheep\'s milk lifted by the soft fruit of Lesbos olive oil.","sources":[{"label":"Wikipedia: Ladotyri Mytilinis","url":"https://en.wikipedia.org/wiki/Ladotyri_Mytilinis"},{"label":"Qualigeo: Ladotyri Mytilinis PDO","url":"https://www.qualigeo.eu/en/product/ladotyri-mytilinis-pdo/"}],"pronunciation":{"ipa":"/laðoˈtiri mitiˈlinis/","respelling":"lah-thoh-TEE-ree mee-tee-LEE-nees"},"region_polygon":{"type":"Polygon","coordinates":[[[25.85,39.45],[26.3,39.45],[26.6,39.3],[26.55,39.0],[26.2,38.95],[25.85,39.15],[25.85,39.45]]]}},{"name":"Manouri","lat":40.0,"lon":22.0,"country":"Greece","where":"Western & Central Macedonia, Thessaly","hint":"Northern Greek mainland","desc":"Soft fresh whey cheese from sheep/goat milk; rich, slightly sweet, like a Greek ricotta.","image":"manouri.webp","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"pasteurized","style":["fresh","whey","cream-enriched"],"ageing_min_days":0,"format":"cylindrical log, 20–30 cm × 10–12 cm","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Manouri is Greece\'s premium whey cheese — the cream-enriched cousin of mizithra and anthotyro — produced in Central and Western Macedonia and Thessaly under PDO. The spec uses the whey left over from feta or related brined-cheese production, derived from sheep\'s or goat\'s milk, then enriches it with whole milk or cream from sheep or goats so the finished cheese carries at least seventy per cent fat in dry matter. The mixture is gradually heated to 88–90 °C with constant stirring, causing the whey proteins to denature and coagulate; the warm curd is then ladled into cloth bags, drained, and shaped into long cylindrical logs without further salting or rind formation. EU PDO came in 1996. Manouri is eaten fresh, within days. The paste is bright white, soft, dense and very smooth, with a clean, creamy, faintly nutty flavour that pairs equally well with honey and walnuts on the dessert plate or with cured meats on the meze tray.","sources":[{"label":"Qualigeo: Manouri PDO","url":"https://www.qualigeo.eu/en/product/manouri-pdo/"},{"label":"Wikipedia: Manouri","url":"https://en.wikipedia.org/wiki/Manouri"}],"pronunciation":{"ipa":"/maˈnuri/","respelling":"mah-NOO-ree"},"region_polygon":{"type":"Polygon","coordinates":[[[21.1,40.95],[22.2,41.05],[23.2,40.85],[23.4,40.3],[23.1,39.8],[22.55,39.2],[21.7,39.3],[21.2,39.8],[21.05,40.5],[21.1,40.95]]]}},{"name":"Metsovone","lat":39.77,"lon":21.18,"country":"Greece","where":"Metsovo, Epirus","hint":"Pindus mountains, near Metsovo","desc":"Pasta-filata cow/sheep cheese, lightly smoked over fragrant wood.","image":"metsovone.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"any","style":["semi-hard","pasta-filata","smoked"],"ageing_min_days":90,"format":"elongated cylinder tied with twine, ~1 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Metsovone is the smoked pasta-filata cheese of Metsovo, the mountain town in the Pindus range of Epirus. The PDO requires that at least eighty per cent of the milk be cow\'s, with the balance drawn from sheep and goats raised in the area. The cheese is built on the pasta-filata technique imported from Italian provolone tradition: the curd is acidified, then plunged into hot water and stretched and kneaded into pliable strands before being shaped into elongated cylinders, tied with twine, and brined. After a maturation of about three months, the cheese is smoked for roughly twelve days over the aromatic woods, vines and herbs of the surrounding mountains, picking up the golden-brown rind and deep wood-smoke perfume that define it. EU PDO came in 1996. The paste is firm and elastic with the resinous warmth of the smoke balancing a clean lactic core; Metsovone melts beautifully and is famous flame-finished as saganaki, or grated and slipped over hot greens.","sources":[{"label":"TheCheeseAtlas: Metsovone","url":"https://thecheeseatlas.com/cheese-profiles/metsovone/"},{"label":"EU DOOR document: Metsovone (archived)","url":"https://web.archive.org/web/20121103071313/http://ec.europa.eu/agriculture/quality/door/documentDisplay.html?chkDocument=4523_1_en"},{"label":"Wikipedia: Metsovone","url":"https://en.wikipedia.org/wiki/Metsovone"}],"pronunciation":{"ipa":"/metsoˈvone/","respelling":"met-soh-VOH-nay"},"region_polygon":{"type":"Polygon","coordinates":[[[20.95,39.95],[21.2,39.95],[21.35,39.85],[21.4,39.65],[21.2,39.55],[20.95,39.65],[20.85,39.8],[20.95,39.95]]]}},{"name":"Pichtogalo Chanion","lat":35.51,"lon":24.02,"country":"Greece","where":"Chania, western Crete","hint":"Western Crete","desc":"Fresh soft sheep/goat-milk cheese with high fat; the cream filling for sweet bougatsa.","image":"pixtogalo_chanion.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["fresh","soft","spreadable","acid-curd"],"ageing_min_days":1,"format":"soft paste, ~1 kg portions","year_recognized":1994,"animal_breed":null,"vegetarian":null,"desc_long":"Pichtogalo Chanion — locally also called Chaniotiki Mizithra — is the soft fresh spreadable cheese of the Chania prefecture in western Crete. The PDO restricts production to Chania and the milk to sheep, goat, or a blend, drawn from animals grazing the herb-rich Cretan landscape. Production must begin within forty-eight hours of milking: the filtered raw milk is set with natural rennet at the unusually low temperature of 18–25 °C and left to coagulate over about two hours, then allowed to acidify for a further twenty-four hours before draining. The cheese carries no rind and is sold as a bright white, creamy paste with moisture up to sixty-five per cent and fat in dry matter of at least fifty per cent. EU PDO came in 1994. The flavour is mild and milky with a clear lactic tang, reminiscent of a thick yogurt; on Crete it is the defining ingredient of the regional savoury pies kalitsounia and bourekakia, and is also eaten by the spoonful with thyme honey.","sources":[{"label":"Slow Food Ark of Taste: Pichtogalo Chanion","url":"https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/pichtogalo-chanion/"}],"pronunciation":{"ipa":"/pixtoˈɣalo xaˈnion/","respelling":"peekh-toh-GHAH-loh khah-NYOHN"},"region_polygon":{"type":"Polygon","coordinates":[[[23.45,35.65],[24.05,35.65],[24.3,35.5],[24.3,35.2],[23.95,35.1],[23.55,35.2],[23.45,35.4],[23.45,35.65]]]}},{"name":"San Michali","lat":37.45,"lon":24.92,"country":"Greece","where":"Syros, Cyclades","hint":"Syros, Cyclades","desc":"Hard cow\'s-milk cheese with small eyes; spicy bite when aged — rare cow cheese among Greek islands.","image":"san_michali.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["hard","pressed","salted"],"ageing_min_days":120,"format":"wheel, ~4–8 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"San Michali is the only PDO cheese of the Cyclades, made on the small island of Syros and the only Greek PDO cheese built exclusively on cow\'s milk. The spec restricts both the herds and the production to Syros. The milk is skimmed and pasteurised, then coagulated at about 32–34 °C; the curd is cut to corn-kernel size, scalded to 48–50 °C, partly salted, and pressed into wheel moulds before being finished in brine. Wheels mature at least four months on wooden boards. EU PDO came in 1996. The cheese has a hard, dense, ivory-yellow paste, sparsely eyed, with a flavour that runs from sharp and salty in young wheels to deeply nutty — with notes specifically of hazelnut — in long-aged ones; the character is widely attributed to the diet of the Syros herds, which graze the wild herbs and brush of the island. Ten litres of milk make one kilo of finished cheese.","sources":[{"label":"TheCheeseAtlas: San Michali","url":"https://thecheeseatlas.com/cheese-profiles/san-michali/"}],"pronunciation":{"ipa":"/san miˈxali/","respelling":"san mee-KHAH-lee"},"region_polygon":{"type":"Polygon","coordinates":[[[24.85,37.5],[24.97,37.5],[25.0,37.4],[24.95,37.35],[24.85,37.4],[24.85,37.5]]]}},{"name":"Sfela","lat":37.05,"lon":22.42,"country":"Greece","where":"Messinia & Laconia, Peloponnese","hint":"Southern Peloponnese","desc":"Salty sheep/goat-milk cheese cut into long strips (\'sfela\'); brined like feta.","image":"sfela.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"any","style":["semi-hard","brined"],"ageing_min_days":90,"format":"strips in barrels, ~1 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Sfela is the brine-cured strip cheese of the southern Peloponnese, made in the Messinia and Laconia regional units and named for the long flat slices — sfelides — in which the curd is cut. The PDO permits sheep\'s milk, goat\'s milk, or a blend, sourced from the protected area. The milk is set at 30–32 °C, the curd cut and cooked to 38–40 °C with constant stirring, drained in cloth, lightly pressed, sliced into the characteristic strips, dry-salted and then submerged in 20 °Bé brine in barrels or metal containers. Maturation is at least three months. EU PDO came in 1996. The finished cheese is a pale-yellow rectangular slice without rind, threaded with small irregular eyes, with a sharp salty flavour, faintly sour aroma and a strong, persistent finish — a working cheese of the Peloponnesian rural table, often crumbled over horta or paired with rye bread and olives.","sources":[{"label":"Qualigeo: Sfela PDO","url":"https://www.qualigeo.eu/en/product/sfela-pdo/"},{"label":"Wikipedia: Kalamata","url":"https://en.wikipedia.org/wiki/Kalamata"}],"pronunciation":{"ipa":"/ˈsfela/","respelling":"SFEH-lah"},"region_polygon":{"type":"Polygon","coordinates":[[[21.5,37.3],[21.95,37.4],[22.5,37.3],[22.75,36.8],[22.6,36.45],[22.1,36.45],[21.65,36.65],[21.5,36.95],[21.5,37.3]]]}},{"name":"Xygalo Siteias","lat":35.21,"lon":26.1,"country":"Greece","where":"Sitia, eastern Crete","hint":"Eastern Crete","desc":"Soft fresh sheep/goat-milk cheese, slightly sour, traditionally aged in clay pots.","image":"xygalo_siteias.jpg","name_protections":["PDO"],"milk_types":["goat","sheep"],"pasteurization":"any","style":["fresh","soft","spreadable","fermented"],"ageing_min_days":30,"format":"soft paste in tubs","year_recognized":2011,"animal_breed":null,"vegetarian":null,"desc_long":"Xygalo Siteias is a soft, yogurt-like fermented cheese from the Sitia region of eastern Crete in the Lasithi prefecture, made from goat\'s milk or a blend of goat and sheep milk drawn from native Cretan breeds — Sitia, Psiloritis and Sfakia. The PDO permits an optional pasteurisation, then calls for the milk to be cooled to 25 °C, salted to no more than two per cent by weight, lightly inoculated with native lactic cultures (often a spoonful of yogurt or the previous batch\'s whey), and set with a small amount of rennet from suckling-lamb stomachs. The cheese ferments for twenty-four hours, drains briefly, and matures at least one month — two if the milk was raw. EU PDO came in 2011. The finished cheese carries up to seventy-five per cent moisture, very little salt, and a thick yogurt-like body marked by a clean, lactic, faintly sour flavour. On Crete it is the canonical filling for sweet and savoury island pies and the centrepiece of a Sitian breakfast plate.","sources":[{"label":"Wikipedia: Xygalo Siteias","url":"https://en.wikipedia.org/wiki/Xygalo_Siteias"}],"pronunciation":{"ipa":"/ˈksiɣalo siˈtias/","respelling":"KSEE-ghah-loh see-TEE-ahs"},"region_polygon":{"type":"Polygon","coordinates":[[[25.85,35.3],[26.2,35.3],[26.35,35.15],[26.3,35.0],[26.0,34.95],[25.8,35.05],[25.75,35.2],[25.85,35.3]]]}},{"name":"Xynomyzithra Kritis","lat":35.3,"lon":24.8,"country":"Greece","where":"Crete","hint":"Crete","desc":"Sour fresh whey cheese — the tart Cretan answer to manouri; used in dakos and pies.","image":"xynomyzithra_kritis.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["fresh","whey","soft","spreadable","acid"],"ageing_min_days":1,"format":"soft paste in cloth bags, ~1 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Xynomyzithra Kritis — \\"sour mizithra of Crete\\" — is the acidulated whey cheese of the island, produced across the four Cretan prefectures of Chania, Rethymno, Heraklion and Lasithi from the whey left over after making Graviera Kritis or Kefalotyri Kritis. The PDO requires that sheep\'s milk, goat\'s milk, or a blend be used for the parent wheel, so the whey carries the same character into the second cheese. The whey is filtered and heated to 92 °C with constant stirring for about thirty minutes; when the temperature passes through 68–70 °C, whole sheep or goat milk equal to roughly fifteen per cent of the mass is folded in. The coagulum rests thirty minutes, drains in moulds three to five hours, is salted at 1.5–2 % and finally packed into cloth bags. EU PDO came in 1996. The cheese is white, soft, slightly grainy, with no rind, and the flavour is the namesake clean sour-and-sweet — close to a fresh yogurt-cheese, used everywhere in Cretan cooking and most famously crumbled over dakos.","sources":[{"label":"Qualigeo: Xynomyzithra Kritis PDO","url":"https://www.qualigeo.eu/en/product/xynomyzithra-kritis-pdo/"},{"label":"Wikipedia: Xynomizithra","url":"https://en.wikipedia.org/wiki/Xynomizithra"}],"pronunciation":{"ipa":"/ksinomiˈziθra ˈkritis/","respelling":"ksee-noh-mee-ZEE-thrah KREE-tees"},"region_polygon":{"type":"Polygon","coordinates":[[[23.45,35.65],[24.2,35.7],[25.2,35.45],[26.2,35.3],[26.3,34.95],[25.45,34.85],[24.2,34.95],[23.55,35.2],[23.45,35.45],[23.45,35.65]]]}},{"name":"Imokilly Regato","lat":51.95,"lon":-8.1,"country":"Ireland","where":"Imokilly, County Cork","hint":"South coast of Ireland","desc":"Italian-style hard cow\'s-milk grating cheese; Ireland\'s only PDO cheese.","image":"imokilly_regato.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["hard","pressed","italian-style"],"ageing_min_days":270,"format":"wheel, ~10 kg","year_recognized":1999,"animal_breed":null,"vegetarian":null,"desc_long":"Imokilly Regato is Ireland\'s only PDO cheese — and an unexpected one: a Romano-inspired hard pressed cow\'s-milk wheel made in Mogeely, County Cork by the Dairygold cooperative\'s Imokilly Cheese Company. The PDO restricts production to the Mogeely dairy and requires milk drawn from cows grazing the baronies of Imokilly, Fermoy and Muskerry in East Cork between March and October. Milk is pasteurised, cooled to 32–34 °C, set with rennet, the curd cut and pressed into wheels, then salted twice — the second salting done by hand. Wheels age nine to twelve months. EU PDO came in 1999. The cheese was developed when the cooperative looked for a way to add value to seasonal surplus milk by making a long-keeping Italian-style table cheese; the result is a hard, golden, faintly granular wheel with a clean, salty, savoury flavour that grates onto pasta, melts onto pizza, and stands at the curious geographic crossroads of Mediterranean technique and Atlantic-Irish pasture.","sources":[{"label":"Wikipedia: Imokilly Regato","url":"https://en.wikipedia.org/wiki/Imokilly_Regato"},{"label":"EUR-Lex: Commission Regulation (EC) No 2107/1999 (Imokilly Regato PDO, archived PDF)","url":"https://web.archive.org/web/20190215120428/https://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:L:1999:258:0003:0004:EN:PDF"}],"pronunciation":{"ipa":"/ɪˈmɒkɪli rɪˈɡɑːtoʊ/","respelling":"ih-MOK-il-ee re-GAH-toh"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.4,52.05],[-7.95,52.05],[-7.85,51.9],[-8.0,51.65],[-8.4,51.65],[-8.55,51.85],[-8.4,52.05]]]}},{"name":"Asiago","lat":45.87,"lon":11.51,"country":"Italy","where":"Asiago plateau, Veneto/Trentino","hint":"Asiago plateau, NE Italy","desc":"Cow\'s-milk cheese in fresh \'pressato\' or aged \'d\'allevo\' versions; staple of the high pastures above Vicenza.","image":"asiago.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["pressed","cooked-curd"],"ageing_min_days":20,"format":"wheel, 11–15 kg, 30–40 cm × ~15 cm","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Asiago is a cow\'s-milk cheese from northeastern Italy, produced across four provinces straddling the Veneto and Trentino-Alto Adige regions on and around the Asiago plateau. The PDO covers two recognisable styles that share a cooked-curd, pressed technique but diverge sharply in age: Asiago Pressato is matured only twenty to forty days and presents a soft, almost buttery paste with a pale ivory colour and gentle dairy sweetness, while Asiago d\'Allevo ranges from semi-hard mezzano (four to six months) to vecchio (around a year) and stravecchio (eighteen months or more), accumulating granular structure, savoury depth and a piquant edge that rivals harder grating cheeses. Both versions are produced as cylindrical wheels of roughly eleven to fifteen kilograms. The hill pastures above Vicenza give the d\'Allevo style a Slow Food following that prizes long-aged farmhouse lots.","sources":[{"label":"Wikipedia: Asiago cheese","url":"https://en.wikipedia.org/wiki/Asiago_cheese"},{"label":"Disciplinare di produzione DOP Asiago (archived)","url":"https://web.archive.org/web/20061017175249/http://www.milkonline.com/fiera/cheese/disciplinari/Asiago.htm"}],"pronunciation":{"ipa":"/aˈzjaːɡo/","respelling":"ah-ZYAH-goh"},"region_polygon":{"type":"Polygon","coordinates":[[[11.3,46.0],[11.6,46.1],[12.0,46.0],[12.2,45.85],[12.05,45.7],[11.65,45.65],[11.3,45.75],[11.25,45.9],[11.3,46.0]]]}},{"name":"Bitto","lat":46.2,"lon":9.6,"country":"Italy","where":"Valtellina, Lombardy","hint":"Valtellina valleys, Lombard Alps","desc":"Hard summer-only Alpine cow\'s-milk cheese (sometimes with goat); can age 10+ years.","image":"bitto.jpg","name_protections":["PDO"],"milk_types":["cow","goat"],"pasteurization":"raw","style":["hard","alpine","cooked-curd"],"ageing_min_days":70,"format":"wheel, ~9–25 kg, 30–50 cm diameter","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Bitto is an alpine cow\'s-milk cheese (with up to ten percent goat\'s milk permitted) made only during the summer high-pasture months in the upper Valtellina and Val Brembana valleys of Lombardy. Production happens at the malga huts above the treeline between June and September, where milk drawn moments after milking is set in copper cauldrons over wood fires, cooked, pressed and shaped into firm wheels. The PDO, granted in 1997, requires the cheese to age at least seventy days, but Bitto\'s defining trait is its capacity for extraordinarily long maturation — wheels routinely keep for five to ten years and remain edible, deepening into what is sometimes called a meditation cheese. The traditional protocol has been the subject of a long public dispute between producers using only on-pasture summer milk (the Storico Ribelle faction) and broader PDO rules that permit slightly more flexibility. The flavour is concentrated, nutty and intensely savoury, with a granular texture that fragments under the knife.","sources":[{"label":"Wikipedia: List of Italian PDO cheeses (Bitto)","url":"https://en.wikipedia.org/wiki/List_of_Italian_PDO_cheeses"}],"pronunciation":{"ipa":"/ˈbitto/","respelling":"BEET-toh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.4,46.3],[9.7,46.3],[9.85,46.25],[9.8,46.1],[9.65,46.05],[9.45,46.05],[9.35,46.15],[9.4,46.3]]]}},{"name":"Bra","lat":44.69,"lon":7.86,"country":"Italy","where":"Cuneo province, Piedmont","hint":"Piedmont","desc":"Pressed cow\'s-milk wheel in \'tenero\' (semi-soft) or \'duro\' (hard) versions; named after the town of Bra.","image":"bra.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["pressed"],"ageing_min_days":45,"format":"wheel, ~6 kg, 30–40 cm diameter, 7–9 cm tall","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Bra is a Piedmontese cow\'s-milk cheese — small additions of sheep and goat milk are also permitted — produced in the province of Cuneo and named for the market town through which it historically passed. Two PDO-recognised forms share the production but diverge by age: Bra tenero is pressed and ripened a minimum of forty-five days, yielding a pale, supple paste with mild buttery character, while Bra duro is matured six months or more, drying to a firmer cinnamon-coloured wheel with a piquant, lightly bitter finish. Either pasteurised or raw milk is allowed. The cheese received EU PDO recognition in 1996 and is most often eaten as a table cheese in the tenero form and grated or shaved over polenta and pasta in the duro form. The Alta Langa hill country that supplies the milk overlaps with Piedmont\'s most famous wine zones, and Bra finds easy pairings among local Nebbiolo and Barbera reds.","sources":[{"label":"Wikipedia: Bra cheese","url":"https://en.wikipedia.org/wiki/Bra_cheese"}],"pronunciation":{"ipa":"/bra/","respelling":"BRAH"},"region_polygon":{"type":"Polygon","coordinates":[[[7.4,44.8],[7.8,44.95],[8.1,44.85],[8.15,44.55],[7.95,44.3],[7.5,44.3],[7.35,44.45],[7.3,44.65],[7.4,44.8]]]}},{"name":"Caciocavallo Silano","lat":39.55,"lon":16.5,"country":"Italy","where":"Sila plateau & southern Apennines","hint":"Southern Italy","desc":"Pasta-filata cow\'s-milk cheese tied in pairs (\'on horseback\') and hung to age.","image":"caciocavallo_silano.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["pasta-filata","semi-hard"],"ageing_min_days":30,"format":"teardrop, ~1–2.5 kg, hung in pairs over a rope","year_recognized":1993,"animal_breed":null,"vegetarian":null,"desc_long":"Caciocavallo Silano is a stretched-curd cow\'s-milk cheese produced across five regions of southern Italy — Basilicata, Calabria, Campania, Molise and Apulia — its name preserving the centuries-old practice of tying wheels in pairs over a horizontal pole to age \'on horseback\' (a cavallo). The pasta-filata technique heats and stretches the curd into a pliable mass that is then formed by hand into a teardrop or gourd shape and tied off at the neck. Ageing begins at a minimum of thirty days and may continue for many months, during which the rind hardens to a smooth amber and the interior develops a firmer, increasingly savoury character. The PDO was granted in 1993 and covers what is functionally a family of related farmhouse and dairy production styles tied to the Sila plateau and the surrounding mountainous south. Sliced young the cheese is supple and milky; well aged it grates into a sharp seasoning for southern Italian baked pastas and polentas.","sources":[{"label":"Wikipedia: Caciocavallo","url":"https://en.wikipedia.org/wiki/Caciocavallo"},{"label":"Disciplinare di produzione DOP Caciocavallo Silano (Regione Campania, archived PDF)","url":"https://web.archive.org/web/20111004165208/http://www.sito.regione.campania.it/agricoltura/tipici/pdf/disciplinare-caciocavallo-silano.pdf"}],"pronunciation":{"ipa":"/kat.tʃo.kaˈvallo siˈlaːno/","respelling":"kah-choh-kah-VAHL-loh see-LAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[14.5,41.8],[15.5,42.0],[16.8,41.5],[17.1,40.5],[17.3,39.8],[17.2,38.9],[16.1,38.4],[15.7,38.55],[15.65,39.5],[14.8,40.5],[14.5,41.3],[14.5,41.8]]]}},{"name":"Canestrato di Moliterno","lat":40.24,"lon":15.86,"country":"Italy","where":"Basilicata","hint":"Lucanian Apennines","desc":"Hard sheep/goat-milk cheese aged in \'fondaco\' cellars at Moliterno; basket-imprinted rind.","image":"canestrato_di_moliterno.jpg","name_protections":["PGI"],"milk_types":["sheep","goat"],"pasteurization":null,"style":["hard","basket-pressed"],"ageing_min_days":60,"format":"wheel pressed in reed basket","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Canestrato di Moliterno is a hard, basket-pressed cheese from Basilicata in southern Italy, made from a blend of sheep and goat milk. The name comes from its production in canestri — woven reed baskets that imprint a characteristic ridged pattern on the rind during pressing. Wheels mature for a minimum of sixty days in cool cellars known as fondaci, where they take on a firmer interior and a pungent, savoury character that suits both table use and grating. Italian PGI status was registered in 2010, formalising a tradition rooted in the small mountain dairies of the Val d\'Agri. Younger wheels remain supple and milky, while longer ageing pushes the flavour toward sharp piquant notes that complement Lucanian cured meats.","sources":[{"label":"Wikipedia: Canestrato di Moliterno","url":"https://en.wikipedia.org/wiki/Canestrato_di_Moliterno"}],"pronunciation":{"ipa":"/ka.neˈstraːto di mo.liˈtɛrno/","respelling":"kah-nes-TRAH-toh dee moh-lee-TAIR-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[15.7,40.4],[15.95,40.45],[16.15,40.4],[16.2,40.15],[16.05,39.95],[15.8,39.9],[15.65,40.1],[15.7,40.4]]]}},{"name":"Canestrato Pugliese","lat":41.46,"lon":15.55,"country":"Italy","where":"Foggia & Bari, Apulia","hint":"Apulia","desc":"Hard sheep\'s-milk cheese pressed in reed baskets (canestri) that mark the rind.","image":"canestrato_pugliese.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":null,"style":["hard","basket-pressed"],"ageing_min_days":null,"format":"wheel pressed in reed basket","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Canestrato Pugliese is a hard basket-pressed cheese from the province of Foggia in northern Apulia, traditionally made from the milk of Gentile di Puglia and other native sheep that moved seasonally across the Tavoliere plain. The cheese takes its name from the canestro, a reed basket that drains and shapes the curd and leaves a distinctive ribbed imprint on the rind. After salting and several months of ageing, the wheels develop a firm straw-coloured paste and a robust, savoury flavour with a salty finish. The EU recognised Canestrato Pugliese as a PDO in 1996. It is most often served grated over hearty pasta dishes or sliced thinly alongside cured meats and crusty Apulian bread.","sources":[{"label":"Wikipedia: Canestrato Pugliese","url":"https://en.wikipedia.org/wiki/Canestrato_Pugliese"}],"pronunciation":{"ipa":"/ka.neˈstraːto puʎˈʎeːze/","respelling":"kah-nes-TRAH-toh poo-LYAY-zay"},"region_polygon":{"type":"Polygon","coordinates":[[[15.2,41.95],[15.8,42.0],[16.2,41.9],[17.0,41.3],[16.8,40.95],[16.2,40.85],[15.4,41.1],[15.1,41.4],[15.2,41.95]]]}},{"name":"Casatella Trevigiana","lat":45.67,"lon":12.25,"country":"Italy","where":"Treviso province, Veneto","hint":"Veneto, near Treviso","desc":"Soft fresh cow\'s-milk cheese, mild and milky; eaten very young, spreads like butter.","image":"casatella_trevigiana.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["fresh","soft"],"ageing_min_days":4,"format":"small wheel 200–700 g, or large wheel ~2 kg","year_recognized":2008,"animal_breed":["Frisona","Pezzata Rossa","Bruna","Burlina"],"vegetarian":false,"desc_long":"Casatella Trevigiana is a fresh, soft cow\'s-milk cheese produced across the entire Province of Treviso in the Veneto. The PDO specifies milk drawn from Frisona, Pezzata Rossa, Bruna and Burlina cattle whose daily feed must be at least ninety percent local forage. The milk is pasteurised, set with bovine rennet, gently broken to hazelnut-sized curds, then moulded and briefly brined; ripening lasts only four to eight days at refrigerator temperatures, after which the cheese is ready to eat. It is sold either as small individual pieces of about 200 to 700 grams or as larger wheels of around two kilograms. The paste is white to cream, the rind is barely formed, and the character is mild and milky with a clean lactic tang — a casual table cheese paired naturally with soft polenta, charcuterie, and the wines of the surrounding hills.","sources":[{"label":"Casatella Trevigiana PDO specification (qualigeo.eu)","url":"https://www.qualigeo.eu/en/product/casatella-trevigiana-pdo/"},{"label":"EU PDO application (eur-lex)","url":"https://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:C:2007:204:0020:0023:EN:PDF"}],"pronunciation":{"ipa":"/ka.zaˈtɛlla tre.viˈdʒaːna/","respelling":"kah-zah-TEL-lah tre-vee-JAH-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[11.85,46.05],[12.2,46.1],[12.55,45.95],[12.75,45.7],[12.65,45.5],[12.2,45.45],[11.85,45.55],[11.8,45.85],[11.85,46.05]]]}},{"name":"Casciotta d\'Urbino","lat":43.72,"lon":12.64,"country":"Italy","where":"Pesaro-Urbino, Marche","hint":"Marche, hills around Urbino","desc":"Soft sheep-and-cow milk cheese with delicate sweet flavor; favored by Michelangelo.","image":"casciotta_durbino.jpg","name_protections":["PDO"],"milk_types":["sheep","cow"],"pasteurization":"pasteurized","style":["semi-soft","fresh"],"ageing_min_days":14,"format":"wheel, 800 g – 1.2 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Casciotta d\'Urbino is a small semi-soft cheese from the Marche region, produced in the province of Pesaro and Urbino. The recipe blends roughly seventy to eighty percent sheep\'s milk with twenty to thirty percent cow\'s milk; the result is a paler and milder cheese than a pure sheep\'s-milk pecorino, with a soft, crumbly texture and a delicate dairy sweetness. Wheels weigh between 800 grams and 1.2 kilograms and ripen for as little as two weeks before going to market. The cheese received EU PDO recognition in 1996, though the dialect word \'casciotta\' is much older and in this region denotes a traditional class of small farmhouse table cheeses. It is most often eaten fresh as a table cheese.","sources":[{"label":"Wikipedia: Casciotta d\'Urbino","url":"https://en.wikipedia.org/wiki/Casciotta_d%27Urbino"}],"pronunciation":{"ipa":"/kaˈʃɔtta durˈbiːno/","respelling":"kah-SHOT-tah door-BEE-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[12.2,43.95],[12.5,44.0],[12.85,43.95],[13.0,43.75],[12.95,43.55],[12.65,43.55],[12.3,43.65],[12.2,43.85],[12.2,43.95]]]}},{"name":"Castelmagno","lat":44.42,"lon":7.18,"country":"Italy","where":"Cuneo province, Piedmont","hint":"Maritime Alps, Piedmont","desc":"Crumbly raw cow\'s-milk wheel aged in caves; sometimes naturally veers blue with age.","image":"castelmagno.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","blue"],"ageing_min_days":60,"format":"wheel, 2–7 kg","year_recognized":1996,"animal_breed":["Piedmontese"],"vegetarian":null,"desc_long":"Castelmagno is a semi-hard cow\'s-milk cheese from the Valle Grana in the province of Cuneo, produced in only three Piedmontese municipalities and named for the village of Castelmagno itself. Milk drawn from local Piedmontese cattle (and, by tradition, sometimes mixed with small additions of sheep or goat milk) is set raw and then aged for at least sixty days in cool stone cellars, where the wheels develop a thin natural rind and a paste that crumbles cleanly. With longer maturation, naturally occurring moulds occasionally produce a streak of blue veining through the interior, lending the cheese a sharp, almost piquant edge alongside its lactic core. The EU recognised the PDO in 1996, formalising centuries of production in the Maritime Alps. Castelmagno appears widely in Piedmontese cuisine — shaved over gnocchi, stirred into risotto, and partnered with the region\'s powerful Nebbiolo reds.","sources":[{"label":"Wikipedia: Castelmagno cheese","url":"https://en.wikipedia.org/wiki/Castelmagno_cheese"},{"label":"Disciplinare di produzione DOP Castelmagno (Regione Piemonte)","url":"https://www.regione.piemonte.it/governo/bollettino/abbonati/2005/13/siste/00000002.htm"}],"pronunciation":{"ipa":"/ka.stelˈmaɲɲo/","respelling":"kah-stel-MAH-nyoh"},"region_polygon":{"type":"Polygon","coordinates":[[[7.1,44.45],[7.25,44.45],[7.35,44.42],[7.38,44.32],[7.25,44.28],[7.1,44.32],[7.05,44.4],[7.1,44.45]]]}},{"name":"Fiore Sardo","lat":40.2,"lon":9.1,"country":"Italy","where":"Sardinia","hint":"Inland Sardinia","desc":"Hard raw sheep\'s-milk shepherd\'s cheese, lightly smoked over open hearths; ancient pre-Roman style.","image":"fiore_sardo.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","smoked"],"ageing_min_days":105,"format":"wheel, 3–4 kg, conical sides","year_recognized":1996,"animal_breed":["Sarda"],"vegetarian":false,"desc_long":"Fiore Sardo is a raw sheep\'s-milk cheese from Sardinia, made from the whole milk of native Sarda ewes and set with lamb or kid rennet in copper cauldrons known as lapiolos. After breaking, the curd is hand-kneaded into characteristic concave-sided wheels, scalded briefly in hot water, brined for a day and a half, and then smoked over Mediterranean shrubs for ten to fifteen days, which leaves the rind a deep golden colour. Ripening continues in cool damp cellars for a minimum of three and a half months for table use and at least six months for grating-grade wheels of three to four kilograms. The PDO was granted in 1996, but Fiore Sardo\'s roots run back through Sardinian pastoral tradition, predating the more industrial Pecorino Sardo. The flavour is concentrated and faintly smoky, with the salty, slightly piquant intensity that comes of true raw-milk ageing.","sources":[{"label":"Wikipedia: Fiore Sardo","url":"https://en.wikipedia.org/wiki/Fiore_Sardo"},{"label":"Qualigeo Fiore Sardo PDO spec","url":"https://www.qualigeo.eu/en/product/fiore-sardo-pdo/"}],"pronunciation":{"ipa":"/ˈfjoːre ˈsardo/","respelling":"FYOH-ray SAR-doh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.2,41.25],[8.85,41.2],[9.6,41.1],[9.85,40.5],[9.85,39.8],[9.5,39.1],[9.1,38.9],[8.55,38.9],[8.3,39.4],[8.3,40.2],[8.15,40.65],[8.2,41.25]]]}},{"name":"Fontina","lat":45.74,"lon":7.32,"country":"Italy","where":"Aosta Valley","hint":"Aosta Valley","desc":"Soft, supple cow\'s-milk Alpine cheese that melts into fonduta valdostana.","image":"fontina.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-soft","washed-rind"],"ageing_min_days":80,"format":"wheel, ~8–12 kg, ~40 cm diameter","year_recognized":1996,"animal_breed":["Valdostana"],"vegetarian":false,"desc_long":"Fontina is a semi-soft cow\'s-milk cheese produced exclusively in the Aosta Valley, the small autonomous region tucked into the Italian side of the western Alps. The PDO requires unpasteurised milk from a single milking of native Valdostana cattle, processed twice daily and pressed into wheels of about eight to twelve kilograms before being aged on wooden boards in cool, humid Alpine cellars. As the wheels mature, a thin orange washed rind develops over a pale ivory paste shot through with a few small holes; the texture stays supple while the flavour deepens from milky and grassy in younger wheels to mushroomy, nutty and intensely savoury after several months. EU PDO recognition came in 1996. The cheese melts cleanly without separating, which is why it has become the obligatory base of the regional dish fonduta valdostana, served warm with white truffle when in season.","sources":[{"label":"Wikipedia: Fontina","url":"https://en.wikipedia.org/wiki/Fontina"}],"pronunciation":{"ipa":"/fonˈtiːna/","respelling":"fohn-TEE-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[6.85,45.95],[7.1,45.92],[7.4,45.95],[7.8,45.95],[7.95,45.85],[7.85,45.65],[7.45,45.55],[7.1,45.65],[6.9,45.75],[6.85,45.95]]]}},{"name":"Formaggella del Luinese","lat":46.0,"lon":8.74,"country":"Italy","where":"Varese province, Lombardy","hint":"Lake Maggiore, Lombardy","desc":"Soft raw goat\'s-milk cheese with bloomy rind; from hills above Lake Maggiore.","image":"formaggella_del_luinese.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["semi-hard"],"ageing_min_days":20,"format":"small wheel, ~700–900 g","year_recognized":2011,"animal_breed":["Camosciata delle Alpi","Nera di Verzasca","Saanen"],"vegetarian":null,"desc_long":"Formaggella del Luinese is a semi-hard goat\'s-milk cheese from the hills of the northern Varese province, named for the town of Luino on the eastern shore of Lake Maggiore. The PDO specifies whole raw milk from Camosciata delle Alpi, Nera di Verzasca and Saanen goats, processed within thirty hours of milking and aged for a minimum of twenty days in cool cellars. Wheels are small — a kilogram or under — with a thin natural rind and a pale ivory paste that holds together tightly but yields under the knife. The flavour is mild and gently caprine, with the clean lactic tang and slight floral character that comes of pasture-fed goat milk; longer-aged wheels turn firmer and more concentrated. PDO recognition was granted in 2011, making it one of the more recently registered Italian goat cheeses.","sources":[{"label":"Qualigeo Formaggella del Luinese PDO spec","url":"https://www.qualigeo.eu/en/product/formaggella-del-luinese-pdo/"}],"pronunciation":{"ipa":"/for.madˈdʒɛlla del lwiˈneːze/","respelling":"for-mah-JEL-lah del lwee-NAY-zay"},"region_polygon":{"type":"Polygon","coordinates":[[[8.6,46.2],[8.85,46.2],[9.0,46.1],[9.05,45.95],[8.9,45.85],[8.65,45.85],[8.55,46.0],[8.6,46.2]]]}},{"name":"Formaggio di Fossa di Sogliano","lat":44.0,"lon":12.3,"country":"Italy","where":"Emilia-Romagna & Marche","hint":"Romagna-Marche border","desc":"Sheep (or cow) cheese aged 80–100 days in tufa pits; emerges with sharp, complex pungency.","image":"formaggio_fossa_sogliano.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":null,"style":["semi-hard","pit-ripened"],"ageing_min_days":80,"format":"irregular block ~500–900 g, no rind","year_recognized":2009,"animal_breed":null,"vegetarian":null,"desc_long":"Formaggio di Fossa di Sogliano is a unique pit-ripened cheese from the Romagna-Marche borderlands, made variously from cow\'s, sheep\'s or goat\'s milk (or blends) and finished by months underground. After initial moulding the wheels are wrapped in cotton or canvas bags and lowered into flask-shaped tufa pits dug into the rock around Sogliano al Rubicone — pits that may be ten or more years old, perpetually re-used, and a few metres deep. The anaerobic, humid conditions inside the fossa, packed with neighbouring bundles and warmed by their own fermentation, transform the cheese over eighty to a hundred days into an irregular, almost crustless block of pale paste with a sharp, herbaceous, slightly bitter character. The PDO was granted in 2009. Tradition fixes the pit-opening on Saint Catherine\'s Day on the twenty-fifth of November, when the cheese is \'resurrected\' to fairs that draw producers and curious eaters across the region.","sources":[{"label":"Wikipedia: Formaggio di Fossa","url":"https://en.wikipedia.org/wiki/Formaggio_di_fossa"}],"pronunciation":{"ipa":"/forˈmaddʒo di ˈfɔssa di soʎˈʎaːno/","respelling":"for-MAH-joh dee FOH-sah dee soh-LYAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[12.1,44.2],[12.4,44.25],[12.65,44.1],[12.85,43.85],[12.75,43.65],[12.4,43.65],[12.2,43.85],[12.05,44.05],[12.1,44.2]]]}},{"name":"Formai de Mut dell\'Alta Valle Brembana","lat":45.99,"lon":9.78,"country":"Italy","where":"Upper Brembana valley, Bergamo","hint":"Bergamo Alps","desc":"Alpine cow\'s-milk cheese with small eyes; summer-only mountain production.","image":"formai_de_mut_dellalta_valle_brembana.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","alpine","cooked-curd"],"ageing_min_days":45,"format":"wheel, 8–12 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Formai de Mut dell\'Alta Valle Brembana is a raw cow\'s-milk Alpine cheese from the upper Brembana valley in the province of Bergamo, made traditionally during the summer transhumance when herds move to the malga huts above the tree line. Whole evening and morning milk are combined, set with rennet, gently cooked and pressed into wheels of around eight to twelve kilograms, which age on wooden boards in cool cellars for at least a month and a half. The thin natural rind protects a pliable straw-coloured paste shot through with a sparse pattern of small holes; the flavour begins gently floral and grassy in young wheels and grows fruitier and more aromatic as the cheese matures over six months or more. PDO recognition came in 1996. The cheese is best appreciated lightly aged as a table cheese, paired with the rye breads and polenta typical of the Bergamasque mountains.","sources":[{"label":"Wikipedia: Formai de Mut dell\'Alta Valle Brembana","url":"https://en.wikipedia.org/wiki/Formai_de_Mut_dell%27Alta_Valle_Brembana"}],"pronunciation":{"ipa":"/forˈmai de ˈmut/","respelling":"for-MY day MOOT"},"region_polygon":{"type":"Polygon","coordinates":[[[9.65,46.1],[9.85,46.1],[10.0,46.05],[10.05,45.9],[9.9,45.8],[9.7,45.85],[9.6,46.0],[9.65,46.1]]]}},{"name":"Gorgonzola","lat":45.53,"lon":9.4,"country":"Italy","where":"Lombardy & Piedmont","hint":"Po Valley around Milan","desc":"Cow\'s-milk blue, soft \'dolce\' or firmer \'piccante\'; named for a Milanese town.","image":"gorgonzola.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["soft","blue","natural-rind"],"ageing_min_days":50,"format":"cylinder, ~9–13 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Gorgonzola is a soft cow\'s-milk blue cheese from the Po Valley, with PDO production covering numerous provinces of Lombardy and Piedmont and traditionally taking its name from the town of Gorgonzola just east of Milan. Pasteurised milk is set, drained, lightly salted and spiked with Penicillium spores; the wheels are then pierced with needles to admit air and grow the characteristic greenish-blue veins through a soft white paste. Two PDO styles share the recipe but diverge in age and intensity: Gorgonzola Dolce, ripened around fifty days, is mild, sweet and spoonably creamy; Gorgonzola Piccante is aged closer to three months and turns firmer, drier and assertively sharp. EU PDO came in 1996. The cheese is iconic in Italian cooking — folded into risotto, melted over pasta, paired with pears, walnuts and full-bodied red wines like Amarone.","sources":[{"label":"Wikipedia: Gorgonzola","url":"https://en.wikipedia.org/wiki/Gorgonzola"},{"label":"Regione Lombardia: Gorgonzola DOP","url":"https://www.buonalombardia.regione.lombardia.it/wps/portal/site/buonalombardia/DettaglioRedazionale/prodotti/dop/gorgonzola-dop"}],"pronunciation":{"ipa":"/ɡor.ɡonˈdzɔːla/","respelling":"gor-gohn-DZOH-lah"},"region_polygon":{"type":"Polygon","coordinates":[[[7.5,46.0],[8.5,46.2],[10.2,46.0],[10.8,45.4],[10.5,44.95],[9.3,44.85],[8.0,44.85],[7.3,45.3],[7.2,45.7],[7.5,46.0]]]}},{"name":"Grana Padano","lat":45.1,"lon":10.5,"country":"Italy","where":"Po Valley (five regions)","hint":"Po Valley","desc":"Hard cow\'s-milk grating cheese, slightly milder than Parmigiano with a broader production area.","image":"grana_padano.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","grana","cooked","pressed","granular"],"ageing_min_days":270,"format":"wheel, 24–40 kg, 35–45 cm × 15–18 cm","year_recognized":1955,"animal_breed":null,"vegetarian":false,"desc_long":"Grana Padano is a hard, cooked-curd cow\'s-milk cheese produced across a broad swathe of the Po Valley spanning Piedmont, Lombardy, Veneto, Emilia-Romagna, parts of Trento and South Tyrol — the widest production zone of any Italian PDO grana cheese. Daily production combines partially skimmed milk from twice-daily milkings in copper cauldrons, where it is set with calf rennet and natural whey starter, cooked, and broken into rice-grain curds before being pressed into the familiar large wheels of twenty-four to forty kilograms. Maturation runs a minimum of nine months and as long as twenty months or more for the Riserva grade, on wooden boards in temperature-controlled storehouses where the wheels are turned regularly. Italian protection followed in 1955 and EU PDO recognition in 1996. Grana Padano is milder and somewhat less complex than Parmigiano Reggiano — the spec permits silage in cattle feed and a slightly broader regional milk supply — but the same fundamental craft produces an indispensable grating and table cheese with a clean, sweet, deeply savoury flavour.","sources":[{"label":"Wikipedia: Grana Padano","url":"https://en.wikipedia.org/wiki/Grana_Padano"},{"label":"Grana Padano PDO specifications (Consorzio, PDF)","url":"https://www.granapadano.it/public/file/SpecificationsGBOct2022-50252.pdf"}],"pronunciation":{"ipa":"/ˈɡraːna paˈdaːno/","respelling":"GRAH-nah pah-DAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[7.2,46.1],[8.5,46.5],[11.0,46.5],[13.5,46.1],[13.2,45.5],[12.2,45.2],[10.5,44.8],[9.3,44.85],[7.7,44.8],[7.1,45.15],[7.0,45.7],[7.2,46.1]]]}},{"name":"Montasio","lat":46.4,"lon":13.4,"country":"Italy","where":"Friuli-Venezia Giulia & eastern Veneto","hint":"Friuli & eastern Veneto","desc":"Cow\'s-milk wheel aged from fresh table cheese to grating-old; the curd of frico.","image":"montasio.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","cooked-curd","pressed"],"ageing_min_days":60,"format":"wheel, ~6–8 kg","year_recognized":1986,"animal_breed":null,"vegetarian":null,"desc_long":"Montasio is a cow\'s-milk cheese from northeastern Italy, produced across Friuli-Venezia Giulia and the eastern strip of the Veneto and named for the Montasio plateau where the recipe is reputed to have originated in the medieval abbey of Moggio Udinese. The curd is gently cooked, pressed and aged for a minimum of two months, with longer maturation moving the cheese from a supple, pale yellow young version through firmer, more aromatic table forms and finally into hard, grating wheels of a year or more. Italian protection came in 1986, well before the EU PDO scheme. Beyond the cheese plate, Montasio is the obligatory base of frico — the Friulian crisped-cheese dish, eaten on its own or stretched with potato — and it slips naturally into Alpine cooking alongside polenta, smoked pork and the region\'s white wines.","sources":[{"label":"Wikipedia: Montasio","url":"https://en.wikipedia.org/wiki/Montasio"}],"pronunciation":{"ipa":"/monˈtaːzjo/","respelling":"mohn-TAH-zyoh"},"region_polygon":{"type":"Polygon","coordinates":[[[12.4,46.55],[13.2,46.55],[13.85,46.5],[13.85,46.0],[13.5,45.65],[12.85,45.55],[12.4,45.85],[12.3,46.2],[12.4,46.55]]]}},{"name":"Monte Veronese","lat":45.6,"lon":11.0,"country":"Italy","where":"Lessini mountains, Verona","hint":"Lessini mountains north of Verona","desc":"Cow\'s-milk cheese in whole-milk or \'allevo\' (semi-skim, aged) form.","image":"monte_veronese.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","pressed"],"ageing_min_days":25,"format":"wheel, 6–10 kg, 25–35 cm diameter","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Monte Veronese is a raw cow\'s-milk cheese from the Lessini Mountains and prealps north of Verona, with the PDO covering two related but distinct forms made from the same milk supply. Monte Veronese Latte Intero uses whole milk and is matured roughly twenty-five days to two months, yielding a pale wheel of seven to ten kilograms with a fine eye structure and a sweet, gently fruity flavour. Monte Veronese d\'Allevo is produced from partially skimmed milk and aged longer — sixty days for the table version and six months or more for the grating version — developing more pronounced, fragrant and slightly piquant character. Italian denomination followed in 1993 and EU PDO recognition in 1996. The two styles together cover the spectrum from a milky everyday table cheese to a sharp finishing cheese shaved over polenta and risotto.","sources":[{"label":"Wikipedia: Monte Veronese","url":"https://en.wikipedia.org/wiki/Monte_Veronese"},{"label":"Gazzetta Ufficiale: DPCM 9 aprile 1993 (DOP Monte Veronese)","url":"http://www.gazzettaufficiale.it/eli/id/1993/08/21/093A4656/sg"},{"label":"EUR-Lex: Commission Regulation (EC) No 1263/96 (GI registration)","url":"http://eur-lex.europa.eu/legal-content/EN/TXT/?qid=1405160711350&uri=CELEX:31996R1263"}],"pronunciation":{"ipa":"/ˈmonte ve.roˈneːze/","respelling":"MOHN-tay vay-roh-NAY-zay"},"region_polygon":{"type":"Polygon","coordinates":[[[10.8,45.75],[11.1,45.8],[11.3,45.75],[11.3,45.55],[11.1,45.45],[10.85,45.5],[10.75,45.65],[10.8,45.75]]]}},{"name":"Mozzarella di Bufala Campana","lat":41.0,"lon":14.3,"country":"Italy","where":"Campania (& parts of Lazio, Apulia, Molise)","hint":"Coastal plain south of Naples","desc":"Fresh stretched-curd water-buffalo milk; the original mozzarella, eaten within days.","image":"mozzarella_di_bufala_campana.jpg","name_protections":["PDO"],"milk_types":["buffalo"],"pasteurization":"any","style":["fresh","soft","pasta-filata"],"ageing_min_days":null,"format":"ball, typically 100–500 g","year_recognized":1993,"animal_breed":["Italian Mediterranean buffalo"],"vegetarian":null,"desc_long":"Mozzarella di Bufala Campana is a fresh stretched-curd cheese made from the milk of Italian Mediterranean water buffalo, produced under PDO rules across a designated zone that takes in much of the Campania coastal plain as well as parts of Lazio, Molise and northern Apulia. Milk is set with rennet and broken into curds that are heated and then worked in hot water until the proteins draw out into long elastic strands; the mass is hand-torn or cut into balls (mozzata, the word that gives the cheese its name), brined, packed in their own whey and eaten within days. The result is a glossy white ball with a thin skin and a moist, layered interior that breaks open into milky strands when cut. EU PDO came in 1996 following Italian protection in 1993. Far richer and more aromatic than cow\'s-milk mozzarella, the buffalo version is the centerpiece of caprese, the gold standard topping for Neapolitan pizza, and a fresh cheese best eaten at room temperature with little adornment.","sources":[{"label":"Wikipedia: Mozzarella di bufala campana","url":"https://en.wikipedia.org/wiki/Mozzarella_di_bufala_campana"},{"label":"EUR-Lex: Commission Regulation (EC) No 1107/96 (PDO registration)","url":"https://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=CELEX:31996R1107:EN:HTML"}],"pronunciation":{"ipa":"/mot.tsaˈrɛlla di ˈbuːfala kamˈpaːna/","respelling":"moht-tsah-REL-lah dee BOO-fah-lah kam-PAH-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[13.3,41.5],[13.8,41.65],[14.4,41.55],[15.4,41.45],[15.8,41.3],[15.6,40.65],[15.4,40.05],[14.85,40.0],[14.3,40.45],[13.65,40.95],[13.2,41.2],[13.3,41.5]]]}},{"name":"Murazzano","lat":44.47,"lon":7.97,"country":"Italy","where":"Alta Langa, Piedmont","hint":"Alta Langa hills, Piedmont","desc":"Soft cylindrical sheep\'s-milk cheese (some cow allowed); mild and dairy-sweet.","image":"murazzano.jpg","name_protections":["PDO"],"milk_types":["sheep","cow"],"pasteurization":null,"style":["fresh","soft"],"ageing_min_days":4,"format":"cylinder, 300–400 g, 10–15 cm diameter","year_recognized":1996,"animal_breed":["delle Langhe"],"vegetarian":null,"desc_long":"Murazzano is a small fresh cheese from the Alta Langa hills of southern Piedmont, traditionally made from the milk of delle Langhe sheep with the option to add up to forty percent cow\'s milk. The PDO covers around fifty municipalities in the province of Cuneo and dates back to a tradition far older than its formal recognition. Milk is set with liquid rennet at roughly body temperature, the curd is gently broken and ladled into the perforated cylindrical fascelle moulds, lightly dry-salted and rested only a few days — a minimum of four — before the small disks are ready to eat. The wheels are little, 300 to 400 grams, with white slightly fringed surfaces and a soft, almost milky paste underneath. The flavour is fresh, dairy-sweet and lightly herbal; older wheels turn firmer and more concentrated and pair beautifully with Langhe red wines and the local hazelnuts that dominate the surrounding hillsides.","sources":[{"label":"Qualigeo Murazzano PDO spec","url":"https://www.qualigeo.eu/en/product/murazzano-pdo/"}],"pronunciation":{"ipa":"/mu.ratˈtsaːno/","respelling":"moo-rah-TSAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[7.85,44.55],[8.1,44.55],[8.3,44.45],[8.3,44.3],[8.1,44.2],[7.85,44.25],[7.8,44.4],[7.85,44.55]]]}},{"name":"Nostrano Valtrompia","lat":45.78,"lon":10.18,"country":"Italy","where":"Val Trompia, Brescia","hint":"Brescian pre-Alps","desc":"Hard cow\'s-milk wheel sometimes flavored with saffron; a year-plus of ageing.","image":"nostrano_valtrompia.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","cooked-curd","pressed"],"ageing_min_days":365,"format":"wheel, 8–18 kg, 30–45 cm × 8–12 cm","year_recognized":2012,"animal_breed":null,"vegetarian":null,"desc_long":"Nostrano Valtrompia is a hard cow\'s-milk cheese from the Val Trompia and a handful of adjoining municipalities in the province of Brescia, distinguished by a small but defining ingredient — saffron, added at the milk stage to brighten what would otherwise be a paler partially-skimmed paste. Raw milk from up to four milkings is pooled in single-walled copper vats heated over open flame, cooked to around fifty degrees and pressed into substantial wheels of eight to eighteen kilograms. Maturation runs a minimum of twelve months in cool stone cellars, where the rind hardens to an amber crust and the interior turns straw-yellow and increasingly granular. PDO recognition came in 2012. Long-aged Nostrano develops a sharp, intensely savoury character with the warm aromatic suggestion of the saffron underneath, and is most often grated over polenta or eaten in thin slivers as a finishing cheese.","sources":[{"label":"Qualigeo / East Lombardy Nostrano Valtrompia spec","url":"https://www.eastlombardy.it/en/prodotti-tipici/brescia/nostrano-valtrompia/"}],"pronunciation":{"ipa":"/noˈstraːno valˈtrompja/","respelling":"noh-STRAH-noh val-TROHM-pyah"},"region_polygon":{"type":"Polygon","coordinates":[[[10.05,45.95],[10.25,45.95],[10.4,45.85],[10.4,45.7],[10.25,45.55],[10.1,45.55],[10.0,45.75],[10.05,45.95]]]}},{"name":"Parmigiano Reggiano","lat":44.7,"lon":10.63,"country":"Italy","where":"Parma, Reggio Emilia, Modena, Bologna (W of Reno), Mantua (S of Po)","hint":"Emilia, between Bologna and Modena","desc":"Hard aged cow\'s-milk grating cheese, 12-36+ months; each wheel inspected and pin-fire-branded.","image":"parmigiano_reggiano.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","grana","cooked","pressed","granular"],"ageing_min_days":365,"format":"wheel, ~38 kg, 40–45 cm × 18–24 cm","year_recognized":1955,"animal_breed":["Friesian","Reggiana"],"vegetarian":false,"desc_long":"Parmigiano Reggiano is a hard, cooked-curd cow\'s-milk cheese produced in the provinces of Parma, Reggio Emilia, Modena, Bologna (west of the Reno) and Mantua (south of the Po), in the Emilia heartland of northern Italy. The day\'s production begins with a blend of partially skimmed evening milk and whole morning milk, set in copper cauldrons with calf rennet and a natural whey starter and then cooked to about 55 °C before being pressed into the iconic 38-kilogram wheels. After roughly three weeks of brining in Mediterranean sea salt, the wheels age on wooden boards for a minimum of twelve months, with stravecchio versions extending to three years and beyond. The Consorzio Parmigiano Reggiano was founded in 1934 and Italian national protection followed in 1955; EU PDO recognition came in 1996. The flavour is intensely savoury, complex, and high in free glutamates, and the long ageing and rigorous wheel-by-wheel inspection have made Parmigiano Reggiano the benchmark for grana-family cheeses worldwide.","sources":[{"label":"Wikipedia: Parmigiano Reggiano","url":"https://en.wikipedia.org/wiki/Parmigiano_Reggiano"}],"pronunciation":{"ipa":"/par.miˈdʒaːno redˈdʒaːno/","respelling":"par-mih-JAH-noh reh-JAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.65,45.1],[10.2,45.2],[11.1,45.15],[11.5,44.65],[11.3,44.1],[10.5,44.1],[9.9,44.3],[9.65,44.6],[9.6,44.9],[9.65,45.1]]]}},{"name":"Pecorino di Filiano","lat":40.69,"lon":15.66,"country":"Italy","where":"Potenza province, Basilicata","hint":"Lucanian Apennines","desc":"Hard sheep\'s-milk cheese rubbed with olive oil and wine vinegar during ageing.","image":"pecorino_di_filiano.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard"],"ageing_min_days":180,"format":"wheel, 2.5–5 kg","year_recognized":2007,"animal_breed":null,"vegetarian":null,"desc_long":"Pecorino di Filiano is a hard sheep\'s-milk cheese from the province of Potenza in Basilicata, taking its name from the town of Filiano in the Apennine highlands where the recipe is preserved by a small consortium of producers. The milk is raw, set with lamb rennet and worked in the traditional way, and the resulting wheels age a minimum of six months in cool, humid cellars — long enough to develop a firm straw-coloured paste and a thin natural rind. EU PDO recognition came in 2007. The cheese has the concentrated, frankly savoury character of southern Italian raw-milk pecorini, with a piquant edge that sharpens further over a year or more of ageing. An annual September festival in Filiano celebrates the new production.","sources":[{"label":"Wikipedia: Pecorino di Filiano","url":"https://en.wikipedia.org/wiki/Pecorino_di_Filiano"},{"label":"Guide to PDO/PGI products: Pecorino di Filiano (archived)","url":"https://web.archive.org/web/20150103142550/http://www.10q.it/prodottoDO.php?id_prodotto=163&lang=en"}],"pronunciation":{"ipa":"/pe.koˈriːno di fiˈljaːno/","respelling":"peh-koh-REE-noh dee fee-LYAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[15.4,40.85],[15.65,40.85],[15.85,40.75],[15.85,40.55],[15.7,40.4],[15.45,40.45],[15.35,40.65],[15.4,40.85]]]}},{"name":"Pecorino di Picinisco","lat":41.65,"lon":13.83,"country":"Italy","where":"Comino valley, Lazio","hint":"Apennines of southern Lazio","desc":"Hard sheep\'s-milk cheese from Apennine pastures; \'scamosciato\' young, \'stagionato\' aged.","image":"pecorino_di_picinisco.png","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["hard","uncooked"],"ageing_min_days":30,"format":"cylinder, ~1–2.5 kg","year_recognized":2013,"animal_breed":null,"vegetarian":null,"desc_long":"Pecorino di Picinisco is a raw sheep\'s-milk cheese from the Comino valley in the southern Lazio province of Frosinone, with the PDO allowing up to a quarter of the milk to come from goats grazing the same Apennine pastures. The cheese is made in two recognised forms: scamosciato, ripened between thirty and sixty days, presents a soft, supple paste and a mild, dairy-forward flavour; stagionato is aged ninety days or more, drying into a firmer, more compact cheese with a wrinkled rind and concentrated, lightly piquant character that grows sharper over time. EU PDO recognition came in 2013. Both versions speak distinctly of mountain pasture — the herb-rich air and wild forage of the central Apennines come through clearly in the cheese.","sources":[{"label":"Qualigeo Pecorino di Picinisco PDO spec","url":"https://www.qualigeo.eu/en/product/pecorino-di-picinisco-pdo/"}],"pronunciation":{"ipa":"/pe.koˈriːno di pi.tʃiˈnisko/","respelling":"peh-koh-REE-noh dee pee-chee-NEES-koh"},"region_polygon":{"type":"Polygon","coordinates":[[[13.7,41.75],[13.85,41.75],[13.95,41.7],[13.95,41.55],[13.85,41.45],[13.7,41.5],[13.65,41.65],[13.7,41.75]]]}},{"name":"Pecorino Romano","lat":40.1,"lon":9.1,"country":"Italy","where":"Sardinia (~90%), Lazio, Tuscany (Grosseto)","hint":"Sardinia & central Italy","desc":"Hard salty sheep\'s-milk grating cheese; the staple of cacio e pepe and amatriciana.","image":"pecorino_romano.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","salted","pressed"],"ageing_min_days":150,"format":"cylinder, 20–35 kg, 25–35 cm × 25–40 cm","year_recognized":1955,"animal_breed":null,"vegetarian":false,"desc_long":"Pecorino Romano is the senior member of Italy\'s family of hard sheep\'s-milk cheeses, originally a Roman product but today produced overwhelmingly in Sardinia, with smaller quantities still coming from Lazio and the province of Grosseto in southern Tuscany. The PDO requires whole raw sheep\'s milk set with lamb rennet, and the cheese carries a defining, deliberately high salt content — wheels are dry-salted in stages over many weeks. Maturation lasts a minimum of five months for table use and at least eight for grating-grade wheels, which weigh between twenty and thirty-five kilograms. Italian protection followed in 1955 and EU PDO recognition in 1996. The flavour is sharp, deeply savoury and frankly salty, with a crumbly straw-coloured paste — the indispensable grating cheese behind cacio e pepe, carbonara and amatriciana, and the cheese that perhaps more than any other defines the taste of Roman cooking.","sources":[{"label":"Wikipedia: Pecorino Romano","url":"https://en.wikipedia.org/wiki/Pecorino_Romano"},{"label":"Disciplinare di produzione DOP Pecorino Romano (Consorzio, PDF)","url":"https://www.pecorinoromano.com/application/files/1914/9069/8657/Disciplinare-2009-GU-n-271_.pdf"}],"pronunciation":{"ipa":"/pe.koˈriːno roˈmaːno/","respelling":"peh-koh-REE-noh roh-MAH-noh"},"region_polygon":{"type":"MultiPolygon","coordinates":[[[[10.95,42.95],[11.35,42.95],[12.8,42.75],[13.8,42.05],[13.85,41.3],[13.55,41.2],[12.2,41.2],[11.4,42.3],[10.8,42.5],[10.95,42.95]]],[[[8.2,41.25],[8.85,41.2],[9.6,41.1],[9.85,40.5],[9.85,39.8],[9.5,39.1],[9.1,38.9],[8.55,38.9],[8.3,39.4],[8.3,40.2],[8.15,40.65],[8.2,41.25]]]]}},{"name":"Pecorino Sardo","lat":40.0,"lon":9.0,"country":"Italy","where":"Sardinia","hint":"Sardinia","desc":"Sheep\'s-milk cheese in soft \'dolce\' (young) and hard \'maturo\' (aged) forms; the everyday Sardinian table cheese.","image":"pecorino_sardo.webp","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["uncooked","pressed"],"ageing_min_days":20,"format":"wheel, 1–4 kg","year_recognized":1991,"animal_breed":["Sarda"],"vegetarian":null,"desc_long":"Pecorino Sardo is a raw sheep\'s-milk cheese made across Sardinia from native Sarda ewes, distinguished from its more famous compatriots — the rustic, smoked Fiore Sardo and the very salty grating Pecorino Romano — by a gentler character and a wider range of finished styles. The PDO covers two age classes: Dolce, ripened twenty to sixty days, yields wheels of one to about two kilograms with a soft yellow rind and a pale, slightly nutty paste suited to the table; Maturo, aged beyond two months and reaching wheels of up to four kilograms, deepens in colour and flavour with a firmer interior and an aromatic, lightly piquant edge. Italian protection followed in 1991 and EU PDO came in 1996. The cheese is the everyday pecorino of Sardinian kitchens, eaten young with fresh fava beans in spring and shaved over pasta when older.","sources":[{"label":"Wikipedia: Pecorino Sardo","url":"https://en.wikipedia.org/wiki/Pecorino_Sardo"},{"label":"SardegnaAgricoltura: Pecorino Sardo DOP","url":"https://www.sardegnaagricoltura.it/index.php?xsl=443&s=45306&v=2&c=3592"}],"pronunciation":{"ipa":"/pe.koˈriːno ˈsardo/","respelling":"peh-koh-REE-noh SAR-doh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.2,41.25],[8.85,41.2],[9.6,41.1],[9.85,40.5],[9.85,39.8],[9.5,39.1],[9.1,38.9],[8.55,38.9],[8.3,39.4],[8.3,40.2],[8.15,40.65],[8.2,41.25]]]}},{"name":"Pecorino Siciliano","lat":37.5,"lon":14.0,"country":"Italy","where":"Sicily","hint":"Sicily","desc":"Hard sheep\'s-milk cheese sometimes studded with whole black peppercorns; ancient lineage.","image":"pecorino_siciliano.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":null,"style":["semi-hard","basket-pressed"],"ageing_min_days":120,"format":"cylinder, ~12 kg","year_recognized":1955,"animal_breed":null,"vegetarian":null,"desc_long":"Pecorino Siciliano is a semi-hard sheep\'s-milk cheese produced widely across the western and central provinces of Sicily, formed in the traditional reed canestri that imprint a ribbed pattern on the rind and then pressed and salted by hand. Italian designation came in 1955 and EU PDO protection in 1996, formalising a tradition already noted by classical authors as one of the great cheeses of the ancient Mediterranean. The PDO covers a plain version and a popular regional variant — Pecorino Pepato — studded with whole black peppercorns scattered through the curd. The aged interior turns straw-yellow and develops a clean, savoury, faintly piquant flavour; the cheese is eaten table-style when young and grated over pastas like pasta alla Norma or sliced thinly into Sicilian antipasti when fully matured.","sources":[{"label":"Wikipedia: Pecorino Siciliano","url":"https://en.wikipedia.org/wiki/Pecorino_Siciliano"}],"pronunciation":{"ipa":"/pe.koˈriːno si.tʃiˈljaːno/","respelling":"peh-koh-REE-noh see-chee-LYAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[12.45,38.15],[13.3,38.3],[14.5,38.3],[15.65,38.3],[15.65,38.0],[15.3,37.05],[14.85,36.65],[13.95,36.65],[12.95,37.3],[12.4,37.55],[12.45,38.15]]]}},{"name":"Pecorino Toscano","lat":43.4,"lon":11.3,"country":"Italy","where":"Tuscany & adjacent zones","hint":"Tuscany","desc":"Sheep\'s-milk cheese from soft fresh wheels to hard aged grating wheels; gentler than Romano.","image":"pecorino_toscano.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"pasteurized","style":["semi-soft","semi-hard"],"ageing_min_days":20,"format":"wheel, 1–3.5 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Pecorino Toscano is a sheep\'s-milk cheese produced across Tuscany and a few adjoining districts of Umbria and Lazio, the gentlest of the major Italian pecorini and the everyday table cheese of central Italy. The PDO recognises two age classes: a fresh, semi-soft version matured about twenty days, with a thin pale rind and a delicately milky paste; and the stagionato, aged four months or more, which dries into a firmer, deeper-flavoured wheel of one to three and a half kilograms. The milk is pasteurised and set with rennet, salted lightly and pressed into smooth-sided wheels. EU PDO came in 1996 but the cheese itself traces back through Etruscan and Roman accounts of the region\'s pastoral economy. Younger Pecorino Toscano partners naturally with pears, honey and fresh fava beans; aged versions go into Tuscan farmhouse cooking and pair instinctively with the region\'s Sangiovese reds.","sources":[{"label":"Wikipedia: Pecorino Toscano","url":"https://en.wikipedia.org/wiki/Pecorino_Toscano"}],"pronunciation":{"ipa":"/pe.koˈriːno tosˈkaːno/","respelling":"peh-koh-REE-noh tohs-KAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[10.1,44.45],[10.55,44.45],[11.45,44.3],[12.1,44.1],[12.35,43.85],[12.3,43.3],[12.1,42.85],[11.45,42.3],[11.0,42.4],[10.4,42.85],[10.1,43.65],[9.95,44.2],[10.1,44.45]]]}},{"name":"Piacentinu Ennese","lat":37.57,"lon":14.27,"country":"Italy","where":"Enna province, Sicily","hint":"Central Sicily","desc":"Hard sheep\'s-milk cheese flavored with saffron and whole black peppercorns — bright yellow inside.","image":"piacentinu_ennese.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","saffron-tinted","peppercorn-studded"],"ageing_min_days":60,"format":"cylinder, 3.5–4.5 kg, 20–21 cm diameter","year_recognized":2011,"animal_breed":null,"vegetarian":null,"desc_long":"Piacentinu Ennese is a hard sheep\'s-milk cheese from nine municipalities of the central Sicilian province of Enna, immediately recognisable for its bright yellow-orange paste — coloured by saffron added at the milk stage — and the whole black peppercorns scattered through the wheel. Production uses raw sheep\'s milk set with rennet and pressed into wheels of about four kilograms, which age a minimum of sixty days in cool cellars. EU PDO recognition came in 2011 after a long campaign by a local consortium to formalise the recipe. The flavour combines the warm aromatic depth of saffron with the gentle savour of well-aged sheep\'s-milk paste, broken by the sharp heat of the peppercorns; the cheese is sliced thin as part of a Sicilian antipasto plate or grated into traditional Ennese pasta dishes.","sources":[{"label":"Qualigeo Piacentinu Ennese PDO spec / Volpetti","url":"https://www.volpetti.com/en/prodotto/piacentinu-ennese-cheese-pdo/"}],"pronunciation":{"ipa":"/pja.tʃenˈtiːnu enˈneːze/","respelling":"pyah-chen-TEE-noo en-NAY-zay"},"region_polygon":{"type":"Polygon","coordinates":[[[14.05,37.85],[14.35,37.85],[14.65,37.75],[14.7,37.5],[14.5,37.3],[14.2,37.3],[14.0,37.55],[14.05,37.85]]]}},{"name":"Piave","lat":46.14,"lon":12.22,"country":"Italy","where":"Belluno province, Veneto","hint":"Dolomite foothills, Veneto","desc":"Hard cow\'s-milk wheel named after the Piave river; ages fresh to mezzano to vecchio.","image":"piave.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["hard","cooked-curd"],"ageing_min_days":20,"format":"wheel, ~6–7 kg, 32 cm diameter","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Piave is a hard cooked-curd cow\'s-milk cheese from the province of Belluno in the Veneto, named for the river that runs through the Dolomite foothills where it is made. The PDO recognises five distinct age classes that span almost the cheese\'s whole life: Fresco (twenty to sixty days), Mezzano (two to six months), Vecchio (six months to a year), Selezione Oro (twelve months) and Riserva (eighteen months or more). The youngest wheels are pale, supple and gently sweet; longer ageing pulls the paste tight and yellow and concentrates the flavour into something close to a young Parmesan, dense, savoury and increasingly granular. EU PDO recognition came in 2010. Mature Piave grates cleanly over pasta and risotto and pairs naturally with the structured red wines of the surrounding hills.","sources":[{"label":"Wikipedia: Piave cheese","url":"https://en.wikipedia.org/wiki/Piave_cheese"},{"label":"Consorzio Tutela: Piave DOP / PDO","url":"https://www.formaggiopiave.it/piavecheese/consortium/dop/"}],"pronunciation":{"ipa":"/ˈpjaːve/","respelling":"PYAH-vay"},"region_polygon":{"type":"Polygon","coordinates":[[[11.85,46.65],[12.35,46.7],[12.65,46.65],[12.8,46.45],[12.65,46.1],[12.3,46.0],[11.85,46.1],[11.75,46.4],[11.85,46.65]]]}},{"name":"Provolone del Monaco","lat":40.63,"lon":14.38,"country":"Italy","where":"Sorrento peninsula, Campania","hint":"Sorrento peninsula, S of Naples","desc":"Hard pasta-filata cow\'s-milk cheese aged 6+ months; named for monks who shipped it across the bay.","image":"provolone_del_monaco.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["pasta-filata","semi-hard"],"ageing_min_days":180,"format":"pear or melon shape, ~3–8 kg, divided into six wedges by raffia","year_recognized":2010,"animal_breed":["Agerolese","Frisona","Brunalpina","Pezzata Rossa","Jersey","Podolica"],"vegetarian":false,"desc_long":"Provolone del Monaco is a stretched-curd cow\'s-milk cheese from the Sorrento peninsula in Campania, produced from raw milk drawn — by PDO requirement — at least twenty percent from the local Agerolese breed and the rest from a small list of cattle raised on the same coastal hills. The pasta-filata curd is heated, worked into a pliable mass and shaped into the characteristic pear or melon form, then bound and hung with raffia cords that leave the finished wheels divided into six rounded wedges. Ageing runs at least six months in cool cellars and frequently extends much longer, during which the rind dries to pale yellow and the interior turns deeper and more concentrated. EU PDO came in 2010. The name supposedly recalls hooded monks (monaco) — likely the woollen cloaks worn by sailors carrying the cheese across the Bay of Naples — and the flavour ranges from milky-mellow in younger wheels to sharp and frankly piquant when fully matured.","sources":[{"label":"Volpetti / Qualigeo Provolone del Monaco PDO spec","url":"https://www.volpetti.com/en/prodotto/provolone-del-monaco-pdo-piece/"},{"label":"Regione Campania: Prodotti Tipici — Provolone del Monaco (archived)","url":"https://web.archive.org/web/20211203121838/http://www.agricoltura.regione.campania.it/tipici/provolone_monaco-new.html"},{"label":"Wikipedia: Provolone","url":"https://en.wikipedia.org/wiki/Provolone"}],"pronunciation":{"ipa":"/pro.voˈloːne del ˈmɔːnako/","respelling":"proh-voh-LOH-nay del MOH-nah-koh"},"region_polygon":{"type":"Polygon","coordinates":[[[14.3,40.7],[14.45,40.7],[14.55,40.65],[14.55,40.55],[14.45,40.5],[14.3,40.55],[14.25,40.62],[14.3,40.7]]]}},{"name":"Provolone Valpadana","lat":45.0,"lon":10.0,"country":"Italy","where":"Po Valley","hint":"Po Valley","desc":"Pasta-filata cow\'s-milk cheese in dolce or piccante; moulded into pears, sausages and giant cylinders.","image":"provolone_valpadana.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["pasta-filata","semi-hard","hard"],"ageing_min_days":30,"format":"many shapes — sausage, pear, melon or large cylinder — from ~500 g to over 100 kg","year_recognized":1996,"animal_breed":null,"vegetarian":false,"desc_long":"Provolone Valpadana is a pasta-filata cow\'s-milk cheese produced across the Po Valley, covering parts of Lombardy, Veneto, Emilia-Romagna and Trentino — the broadest production zone of any Italian pasta-filata PDO. The defining technical choice is in the rennet: Dolce versions are coagulated with calf rennet paste, yielding a mild, milky-buttery cheese; Piccante versions use kid or lamb rennet rich in pre-gastric lipase, which over months of ageing produces a sharp, peppery, distinctly piquant flavour. The curd is heated, stretched in hot water and hand-formed into a remarkable variety of shapes — small sausages and gourds for sale by the slice, all the way up to giant cylinders weighing over a hundred kilograms and hung by rope from cellar ceilings. PDO recognition came in 1996. Provolone Valpadana fills out the deli case across Italy in both forms — Dolce as a melting and table cheese, Piccante as a sharp grating finish for pasta and pizza.","sources":[{"label":"Wikipedia: Provolone","url":"https://en.wikipedia.org/wiki/Provolone"}],"pronunciation":{"ipa":"/pro.voˈloːne val.paˈdaːna/","respelling":"proh-voh-LOH-nay val-pah-DAH-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[9.4,45.9],[10.5,46.0],[11.8,45.5],[12.1,45.1],[11.85,44.85],[10.5,44.85],[9.5,45.0],[9.3,45.5],[9.4,45.9]]]}},{"name":"Puzzone di Moena / Spretz Tzaorì","lat":46.38,"lon":11.66,"country":"Italy","where":"Val di Fassa & Val di Fiemme, Trentino","hint":"Trentino, Dolomites","desc":"Washed-rind cow\'s-milk cheese whose name means \'stinker\' — pungent in a small, intense package.","image":"puzzone_di_moena.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","washed-rind"],"ageing_min_days":90,"format":"cylinder, ~10 kg","year_recognized":2014,"animal_breed":null,"vegetarian":null,"desc_long":"Puzzone di Moena is a raw cow\'s-milk washed-rind cheese from the Val di Fassa and Val di Fiemme valleys of Trentino, whose Italian name — \'big stinker\' — does an honest job of describing the aroma. The local Ladin name, Spretz Tzaorì, means roughly \'cheese with flavour\'. Production begins with raw milk from cattle grazed in these eastern Dolomite valleys; the wheels are pressed, brined and then aged for a minimum of three months in cool cellars where the rind is washed regularly with warm salted water. The microbial activity that follows produces a sticky, brick-orange rind and the famously penetrating odour, with hints of animal, hay and ammonia. EU PDO came in 2014. Behind the smell sits a surprisingly composed paste — pale, supple, mildly savoury and faintly sweet — that softens to almost spoonable in the most ripened wheels.","sources":[{"label":"Wikipedia: Puzzone di Moena","url":"https://en.wikipedia.org/wiki/Puzzone_di_Moena"},{"label":"EUR-Lex: PDO registration application — Puzzone di Moena (OJ C 77/2013, PDF)","url":"https://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:C:2013:077:0021:0024:IT:PDF"}],"pronunciation":{"ipa":"/putˈtsoːne di moˈɛːna/","respelling":"poot-TSOH-nay dee moh-AY-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[11.3,46.4],[11.55,46.5],[11.85,46.45],[11.9,46.3],[11.75,46.15],[11.45,46.15],[11.3,46.25],[11.3,46.4]]]}},{"name":"Quartirolo Lombardo","lat":45.5,"lon":9.5,"country":"Italy","where":"Lombardy","hint":"Lombardy","desc":"Soft square cow\'s-milk cheese named for autumn\'s \'fourth cut\' of grass; lemony, fresh.","image":"quartirolo_lombardo.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":null,"style":["soft"],"ageing_min_days":5,"format":"rectangular block, 1.5–3.5 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Quartirolo Lombardo is a soft cow\'s-milk cheese from Lombardy whose name preserves the older Italian dairying calendar: erba quartirola was the fourth cut of grass, taken in autumn after the third haymaking, and the cheese was traditionally made from milk drawn while the cattle grazed it. Today the PDO permits production year-round across Lombardy from whole or partially skimmed cow\'s milk, but the cheese has kept its characteristic squarish silhouette and pale, lemony paste. Wheels weigh between one and a half and three and a half kilograms and may be sold at just five days for the freshest soft-paste version or aged a month or more for a firmer, more aromatic version. EU PDO recognition came in 1996. The flavour begins clean and gently sour, with that fresh-cheese tang, and acquires herbaceous, slightly bitter notes in the mature wheels.","sources":[{"label":"Wikipedia: Quartirolo Lombardo","url":"https://en.wikipedia.org/wiki/Quartirolo_Lombardo"},{"label":"EUR-Lex: PDO amendment application — Quartirolo Lombardo (Reg 1151/2012)","url":"https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52017XC0629(04)&qid=1740063277287"}],"pronunciation":{"ipa":"/kwar.tiˈrɔːlo lomˈbardo/","respelling":"kwar-tee-ROH-loh lohm-BAR-doh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.8,46.1],[9.5,46.15],[10.3,46.1],[10.8,46.0],[10.8,45.2],[9.8,45.0],[9.1,45.0],[8.75,45.25],[8.7,45.85],[8.8,46.1]]]}},{"name":"Ragusano","lat":36.93,"lon":14.74,"country":"Italy","where":"Ragusa & Syracuse provinces, Sicily","hint":"Southeast Sicily","desc":"Pasta-filata cow\'s-milk brick from Modicana cows; aged on wooden beams, develops sharp depth.","image":"ragusano.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["pasta-filata","hard"],"ageing_min_days":90,"format":"parallelepiped (rectangular block), 10–16 kg","year_recognized":1996,"animal_breed":["Modicana"],"vegetarian":false,"desc_long":"Ragusano is a hard pasta-filata cow\'s-milk cheese from the southeastern Sicilian provinces of Ragusa and Siracusa, made by PDO rule from the raw milk of Modicana cattle — a rare native breed kept on grass and hay across the Iblei plateau. The curd is heated and worked in hot water at seventy to eighty degrees until pliable, then formed by hand into the characteristic rectangular parallelepiped (rather than the rounder pear shape of mainland caciocavallo) and bound with rope to age. Young wheels of about two months are mild, supple and grass-sweet; longer ageing concentrates the flavour into a sharp, peppery, deeply savoury cheese that grates beautifully. EU PDO recognition came in 1996, but Ragusano\'s history runs back at least to the medieval Hauteville period when the cheese was exported in quantity. When the milk comes from other breeds the producers use the Sicilian dialect name \'Cosacavaddu Rausanu\' rather than the protected designation.","sources":[{"label":"Volpetti / Slow Food Ragusano PDO spec","url":"https://www.volpetti.com/en/prodotto/ragusano-cheese-pdo/"},{"label":"Wikipedia: Ragusano cheese","url":"https://en.wikipedia.org/wiki/Ragusano_cheese"}],"pronunciation":{"ipa":"/ra.ɡuˈzaːno/","respelling":"rah-goo-ZAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[14.45,37.2],[14.75,37.2],[15.1,37.05],[15.15,36.8],[14.85,36.65],[14.5,36.7],[14.4,36.95],[14.45,37.2]]]}},{"name":"Raschera","lat":44.3,"lon":7.85,"country":"Italy","where":"Cuneo province, Piedmont","hint":"Maritime Alps, Piedmont","desc":"Square cow\'s-milk Alpine cheese (sheep/goat allowed); semi-firm with small eyes.","image":"raschera.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":30,"format":"cylinder 30–40 cm or square ~40 cm","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Raschera is a semi-hard cheese from the province of Cuneo in the Piedmontese Maritime Alps, made predominantly from cow\'s milk but allowed under PDO rule to include small additions of sheep or goat milk. The cheese is unusual for being produced in two formats — a conventional round cylinder and a distinctly square wheel that recalls the cheese\'s older shape and makes for easier transport from the high pastures. Wheels age a minimum of thirty days in cool cellars and develop a thin grey-red rind around an ivory-white interior dotted with small irregular eyes. Producers who work above thousand metres of altitude in designated municipalities may add the suffix \'di alpeggio\' to indicate true mountain pasture production. EU PDO came in 1996. The flavour is gentle and milky when young, with a faint salty edge that sharpens noticeably with longer ageing — at home both as a table cheese and melted over polenta or Piedmontese gnocchi.","sources":[{"label":"Wikipedia: Raschera","url":"https://en.wikipedia.org/wiki/Raschera"}],"pronunciation":{"ipa":"/raˈskeːra/","respelling":"rah-SKAY-rah"},"region_polygon":{"type":"Polygon","coordinates":[[[7.3,44.55],[7.8,44.55],[8.05,44.45],[8.05,44.2],[7.85,44.05],[7.45,44.05],[7.25,44.2],[7.2,44.4],[7.3,44.55]]]}},{"name":"Robiola di Roccaverano","lat":44.62,"lon":8.3,"country":"Italy","where":"Asti & Alessandria provinces, Piedmont","hint":"Alta Langa hills","desc":"Small soft goat (often mixed with cow/sheep) cheese; the only Italian PDO fully made from goat milk.","image":"robiola_di_roccaverano.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["soft","fresh","bloomy-rind"],"ageing_min_days":4,"format":"small disc, 250–400 g, 2.5–4 cm tall","year_recognized":1979,"animal_breed":["Roccaverano","Camosciata Alpina"],"vegetarian":null,"desc_long":"Robiola di Roccaverano is a soft goat\'s-milk cheese from the Langhe and Monferrato hills on the border of the provinces of Asti and Alessandria in southern Piedmont. The PDO specifies raw whole milk from Roccaverano and Camosciata Alpina goats and their crosses; following a 2023 revision the protected name is reserved for pure goat-milk production, after a long period in which up to half of the milk could come from cows or sheep. Wheels are small — a quarter to four hundred grams — and are sold in two states: Fresco, aged four to ten days and presenting a fresh, lactic, almost yoghurty paste under a barely-formed rind, and Affinata or Stagionata, aged at least eleven days and continuing through more concentrated, faintly hazelnut-tinged stages. PDO recognition came in 1979, among the earliest Italian cheeses formally protected. Robiola di Roccaverano is a benchmark of Piedmontese farmstead cheesemaking, partnered naturally with the wines of the surrounding Alta Langa.","sources":[{"label":"Qualigeo Robiola di Roccaverano PDO spec","url":"https://www.qualigeo.eu/en/product/robiola-di-roccaverano-pdo/"},{"label":"Wikipedia: Robiola","url":"https://en.wikipedia.org/wiki/Robiola"}],"pronunciation":{"ipa":"/roˈbjɔːla di rok.ka.veˈraːno/","respelling":"roh-BYOH-lah dee rohk-kah-vay-RAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.15,44.7],[8.4,44.75],[8.6,44.65],[8.6,44.5],[8.35,44.4],[8.15,44.45],[8.1,44.6],[8.15,44.7]]]}},{"name":"Salva Cremasco","lat":45.36,"lon":9.69,"country":"Italy","where":"Cremona & nearby provinces, Lombardy","hint":"Lombardy","desc":"Square cow\'s-milk cheese aged in cool cellars; traditionally eaten with pickled \'tighe\' peppers.","image":"salva_cremasco.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft","washed-rind"],"ageing_min_days":75,"format":"rectangular block, 1.3–5 kg","year_recognized":2002,"animal_breed":null,"vegetarian":null,"desc_long":"Salva Cremasco is a cow\'s-milk cheese from the Crema area of Lombardy and the neighbouring provinces of Bergamo and Brescia, formed in a distinctive square-cornered block rather than the typical round wheel. The PDO allows either raw or pasteurised whole milk; wheels age in cool damp cellars where the rind develops a yellow mould that producers may rub in with oil to deepen the colour and concentrate the aroma. Maturation lasts a minimum of about two and a half months and frequently extends to a year or more, taking the cheese from a mild milky-tangy youth toward a firmer, increasingly assertive paste. EU PDO recognition came in 2002. The classic local way to eat it is \'salva con le tighe\' — cubed Salva with pickled green Lombard chillies and a little olive oil, a sharp-and-creamy pairing that the cheese is named for in regional cooking.","sources":[{"label":"Wikipedia: Salva Cremasco","url":"https://en.wikipedia.org/wiki/Salva_Cremasco"},{"label":"Disciplinare di produzione DOP Salva Cremasco (Consorzio, PDF)","url":"http://www.salvacremasco.com/images/stories/DISCIPLINARE/Disciplinare_salva_cremasco_24dic10.pdf"}],"pronunciation":{"ipa":"/ˈsalva kreˈmasko/","respelling":"SAHL-vah kreh-MAHS-koh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.0,45.95],[9.6,46.0],[10.3,45.95],[10.3,45.3],[9.85,45.05],[9.2,45.05],[8.85,45.3],[8.95,45.65],[9.0,45.95]]]}},{"name":"Spressa delle Giudicarie","lat":46.0,"lon":10.7,"country":"Italy","where":"Giudicarie valleys, Trentino","hint":"Trentino","desc":"Pressed lean cow\'s-milk mountain cheese; one of the Alps\' oldest semi-skimmed cheeses.","image":"spressa_delle_giudicarie.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","pressed","alpine"],"ageing_min_days":90,"format":"cylinder, ~7–10 kg, ~25 cm diameter","year_recognized":2003,"animal_breed":["Rendena"],"vegetarian":null,"desc_long":"Spressa delle Giudicarie is a partially-skimmed cow\'s-milk cheese from the Giudicarie valleys of southern Trentino, traditionally made from the milk drawn from native Rendena cattle. Like several of the lower-fat cheeses of the Alps, Spressa has its roots in dairy economy: cream was skimmed off the evening milk for butter and the remaining milk pooled with the morning\'s whole milk for cheesemaking. The curd is pressed and aged a minimum of three months for table use and at least six months for harder versions, on wooden boards in cool cellars where the rind ripens to a brown crust around a pale ivory paste shot with small irregular holes. EU PDO came in 2003. Younger wheels are mild and gently milky, with longer-aged versions turning firmer, drier and lightly piquant — a clean Alpine pairing for polenta and the southern Trentino Marzemino reds.","sources":[{"label":"Wikipedia: Spressa delle Giudicarie","url":"https://en.wikipedia.org/wiki/Spressa_delle_Giudicarie"},{"label":"Ministero delle Politiche Agricole: Disciplinare DOP Spressa delle Giudicarie","url":"http://www.politicheagricole.it/flex/cm/pages/ServeAttachment.php/L/IT/D/1%252F0%252Fa%252FD.2ce78b1d3abae353f15d/P/BLOB%3AID%3D3340"}],"pronunciation":{"ipa":"/ˈsprɛssa delle dʒu.diˈkaːrje/","respelling":"SPRES-sah del-lay joo-dee-KAH-ryay"},"region_polygon":{"type":"Polygon","coordinates":[[[10.5,46.2],[10.75,46.25],[10.95,46.2],[11.0,46.0],[10.85,45.85],[10.55,45.85],[10.45,46.0],[10.5,46.2]]]}},{"name":"Squacquerone di Romagna","lat":44.41,"lon":12.2,"country":"Italy","where":"Emilia-Romagna","hint":"Romagna plains","desc":"Very soft, almost runny fresh cow\'s-milk cheese; the classic filling for warm piadina.","image":"squacquerone_di_romagna.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["fresh","soft","spreadable"],"ageing_min_days":1,"format":"loose, sold in tubs ~100 g – 2 kg, no rind","year_recognized":2012,"animal_breed":null,"vegetarian":null,"desc_long":"Squacquerone di Romagna is a fresh cow\'s-milk cheese from across Emilia-Romagna, defined by being barely a cheese at all in the structural sense — the very wet, almost spoonable paste has essentially no rind and breaks like clotted cream under a knife. The PDO permits raw or pasteurised milk, set with rennet and minimally drained before being shaped (or simply portioned) and refrigerated; the cheese is sold within days of production and eaten immediately. The flavour is ivory-white, milky-sweet with a quick lactic tang — the same fresh-cheese profile that has made Squacquerone the classic filling for the warm piadina flatbreads of the Romagna coast, often layered with rocket and prosciutto. EU PDO recognition came in 2012.","sources":[{"label":"Wikipedia: Squacquerone di Romagna","url":"https://en.wikipedia.org/wiki/Squacquerone_di_Romagna"}],"pronunciation":{"ipa":"/skwak.kweˈroːne di roˈmaɲɲa/","respelling":"skwak-kweh-ROH-nay dee roh-MAH-nyah"},"region_polygon":{"type":"Polygon","coordinates":[[[11.1,44.85],[11.65,44.95],[12.3,44.85],[12.65,44.45],[12.85,44.0],[12.5,43.85],[11.85,43.95],[11.2,44.1],[11.0,44.5],[11.1,44.85]]]}},{"name":"Stelvio / Stilfser","lat":46.53,"lon":10.45,"country":"Italy","where":"South Tyrol","hint":"South Tyrol","desc":"Semi-hard washed-rind cow\'s-milk cheese from Alpine pastures; mild orange rind, supple paste.","image":"stelvio.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","washed-rind","alpine"],"ageing_min_days":60,"format":"cylinder, 8–10 kg, 36–38 cm × 8–10 cm","year_recognized":2007,"animal_breed":null,"vegetarian":null,"desc_long":"Stelvio, known in its bilingual home as Stilfser, is a washed-rind cow\'s-milk cheese from the high pastures of South Tyrol, the first cheese of the autonomous Alto Adige region to win European PDO recognition. Wheels are pressed and brined and then matured on wooden boards for a minimum of sixty days, during which they are turned and washed twice a week with a salt brine carrying the local microflora; the resulting rind ranges from yellow-orange through a deep red-brown, with a smooth or lightly tacky surface. Inside, the paste is pale ivory, supple, dotted with small irregular eyes, and gently mushroomy. EU PDO came in 2007. The flavour is forthright and slightly tangy with the savoury, faintly pungent edge of a true washed-rind, easy on the palate next to the alpine breads and cured meats of the region.","sources":[{"label":"Stilfser official producer / PDO spec","url":"https://www.stilfser.it/en/stelvio-pdo.html"}],"pronunciation":{"ipa":"/ˈstɛlvjo/ · /ˈʃtɪlfsɐ/","respelling":"STEL-vyoh · SHTILF-zer"},"region_polygon":{"type":"Polygon","coordinates":[[[10.4,46.85],[10.85,46.95],[11.35,47.0],[11.85,46.7],[12.3,46.65],[12.3,46.5],[11.85,46.3],[11.2,46.3],[10.6,46.5],[10.45,46.65],[10.4,46.85]]]}},{"name":"Taleggio","lat":45.95,"lon":9.58,"country":"Italy","where":"Lombardy (& parts of Piedmont, Veneto)","hint":"Lombard pre-Alps","desc":"Soft washed-rind cow\'s-milk square with pink-orange crust; mild despite a strong aroma.","image":"taleggio.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind"],"ageing_min_days":40,"format":"square block, 1.8–2.2 kg, 18–20 cm × 5–8 cm","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Taleggio is a soft washed-rind cow\'s-milk cheese from the Val Taleggio in the Lombard pre-Alps, with PDO production extending across the broader Lombardy plain and into parts of Piedmont and Veneto. The recipe traces back centuries — wheels were traditionally cured in the cold caves of the Bergamasque hills before refrigerated cellars made the cheese a mainstream product. The square 1.8 to 2.2 kilogram blocks are washed with a seawater sponge about once a week through forty days or more of ageing, encouraging the orange-pink crust and discouraging unwanted moulds. EU PDO recognition came in 1996. Behind a remarkably pungent aroma, the paste is surprisingly mild — buttery, lightly fruity, with a tangy edge near the rind — and Taleggio is at home both on the cheese board and melted into risotto, polenta or a baked pasta.","sources":[{"label":"Wikipedia: Taleggio cheese","url":"https://en.wikipedia.org/wiki/Taleggio_cheese"}],"pronunciation":{"ipa":"/taˈlɛddʒo/","respelling":"tah-LEJ-joh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.3,46.1],[9.0,46.15],[10.3,46.1],[12.5,45.95],[12.5,45.7],[9.8,45.05],[8.85,45.2],[8.2,45.7],[8.3,46.1]]]}},{"name":"Toma Piemontese","lat":45.4,"lon":7.6,"country":"Italy","where":"Piedmont","hint":"Piedmont","desc":"Semi-hard cow\'s-milk Alpine cheese; supple paste with light hazelnut notes.","image":"toma_piemontese.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":15,"format":"cylinder, 1.8–9 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Toma Piemontese is a cow\'s-milk cheese produced across the Piedmont region, the most widely-made representative of a much older family of regional \'toma\' cheeses that gave their name to Italy\'s broad category of pressed mountain wheels. The PDO recognises both whole-milk and semi-fat versions, with wheels ranging from under two kilograms up to nine and a softer young paste giving way to firmer, more concentrated character with longer maturation. EU PDO came in 1996. Toma melts exceptionally well, which is why it features in classic Piedmontese fonduta and in dishes that gently warm the cheese rather than serving it cold. Young Toma is gently buttery and grass-sweet; longer-aged wheels develop a piquant, slightly woody character at home with bagna càuda and the region\'s structured red wines.","sources":[{"label":"Wikipedia: Toma (cheese)","url":"https://en.wikipedia.org/wiki/Toma_(cheese)"},{"label":"Disciplinare di produzione DOP Toma Piemontese (archived)","url":"https://web.archive.org/web/20061017175429/http://www.milkonline.com/fiera/cheese/disciplinari/Toma%20Piemontese.htm"}],"pronunciation":{"ipa":"/ˈtɔːma pje.monˈteːze/","respelling":"TOH-mah pyay-mohn-TAY-zay"},"region_polygon":{"type":"Polygon","coordinates":[[[6.65,45.4],[7.0,46.1],[7.9,46.2],[8.6,46.25],[8.95,46.05],[9.0,45.65],[8.95,44.85],[8.4,44.55],[7.85,44.1],[7.35,44.1],[6.85,44.4],[6.65,44.85],[6.65,45.4]]]}},{"name":"Valle d\'Aosta Fromadzo","lat":45.74,"lon":7.32,"country":"Italy","where":"Aosta Valley","hint":"Aosta Valley","desc":"Semi-hard cow\'s-milk cheese (sometimes blended with goat), partially skimmed; herbal Alpine flavor.","image":"valle_daosta_fromadzo.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","alpine","pressed"],"ageing_min_days":60,"format":"cylinder, 1–7 kg","year_recognized":1996,"animal_breed":["Valdostana"],"vegetarian":null,"desc_long":"Valle d\'Aosta Fromadzo is a partially-skimmed cow\'s-milk cheese from the high valleys of the Aosta region, produced from the raw milk of Valdostana cattle and frequently rounded out in older versions with a small addition of goat\'s milk for character. The recipe distinguishes itself from Fontina — the more famous Aostan PDO — by being made from skimmed evening milk pooled with whole morning milk, yielding a leaner, drier paste suited to longer ageing. Wheels of one to seven kilograms are pressed and cured for a minimum of two months, with longer-aged versions developing pronounced herbal and fruity notes from the wild alpine pastures the cattle graze. EU PDO came in 1996. Fromadzo is a quieter, more workaday cheese than Fontina, used in everyday Aostan kitchens and increasingly sought out by enthusiasts of long-aged farmstead production.","sources":[{"label":"Wikipedia: Valle d\'Aosta Fromadzo","url":"https://en.wikipedia.org/wiki/Valle_d%27Aosta_Fromadzo"}],"pronunciation":{"ipa":"/ˈvalle daˈɔsta froˈmaddzo/","respelling":"VAL-lay dah-OHS-tah froh-MAH-tsoh"},"region_polygon":{"type":"Polygon","coordinates":[[[6.85,45.95],[7.1,45.92],[7.4,45.95],[7.8,45.95],[7.95,45.85],[7.85,45.65],[7.45,45.55],[7.1,45.65],[6.9,45.75],[6.85,45.95]]]}},{"name":"Valtellina Casera","lat":46.2,"lon":9.85,"country":"Italy","where":"Valtellina, Lombardy","hint":"Valtellina valleys","desc":"Semi-skimmed cow\'s-milk Alpine cheese aged in cool \'casere\'; the curd of pizzoccheri.","image":"valtellina_casera.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","alpine","pressed"],"ageing_min_days":70,"format":"cylinder, 7–12 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Valtellina Casera is a semi-fat cow\'s-milk cheese from the long alpine valley of the Valtellina in the Lombard province of Sondrio. The recipe begins with raw milk that has been partially skimmed — cream lifted for butter — and is then set, pressed and aged in cool stone cellars called casere, the structures that give the cheese its name. Wheels age a minimum of seventy days and frequently extend much longer, taking on a pale ivory to straw-yellow paste shot through with small irregular eyes. EU PDO came in 1996. The flavour is forthright, gently sweet and grass-fed, with a clean savoury finish that thickens with age; the cheese is the curd of pizzoccheri, the buckwheat-pasta dish layered with cabbage, potatoes, garlic and melted Casera that defines Valtellina cooking.","sources":[{"label":"Wikipedia: Valtellina Casera","url":"https://en.wikipedia.org/wiki/Valtellina_Casera"},{"label":"EUR-Lex: Commission Regulation (EC) No 1263/96 (GI registration)","url":"http://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=CELEX:31996R1263:EN:NOT"}],"pronunciation":{"ipa":"/val.telˈliːna kaˈzɛːra/","respelling":"val-tel-LEE-nah kah-ZAIR-ah"},"region_polygon":{"type":"Polygon","coordinates":[[[9.3,46.3],[9.7,46.45],[10.3,46.5],[10.5,46.3],[10.4,46.05],[9.85,46.0],[9.4,46.05],[9.25,46.15],[9.3,46.3]]]}},{"name":"Vastedda della valle del Belìce","lat":37.65,"lon":13.0,"country":"Italy","where":"Belìce valley, western Sicily","hint":"Western Sicily","desc":"Rare pasta-filata sheep\'s-milk cheese — unusual stretched curd from ewe milk; fresh, soft, slightly tart.","image":"vastedda_della_valle_del_belìce.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["fresh","pasta-filata"],"ageing_min_days":null,"format":"flat disc, 15–17 cm diameter, 500–700 g","year_recognized":2010,"animal_breed":["Valle del Belìce"],"vegetarian":false,"desc_long":"Vastedda della Valle del Belìce is a rare oddity within Italian cheese tradition — a pasta-filata cheese made from pure sheep\'s milk, a technique almost universally used with cow\'s milk and held by the producers to be unique in Italy. The PDO covers eighteen municipalities across the Sicilian provinces of Agrigento, Trapani and Palermo, and requires raw whole milk from native Valle del Belìce ewes processed within forty-eight hours of milking. Curd from a first round of cheesemaking is allowed to acidify, then sliced and stretched by hand in hot water in copper vessels called piddiaturi, before being shaped into the flat, crustless disc that gives the cheese its name — vastedda is also the Sicilian word for a round flatbread. Wheels are about fifteen centimetres across and half a kilo in weight, sold within a few days of production. EU PDO came in 2010. The flavour is mild, faintly tangy and quietly milky, with the silky texture of a well-stretched mozzarella but the richer dairy depth of sheep\'s milk.","sources":[{"label":"Consorzio Vastedda della Valle del Belìce / Qualigeo spec","url":"https://www.consorziovastedda.eu/site/en/territorio.html"},{"label":"Wikipedia: Vastedda","url":"https://en.wikipedia.org/wiki/Vastedda"}],"pronunciation":{"ipa":"/vaˈstɛdda della ˈvalle del beˈliːtʃe/","respelling":"vah-STED-dah del-lah VAL-lay del beh-LEE-chay"},"region_polygon":{"type":"Polygon","coordinates":[[[12.65,38.0],[13.0,38.05],[13.4,37.95],[13.5,37.75],[13.3,37.55],[12.9,37.55],[12.65,37.75],[12.65,38.0]]]}},{"name":"Lietuviškas varškės sūris","lat":55.3,"lon":24.0,"country":"Lithuania","where":"Throughout Lithuania","hint":"Lithuania","desc":"Pressed fresh-curd cow\'s-milk cheese; firm, mild, eaten with honey or in dumplings.","image":"lietuviskas_varskes_suris.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["fresh","acid-curd","low-fat","smoked"],"ageing_min_days":1,"format":"triangular prism with rounded corners, ~250 g – 1 kg","year_recognized":2017,"animal_breed":null,"vegetarian":true,"desc_long":"Lietuviškas varškės sūris is Lithuania\'s traditional curd cheese — a fresh acid-set cheese made throughout the country, with documentary references back to the sixteenth century and roots that historians put deeper into the medieval period. The PGI ties production to Lithuanian territory and to a traditional method that uses lactic-acid-bacteria starter culture only — no rennet — to set the milk. Once the curd has developed, it is hand-packed (or mechanically packed) into the characteristic triangular cloth bags whose rounded corners give the finished cheese its signature triangular-prism shape, then drained and pressed. The cheese can be sold fresh, or further dried, smoked or baked for longer keeping; salt and aromatic herbs may be added but most varieties are unflavoured. EU PGI came in 2017. The cheese is dense, mild, gently tangy and very low in fat; it is sliced for bread, drizzled with honey for dessert, or fried with onions as the classic Lithuanian curd-cheese-and-onion plate.","sources":[{"label":"EUR-Lex: Lietuviškas varškės sūris PGI application","url":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:52017XC0802(03)"},{"label":"Wikipedia: Lithuanian cuisine","url":"https://en.wikipedia.org/wiki/Lithuanian_cuisine"}],"pronunciation":{"ipa":"/lʲɛtʊˈvʲɪʃkəs vɐrʃˈkʲeːs ˈsuːrʲɪs/","respelling":"lyeh-too-VEESH-kahs vahrsh-KAYS SOO-rees"},"region_polygon":{"type":"Polygon","coordinates":[[[21.0,56.4],[22.3,56.45],[24.05,56.4],[25.85,56.05],[26.85,55.3],[26.45,54.3],[25.05,54.1],[23.65,54.05],[22.65,54.4],[21.3,54.8],[20.95,55.55],[21.0,56.4]]]}},{"name":"Boerenkaas","lat":52.0,"lon":5.0,"country":"Netherlands","where":"Across the Netherlands","hint":"Netherlands — farmstead","desc":"Traditional raw cow\'s-milk farmhouse cheese made on the farm where the milk was produced.","image":"boerenkaas.jpeg","name_protections":["TSG"],"milk_types":["cow","goat","sheep","buffalo"],"pasteurization":"raw","style":["semi-hard","hard","pressed","farmhouse"],"ageing_min_days":28,"format":"wheel, varies","year_recognized":2007,"animal_breed":null,"vegetarian":null,"desc_long":"Boerenkaas — literally \\"farmer\'s cheese\\" — is the EU-protected name for traditional Dutch farmhouse cheese made from raw, unpasteurised milk on the farm where the milk is produced. The TSG (Traditional Speciality Guaranteed) permits cow\'s, goat\'s, sheep\'s or buffalo\'s milk; at least half of the milk in any batch must come from the farm\'s own herd, with bought-in milk capped at the farm\'s own output and drawn from no more than two outside dairies. Milk must not be heated above 40 °C and must be turned into cheese within forty hours of milking. The curd is set with rennet over twenty-five to forty minutes, cut, stirred, scalded, pressed, and brined, then matured at least four weeks. EU TSG came in 2007. Boerenkaas is most often a Gouda-style wheel, but can be spiced with cumin or other herbs. Because the milk is raw and the make is done on-farm, the cheeses carry a markedly more varied microbial fingerprint than industrial Gouda, with sharper, deeper and more individual flavours that turn striking in the long-aged Boeren-Goudse Oplegkaas grade.","sources":[{"label":"Qualigeo: Boerenkaas TSG","url":"https://www.qualigeo.eu/en/prodotto-qualigeo/boerenkaas-stg/"},{"label":"EUR-Lex: Commission Regulation (EC) No 977/2009 (Boerenkaas TSG registration, PDF)","url":"https://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:L:2009:274:0019:0024:EN:PDF"},{"label":"Wikipedia: Boerenkaas","url":"https://en.wikipedia.org/wiki/Boerenkaas"}],"pronunciation":{"ipa":"/ˈbuːrənkaːs/","respelling":"BOOR-en-kahss"},"region_polygon":{"type":"Polygon","coordinates":[[[3.4,53.5],[4.2,53.5],[5.45,53.5],[6.95,53.45],[7.1,52.55],[7.0,51.95],[6.2,51.45],[5.85,50.9],[5.05,51.3],[4.2,51.4],[3.5,51.55],[3.4,53.5]]]}},{"name":"Boeren-Leidse met sleutels","lat":52.16,"lon":4.49,"country":"Netherlands","where":"Around Leiden, South Holland","hint":"South Holland, around Leiden","desc":"Firm cow\'s-milk cheese flecked with cumin and stamped with the crossed-keys arms of Leiden.","image":"boeren-leidse_met_sleutels.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","low-fat","pressed","cumin"],"ageing_min_days":90,"format":"wheel, ~3–10 kg, branded with crossed keys","year_recognized":1997,"animal_breed":null,"vegetarian":null,"desc_long":"Boeren-Leidse met sleutels is the protected farmhouse version of Leidse kaas — the cumin-spiced hard cheese of the Oude Rijn region around Leiden in South Holland, made with the crossed keys of the city\'s coat of arms embossed on the rind. The PDO requires raw skimmed cow\'s milk from the farm\'s own herd, with cumin seed worked into the middle layer of curd at about 75 g per 100 litres of milk; the seed sits sandwiched between two cumin-free layers, which both grants the cheese its signature speckled core and helps the dense low-fat wheel slice without crumbling. Wheels are pressed, brined and matured at least three months, often considerably longer. EU PDO came in 1997. The cheese is markedly leaner and harder than Gouda, with a deep yellow paste, an intense salty-savoury character, and the warm seed perfume of cumin running through it from the first bite — an emphatic survival of Holland\'s traditional skim-milk hard-cheese tradition.","sources":[{"label":"Wikipedia: Leyden cheese","url":"https://en.wikipedia.org/wiki/Leyden_cheese"},{"label":"EU DOOR registry: Boeren-Leidse met sleutels (archived)","url":"https://web.archive.org/web/20121025034127/http://ec.europa.eu/agriculture/quality/door/registeredName.html?denominationId=140"}],"pronunciation":{"ipa":"/ˈbuːrən ˈlɛidsə mɛt ˈsløtəls/","respelling":"BOOR-en LAY-tsuh met SLEU-tels"},"region_polygon":{"type":"Polygon","coordinates":[[[4.2,52.3],[4.65,52.3],[4.85,52.2],[4.85,52.0],[4.5,51.95],[4.2,52.05],[4.2,52.3]]]}},{"name":"Edam Holland","lat":52.51,"lon":5.05,"country":"Netherlands","where":"Netherlands","hint":"Netherlands","desc":"Cow\'s-milk sphere with red wax rind; named for the harbour town of Edam, designed to travel.","image":"edam_holland.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed","washed-curd","ball"],"ageing_min_days":28,"format":"ball, ~1.7–2 kg, red-or-yellow wax","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Edam Holland is the protected name of the Netherlands\' great export cheese, recognisable worldwide by its red wax sphere. The PGI restricts production and ripening to the Netherlands, requires the milk to come from Dutch dairy farms, and allows whole, partially-skimmed or skimmed cow\'s milk that has either undergone no heat treatment or a sub-pasteurisation thermisation. Milk is cooled to no more than 6 °C on the farm and delivered in refrigerated tankers; set with rennet at about 30 °C, the curd is cut, drained and pressed into the iconic ball shape, brined, and matured naturally — open to the air, turned and inspected regularly — for a minimum of twenty-eight days for Baby Edam and up to a year or more for the aged grade. EU PGI came in 2010. The cheese has a fat content of forty per cent in dry matter — leaner than Gouda — and a paste that starts pale, supple and gently sweet, deepening to firm, savoury and faintly salty as it ages.","sources":[{"label":"Edam Holland PGI single document (EUR-Lex)","url":"https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52020XC0224(01)"},{"label":"Qualigeo: Edam Holland PGI","url":"https://www.qualigeo.eu/en/product/edam-holland-pgi/"},{"label":"Wikipedia: Edam cheese","url":"https://en.wikipedia.org/wiki/Edam_cheese"}],"pronunciation":{"ipa":"/ˈeːdɑm ˈɦɔlɑnt/","respelling":"AY-dam HOH-lant"},"region_polygon":{"type":"Polygon","coordinates":[[[3.4,53.5],[4.2,53.5],[5.45,53.5],[6.95,53.45],[7.1,52.55],[7.0,51.95],[6.2,51.45],[5.85,50.9],[5.05,51.3],[4.2,51.4],[3.5,51.55],[3.4,53.5]]]}},{"name":"Gouda Holland","lat":52.01,"lon":4.71,"country":"Netherlands","where":"Netherlands","hint":"Netherlands","desc":"Wheel cow\'s-milk cheese aged from jong (4 wks) to oude (12+ months); caramel notes develop with age.","image":"gouda_holland.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","hard","pressed","washed-curd"],"ageing_min_days":28,"format":"flattened wheel, ~2.5–20 kg","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Gouda Holland is the EU-protected name for the Dutch national cheese — a naturally matured semi-hard pressed wheel that takes its name from the cheese market town of Gouda. The PGI restricts production and ripening to the Netherlands and requires the milk to come from Dutch dairy farms. The milk is pasteurised at 72 °C for fifteen seconds, set with rennet at about 30 °C, the curd cut, washed, pressed into the iconic flat-edged wheel, brined and matured in Dutch cellars at a minimum of 12 °C. The wheel must mature at least twenty-eight days; in practice grades run from jong (one month) through belegen (four months), oud (ten months) and overjarige (a year or more). EU PGI came in 2010. Fat in dry matter sits between 48 % and 52 %, and salt in dry matter at most 4 %. Young Gouda is mild, supple and milky-sweet; well-aged wheels develop a deep amber paste, butterscotch-and-broth flavours and crunchy tyrosine crystals that put long-aged Gouda among the world\'s great connoisseur cheeses.","sources":[{"label":"EU Agri: Gouda Holland PGI / Noord-Hollandse Gouda PDO","url":"https://agriculture.ec.europa.eu/farming/geographical-indications-and-quality-schemes/geographical-indications-food-and-drink/gouda-holland-pgi-noord-hollandse-gouda-pdo_en"},{"label":"Wikipedia: Gouda, South Holland","url":"https://en.wikipedia.org/wiki/Gouda,_South_Holland"}],"pronunciation":{"ipa":"/ˈɣʌu̯daː ˈɦɔlɑnt/","respelling":"KHOW-dah HOH-lant"},"region_polygon":{"type":"Polygon","coordinates":[[[3.4,53.5],[4.2,53.5],[5.45,53.5],[6.95,53.45],[7.1,52.55],[7.0,51.95],[6.2,51.45],[5.85,50.9],[5.05,51.3],[4.2,51.4],[3.5,51.55],[3.4,53.5]]]}},{"name":"Kanterkaas / Kanternagelkaas / Kanterkomijnekaas","lat":53.2,"lon":6.6,"country":"Netherlands","where":"Groningen, Friesland, Drenthe","hint":"Northern Netherlands","desc":"Firm low-fat cow\'s-milk loaf, plain or with cumin (komijne) or cloves (nagel).","image":"kanterkaas.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["hard","low-fat","pressed","cumin","clove"],"ageing_min_days":28,"format":"flattened cylinder, ~3–8.5 kg","year_recognized":2000,"animal_breed":null,"vegetarian":null,"desc_long":"The Kanterkaas PDO covers three closely related Frisian cheeses: plain Kanterkaas, Kanterkomijnekaas (spiced with cumin), and Kanternagelkaas (spiced with both cumin and cloves). The PDO restricts production to the province of Friesland and the Westerkwartier district of Groningen, and requires pasteurised cow\'s milk thermised at 72 °C for fifteen seconds. Two fat grades are permitted: a 20+ skim-milk grade with twenty to twenty-five per cent fat in dry matter, and a 40+ grade at forty to forty-four per cent. The flattened-cylinder wheels weigh three to eight and a half kilograms, are pressed, brined, and matured at least four weeks at 12 °C. EU PDO came in 2000. The rind is natural or coated with a colourless or yellowish wax; Kanterkomijnekaas may carry a red wax. The plain version is firm, salty and milky; the spiced versions thread warm cumin (and in the Kanternagelkaas, the bell-clear sweetness of clove) through a robust, savoury paste — an old north-Netherlands tradition for keeping winter cheese fragrant.","sources":[{"label":"Qualigeo: Kanterkaas / Kanternagelkaas / Kanterkomijnekaas PDO","url":"https://www.qualigeo.eu/en/product/kanterkaas-kanternagelkaas-kanterkomijnekaas-pdo/"},{"label":"Wikipedia: Kanterkaas","url":"https://en.wikipedia.org/wiki/Kanterkaas"}],"pronunciation":{"ipa":"/ˈkɑntərkaːs/","respelling":"KAHN-ter-kahss"},"region_polygon":{"type":"Polygon","coordinates":[[[5.0,53.5],[6.0,53.55],[6.65,53.4],[6.55,53.05],[5.75,52.8],[5.05,52.8],[4.85,53.1],[5.0,53.5]]]}},{"name":"Noord-Hollandse Edammer","lat":52.5,"lon":5.0,"country":"Netherlands","where":"North Holland","hint":"North Holland","desc":"Edam-style red-rinded sphere made only from North-Holland milk; mild and slightly nutty.","image":"noord_hollandse_edammer.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","pressed","washed-curd","ball"],"ageing_min_days":28,"format":"ball, ~1.7–2 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Noord-Hollandse Edammer is the PDO version of Edam, restricted to milk from dairy farms in the province of North Holland and to maturation in Noord-Holland cellars. The recipe follows the classic Edam method: pasteurised partly-skimmed cow\'s milk is set with calf rennet, the curd cut into five-or-six-millimetre cubes, scalded, drained and pressed into the iconic ball mould, then brined for several days to bring the salt to spec. Wheels mature open-air for at least twenty-eight days, with two to three months for the typical jong grade and over six months for the more concentrated aged version. EU PDO came in 1996 — the original Edam protection, fourteen years before the broader Edam Holland PGI was registered. The cheese is lean (around forty per cent fat in dry matter), pale-ivory in paste, mildly sweet and supple when young, becoming firm, faintly salty and quietly nutty with age — and almost universally recognised in its red-wax export form.","sources":[{"label":"Qualigeo: Noord-Hollandse Edammer PDO","url":"https://www.qualigeo.eu/en/product/noord-hollandse-edammer-pdo/"},{"label":"Wikipedia: Gouda cheese","url":"https://en.wikipedia.org/wiki/Gouda_cheese"}],"pronunciation":{"ipa":"/noːrt ˈɦɔlɑntsə eːˈdɑmər/","respelling":"NORT HOH-lant-suh ay-DAH-mer"},"region_polygon":{"type":"Polygon","coordinates":[[[4.45,53.05],[5.1,53.1],[5.4,52.85],[5.3,52.45],[4.8,52.3],[4.5,52.5],[4.45,53.05]]]}},{"name":"Noord-Hollandse Gouda","lat":52.5,"lon":5.0,"country":"Netherlands","where":"North Holland","hint":"North Holland","desc":"Gouda wheel made strictly from North-Holland cow\'s milk; richer fat content than the PGI Gouda Holland.","image":"noord-hollandse_gouda.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","hard","pressed","washed-curd"],"ageing_min_days":28,"format":"flattened wheel, ~4–20 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Noord-Hollandse Gouda is the older, narrower PDO sibling of Gouda Holland: the same flat-wheeled pressed cheese, but made only from cow\'s milk drawn from the heavy clay-pasture dairy farms of the province of North Holland and matured entirely within Noord-Holland. The PDO maintains a continuous cold chain — milk cooled on-farm to no more than 6 °C, transported insulated, processed within 96 hours, and pasteurised at 72 °C for fifteen seconds before being set with rennet at about 30 °C. After cutting, washing and pressing, wheels are brined, then ripened in open-air cellars where the rind is turned and dressed regularly, and where the famously rich Noord-Holland marshland milk slowly delivers the cheese\'s hallmark deep, butterscotch-edged maturity. EU PDO came in 1996, four-teen years before the broader Gouda Holland PGI. The flavour at young grades is mild and milky; well-aged Noord-Hollandse Gouda becomes amber, dense and laced with tyrosine crystals — among the most prized aged Dutch cheeses.","sources":[{"label":"EU Agri: Noord-Hollandse Gouda PDO","url":"https://agriculture.ec.europa.eu/farming/geographical-indications-and-quality-schemes/geographical-indications-food-and-drink/gouda-holland-pgi-noord-hollandse-gouda-pdo_en"},{"label":"Wikipedia: Gouda cheese","url":"https://en.wikipedia.org/wiki/Gouda_cheese"}],"pronunciation":{"ipa":"/noːrt ˈɦɔlɑntsə ˈɣʌu̯daː/","respelling":"NORT HOH-lant-suh KHOW-dah"},"region_polygon":{"type":"Polygon","coordinates":[[[4.45,53.05],[5.1,53.1],[5.4,52.85],[5.3,52.45],[4.8,52.3],[4.5,52.5],[4.45,53.05]]]}},{"name":"Bryndza Podhalańska","lat":49.3,"lon":19.95,"country":"Poland","where":"Podhale, Tatra mountains","hint":"Polish Tatras","desc":"Soft spreadable raw sheep\'s-milk cheese from highlander (góral) summer pastures.","image":"bryndza_podhalanska.jpg","name_protections":["PDO"],"milk_types":["sheep","cow"],"pasteurization":"raw","style":["fresh","soft","salted","spreadable"],"ageing_min_days":14,"format":"soft mass, ~250 g – 5 kg","year_recognized":2007,"animal_breed":["Polska Owca Górska","Polska Krowa Czerwona"],"vegetarian":null,"desc_long":"Bryndza Podhalańska is the soft, salted sheep cheese of the Polish Tatra foothills — a tradition shared across the Carpathian arc but distinctively expressed in the Podhale highlands of Lesser Poland and the Beskid Żywiecki valleys of Silesia. The PDO restricts production to twelve named districts and the milk to that of the Polska Owca Górska (Polish Mountain Sheep), with up to forty per cent milk from the local Polska Krowa Czerwona red cattle permitted. Production runs only May through September, when the flocks are grazed on the alpine pastures. The raw sheep\'s milk is set with rennet and the curd matures briefly as a small bundle cheese, then is shredded, salted, and worked into the characteristic soft, creamy paste. EU PDO came in 2007; documentary references to bryndza in the region go back to 1527. The flavour is clean and tangy, sharply salty, with the lanolin warmth of mountain sheep — eaten by the spoon onto rye bread, melted into pierogi fillings, or stirred into the Tatra shepherd\'s pasta dish kwaśnica.","sources":[{"label":"Qualigeo: Bryndza Podhalańska PDO","url":"https://www.qualigeo.eu/en/product/bryndza-podhalanska-pdo/"},{"label":"Slow Food Ark of Taste: Raw Milk Podhale Bryndza","url":"https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/bryndza-podhalanska/"},{"label":"EUR-Lex: Commission Regulation (EC) No 642/2007 (Bryndza Podhalańska PDO)","url":"http://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=CELEX:32007R0642:EN:NOT"},{"label":"Wikipedia: Bryndza","url":"https://en.wikipedia.org/wiki/Bryndza"}],"pronunciation":{"ipa":"/ˈbrɨndza pɔdxaˈlaj̃ska/","respelling":"BRIN-dzah pod-hah-LIE-nyskah"},"region_polygon":{"type":"Polygon","coordinates":[[[19.0,49.7],[19.4,49.75],[19.8,49.7],[20.2,49.55],[20.1,49.3],[19.65,49.2],[19.15,49.25],[18.9,49.45],[19.0,49.7]]]}},{"name":"Oscypek","lat":49.3,"lon":19.95,"country":"Poland","where":"Podhale, Tatra mountains","hint":"Polish Tatras","desc":"Smoked spindle-shaped salted sheep\'s-milk cheese pressed in carved wooden moulds.","image":"oscypek.jpg","name_protections":["PDO"],"milk_types":["sheep","cow"],"pasteurization":"raw","style":["hard","smoked","pasta-filata","spindle"],"ageing_min_days":14,"format":"spindle, ~600–800 g, 17–23 cm long","year_recognized":2008,"animal_breed":null,"vegetarian":null,"desc_long":"Oscypek is the spindle-shaped smoked cheese of the Polish Tatra mountains, made by highland shepherds (bacówki) in wooden huts above Zakopane and elsewhere along the southern foothills. The PDO requires at least sixty per cent sheep\'s milk — from the Polska Owca Górska breed — with the remainder permitted as cow\'s milk; the cheese may only be produced between late April and early October when the flocks are on summer pasture. The curd is heated, kneaded, briefly stretched in the pasta-filata fashion, then pressed by hand into the elaborately carved wooden spindle moulds that imprint the cheese\'s signature geometric pattern. Wheels are soaked in salt brine, then smoked over pine or spruce wood in the same hut where they were made. Oscypek became the first Polish product to earn EU PDO protection in 2008. Wheels weigh six hundred to eight hundred grams and run seventeen to twenty-three centimetres long; the paste is firm and ivory-yellow, the rind a deep tan-amber from the smoke, and the flavour resinous, salty, and sheep-milk-rich.","sources":[{"label":"Wikipedia: Oscypek","url":"https://en.wikipedia.org/wiki/Oscypek"},{"label":"Slow Food Presidia: Oscypek","url":"https://www.fondazioneslowfood.com/en/slow-food-presidia/oscypek/"},{"label":"EUR-Lex: Commission Regulation (EC) No 127/2008 (Oscypek PDO, PDF)","url":"https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:32008R0127"}],"pronunciation":{"ipa":"/ɔsˈtsɨpɛk/","respelling":"ohs-TSI-pek"},"region_polygon":{"type":"Polygon","coordinates":[[[19.0,49.7],[19.4,49.75],[19.8,49.7],[20.2,49.55],[20.1,49.3],[19.65,49.2],[19.15,49.25],[18.9,49.45],[19.0,49.7]]]}},{"name":"Redykołka","lat":49.3,"lon":19.95,"country":"Poland","where":"Podhale, Tatra mountains","hint":"Polish Tatras","desc":"Small smoked sheep\'s-milk cheese in decorative shapes — birds, hearts, stags — gift cousin of oscypek.","image":"redykołka.jpg","name_protections":["PDO"],"milk_types":["sheep","cow"],"pasteurization":"raw","style":["semi-hard","smoked","decorative"],"ageing_min_days":7,"format":"small decorative shape, ~30–300 g","year_recognized":2009,"animal_breed":null,"vegetarian":null,"desc_long":"Redykołka is the diminutive sibling of Oscypek — a small smoked cheese made in the Polish Tatra mountains from the same milk, by the same shepherds, but in the playful shapes of animals, birds, hearts and tiny spindles rather than the formal carved cylinder of Oscypek. The PDO permits sheep\'s milk with a cow\'s-milk admixture, and ties production to the same Podhale and Beskid pastures and the same May-to-October season. The name derives from redyk, the ceremonial procession by which the flocks are driven up to the summer alpages in spring and back down in autumn; redykołki were historically given as gifts on these occasions, always in even numbers, to children and travellers. EU PDO came in 2009. Each piece must not exceed three hundred grams and the smallest spindle versions run thirty to sixty grams. The cheese is drier and more crumbly than Oscypek but otherwise close in profile — white-ivory paste, straw-amber smoked rind, salty resinous flavour — and is the closest thing in the European GI register to a sculptural cheese.","sources":[{"label":"Cheese Professor: Polish cheeses guide","url":"https://www.cheeseprofessor.com/blog/10-great-polish-cheeses"},{"label":"EUR-Lex: Commission Regulation (EC) No 1176/2009 (Redykołka PDO)","url":"http://data.europa.eu/eli/reg/2009/1176/oj/eng"},{"label":"Wikipedia: Redykołka","url":"https://en.wikipedia.org/wiki/Redykołka"}],"pronunciation":{"ipa":"/rɛdɨˈkɔwka/","respelling":"reh-di-KOW-kah"},"region_polygon":{"type":"Polygon","coordinates":[[[19.0,49.7],[19.4,49.75],[19.8,49.7],[20.2,49.55],[20.1,49.3],[19.65,49.2],[19.15,49.25],[18.9,49.45],[19.0,49.7]]]}},{"name":"Ser koryciński swojski","lat":53.45,"lon":23.55,"country":"Poland","where":"Korycin, Podlasie","hint":"Podlasie, NE Poland","desc":"Soft pressed cow\'s-milk cheese in a cylinder; plain or with herbs, peppercorns, nettle.","image":"ser_korycinski_swojski.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed","farmhouse"],"ageing_min_days":2,"format":"flattened sphere, ~2.5–5 kg, fluted","year_recognized":2012,"animal_breed":null,"vegetarian":null,"desc_long":"Ser koryciński swojski is the farmhouse cheese of the Korycin, Suchowola and Janów districts of Podlasie in northeastern Poland — a tradition that grew up among small-holder dairies of the Sokółka County and was formalised under PGI in 2012. The spec requires whole cow\'s milk, raw or pasteurised, from cattle that pasture-graze at least one hundred-fifty days a year on local forages, with hay, cereal and silage as the winter feed. Rennet and table salt are added; pasteurised batches also receive lactic acid cultures. No physical or chemical treatment beyond pasteurisation and filtering is permitted. Optional add-ins — caraway, dill, garlic, paprika, basil, fenugreek, nuts, sun-dried tomato — give the cheese a wide style range. The PGI defines three age grades: świeży (fresh, two to four days), leżakowany (matured, five to fourteen days) and dojrzały (ripe, beyond fourteen days). Wheels are flattened spheres up to thirty centimetres across with a distinct fluted surface and plentiful small eyes, weighing 2.5–5 kg.","sources":[{"label":"GOV.UK: Ser koryciński swojski PGI","url":"https://www.gov.uk/protected-food-drink-names/ser-korycinski-swojski"},{"label":"Wikipedia: Korycinski","url":"https://en.wikipedia.org/wiki/Korycinski"}],"pronunciation":{"ipa":"/sɛr kɔrɨˈtɕiɲskʲi ˈsfɔjskʲi/","respelling":"ser koh-ri-CHEEN-skee SFOY-skee"},"region_polygon":{"type":"Polygon","coordinates":[[[22.95,53.7],[23.3,53.75],[23.55,53.65],[23.55,53.45],[23.25,53.35],[22.95,53.45],[22.95,53.7]]]}},{"name":"Wielkopolski ser smażony","lat":52.4,"lon":16.9,"country":"Poland","where":"Greater Poland (Wielkopolska)","hint":"Wielkopolska, western Poland","desc":"Fried/melted sour-milk curd cheese; spreadable, with caraway or paprika.","image":"wielkopolski_ser_smazony.jpeg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["fried-curd","sour-curd","spreadable"],"ageing_min_days":2,"format":"small block or jar, ~150–250 g","year_recognized":2009,"animal_breed":null,"vegetarian":null,"desc_long":"Wielkopolski ser smażony is the fried sour-curd cheese of Greater Poland (Wielkopolska), a regional specialty in which a ripened twaróg (quark) is melted with butter and salt to produce a glossy, spreadable cheese with a notably long shelf life. The PGI restricts production to the administrative boundaries of the Wielkopolska Voivodeship. Skimmed milk is heated for thirty seconds at 70–75 °C, soured at 20–23 °C with a starter culture, then slowly warmed over about two hours to 32–33 °C; the curd is drained and ripened two to three days at 16–27 °C, after which it is mixed with butter (no other fat is allowed), salt, and optionally caraway, and fried for about fifteen minutes at no less than 90 °C. The hot cheese must be packed immediately at the producing dairy. EU PGI came in 2009. The cheese has a firm, glossy, elastic consistency and a colour from light cream to deep yellow; the flavour is rich, salty and lightly nutty — eaten on rye bread with onion and pickle, a household staple of Wielkopolska tables.","sources":[{"label":"Qualigeo: Wielkopolski ser smażony PGI","url":"https://www.qualigeo.eu/en/product/wielkopolski-ser-smazony-pgi/"},{"label":"Wikipedia: Wielkopolski ser smażony","url":"https://en.wikipedia.org/wiki/Wielkopolski_ser_sma%C5%BCony"}],"pronunciation":{"ipa":"/vʲɛlkɔˈpɔlskʲi sɛr smaˈʐɔnɨ/","respelling":"vyel-koh-POL-skee ser smah-ZHOH-ni"},"region_polygon":{"type":"Polygon","coordinates":[[[15.6,53.1],[16.65,53.15],[17.85,53.05],[19.1,52.85],[19.3,52.1],[18.55,51.35],[17.5,51.35],[16.45,51.55],[15.65,51.8],[15.55,52.5],[15.6,53.1]]]}},{"name":"Queijo de Azeitão","lat":38.52,"lon":-9.02,"country":"Portugal","where":"Serra da Arrábida, near Setúbal","hint":"Setúbal peninsula, south of Lisbon","desc":"Soft sheep\'s-milk cheese curdled with wild cardoon thistle; runny enough to spoon.","image":"queijo_de_azeitão.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-soft","cardoon-rennet","thistle"],"ageing_min_days":21,"format":"small flat cylinder, ~100–250 g","year_recognized":1996,"animal_breed":null,"vegetarian":true,"desc_long":"Queijo de Azeitão is the small soft cardoon-rennet cheese of the Arrábida foothills south of Lisbon, made in the councils of Palmela, Sesimbra and Setúbal. The recipe is a southern cousin of Serra da Estrela, brought to the Azeitão area in the nineteenth century by Gaspar Henriques de Paiva, who introduced Bordaleira sheep to the region. The PDO requires raw ewe\'s milk and a vegetable rennet of macerated Cynara cardunculus flowers: the milk is warmed to 30–32 °C, salted at twenty grams per litre, set with the cardoon infusion, drained, moulded into short flat cylinders of one hundred to two-hundred-fifty grams and aged at least twenty-one days. EU PDO came in 1996. The cheese has a malleable yellowish rind and a creamy, almost-runny ivory paste, with a flavour that is gently sheepish, faintly bitter from the cardoon, and very long on the palate. Like Serra, it is eaten by cutting off the top and spooning out the paste.","sources":[{"label":"DGADR: Queijo de Azeitão PDO","url":"https://tradicional.dgadr.gov.pt/en/categories/cheese-and-other-dairy-products/37-queijo-de-azeitao-pdo"},{"label":"Wikipedia: Queijo de Azeitão","url":"https://en.wikipedia.org/wiki/Queijo_de_Azeitão"}],"pronunciation":{"ipa":"/ˈkɐjʒu dɨ ɐzɐjˈtɐ̃w/","respelling":"KAY-zhoo duh ah-zay-TOWNG"},"region_polygon":{"type":"Polygon","coordinates":[[[-9.2,38.65],[-8.85,38.65],[-8.65,38.55],[-8.7,38.4],[-9.1,38.4],[-9.2,38.55],[-9.2,38.65]]]}},{"name":"Queijo de Cabra Transmontano / Velho","lat":41.6,"lon":-7.0,"country":"Portugal","where":"Trás-os-Montes","hint":"Trás-os-Montes, NE Portugal","desc":"Hard goat\'s-milk cheese from Serrana goats; an aged \'Velho\' version goes deeply pungent.","image":"queijo_de_cabra_transmontano.jpeg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["hard","pressed"],"ageing_min_days":60,"format":"wheel, ~600 g – 1 kg","year_recognized":1996,"animal_breed":["Serrana"],"vegetarian":null,"desc_long":"Queijo de Cabra Transmontano is the goat cheese of Trás-os-Montes in northeastern Portugal, made from raw milk of the Cabra Serrana breed in the rugged Bragança and Vila Real districts. The Serrana goats are raised semi-extensively and graze on broom, heather and other aromatic shrubs of the highlands — a diet that gives the milk a strongly herbal character. The PDO calls for the filtered milk to be warmed to 35 °C, set with natural rennet, drained, salted, and matured at least sixty days with regular turning and washing. Wheels matured beyond ninety days — sometimes up to two years — earn the Velho suffix and are traditionally rubbed with olive oil and paprika, giving the rind its characteristic ochre red. EU PDO came in 1996. Young Transmontano carries a white rind, firm paste and clean herbal-goat flavour; Velho develops a dense brittle paste, a punchy goat tang and a long, almost nutty finish — a remarkable expression of mountain goat dairying.","sources":[{"label":"Qualigeo: Queijo de Cabra Transmontano / Velho PDO","url":"https://www.qualigeo.eu/en/product/queijo-de-cabra-transmontanoqueijo-de-cabra-transmontano-velho-pdo/"},{"label":"Wikipedia: Queijo de Cabra Transmontano","url":"https://en.wikipedia.org/wiki/Queijo_de_Cabra_Transmontano"}],"pronunciation":{"ipa":"/ˈkɐjʒu dɨ ˈkaβɾɐ tɾɐ̃ʒmõˈtɐnu/","respelling":"KAY-zhoo duh KAH-brah trahnzh-mohn-TAH-noo"},"region_polygon":{"type":"Polygon","coordinates":[[[-7.5,41.95],[-6.55,41.95],[-6.3,41.7],[-6.5,41.3],[-7.4,41.3],[-7.85,41.45],[-7.85,41.75],[-7.5,41.95]]]}},{"name":"Queijo de Évora","lat":38.57,"lon":-7.91,"country":"Portugal","where":"Évora district, Alentejo","hint":"Central Alentejo","desc":"Sheep\'s-milk cheese in semi-hard or hard form, slightly piquant and salty.","image":"queijo_de_evora.webp","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","semi-hard","cardoon-rennet","thistle"],"ageing_min_days":30,"format":"small wheel, ~150–300 g","year_recognized":1996,"animal_breed":["Merina Branca"],"vegetarian":true,"desc_long":"Queijo de Évora is the cardoon-rennet sheep cheese of central Alentejo, made around the city of Évora in a tradition rooted in the abundant Merino sheep flocks of the region. The PDO requires raw milk from the Merina Branca breed, processed within an hour of milking, and an aqueous infusion of cardoon (Cynara cardunculus) flowers as the only coagulant. Coagulation takes twenty to forty minutes; the cheese is then drained, moulded into small wheels of one hundred-fifty to three hundred grams, and matured at 8–15 °C and high humidity. Sold as a semi-hard cheese at thirty days or as a hard cheese at ninety, the latter version is the more characteristic. EU PDO came in 1996. The cheese has a thin yellowish rind and a firm ivory paste with few or no eyes; the flavour is markedly piquant, faintly bitter from the cardoon, and concentrated in the harder grades — sharper and more aggressive than its cousins Serra da Estrela and Serpa.","sources":[{"label":"Qualigeo: Queijo de Évora PDO","url":"https://www.qualigeo.eu/en/product/queijo-de-evora-pdo/"},{"label":"DGADR: Queijo de Évora PDO","url":"https://tradicional.dgadr.gov.pt/en/categories/cheese-and-other-dairy-products/371-queijo-de-evora-dop-en"}],"pronunciation":{"ipa":"/ˈkɐjʒu dɨ ˈɛvuɾɐ/","respelling":"KAY-zhoo duh EH-voo-rah"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.4,38.85],[-7.85,38.95],[-7.2,38.8],[-7.15,38.4],[-7.65,38.2],[-8.3,38.3],[-8.45,38.6],[-8.4,38.85]]]}},{"name":"Queijo de Nisa","lat":39.5,"lon":-7.65,"country":"Portugal","where":"Alto Alentejo","hint":"Northern Alentejo","desc":"Sheep\'s-milk cheese curdled with cardoon; semi-hard, lightly piquant, distinctive eye-pattern.","image":"queijo_de_nisa.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-hard","cardoon-rennet","thistle"],"ageing_min_days":45,"format":"small wheel, ~200 g – 1.3 kg","year_recognized":1996,"animal_breed":["Merina Branca"],"vegetarian":true,"desc_long":"Queijo de Nisa is a semi-hard cardoon-rennet sheep cheese from the Alto Alentejo, made in the upland zone around Nisa, Crato, Castelo de Vide, Marvão, Portalegre, Monforte, Arronches and Alter do Chão in the Portalegre district. The PDO requires raw milk from the Merina Branca breed and a coagulant made from an aqueous infusion of the stamens of Cynara cardunculus. The set milk is coagulated at 25–28 °C over forty-five to sixty minutes, the curd cut, moulded and hand-pressed, then aged in two phases — fifteen to twenty days at 8–10 °C and eighty per cent humidity, then a further month at slightly warmer temperatures and higher humidity. EU PDO came in 1996. The wheels carry a thin natural rind and a firm ivory paste shot through with small irregular gas holes; the flavour is sharp, sheep-fatted and faintly herbaceous from the cardoon, falling between the buttery softness of Serra and the more aggressive bite of Évora.","sources":[{"label":"Wikipedia: Queijo de Nisa","url":"https://en.wikipedia.org/wiki/Queijo_de_Nisa"},{"label":"Qualigeo: Queijo de Nisa PDO","url":"https://www.qualigeo.eu/en/product/queijo-de-nisa-pdo/"}],"pronunciation":{"ipa":"/ˈkɐjʒu dɨ ˈnizɐ/","respelling":"KAY-zhoo duh NEE-zah"},"region_polygon":{"type":"Polygon","coordinates":[[[-7.95,39.65],[-7.4,39.7],[-7.0,39.55],[-7.05,39.2],[-7.5,39.1],[-7.95,39.25],[-7.95,39.65]]]}},{"name":"Queijo do Pico","lat":38.46,"lon":-28.4,"country":"Portugal","where":"Pico island, Azores","hint":"Azores","desc":"Soft cow\'s-milk cheese from the volcanic island of Pico; salty, intense, runny when ripe.","image":"queijo_do_pico.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","moist","buttery"],"ageing_min_days":17,"format":"wheel, ~700–800 g (16–17 cm dia)","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Queijo do Pico is the soft moist cow\'s-milk cheese of Pico island in the Azores, second of the three Azorean PDO cheeses alongside São Jorge and the Azores\'s smaller Velho. The PDO requires raw milk from cattle reared in extensive conditions on the island\'s volcanic pastures of ryegrass, hop trefoil and aromatic shrubs. Milk is filtered and held at 26–27 °C, set with salted rennet over forty-five to sixty minutes, then the curd is cut to small cubes, drained in muslin, hand-pressed into 16-17 cm moulds, and dry-salted on each side. Wheels finish in chambers at 15–17 °C and 75–85 % humidity over seventeen to thirty days. EU PDO came in 1996. The cheese weighs seven hundred to eight hundred grams and carries 45–49 % fat with 67–71 % moisture — exceptionally moist for a name-protected cheese — with a salty, intensely lactic flavour and a long mineral finish that locals trace to the basaltic terroir of Pico.","sources":[{"label":"Qualigeo: Queijo do Pico PDO","url":"https://www.qualigeo.eu/en/product/queijo-do-pico-pdo/"},{"label":"Wikipedia: Queijo do Pico","url":"https://en.wikipedia.org/wiki/Queijo_do_Pico"},{"label":"Açores Government: Caderno de especificações DOP Queijo do Pico (PDF)","url":"http://www.azores.gov.pt/NR/rdonlyres/45C92927-F130-4E8F-B67B-C472E500AFAC/506819/CadernoEspecificaesDopQueijoDoPico2.pdf"}],"pronunciation":{"ipa":"/ˈkɐjʒu du ˈpiku/","respelling":"KAY-zhoo doo PEE-koo"},"region_polygon":{"type":"Polygon","coordinates":[[[-28.55,38.55],[-28.3,38.55],[-28.0,38.45],[-28.05,38.3],[-28.4,38.3],[-28.55,38.45],[-28.55,38.55]]]}},{"name":"Queijo Mestiço de Tolosa","lat":39.45,"lon":-7.8,"country":"Portugal","where":"Tolosa, Alentejo","hint":"Alentejo","desc":"Mixed sheep-and-goat milk cheese curdled with cardoon; soft to semi-hard.","image":"queijo_mestiço_de_tolosa.jpeg","name_protections":["PGI"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["semi-hard","paprika-rubbed"],"ageing_min_days":21,"format":"small wheel, ~200–500 g","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Queijo Mestiço de Tolosa is the \\"mixed-blood\\" cheese of the Alto Alentejo, named for its built-in blend of sheep\'s and goat\'s milk — the recipe accepts ratios anywhere from 20:80 to 80:20, never pure. The PGI restricts production to a fifteen-municipality zone in the Portalegre district around Nisa, Crato, Castelo de Vide and Marvão. After the raw milk is filtered through muslin and heated to 30 °C, coagulation is set either with animal rennet or with a cardoon infusion. Curds are drained, salted over four to five days, and matured for three to four weeks in a climate-controlled chamber, during which each wheel is soaked in a bath of pimento powder and water that gives the rind its signature orange-red colour. EU PGI came in 1996. The cheese has a firm, faintly elastic paste and a flavour that balances the sweetness of sheep\'s milk with the goat\'s-milk tang, lifted by the warm sweet bite of the paprika rind. The recipe dates to the first years of the twentieth century.","sources":[{"label":"DGADR: Queijo Mestiço de Tolosa PGI","url":"https://tradicional.dgadr.gov.pt/en/categories/cheese-and-other-dairy-products/388-queijo-mestico-de-tolosa-igp-en"}],"pronunciation":{"ipa":"/ˈkɐjʒu mɨʃˈtisu dɨ tuˈlozɐ/","respelling":"KAY-zhoo mesh-TEE-soo duh too-LOH-zah"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.0,39.7],[-7.3,39.75],[-6.9,39.55],[-7.0,39.05],[-7.65,38.9],[-8.1,39.05],[-8.2,39.45],[-8.0,39.7]]]}},{"name":"Queijo Rabaçal","lat":39.96,"lon":-8.45,"country":"Portugal","where":"Coimbra district","hint":"Central Portugal","desc":"Small mixed sheep-and-goat milk cheese; firm, slightly piquant, ages dry.","image":"queijo_rabaçal.jpeg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["semi-hard","pressed"],"ageing_min_days":20,"format":"small wheel, ~300–600 g","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Queijo Rabaçal is the small farmhouse cheese of the central Portuguese hills between Coimbra and Leiria, made in a defined zone around Penela, Condeixa-a-Nova, Soure, Ansião, Alvaiázere and Pombal. The PDO requires a two-thirds-sheep, one-third-goat milk blend, both raw and hand-collected, with the animals grazed on the herb-rich uplands where Thymus mastichina (\\"Santa Maria\\" thyme) grows wild — a flora the cheese famously expresses in its aroma. The milk is filtered, warmed to 30 °C, set with goat-abomasum rennet over forty-five minutes, drained by hand, lightly pressed, salted, and matured at 10–15 °C with no more than eighty-five per cent humidity for at least twenty days. EU PDO came in 1996. Wheels are dull-white, semi-hard, sparsely eyed, with 45 % fat and 52–60 % moisture. The flavour is gently lactic and sweet up front, with the thyme-grazing perfume lifting the finish — a discreet, very regional cheese that rewards close attention.","sources":[{"label":"Qualigeo: Queijo Rabaçal PDO","url":"https://www.qualigeo.eu/en/product/queijo-rabacal-pdo/"}],"pronunciation":{"ipa":"/ˈkɐjʒu ʁɐβɐˈsal/","respelling":"KAY-zhoo rah-bah-SAHL"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.65,40.2],[-8.3,40.25],[-8.1,40.05],[-8.2,39.8],[-8.55,39.75],[-8.7,39.95],[-8.65,40.2]]]}},{"name":"Queijo S. Jorge","lat":38.65,"lon":-28.0,"country":"Portugal","where":"São Jorge island, Azores","hint":"Azores","desc":"Aged hard cow\'s-milk cheese, sharp and lightly piquant — flavored by lush Atlantic island grass.","image":"queijo__s_jorge.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","pressed"],"ageing_min_days":90,"format":"wheel, ~8–12 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Queijo São Jorge is the great cow\'s-milk cheese of the Azores, produced exclusively on the island of São Jorge in the central Azorean archipelago. The PDO requires whole raw milk from cattle grazed on the island\'s volcanic pastures and forbids pasteurisation in order to preserve the natural microbial flora that gives São Jorge its distinctive piquancy. Only salt and whey from the previous day\'s batch may be used alongside the rennet. The pressed curd rests at least thirty days at ambient temperature, then ages at 12–14 °C and 80–85 % humidity for at least another sixty days, for a minimum total ripening of ninety days. EU PDO came in 1996. The wheels are hard to semi-hard, yellow, marked by small irregular eyes and a firm but brittle paste. The flavour is sharp and intensely savoury — moreso the longer the wheel matures — with the salt and grass of the mid-Atlantic clearly audible in mature lots.","sources":[{"label":"Qualigeo: Queijo S. Jorge PDO","url":"https://www.qualigeo.eu/en/product/queijo-s-jorge-pdo/"},{"label":"Wikipedia: São Jorge cheese","url":"https://en.wikipedia.org/wiki/S%C3%A3o_Jorge_cheese"},{"label":"Diário da República: Decreto Regulamentar Regional 24/86/A (Queijo S. Jorge, PDF)","url":"https://dre.pt/pdf1sdip/1986/07/15500/16451646.PDF"}],"pronunciation":{"ipa":"/ˈkɐjʒu sɐ̃w ˈʒɔɾʒɨ/","respelling":"KAY-zhoo sown ZHOR-zhuh"},"region_polygon":{"type":"Polygon","coordinates":[[[-28.4,38.8],[-28.1,38.75],[-27.75,38.65],[-27.8,38.55],[-28.2,38.6],[-28.35,38.7],[-28.4,38.8]]]}},{"name":"Queijo Serpa","lat":37.95,"lon":-7.6,"country":"Portugal","where":"Baixo Alentejo","hint":"Southern Alentejo","desc":"Soft sheep\'s-milk cheese curdled with cardoon; ripe interior, pungent and runny.","image":"queijo_serpa.jpeg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-soft","cardoon-rennet","thistle"],"ageing_min_days":30,"format":"small wheel, ~200 g – 2 kg","year_recognized":1996,"animal_breed":null,"vegetarian":true,"desc_long":"Queijo Serpa is the cardoon-rennet sheep cheese of the Baixo Alentejo, made across a fifteen-municipality zone centred on Serpa and stretching into the Beja and Setúbal districts. The PDO requires raw ewe\'s milk — historically from Merino flocks, now more often from Lacaune sheep raised in semi-wild conditions across the cork-oak montado. Cardoon flowers (Cynara cardunculus) gathered in late spring are dried, crushed and soaked overnight to make the vegetable rennet, the same coagulant used for Serra da Estrela and Azeitão. The set milk is drained slowly, salted, and aged a minimum of thirty days. EU PDO came in 1996. Serpa has a creamy semi-soft paste with very few eyes, a thin tan rind, and a richer, more piquant flavour than Serra da Estrela — pasture-fed sheep\'s-milk sweetness lifted by the bittering note of the cardoon and a long, savoury finish characteristic of the Alentejo.","sources":[{"label":"Wikipedia: Serpa cheese","url":"https://en.wikipedia.org/wiki/Serpa_cheese"},{"label":"DGADR: Queijo Serpa PDO","url":"https://tradicional.dgadr.gov.pt/en/categories/cheese-and-other-dairy-products/376-queijo-de-serpa-dop-en"}],"pronunciation":{"ipa":"/ˈkɐjʒu ˈsɛɾpɐ/","respelling":"KAY-zhoo SAIR-pah"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.45,38.4],[-7.85,38.4],[-7.3,38.2],[-7.3,37.65],[-7.95,37.55],[-8.5,37.75],[-8.55,38.15],[-8.45,38.4]]]}},{"name":"Queijo Serra da Estrela","lat":40.32,"lon":-7.62,"country":"Portugal","where":"Beira Alta — Serra da Estrela","hint":"Serra da Estrela mountains","desc":"Soft sheep\'s-milk cheese curdled with cardoon flower; sliced open and eaten with a spoon.","image":"queijo_serra_da_estrela.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-soft","cardoon-rennet","thistle"],"ageing_min_days":30,"format":"small wheel, ~700 g – 1.7 kg","year_recognized":1996,"animal_breed":["Bordaleira Serra da Estrela","Churra Mondegueira"],"vegetarian":true,"desc_long":"Queijo Serra da Estrela is the most celebrated cheese of Portugal, made in the mountain districts of Viseu, Coimbra, Guarda and Castelo Branco around the Serra da Estrela range. The PDO restricts the milk to that of the local Bordaleira Serra da Estrela and Churra Mondegueira sheep breeds, and the rennet to an aqueous extract of cardoon (Cynara cardunculus) flowers — making this one of the great vegetable-rennet cheeses of Europe. Raw milk is heated to 28–32 °C, coagulated with the cardoon infusion over forty-five to sixty minutes, then drained slowly and aged at 6–12 °C in eighty to ninety-five per cent humidity, with regular washing and turning. Cheeses are sold from thirty days; wheels aged at least four months earn the suffix Velho. EU PDO came in 1996. Young Serra is famously soft enough that the rind is cut off the top and the molten paste is scooped out with a spoon — buttery, faintly bitter from the cardoon, and intensely sheep-milk-rich. Velho develops a firmer, sharper, more concentrated profile.","sources":[{"label":"Wikipedia: Serra da Estrela cheese","url":"https://en.wikipedia.org/wiki/Serra_da_Estrela_cheese"},{"label":"DGADR: Queijo Serra da Estrela PDO","url":"https://tradicional.dgadr.gov.pt/en/categories/cheese-and-other-dairy-products/377-queijo-da-serra-da-estrela-en"}],"pronunciation":{"ipa":"/ˈkɐjʒu ˈsɛʁɐ dɐ ɨʃˈtɾelɐ/","respelling":"KAY-zhoo SAIR-rah dah esh-TREH-lah"},"region_polygon":{"type":"Polygon","coordinates":[[[-7.9,40.85],[-7.3,40.9],[-6.9,40.75],[-6.95,40.35],[-7.45,40.1],[-7.95,40.3],[-8.0,40.65],[-7.9,40.85]]]}},{"name":"Queijo Terrincho","lat":41.4,"lon":-7.0,"country":"Portugal","where":"Terra Quente, Trás-os-Montes","hint":"Trás-os-Montes","desc":"Semi-hard sheep\'s-milk cheese from Churra-da-Terra-Quente ewes; clean, slightly buttery.","image":"queijo_terrincho.jpeg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-hard","hard","pressed"],"ageing_min_days":30,"format":"small wheel, ~700 g – 1.1 kg","year_recognized":1996,"animal_breed":["Churra da Terra Quente"],"vegetarian":null,"desc_long":"Queijo Terrincho is the sheep cheese of the Douro Superior and Trás-os-Montes hills, made from the raw milk of the Churra da Terra Quente breed — locally called terrincha — which has dominated the region\'s sheep population since the nineteenth century. The PDO covers a thirteen-municipality zone across the Bragança, Vila Real, Viseu and Guarda districts. The milk is filtered, heated to 35 °C, set with animal rennet, moulded, drained, salted and dried, then matured at 5–12 °C and 80–85 % humidity for at least thirty days; wheels aged ninety days or more carry the Velho suffix. EU PDO came in 1996. Young Terrincho has a thin pale rind and a firm ivory paste; Velho is harder, deeper yellow, and considerably more pungent. The flavour is markedly sheep-fat-rich with a clean lactic backbone — a workhorse cheese of the eastern Portuguese mountains that pairs especially well with the strong reds of the Douro Superior.","sources":[{"label":"Qualigeo: Queijo Terrincho PDO","url":"https://www.qualigeo.eu/en/product/queijo-terrincho-pdo/"}],"pronunciation":{"ipa":"/ˈkɐjʒu tɨˈʁĩʃu/","respelling":"KAY-zhoo tuh-REEN-shoo"},"region_polygon":{"type":"Polygon","coordinates":[[[-7.3,41.65],[-6.85,41.65],[-6.5,41.55],[-6.45,41.2],[-6.85,41.0],[-7.25,41.1],[-7.4,41.4],[-7.3,41.65]]]}},{"name":"Queijos da Beira Baixa","lat":39.83,"lon":-7.49,"country":"Portugal","where":"Beira Baixa","hint":"Central-east Portugal","desc":"Family of cheeses (Castelo Branco, Amarelo, Picante) from sheep & goat milk; mild to fiery.","image":"queijos_da_beira_baixa.jpg","name_protections":["PDO"],"milk_types":["sheep","goat"],"pasteurization":"raw","style":["semi-soft","semi-hard","hard"],"ageing_min_days":30,"format":"wheel; varies by sub-type, ~200–800 g","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Queijos da Beira Baixa is a single PDO that bundles three closely related raw-milk cheeses of the Castelo Branco district and adjacent Santarém municipalities. Queijo de Castelo Branco is made from raw ewe\'s milk into a yellow-rinded, semi-hard wheel with a deep sheep-fat character that turns gently spicy with age. Queijo Amarelo da Beira Baixa is made from raw ewe\'s milk or a mixed ewe-and-goat milk, similar in format but with a milder, cleaner, faintly acidic profile and a buttery, almost-runny young grade. Queijo Picante da Beira Baixa is the longest-aged and most distinctive of the three: a hard, greyish-white wheel made from raw ewe and goat milk, salt-and-pepper treated through ripening, and finished with the marked pungency that gives it its name. EU PDO came in 1996. Production traces back to about 1870, when the cheeses found their main market in Lisbon and the recipes were codified in the small mountain dairies of the Beira Interior.","sources":[{"label":"Qualigeo: Queijos da Beira Baixa PDO","url":"https://www.qualigeo.eu/en/product/queijos-da-beira-baixa-queijo-de-castelo-branco-queijo-amarelo-da-beira-baixa-queijo-picante-da-beira-baixa-pdo/"},{"label":"Wikipedia: Castelo Branco cheese","url":"https://en.wikipedia.org/wiki/Castelo_Branco_cheese"}],"pronunciation":{"ipa":"/ˈkɐjʒuʃ dɐ ˈbɐjɾɐ ˈbajʃɐ/","respelling":"KAY-zhoosh dah BAY-rah BY-shah"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.1,40.2],[-7.55,40.25],[-6.95,40.15],[-6.85,39.8],[-7.1,39.55],[-7.65,39.55],[-8.1,39.85],[-8.1,40.2]]]}},{"name":"Telemea de Ibănești","lat":46.82,"lon":24.93,"country":"Romania","where":"Gurghiu valley, Mureș","hint":"Transylvania","desc":"Brined sheep\'s-milk cheese from Gurghiu valley pastures; firm, lightly salty.","image":"telemea_de_ibanesti.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-soft","brined","white"],"ageing_min_days":20,"format":"blocks in brine, ~1 kg","year_recognized":2017,"animal_breed":null,"vegetarian":null,"desc_long":"Telemea de Ibănești is the white brined cheese of the Gurghiu Valley in Mureș County, Transylvania, and the first Romanian cheese to win EU PDO recognition. The spec restricts production to the municipalities of Ibănești, Hodac and Gurghiu, and the milk to that of indigenous cow breeds raised extensively on the valley\'s high-nature-value pastures, with the cattle on grass at least six months a year. The cheese is salted in naturally saline water drawn from the wells at Orșova — a distinguishing detail of the Ibănești tradition — rather than with refined salt. The recipe sets the milk quickly with rennet (in under an hour), cuts the curd to fine grain, and drains and presses it into moulds before brining and maturing for at least twenty days for the mature grade. EU PDO came in 2017. The cheese is white to faintly yellow, lightly crumbly and moist, with a creamy-salty-sour balance that deepens as it matures — a precise expression of the Carpathian dairy tradition that has its broader name, telemea, across Romania and beyond.","sources":[{"label":"Wikipedia: Telemea","url":"https://en.wikipedia.org/wiki/Telemea"}],"pronunciation":{"ipa":"/teleˈme̯a de ibəˈneʃtʲ/","respelling":"teh-leh-MYAH day ee-buh-NESHT"},"region_polygon":{"type":"Polygon","coordinates":[[[24.65,46.85],[25.05,46.9],[25.35,46.8],[25.4,46.55],[25.1,46.4],[24.7,46.5],[24.6,46.7],[24.65,46.85]]]}},{"name":"Telemea de Sibiu","lat":45.79,"lon":24.15,"country":"Romania","where":"Sibiu county","hint":"Southern Transylvania","desc":"Brined sheep\'s-milk cheese, semi-firm with a clean tang; the Romanian feta-style classic.","image":"telemea_de_sibiu.jpg","name_protections":["PGI"],"milk_types":["sheep"],"pasteurization":"raw","style":["semi-soft","semi-hard","brined","white"],"ageing_min_days":21,"format":"blocks in brine, ~1 kg","year_recognized":2019,"animal_breed":null,"vegetarian":null,"desc_long":"Telemea de Sibiu is the protected sheep\'s-milk version of Romanian telemea, made entirely from fresh raw sheep\'s milk in Sibiu county in central Transylvania. The PGI requires every stage — raising, grazing, milking, making and maturing — to take place within Sibiu county; the sheep must graze the local grasslands for two hundred to two hundred-thirty days per year (April through November), with hay and non-fermented green fodder used in winter. The Producers\' Association covers ten member operations with over twenty thousand sheep. The recipe sets the milk with rennet, drains and lightly presses the curd, salts it, and matures it in brine for at least twenty-one days for the mature grade; a fresh version is also produced. EU PGI came in 2019. The cheese is white, firm, lightly moist, with a pleasantly tangy and moderately salty flavour and a clear note of mature wild grasses — the Transylvanian terroir as cheese.","sources":[{"label":"EU Agri: Telemea de Sibiu PGI","url":"https://agriculture.ec.europa.eu/farming/geographical-indications-and-quality-schemes/geographical-indications-food-and-drink/telemea-de-sibiu-pgi_en"},{"label":"Wikipedia: Telemea","url":"https://en.wikipedia.org/wiki/Telemea"}],"pronunciation":{"ipa":"/teleˈme̯a de siˈbiu/","respelling":"teh-leh-MYAH day see-BYOO"},"region_polygon":{"type":"Polygon","coordinates":[[[23.6,46.1],[24.4,46.15],[25.0,46.0],[25.05,45.65],[24.5,45.4],[23.85,45.55],[23.55,45.85],[23.6,46.1]]]}},{"name":"Homoljski sir","lat":44.4,"lon":21.7,"country":"Serbia","where":"Homolje highlands, eastern Serbia","hint":"Eastern Serbia","desc":"White brined cheese from sheep or cow milk; from the remote Homolje mountains.","image":"homoljski_sir.jpeg","name_protections":["GI"],"milk_types":["sheep","cow","goat"],"pasteurization":"raw","style":["semi-soft","brined","white"],"ageing_min_days":30,"format":"blocks in brine, ~1 kg","year_recognized":2018,"animal_breed":null,"vegetarian":null,"desc_long":"Homoljski sir is the white brined cheese of the Homolje mountains and valleys of eastern Serbia, a sheep-and-cow blend (sometimes with goat) made by smallholder shepherds and small dairies across the Homoljska Planina foothills. The Serbian national appellation specifies the Homolje area and the use of milk from local breeds grazed on the herb-rich limestone pastures. The cheese is set with rennet, the curd cut and drained without pressing, salted and matured in brine for at least a month. The result is the most famous of the white brined cheeses of the eastern Serbian mountain type — bright-white, lightly crumbly, with a pronounced mineral salt-and-pasture profile and a deepening sharpness as it ages. Homoljski sir holds Serbian Geographical Indication protection but has not yet entered the EU PDO/PGI register.","sources":[{"label":"Wikipedia: Serbian cheeses","url":"https://en.wikipedia.org/wiki/Serbian_cheeses"},{"label":"Serbian Intellectual Property Office: GI register","url":"https://www.zis.gov.rs/en/rights/indications-of-geographical-origin/"}],"pronunciation":{"ipa":"/xɔˈmɔʎski siːr/","respelling":"hoh-MOHL-skee SEER"},"region_polygon":{"type":"Polygon","coordinates":[[[21.3,44.5],[21.7,44.55],[22.0,44.45],[22.0,44.1],[21.65,43.95],[21.25,44.05],[21.15,44.3],[21.3,44.5]]]}},{"name":"Krivovirski kačkavalj","lat":43.86,"lon":21.78,"country":"Serbia","where":"Krivi Vir, Boljevac","hint":"Eastern Serbia","desc":"Pasta-filata cow\'s-milk cheese aged on wooden shelves; mountain-village tradition.","image":"krivovirski_kackavalj.jpg","name_protections":["GI"],"milk_types":["sheep","cow","goat"],"pasteurization":"raw","style":["semi-hard","pasta-filata"],"ageing_min_days":60,"format":"wheel, ~5–8 kg","year_recognized":2014,"animal_breed":null,"vegetarian":null,"desc_long":"Krivovirski kačkavalj is the pasta-filata yellow cheese of the Zaječar region of eastern Serbia, named for the village of Krivi Vir in the foothills of the Rtanj massif. It is the Serbian member of the broader Balkan kačkavalj / kashkaval / caciocavallo tradition that spread out from southern Italy across the eastern Mediterranean. The recipe permits sheep\'s milk, cow\'s milk or goat\'s milk, or any mixture. Curds are acidified, the firm mass plunged into hot water and worked into a ribbon in the pasta-filata fashion, then moulded into wheels, brined, and matured for at least two months. Krivovirski kačkavalj holds Serbian national appellation status. The wheels are dense, golden-yellow, with a smooth elastic paste and a clean savoury flavour; longer-aged lots take on a sharper, almost piquant edge and grate well over the country\'s filo-pastry pies and baked beans.","sources":[{"label":"Wikipedia: Serbian cheeses","url":"https://en.wikipedia.org/wiki/Serbian_cheeses"},{"label":"Serbian Intellectual Property Office: GI register","url":"https://www.zis.gov.rs/en/rights/indications-of-geographical-origin/"}],"pronunciation":{"ipa":"/krivoˈvirski katʃkaˈvaʎ/","respelling":"kree-voh-VEER-skee kahch-kah-VAHL-yuh"},"region_polygon":{"type":"Polygon","coordinates":[[[21.55,43.95],[21.95,43.95],[22.2,43.85],[22.25,43.5],[21.95,43.35],[21.55,43.4],[21.4,43.65],[21.55,43.95]]]}},{"name":"Svrljiški kačkavalj","lat":43.41,"lon":22.13,"country":"Serbia","where":"Svrljig","hint":"Eastern Serbia, Svrljig","desc":"Pasta-filata cow\'s-milk cheese; smoky-yellow rind, aged firm.","image":"svrljiški_kackavalj.jpeg","name_protections":["GI"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","pasta-filata"],"ageing_min_days":60,"format":"wheel, ~5–8 kg","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Svrljiški kačkavalj is the yellow pasta-filata cheese of the Svrljig hills and the Nišava valley in southeastern Serbia, traditionally produced from cow\'s milk. Like Krivovirski kačkavalj, it sits in the wider Balkan kačkavalj family that derives ultimately from southern Italian caciocavallo. The curd is acidified, plunged into hot water and worked into a stretchy mass, then moulded into wheels of five to eight kilograms, brined, and matured at least two months in cool cellars. The cheese holds Serbian Geographical Indication protection. The paste is dense and golden with a smooth elastic chew; the flavour begins mellow and butter-rich and deepens with age into a savoury, lightly piquant cheese that grates and grills exceptionally well. Svrljiški and Krivovirski kačkavalj together represent the senior expressions of the central Serbian yellow-cheese tradition.","sources":[{"label":"Wikipedia: Serbian cheeses","url":"https://en.wikipedia.org/wiki/Serbian_cheeses"},{"label":"Serbian Intellectual Property Office: GI register","url":"https://www.zis.gov.rs/en/rights/indications-of-geographical-origin/"}],"pronunciation":{"ipa":"/svrʎiːʃkiː katʃkaˈvaʎ/","respelling":"SVR-lyeesh-kee kahch-kah-VAHL-yuh"},"region_polygon":{"type":"Polygon","coordinates":[[[21.85,43.55],[22.2,43.55],[22.4,43.4],[22.3,43.2],[21.95,43.2],[21.75,43.35],[21.85,43.55]]]}},{"name":"Oravský korbáčik","lat":49.4,"lon":19.55,"country":"Slovakia","where":"Orava region","hint":"Northern Slovakia","desc":"Smoked sheep\'s-milk pasta-filata threads braided into tiny whips (\'korbáče\').","image":"oravsky_korbacik.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"raw","style":["pasta-filata","fresh","braided"],"ageing_min_days":1,"format":"braided whip, ~50–100 g","year_recognized":2011,"animal_breed":null,"vegetarian":null,"desc_long":"Oravský korbáčik is the braided pasta-filata cheese of the Orava region in northern Slovakia, named for its whip-like shape (korbáč = whip) and made by gently steaming the curd, hand-pulling it into long thin strings, plunging the strings into cold water, brining, and then plaiting them into the characteristic braid. The PGI permits raw cow\'s milk and admits both smoked and unsmoked versions. Production is small-scale and tied to the Orava district\'s village dairies. EU PGI came in 2011. The strings are 30–50 cm long before braiding, and each finished whip weighs roughly 50–100 g. The cheese is mild, slightly salty and squeaky against the teeth, with a fresh dairy character close to mozzarella; smoked versions carry a clean wood-smoke aroma. Korbáčik is eaten as a snack — peeled string by string — and is a staple of central European cheese markets and beer-hall plates.","sources":[{"label":"Wikipedia: Korbáčik","url":"https://en.wikipedia.org/wiki/Korb%C3%A1%C4%8Dik"}],"pronunciation":{"ipa":"/ˈɔrafskiː ˈkɔrbaːtʃik/","respelling":"OH-rahf-skee KOR-bah-cheek"},"region_polygon":{"type":"Polygon","coordinates":[[[19.05,49.55],[19.55,49.6],[19.85,49.45],[19.85,49.15],[19.5,49.05],[19.05,49.15],[18.95,49.4],[19.05,49.55]]]}},{"name":"Slovenská bryndza","lat":48.7,"lon":19.7,"country":"Slovakia","where":"Central & northern Slovakia","hint":"Slovakian highlands","desc":"Soft spreadable sheep\'s-milk cheese; the soul of bryndzové halušky.","image":"slovenska_bryndza.jpg","name_protections":["PGI"],"milk_types":["sheep","cow"],"pasteurization":"raw","style":["fresh","soft","salted","spreadable"],"ageing_min_days":5,"format":"soft mass, in tubs","year_recognized":2008,"animal_breed":["Valaska","Zoslachtená valaska","Cigája","Východofrízska ovca"],"vegetarian":null,"desc_long":"Slovenská bryndza is the Slovak national soft sheep cheese — the spreadable salted cheese that, mixed into halušky dumplings with bacon, makes up bryndzové halušky, the country\'s national dish. The PGI requires the cheese to be produced in Slovakia and to contain at least fifty per cent sheep cheese, with the balance permitted as cow cheese. The sheep\'s milk must come from one of four authorised breeds: Valaška, Zošl\'achtená valaška, Cigája and Východofrízska ovca. The make works in two stages. Fresh sheep\'s-milk cheese (hrudkový syr) ripens at 8–20 °C for three to five days, then is cleaned, pressed for two days, milled or ground into 2–5 cm lumps, salted, and homogenised into the bright-white, smooth, creamy paste of finished bryndza. EU PGI came in 2008. Slovak ewe\'s-milk output peaked above thirteen thousand tonnes in 2019; bryndza production runs around four thousand tonnes annually. The flavour is sharp, salty, sheepy and faintly fermented, and it is sold in tubs throughout central Europe.","sources":[{"label":"Qualigeo: Slovenská bryndza PGI","url":"https://www.qualigeo.eu/en/product/slovenska-bryndza-pgi/"},{"label":"EUR-Lex: Commission Regulation (EC) No 676/2008 (Slovenská bryndza PGI)","url":"http://eur-lex.europa.eu/Notice.do?checktexts=checkbox&checktexte=checkbox&val=474677%3Acs&pos=1&page=1&lang=en&pgs=10&nbl=1&list=474677%3Acs%2C&hwords=&action=GO&visu=%23texte"},{"label":"Wikipedia: Bryndza","url":"https://en.wikipedia.org/wiki/Bryndza"}],"pronunciation":{"ipa":"/ˈslɔvɛnskaː ˈbrindza/","respelling":"SLOH-ven-skah BRIN-dzah"},"region_polygon":{"type":"Polygon","coordinates":[[[16.85,49.1],[18.4,49.6],[19.65,49.6],[21.1,49.45],[22.6,49.1],[22.1,48.4],[21.5,48.55],[20.3,48.2],[18.8,47.75],[17.2,48.0],[16.95,48.6],[16.85,49.1]]]}},{"name":"Slovenská parenica","lat":48.7,"lon":19.7,"country":"Slovakia","where":"Central & northern Slovakia","hint":"Slovakian highlands","desc":"Steamed pasta-filata sheep-milk ribbon rolled into a flat spiral and lightly smoked.","image":"slovenska_parenica.jpeg","name_protections":["PGI"],"milk_types":["sheep","cow"],"pasteurization":"raw","style":["semi-hard","pasta-filata","smoked"],"ageing_min_days":5,"format":"S-shaped double cylinder, 5–8 cm tall × 6–8 cm dia","year_recognized":2008,"animal_breed":["Valaska","Zošl\'achtená valaška","Cigája","Východofrízska ovca"],"vegetarian":null,"desc_long":"Slovenská parenica is the pasta-filata sheep cheese of Slovakia — a long ribbon of curd hand-pulled out of hot whey, brined, and wound into the characteristic two-spiral S shape. The PGI permits pure sheep\'s milk from the country\'s four traditional breeds or a sheep-and-cow blend in which sheep\'s milk makes up at least fifty per cent. Production runs across the entire country. The fresh raw milk is set with rennet at 29–32 °C, the curd cut to half-to-one-centimetre grain with a lyre-shaped tool, and the grain compacted into a fist-sized hrudka. Pieces of about 500 g are then plunged into 60–70 °C water and worked along the inside of a wooden vat with a spatula, drawn into a ribbon four to six metres long and six centimetres wide. The cooled ribbon is brined, then wound into the double-cylinder spiral and may be lightly smoked. EU PGI came in 2008. The rind is yellow to honey-brown; the paste white-to-butter-yellow with a clean, gently salty, sheepish flavour and a soft elastic chew.","sources":[{"label":"Qualigeo: Slovenská parenica PGI","url":"https://www.qualigeo.eu/en/product/slovenska-parenica-pgi/"},{"label":"EU PDO/PGI register: Parenica extract (PDF)","url":"https://ec.europa.eu/info/food-farming-fisheries/food-safety-and-quality/certification/quality-labels/geographical-indications-register//pdf/ec_food_12502.pdf"},{"label":"Wikipedia: Parenica","url":"https://en.wikipedia.org/wiki/Parenica"}],"pronunciation":{"ipa":"/ˈslɔvɛnskaː paˈrɛɲitsa/","respelling":"SLOH-ven-skah pah-REH-nyit-sah"},"region_polygon":{"type":"Polygon","coordinates":[[[16.85,49.1],[18.4,49.6],[19.65,49.6],[21.1,49.45],[22.6,49.1],[22.1,48.4],[21.5,48.55],[20.3,48.2],[18.8,47.75],[17.2,48.0],[16.95,48.6],[16.85,49.1]]]}},{"name":"Slovenský oštiepok","lat":48.7,"lon":19.7,"country":"Slovakia","where":"Central & northern Slovakia","hint":"Slovakian highlands","desc":"Smoked spindle-shaped sheep\'s-milk cheese pressed in carved wooden forms.","image":"slovensky_ostiepok.jpg","name_protections":["PGI"],"milk_types":["sheep","cow"],"pasteurization":"any","style":["semi-hard","smoked","moulded"],"ageing_min_days":14,"format":"decorative egg or cone, ~250–500 g","year_recognized":2008,"animal_breed":null,"vegetarian":null,"desc_long":"Slovenský oštiepok is the cousin of Polish oscypek across the Carpathian arc — a semi-hard, lightly smoked or steamed cheese pressed into elaborately carved wooden moulds that imprint the rind with regional geometric patterns. The PGI covers production across more than eighty per cent of Slovak territory and permits pure sheep\'s milk (from Valaška, Zošl\'achtená Valaška or Cigája breeds), pure cow\'s milk, or a mixture; the cheese can be made on a small shepherd\'s-hut scale (bryndziareň, salaš) or industrially. The fresh milk is set with rennet immediately after milking, the curd is moulded into the egg, cone or ellipsoid shape that distinguishes the cheese, then salted in brine, optionally steamed, and most often smoked over coniferous wood, which gives the rind its honey-amber to deep-tan colour. EU PGI came in 2008. Documents in eighteenth-century cheesemaker family archives establish the cheese as a continuous Slovak tradition from at least 1700. The paste runs white to straw-yellow; the flavour is salty, lightly resinous, with the sheep-milk fraction adding warm lanolin depth.","sources":[{"label":"Qualigeo: Slovenský oštiepok PGI","url":"https://www.qualigeo.eu/en/product/slovensky-ostiepok-pgi/"},{"label":"Wikipedia: Oštiepok","url":"https://en.wikipedia.org/wiki/O%C5%A1tiepok"}],"pronunciation":{"ipa":"/ˈslɔvɛnskiː ˈɔʃcɛpɔk/","respelling":"SLOH-ven-skee OSH-tyeh-pok"},"region_polygon":{"type":"Polygon","coordinates":[[[16.85,49.1],[18.4,49.6],[19.65,49.6],[21.1,49.45],[22.6,49.1],[22.1,48.4],[21.5,48.55],[20.3,48.2],[18.8,47.75],[17.2,48.0],[16.95,48.6],[16.85,49.1]]]}},{"name":"Tekovský salámový syr","lat":48.4,"lon":18.6,"country":"Slovakia","where":"Tekov region","hint":"Southwest Slovakia","desc":"Smoked cow\'s-milk pasta-filata cheese formed and aged as a salami-shaped log.","image":"tekovsky_salamovy_syr.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","salami-shape","smoked"],"ageing_min_days":14,"format":"salami-shaped cylinder","year_recognized":2011,"animal_breed":null,"vegetarian":null,"desc_long":"Tekovský salámový syr is the salami-shaped Slovak cheese of the Tekov region on the Nitra-Banská Bystrica border, made from pasteurised full-fat cow\'s milk since the cheese\'s industrial standardisation in 1949. The PGI restricts production to the Tekov area and admits both smoked and unsmoked versions. The cheese is shaped into long cylinders the size and form of a salami — the source of its name — then matured at least two weeks, and in the smoked grade finished over wood-smoke to develop the deep golden-yellow rind colour. EU PGI came in 2011. The paste is soft, pliable and elastic, with countless small irregular eyes; the flavour is mildly acidulous and dairy-sweet in the unsmoked version, gently smoky and warmer in the smoked one. The cheese is eaten in slices like its meat namesake — sometimes on rye bread with horseradish — and is a familiar fixture of Slovak deli counters across the country.","sources":[{"label":"GOV.UK: Tekovský salámový syr PGI","url":"https://www.gov.uk/protected-food-drink-names/tekovsky-salamovy-syr"}],"pronunciation":{"ipa":"/ˈtɛkɔfskiː saˈlaːmɔviː sɪr/","respelling":"TEH-kohf-skee sah-LAH-moh-vee SEER"},"region_polygon":{"type":"Polygon","coordinates":[[[18.3,48.45],[18.75,48.5],[19.0,48.4],[19.05,48.15],[18.7,48.0],[18.3,48.1],[18.3,48.45]]]}},{"name":"Zázrivský korbáčik","lat":49.27,"lon":19.13,"country":"Slovakia","where":"Zázrivá, Orava","hint":"Northern Slovakia, Zázrivá","desc":"Tiny smoked sheep-milk cheese \'whip\' braided from steamed pasta-filata threads.","image":"zazrivsky_korbacik.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"raw","style":["pasta-filata","fresh","braided"],"ageing_min_days":1,"format":"braided whip, ~50–100 g","year_recognized":2011,"animal_breed":null,"vegetarian":null,"desc_long":"Zázrivský korbáčik is the version of korbáčik made in the small mountain town of Zázrivá in the Orava region — the same braided cheese as Oravský korbáčik, but tied by PGI specifically to Zázrivá\'s home dairies. The recipe began to spread in the mid-nineteenth century and grew into a notable supplementary income for the community. The cheese is produced from raw cow\'s milk: the curd is cut, steamed, kneaded by hand, pulled into long thin strings (parenice), immediately plunged into cold water, brined, dried, and finally braided into its signature whip shape. Smoked and unsmoked versions are both permitted. EU PGI came in 2011. Each finished braid weighs roughly fifty to one hundred grams. Like its Oravský cousin, Zázrivský korbáčik is mild, squeaky, gently salty and pulls apart string by string — a textural cheese of the Slovak beer hall and family kitchen.","sources":[{"label":"Slow Food Ark of Taste: Zázrivský Korbáčik","url":"https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/zazrivsky-korbacik/"},{"label":"UK Government: Protected food name — Zázrivský korbáčik","url":"https://www.gov.uk/protected-food-drink-names/zazrivsky-korbacik"},{"label":"Wikipedia: Korbáčik","url":"https://en.wikipedia.org/wiki/Korbáčik"}],"pronunciation":{"ipa":"/ˈzaːzrifskiː ˈkɔrbaːtʃik/","respelling":"ZAH-zreef-skee KOR-bah-cheek"},"region_polygon":{"type":"Polygon","coordinates":[[[19.1,49.3],[19.3,49.3],[19.4,49.25],[19.35,49.15],[19.2,49.15],[19.05,49.2],[19.1,49.3]]]}},{"name":"Bovški sir","lat":46.34,"lon":13.55,"country":"Slovenia","where":"Bovec, Soča valley","hint":"Soča valley, Julian Alps","desc":"Hard sheep\'s-milk Alpine cheese from indigenous Bovec sheep; nutty, gently piquant.","image":"bovski_sir.jpeg","name_protections":["PDO"],"milk_types":["sheep","goat","cow"],"pasteurization":"raw","style":["semi-hard","alpine","pressed"],"ageing_min_days":60,"format":"wheel, ~3–5 kg","year_recognized":2012,"animal_breed":["Bovška"],"vegetarian":null,"desc_long":"Bovški sir is the alpine sheep cheese of Bovec in Slovenia\'s Soča Valley, a northwestern corner of the country where the Julian Alps press up against the Italian border. The PDO requires at least eighty per cent sheep\'s milk from the autochthonous Bovška breed — a small hardy native sheep adapted to the Zgornjesoška valley pastures — with up to twenty per cent goat\'s or cow\'s milk permitted as a declared addition. The milk is set with rennet, the curd cut, scalded and pressed into round wheels of three to five kilograms, brined, and matured at least sixty days in cool cellars. EU PDO came in 2012. The paste is firm, ivory to straw-yellow with sparse small eyes, the rind a thin tan; the flavour is aromatic, full and intense with a faint spicy edge that the local cheesemakers attribute to the herb-rich Alpine grazing of the Bovec basin. Production is small-scale, distributed across the town\'s dairy and two highland alpages within the municipality.","sources":[{"label":"Soča Valley: Bovec Cheese","url":"https://www.soca-valley.com/en/in-search-of-adventure/gastronomy/traditional-food/2021020313250489/bovec-cheese/"}],"pronunciation":{"ipa":"/ˈbɔu̯ʃki ˈsiːr/","respelling":"BOHV-shkee SEER"},"region_polygon":{"type":"Polygon","coordinates":[[[13.4,46.45],[13.65,46.4],[13.75,46.25],[13.65,46.15],[13.45,46.2],[13.35,46.35],[13.4,46.45]]]}},{"name":"Mohant","lat":46.27,"lon":13.88,"country":"Slovenia","where":"Bohinj, Julian Alps","hint":"Bohinj basin, Julian Alps","desc":"Soft ripened cow\'s-milk cheese, kneaded into a paste; intensely pungent.","image":"mohant.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","ripened","anaerobic","spreadable"],"ageing_min_days":15,"format":"soft paste in small clay or wooden vessels (deže)","year_recognized":2013,"animal_breed":["Cika"],"vegetarian":null,"desc_long":"Mohant is the pungent anaerobically-ripened cheese of the Bohinj Valley in Slovenia\'s Julian Alps — one of the most idiosyncratic cheeses in the EU register and a survival of an old central European tradition of vessel-ripened cheese. The PDO requires raw cow\'s milk, traditionally from the native Cika cattle, with morning milk blended with partially-skimmed ripened evening milk. The milk is warmed and set with rennet; after whey draining, the curd is cut, salted by hand, pressed into wooden or clay deže (small ripening vessels) and aged under anaerobic conditions for between fifteen and fifty-six days. EU PDO came in 2013. Summer production from full-fat milk takes about six weeks; winter production from skimmed milk runs up to three months. The cheese is creamy, sharp, sour-tinged, and famously pungent — the local saying compares Mohant to Roquefort for assertiveness without the blue mould — eaten spread on rye bread or potatoes with a glass of homemade brandy.","sources":[{"label":"Slow Food Ark of Taste: Mohant Cheese","url":"https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/mohant-cheese/"}],"pronunciation":{"ipa":"/ˈmɔxant/","respelling":"MOH-hahnt"},"region_polygon":{"type":"Polygon","coordinates":[[[13.75,46.35],[14.05,46.35],[14.15,46.25],[14.05,46.15],[13.8,46.2],[13.7,46.3],[13.75,46.35]]]}},{"name":"Nanoški sir","lat":45.85,"lon":14.05,"country":"Slovenia","where":"Nanos plateau, Inner Carniola","hint":"Karst plateau, SW Slovenia","desc":"Hard cow\'s-milk cheese with small eyes; firm, slightly fruity, ages on the Nanos winds.","image":"nanoski_sir.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":60,"format":"wheel, ~8–10 kg","year_recognized":2011,"animal_breed":["Brown Swiss"],"vegetarian":null,"desc_long":"Nanoški sir is the hard cow\'s-milk cheese of the Nanos plateau and the Vipava Valley in Slovenia\'s Primorska region — the first Slovenian cheese to win EU PDO recognition. The recipe descends from an older sheep-milk cheese also called nanos that was produced on the Nanos plateau from at least the sixteenth century; sheep numbers collapsed in the early twentieth century and disappeared in WWII, and the modern cow-milk Nanoški sir was revived by the Vipava Dairy in 1986 using raw milk drawn predominantly (at least eighty per cent) from the Brown Swiss cattle pastured on the Nanos slopes. The milk must be heat-treated within seventy-two hours of milking; it is warmed to 63–69 °C and set with rennet, the curd scalded and pressed into wheels of eight to ten kilograms. Wheels mature at least sixty days, turned every three days for the first fortnight and once weekly thereafter. EU PDO came in 2011. The paste is firm, ivory-yellow and gently eyed; the flavour is full, savoury and faintly piquant.","sources":[{"label":"Qualigeo: Nanoški sir PDO","url":"https://www.qualigeo.eu/en/product/nanoski-sir-pdo/"}],"pronunciation":{"ipa":"/naˈnɔʃki ˈsiːr/","respelling":"nah-NOSH-kee SEER"},"region_polygon":{"type":"Polygon","coordinates":[[[13.85,45.95],[14.2,46.0],[14.3,45.85],[14.15,45.7],[13.85,45.75],[13.8,45.85],[13.85,45.95]]]}},{"name":"Tolminc","lat":46.18,"lon":13.74,"country":"Slovenia","where":"Tolmin, Soča valley","hint":"Soča valley","desc":"Semi-hard raw cow\'s-milk Alpine cheese; mild and fruity, with a gentle hazelnut finish.","image":"tolminc.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":60,"format":"wheel, ~4–6 kg","year_recognized":2012,"animal_breed":["Braunvieh"],"vegetarian":null,"desc_long":"Tolminc is the hard cow\'s-milk alpine cheese of the upper Soča Valley around Tolmin, in Slovenia\'s northwest near the Italian border — the country\'s other great alpine cheese alongside Bovški sir. The PDO requires raw milk drawn from cattle (predominantly the Braunvieh breed) grazing the alpine pastures around Tolmin, with the milk fermented for at least twelve hours before rennet is added so that the resident microflora can establish the right acidity profile. The curd is cut, scalded, pressed into round wheels of four to six kilograms, brined, and matured in naturally ventilated cellars for a minimum of sixty days; the best wheels rest six to eight months. Slovenia granted national PDO in 2001; EU PDO followed in 2012 after supplementary specification work. The paste is firm, ivory to butter-yellow, sparsely eyed; the flavour begins with clean Alpine pasture sweetness and grows assertively savoury with age. Tolminc production has declined steeply across the past century — of sixty-eight mountain dairies working in the 1930s, fewer than twenty survive.","sources":[{"label":"Slow Food Ark of Taste: Tolminc","url":"https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/tolminc-2/"}],"pronunciation":{"ipa":"/ˈtɔu̯mints/","respelling":"TOW-mints"},"region_polygon":{"type":"Polygon","coordinates":[[[13.55,46.35],[13.85,46.35],[14.0,46.2],[13.9,46.05],[13.55,46.05],[13.45,46.2],[13.55,46.35]]]}},{"name":"Afuega\'l Pitu","lat":43.3,"lon":-6.07,"country":"Spain","where":"Central Asturias","hint":"Asturias, northern Spain","desc":"Soft cow\'s-milk cheese, plain or paprika-spiced (\'roxu\'); the name means \'chokes the throat\'.","image":"afuegal_pitu.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","lactic-set"],"ageing_min_days":21,"format":"cone (atroncáu) or chestnut-shape (trapu), ~200–600 g","year_recognized":2008,"animal_breed":["Friesian","Asturiana de los Valles"],"vegetarian":null,"desc_long":"Afuega\'l Pitu is a small soft cow\'s-milk cheese from central Asturias, one of the four PDOs of the region and the only Spanish cheese whose name expresses the eater\'s reaction to it — literally choke the throat, a wry Asturian compliment for a cheese whose mature wheels turn dry and concentrated. The PDO covers whole raw milk from Friesian and native Asturiana de los Valles cattle, set with a long lactic acidification and drained either in a cone-shaped mould (the atroncáu) or wrapped in cloth (the trapu); each shape gives a recognisable silhouette. Two further variants come from the maker\'s decision about pimentón: a white blancu without paprika, or a roxu (red) version into which sweet and sometimes hot Spanish paprika is blended before moulding, turning the paste a vivid brick-red. Ripening runs from three weeks for the youngest wheels into months for the harder, more concentrated versions. EU PDO came in 2008. Younger Afuega\'l Pitu is mild, fresh and slightly lemon-tangy; the older red form acquires a smoky depth and a slow-building paprika heat.","sources":[{"label":"Wikipedia: Afuega\'l pitu","url":"https://en.wikipedia.org/wiki/Afuega%27l_pitu"},{"label":"Asturias.com on Afuega\'l Pitu","url":"https://en.asturias.com/asturias-products/afuega-cheese-the-red-pitu/"}],"pronunciation":{"ipa":"/aˈfweɣal ˈpitu/","respelling":"ah-FWAY-gahl PEE-too"},"region_polygon":{"type":"Polygon","coordinates":[[[-6.5,43.55],[-6.0,43.55],[-5.6,43.5],[-5.55,43.2],[-5.95,43.1],[-6.4,43.2],[-6.55,43.4],[-6.5,43.55]]]}},{"name":"Arzúa-Ulloa","lat":42.93,"lon":-8.16,"country":"Spain","where":"Galicia","hint":"Galicia","desc":"Soft creamy cow\'s-milk cheese with mild lactic flavor; the everyday Galician table cheese.","image":"arzúa_ulloa.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft"],"ageing_min_days":6,"format":"wheel, ~500 g – 3.5 kg","year_recognized":2010,"animal_breed":["Rubia Gallega","Friesian","Parda Alpina"],"vegetarian":null,"desc_long":"Arzúa-Ulloa is the everyday cow\'s-milk cheese of central Galicia, produced across the municipalities of Arzúa, Melide, the Ulloa and Chantada from the milk of Rubia Gallega, Friesian and Parda Alpina cattle grazed on Galicia\'s rain-fed pastures. The PDO recognises three forms: the young, soft Arzúa-Ulloa ripened a minimum of six days; the cured Arzúa-Ulloa Curado matured at least six months; and the rich Arzúa-Ulloa de Granja, a farmstead version produced only from a single herd\'s milk. Wheels are flat-sided and pale-skinned, weighing anywhere from half a kilogram up to about three and a half. EU PDO came in 2010. Younger Arzúa-Ulloa has a moist, creamy paste with a clean lactic flavour faintly suggestive of butter and warm bread; the cured version turns firmer and more intensely savoury, with a piquant edge that pairs naturally with the dry Albariño and Ribeiro whites of the Galician coast.","sources":[{"label":"Wikipedia: Arzúa-Ulloa cheese","url":"https://en.wikipedia.org/wiki/Arz%C3%BAa-Ulloa_cheese"},{"label":"Foods and Wines from Spain — Arzúa-Ulloa PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/arzua-ulloa-pdo"}],"pronunciation":{"ipa":"/arˈθwa uˈʝoa/","respelling":"ar-THWAH oo-YOH-ah"},"region_polygon":{"type":"Polygon","coordinates":[[[-8.6,43.2],[-8.1,43.15],[-7.6,43.05],[-7.5,42.8],[-7.8,42.55],[-8.3,42.55],[-8.6,42.85],[-8.6,43.2]]]}},{"name":"Cabrales","lat":43.27,"lon":-4.86,"country":"Spain","where":"Picos de Europa, Asturias","hint":"Picos de Europa, Asturias","desc":"Pungent blue cheese from cow (sometimes blended with sheep, goat), aged in mountain caves.","image":"cabrales.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"raw","style":["semi-soft","blue","natural-rind"],"ageing_min_days":60,"format":"cylinder, ~2–5 kg, 7–15 cm tall","year_recognized":1981,"animal_breed":null,"vegetarian":null,"desc_long":"Cabrales is a powerful raw-milk blue cheese from the Picos de Europa, in the heart of the Asturian mountains, made by a small number of producers in four villages on the slopes around Cabrales itself. The PDO permits cow\'s milk alone or a blend with sheep and goat — pure cow gives a more familiar, creamier blue, while the mixed-milk wheels (most common in summer when the small herds of mountain goats and ewes are in milk) push the cheese towards a sharper, more complex character. After a brief initial cure the wheels travel up the mountain to natural limestone caves, where steady cool temperatures and very high humidity allow Penicillium roqueforti to spread freely through the paste over two to five months. Wheels are sold today wrapped in dark green foil; until 1986 the traditional outer wrap was sycamore-maple leaves. Spanish DO came in 1981 and EU PDO followed in 1996. Cabrales is one of the most assertive blues in Europe — moist, intensely savoury, faintly acidic, with a finish that lingers well beyond the bite.","sources":[{"label":"Wikipedia: Cabrales cheese","url":"https://en.wikipedia.org/wiki/Cabrales_cheese"},{"label":"Spanish Ministry of Agriculture (MAPA): DOP Cabrales","url":"https://www.mapa.gob.es/en/alimentacion/temas/calidad-diferenciada/dop-igp/queso_lacteo/DOP_cabrales.aspx"}],"pronunciation":{"ipa":"/kaˈβɾales/","respelling":"kah-BRAH-less"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.05,43.4],[-4.8,43.4],[-4.6,43.3],[-4.55,43.15],[-4.75,43.1],[-5.05,43.2],[-5.05,43.4]]]}},{"name":"Cebreiro","lat":42.71,"lon":-7.03,"country":"Spain","where":"O Cebreiro, Lugo (Galicia)","hint":"Eastern Galicia","desc":"Soft cow\'s-milk cheese in a \'chef\'s hat\' mushroom shape; aged version is firmer and pungent.","image":"cebreiro.jpg","name_protections":["PDO"],"milk_types":["cow","goat"],"pasteurization":"any","style":["fresh","soft"],"ageing_min_days":1,"format":"chef\'s-hat shape, 0.3–2 kg","year_recognized":2008,"animal_breed":["Rubia Gallega","Pardo Alpina","Friesian"],"vegetarian":null,"desc_long":"Cebreiro is a Galician cheese from the mountains of Os Ancares and O Courel in the eastern province of Lugo, immediately recognisable for its distinctive shape: a cylindrical base under a wider domed top that gives the cheese an unmistakable chef\'s-hat silhouette. The PDO accepts cow\'s milk with up to forty percent goat\'s milk, set with rennet and lactic culture, then ladled into the characteristic moulds and either eaten fresh — the youngest cheese resembles a barely-set tinned cream — or ripened a minimum of forty-five days in cool storage for the cured version. Fresh wheels are bright white, soft, and faintly grainy; cured Cebreiro turns straw-yellow with a thin natural rind and a firm, butterfat-rich interior. EU PDO came in 2008. Local tradition serves Cebreiro fresh with honey or quince paste as a country dessert; the cured cheese pairs naturally with Mencía reds of the surrounding Bierzo and Ribeira Sacra.","sources":[{"label":"Foods and Wines from Spain — Cebreiro PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/cebreiro-pdo"},{"label":"Qualigeo Cebreiro PDO spec","url":"https://www.qualigeo.eu/en/product/cebreiro-pdo/"}],"pronunciation":{"ipa":"/θeˈβɾejɾo/","respelling":"theh-BRAY-roh"},"region_polygon":{"type":"Polygon","coordinates":[[[-7.3,42.85],[-7.0,42.85],[-6.85,42.75],[-6.85,42.55],[-7.1,42.45],[-7.35,42.6],[-7.3,42.85]]]}},{"name":"Gamoneu / Gamonedo","lat":43.3,"lon":-4.95,"country":"Spain","where":"Picos de Europa, Asturias","hint":"Western Picos de Europa","desc":"Lightly smoked blue cheese from cow, sheep & goat milk; the rarer cousin of Cabrales.","image":"gamoneu.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"raw","style":["semi-hard","blue","smoked","natural-rind"],"ageing_min_days":60,"format":"cylinder, 0.5–7 kg","year_recognized":2003,"animal_breed":null,"vegetarian":null,"desc_long":"Gamoneu is the lesser-known mountain cheese of western Asturias, made on the high pastures of the Picos de Europa from a blend of cow, sheep and goat milk and recognised in two registered styles. Gamoneu del Puertu is produced only in summer in the high mountain huts above the village of Onís, when shepherds and dairy cattle are together on the puertos; Gamoneu del Valle is made down in the valleys of Cangas de Onís through the rest of the year. Both share the defining steps of the recipe: the curd is drained, salted and given a brief turn through a wood-burning hearth that leaves a faint smoke perfume on the rind before months of cave-ageing concentrate the paste and allow a discreet, naturally appearing blue veining to develop near the surface. EU PDO came in 2003. Gamoneu is sharper and saltier than the more famous Asturian blues, with a smoky, almost herbal complexity that puts it in a category of its own among Spanish mountain cheeses.","sources":[{"label":"Wikipedia: Gamonedo cheese","url":"https://en.wikipedia.org/wiki/Gamonedo_cheese"}],"pronunciation":{"ipa":"/ɡamoˈneu̯/","respelling":"gah-moh-NEH-oo"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.2,43.4],[-5.0,43.4],[-4.95,43.2],[-5.1,43.1],[-5.3,43.15],[-5.3,43.3],[-5.2,43.4]]]}},{"name":"Idiazábal","lat":43.05,"lon":-2.1,"country":"Spain","where":"Basque Country & Navarre","hint":"Basque-Navarrese hills","desc":"Smoked raw sheep\'s-milk cheese from native Latxa and Carranzana ewes.","image":"idiazábal.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","smoked"],"ageing_min_days":60,"format":"wheel, ~1–3 kg","year_recognized":1987,"animal_breed":["Latxa","Carranzana"],"vegetarian":false,"desc_long":"Idiazábal is the great farmhouse sheep\'s-milk cheese of the western Basque Country, made across the highlands of the Spanish Basque provinces and Navarre from the raw milk of two indigenous breeds — the curly-fleeced Latxa and the related Carranzana. The DO specifies whole raw milk set with natural lamb rennet, drained, pressed and salted; ripening runs a minimum of two months in cool damp cellars. Many producers cold-smoke the wheels at the end of ageing, using beech, birch, cherry or white pine, which gives the rind a deeper colour and the paste a familiar perfume of wood smoke. Spanish DO came in 1987 and EU PDO followed in 1996. The flavour is at once buttery and faintly piquant, with the rich savouriness of long-aged sheep\'s milk lifted by the optional smoke. Idiazábal is a benchmark sheep cheese for Spain and is served everywhere from Basque cider houses to high-end pintxos bars, paired with Txakoli white and a hard Basque cured ham.","sources":[{"label":"Wikipedia: Idiazabal cheese","url":"https://en.wikipedia.org/wiki/Idiazabal_cheese"},{"label":"Consejo Regulador DOP Idiazabal","url":"http://www.doidiazabal.com"}],"pronunciation":{"ipa":"/i.djaˈθaβal/","respelling":"ee-dyah-THAH-bahl"},"region_polygon":{"type":"Polygon","coordinates":[[[-3.2,43.3],[-2.2,43.4],[-1.4,43.25],[-1.1,42.75],[-1.8,42.55],[-2.8,42.65],[-3.3,42.95],[-3.2,43.3]]]}},{"name":"Mahón-Menorca","lat":39.89,"lon":4.27,"country":"Spain","where":"Menorca, Balearic Islands","hint":"Menorca, Balearics","desc":"Cow\'s-milk cheese pressed in a cloth (fogasser) that leaves the signature soft corners; ages orange.","image":"mahon-menorca.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":21,"format":"square block ~20 × 20 × 9 cm, 2–3 kg","year_recognized":1985,"animal_breed":null,"vegetarian":null,"desc_long":"Mahón-Menorca is the cow\'s-milk cheese of the Balearic island of Menorca, produced under PDO from a small number of dairies scattered across the island\'s gently rolling stone-walled pastures. The defining step is the way the cheese is shaped: rather than being moulded in a wheel, the freshly drained curd is wrapped in a cotton or linen cloth (the fogasser) whose corners are gathered up and pressed into the cheese, leaving the finished wheel a soft cornered square of about two and a half kilograms and a quarter-metre side. The PDO recognises four classes by age: tierno (under three weeks), semicurado (about two to five months), curado (five months or more) and añejo (over ten months). Spanish PDO came in 1985 and the cheese was renamed Mahón-Menorca in 1997 to emphasise the wider island origin. Younger wheels are pale, supple and gently milky; longer ageing turns the rind a vivid orange and the paste a deeper yellow with a buttery-sweet character and a faint salt-sea edge — the latter sometimes attributed to the salt-laden island winds the wheels age in.","sources":[{"label":"Wikipedia: Mahón cheese","url":"https://en.wikipedia.org/wiki/Mah%C3%B3n_cheese"}],"pronunciation":{"ipa":"/maˈon meˈnoɾka/","respelling":"mah-OHN meh-NOR-kah"},"region_polygon":{"type":"Polygon","coordinates":[[[3.8,40.05],[4.1,40.1],[4.35,39.95],[4.3,39.8],[3.95,39.8],[3.8,39.95],[3.8,40.05]]]}},{"name":"Picón Bejes-Tresviso","lat":43.2,"lon":-4.66,"country":"Spain","where":"Picos de Europa, Cantabria","hint":"Cantabrian Picos","desc":"Blue cheese from cow/sheep/goat milk, aged in limestone mountain caves; pungent and creamy.","image":"picón_bejes_tresviso.jpeg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"raw","style":["semi-soft","blue","natural-rind"],"ageing_min_days":75,"format":"cylinder, 0.7–2.8 kg, 15–20 cm × 7–15 cm","year_recognized":1994,"animal_breed":null,"vegetarian":null,"desc_long":"Picón Bejes-Tresviso is the Cantabrian counterpart to Cabrales — a powerful raw-milk blue cheese from the Picos de Europa, produced in the Liébana valley and along the high cliffs at Tresviso on the southern side of the range. The PDO permits milk from cattle, sheep and goats together, blended to whatever balance the producer prefers; the curd is set with rennet, drained, salted and matured in two stages: a brief initial curing of about two weeks at moderate temperature, followed by a minimum of two months in natural limestone caves whose steady cold and high humidity propagate Penicillium roqueforti through the paste. Spanish DO came in 1994 and EU PDO followed. The cheese carries a moist, sticky natural rind streaked with bluish-grey moulds, and a paste laced with broad teal-blue veining; the flavour is assertive, faintly spicy and salt-forward, sharing the lineage of Cabrales but distinguished by its own valley microclimate.","sources":[{"label":"Wikipedia: Picón Bejes-Tresviso","url":"https://en.wikipedia.org/wiki/Pic%C3%B3n_Bejes-Tresviso"},{"label":"Spanish Ministry of Agriculture (MAPA): DOP Picón Bejes-Tresviso (archived)","url":"https://web.archive.org/web/20080917015235/http://www.mapa.es/es/alimentacion/pags/Denominacion/queso_lacteo/picon_bejes_tresviso.htm"}],"pronunciation":{"ipa":"/piˈkon ˈbexes tɾesˈβiso/","respelling":"pee-KOHN BEH-hess tress-VEE-soh"},"region_polygon":{"type":"Polygon","coordinates":[[[-4.8,43.3],[-4.6,43.35],[-4.4,43.3],[-4.4,43.15],[-4.6,43.1],[-4.8,43.15],[-4.8,43.3]]]}},{"name":"Queso Camerano","lat":42.2,"lon":-2.7,"country":"Spain","where":"Sierra de Cameros, La Rioja","hint":"Sierra de Cameros","desc":"Pressed goat\'s-milk cheese moulded in basket rings; firm, lightly tangy.","image":"queso_camerano.png","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"any","style":["semi-hard","basket-pressed"],"ageing_min_days":15,"format":"cylinder, ~200 g – 1.3 kg, ribbed rind","year_recognized":2003,"animal_breed":["Serrana","Murciano-Granadina","Malagueña","Alpine"],"vegetarian":null,"desc_long":"Queso Camerano is the only PDO cheese of La Rioja and the keeper of a centuries-old goat-cheese tradition from the Sierra de Cameros. The PDO accepts whole milk from Serrana, Murciano-Granadina, Malagueña and Alpine goats and their crosses, raw or pasteurised. The defining sign is on the outside: each cheese is shaped in the cilla, a small woven cane basket whose plaited pattern leaves a vivid ribbed imprint on the rind. The PDO recognises four age classes from fresh to cured, with minimum ageing periods running from fifteen days for the fresh through thirty for the semi-cured to seventy-five days for the cured wheels. EU PDO came in 2003. Younger Camerano is white, almost jellied and gently lactic; the cured version dries into a firmer, deeper-flavoured cheese with the warm caprine character of the high Riojan pastures and the faint herbal notes that come of long ageing.","sources":[{"label":"Foods and Wines from Spain — Queso Camerano PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-camerano-pdo"}],"pronunciation":{"ipa":"/ˈkeso kameˈɾano/","respelling":"KEH-soh kah-meh-RAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.85,42.4],[-2.5,42.4],[-2.3,42.3],[-2.3,42.0],[-2.55,41.85],[-2.8,42.0],[-2.9,42.25],[-2.85,42.4]]]}},{"name":"Queso Casín","lat":43.27,"lon":-5.3,"country":"Spain","where":"Asturian uplands","hint":"Eastern Asturias","desc":"Cow\'s-milk cheese kneaded by hand with a wooden \'gobu\' wheel; spicy, distinctive bite.","image":"queso_casín.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","kneaded"],"ageing_min_days":60,"format":"small dome, ~250–1 kg, stamped top","year_recognized":2008,"animal_breed":["Asturiana de la Montaña","Asturiana de los Valles","Friesian"],"vegetarian":null,"desc_long":"Queso Casín is a hard cow\'s-milk cheese from three small Asturian municipalities at the foot of the Cantabrian mountains — Caso, Sobrescobio and Piloña — and is one of the most unusual cheeses in Spain for its method of production. After the curd has been set and broken, it is passed repeatedly through a kneading machine called the máquina de rabilar (modernised from the original wooden rabil) over five days to two weeks, each pass aerating the paste and producing a uniform ripening inside and out. The cheese is shaped by hand into small domes that traditionally bear a stamp on the upper face. Spanish DO and EU PDO came in 2008. After at least two months of ageing the wheels develop a firm, deep-yellow paste, dense and crumbly, with a forthright savoury flavour, faintly piquant and slightly bitter at the finish — a distinctive cheese with no real analogue in the wider PDO catalogue.","sources":[{"label":"MAPA / Foods and Wines from Spain on Casín PDO","url":"https://www.foodswinesfromspain.com/content/icex-foodswines/en/food/products/cheese/queso-casin-pdo.html"},{"label":"Spanish Ministry of Agriculture (MAGRAMA): DOP Casín (archived)","url":"https://web.archive.org/web/20141006181014/http://www.magrama.gob.es/es/alimentacion/temas/calidad-agroalimentaria/calidad-diferenciada/dop/queso_lacteo/dop_casin.aspx"},{"label":"Wikipedia: Casín cheese","url":"https://en.wikipedia.org/wiki/Casín_cheese"}],"pronunciation":{"ipa":"/ˈkeso kaˈsin/","respelling":"KEH-soh kah-SEEN"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.55,43.3],[-5.35,43.3],[-5.2,43.2],[-5.25,43.05],[-5.5,43.05],[-5.6,43.2],[-5.55,43.3]]]}},{"name":"Queso de Flor de Guía / Media Flor / Queso de Guía","lat":28.13,"lon":-15.65,"country":"Spain","where":"Gran Canaria — north","hint":"Gran Canaria, Canary Islands","desc":"Cheese curdled with cardoon flower from sheep and cow milk; soft, slightly bitter from the thistle.","image":"queso_de_flor_de_guía.jpg","name_protections":["PDO"],"milk_types":["sheep","cow","goat"],"pasteurization":"raw","style":["semi-soft","thistle-rennet"],"ageing_min_days":15,"format":"flat wheel, 2–5 kg, 20–30 cm × 4–8 cm","year_recognized":2008,"animal_breed":null,"vegetarian":true,"desc_long":"Queso de Flor de Guía is the umbrella name for three closely related Canarian cheeses produced in the volcanic uplands of northwest Gran Canaria. All three share a recipe in which the milk — predominantly sheep, with smaller permitted shares of cow and goat — is coagulated not with animal rennet but with a vegetable extract pressed from the flowers of the wild cardoon, the Cynara cardunculus ferocissima of the Canarian highlands. The proportion of cardoon to standard rennet defines the three classes: Flor de Guía is set entirely with thistle, Media Flor uses a balanced mix, and Queso de Guía uses standard rennet. After a brief ageing of at least fifteen days the wheels develop a creamy, faintly bitter paste — the bitter edge is the cardoon\'s signature, and it works against the sheep\'s milk to produce a cheese unlike anything on mainland Spain. EU PDO came in 2008.","sources":[{"label":"Wikipedia: Flor de Guía cheese","url":"https://en.wikipedia.org/wiki/Flor_de_Gu%C3%ADa_cheese"},{"label":"Spanish Ministry of Agriculture (MAPA): DOP Flor de Guía (archived)","url":"https://web.archive.org/web/20090414153909/http://www.mapa.es/es/alimentacion/pags/Denominacion/queso_lacteo/flor_guia.htm"}],"pronunciation":{"ipa":"/ˈkeso de floɾ de ˈɣia/","respelling":"KEH-soh day flor day GHEE-ah"},"region_polygon":{"type":"Polygon","coordinates":[[[-15.8,28.2],[-15.4,28.2],[-15.35,27.95],[-15.5,27.75],[-15.75,27.85],[-15.8,28.05],[-15.8,28.2]]]}},{"name":"Queso de La Serena","lat":38.74,"lon":-5.65,"country":"Spain","where":"La Serena, Extremadura","hint":"Extremadura","desc":"Sheep\'s-milk cheese curdled with wild cardoon; runny enough to be eaten with a spoon (\'al corte\').","image":"queso_la_serena.png","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["soft","thistle-rennet"],"ageing_min_days":60,"format":"wheel, 750 g – 2 kg","year_recognized":1996,"animal_breed":["Merino"],"vegetarian":true,"desc_long":"Queso de La Serena is the great farmhouse sheep\'s-milk cheese of Extremadura, made in the high pastures of the La Serena comarca from the raw whole milk of native Merino ewes. The defining technical choice is the coagulant: rather than animal rennet, La Serena is set with an aqueous extract of cardoon flower (Cynara cardunculus), the wild thistle that gives the cheese a distinctive faint vegetable bitterness alongside its richer milk-and-fat profile. After moulding, the wheels are aged for at least two months in cool cellars; the related Torta de La Serena is the soft-paste version, taken at twenty days and famous for being served by cutting the top off the wheel and scooping the paste with a spoon. Spanish DO came in 1993 and EU PDO followed in 1996. La Serena is a benchmark of the extensive dehesa landscape of southwest Spain — a wide silver-grey plain of holm oak and grazing sheep that also produces the country\'s most prized ibérico hams.","sources":[{"label":"Wikipedia: La Serena cheese","url":"https://en.wikipedia.org/wiki/La_Serena_cheese"}],"pronunciation":{"ipa":"/ˈkeso de la seˈɾena/","respelling":"KEH-soh day lah seh-REH-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.95,39.05],[-5.3,39.1],[-5.0,38.95],[-5.1,38.65],[-5.6,38.55],[-5.9,38.75],[-5.95,39.05]]]}},{"name":"Queso de l\'Alt Urgell y la Cerdanya","lat":42.36,"lon":1.46,"country":"Spain","where":"Pyrenean valleys, Lleida","hint":"Catalan Pyrenees","desc":"Soft cow\'s-milk cheese with washed rind; creamy, very mild, mountain-village origin.","image":"queso_de_lalt_urgell_y_la_cerdanya.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","washed-rind"],"ageing_min_days":45,"format":"wheel, ~2.5 kg","year_recognized":2000,"animal_breed":["Friesian"],"vegetarian":null,"desc_long":"Queso de l\'Alt Urgell y la Cerdanya is a soft pressed cow\'s-milk cheese from the southern Catalan Pyrenees, the only PDO cheese of Catalonia and the patient work of a single cooperative dairy in La Seu d\'Urgell that has been making cheese to the same recipe since the 1950s. The PDO specifies pasteurised whole milk from Friesian cattle pastured in the lush valleys of the Alt Urgell and the high plateau of the Cerdanya, set with rennet and pressed into modest wheels of about two and a half kilograms. Maturation runs a minimum of forty-five days, during which each wheel is regularly washed with brine; the rind ripens to a smooth orange-brown and the paste settles into a pale ivory shot with small irregular eyes. EU PDO came in 2000. The flavour is gentle and creamy, slightly nutty, with a faint mushroomy edge near the rind — a quiet, dignified cheese sometimes sold under the brand name Urgèlia and naturally paired with the dry whites and easy-drinking reds of nearby Empordà.","sources":[{"label":"Foods and Wines from Spain — Alt Urgell PDO","url":"https://www.foodswinesfromspain.com/content/icex-foodswines/en/food/products/cheese/queso-de-l-alt-urgell-y-la-cerdanya-pdo.html"}],"pronunciation":{"ipa":"/ˈkezu də l‿alt urˈʒeʎ/","respelling":"KEH-soo duh lalt oor-ZHEY"},"region_polygon":{"type":"Polygon","coordinates":[[[1.1,42.55],[1.65,42.6],[2.0,42.5],[2.05,42.2],[1.7,42.1],[1.2,42.2],[1.05,42.4],[1.1,42.55]]]}},{"name":"Queso de Murcia","lat":37.99,"lon":-1.13,"country":"Spain","where":"Murcia","hint":"Murcia, SE Spain","desc":"Pressed goat\'s-milk cheese (Murciano-Granadina); sold fresh or cured.","image":"queso_de_murcia.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"pasteurized","style":["semi-hard","pressed"],"ageing_min_days":60,"format":"cylinder, ~300 g – 2 kg","year_recognized":2002,"animal_breed":["Murciano-Granadina"],"vegetarian":null,"desc_long":"Queso de Murcia is the plain goat\'s-milk cheese of the dry southeastern Spanish region, made from the pasteurised milk of native Murciano-Granadina goats — a small dark breed prized for both its richness of milk and its capacity to thrive on the harsh scrubland of the Levante. The PDO recognises two age classes: a fresh Queso de Murcia, white and elastic with a mild lactic tang, eaten within days and often drizzled with olive oil and rosemary; and a Queso de Murcia Curado, ripened a minimum of two months until the paste turns straw-coloured and the flavour deepens into a clean nutty savouriness that holds its own against the bigger Manchego. Wheels are cylindrical and weigh from a few hundred grams up to two kilos. EU PDO came in 2002. The cheese is also the base recipe for the wine-washed Murcia al Vino — the same milk transformed by a long bath in red wine into something quite different.","sources":[{"label":"Foods and Wines from Spain — Queso de Murcia PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-de-murcia-pdo"},{"label":"Wikipedia: Murcian cheese","url":"https://en.wikipedia.org/wiki/Murcian_cheese"}],"pronunciation":{"ipa":"/ˈkeso de ˈmuɾθja/","respelling":"KEH-soh day MOOR-thyah"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.3,38.6],[-1.4,38.8],[-0.75,38.3],[-0.75,37.8],[-1.4,37.45],[-2.05,37.55],[-2.4,38.0],[-2.3,38.6]]]}},{"name":"Queso de Murcia al vino","lat":37.99,"lon":-1.13,"country":"Spain","where":"Murcia","hint":"Murcia, SE Spain","desc":"Goat\'s-milk cheese washed in Monastrell wine — deep purple rind, mild paste.","image":"queso_de_murcia_al_vino.webp","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"pasteurized","style":["semi-hard","pressed","wine-washed"],"ageing_min_days":30,"format":"cylinder, 300–400 g or 1–2 kg, purple rind","year_recognized":2002,"animal_breed":["Murciano-Granadina"],"vegetarian":null,"desc_long":"Queso de Murcia al Vino is one of the most visually distinctive Spanish cheeses: a small or medium pressed goat\'s-milk wheel whose rind is washed in red wine over several days during ageing, turning the surface a deep purple-mauve that hardly looks like a cheese at all. The PDO uses the same pasteurised Murciano-Granadina goat\'s milk as the plain Queso de Murcia, set with rennet and lightly pressed into cylindrical wheels of a few hundred grams or up to two kilograms. After a minimum of thirty days of ageing (or forty-five for the larger wheels) the cheeses are bathed for around three days in the local Monastrell-based Doble Pasta wine from the Jumilla denomination, which both colours the rind and infuses the outer paste with a faint fruit and tannin edge. EU PDO came in 2002. Underneath the wine-stained rind the paste is moist, ivory-white and gently piquant, with a clean caprine sweetness lifted by the trace of red wine — a remarkable counterpoint cheese on a Spanish board.","sources":[{"label":"Foods and Wines from Spain — Murcia al Vino PDO","url":"https://www.foodswinesfromspain.com/content/icex-foodswines/en/food/products/cheese/queso-de-murcia-al-vino-pdo.html"}],"pronunciation":{"ipa":"/ˈkeso de ˈmuɾθja al ˈβino/","respelling":"KEH-soh day MOOR-thyah al VEE-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.3,38.6],[-1.4,38.8],[-0.75,38.3],[-0.75,37.8],[-1.4,37.45],[-2.05,37.55],[-2.4,38.0],[-2.3,38.6]]]}},{"name":"Queso de Valdeón","lat":43.15,"lon":-4.93,"country":"Spain","where":"Valdeón valley, Picos de Europa (León)","hint":"Picos de Europa, León side","desc":"Cow & goat milk blue cheese wrapped in sycamore leaves; aged in mountain caves.","image":"queso_de_valdeón.jpg","name_protections":["PGI"],"milk_types":["cow","goat"],"pasteurization":"any","style":["semi-soft","blue","leaf-wrapped"],"ageing_min_days":45,"format":"cylinder, 0.5–3 kg, wrapped in sycamore leaves","year_recognized":2004,"animal_breed":null,"vegetarian":null,"desc_long":"Queso de Valdeón is a blue cheese from the Posada de Valdeón valley deep inside the Picos de Europa, produced on the León side of the range and recognised as a PGI rather than a PDO because its milk supply comes from a broader area than the production zone. The PGI specifies a blend of at least eighty percent cow\'s milk with sheep or goat milk to balance it out, set with rennet, pierced to admit air, and seeded with Penicillium roqueforti before being aged a minimum of forty-five days for the pasteurised version (and two months for the rarer raw-milk wheels). Finished cheeses are wrapped in dried sycamore-maple leaves that lend a faint mossy note and preserve a traditional packaging once used to ship cheeses out of the mountain valley. EU PGI came in 2004. The paste is moist and ivory with broad blue-green veining; the flavour is markedly intense — salty, peppery and warmly spicy — and the cheese has become an export ambassador for the Picos blues alongside Cabrales and Picón.","sources":[{"label":"Foods and Wines from Spain — Valdeón PGI","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-de-valdeon-pgi"},{"label":"EUR-Lex: PGI registration — Queso de Valdeón (OJ C 110/2003, PDF)","url":"http://eur-lex.europa.eu/LexUriServ/LexUriServ.do?uri=OJ:C:2003:110:0015:0017:EN:PDF"},{"label":"Wikipedia: Valdeón cheese","url":"https://en.wikipedia.org/wiki/Valdeón_cheese"}],"pronunciation":{"ipa":"/ˈkeso de balðeˈon/","respelling":"KEH-soh day val-deh-OHN"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.1,43.2],[-4.85,43.25],[-4.7,43.15],[-4.75,42.95],[-4.95,42.9],[-5.15,43.05],[-5.1,43.2]]]}},{"name":"Queso Ibores","lat":39.5,"lon":-5.5,"country":"Spain","where":"Sierra de las Villuercas, Cáceres","hint":"Eastern Extremadura","desc":"Raw goat\'s-milk cheese rubbed with olive oil or paprika; firm-paste cured wheels.","image":"queso_ibores.webp","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["semi-hard","pressed"],"ageing_min_days":60,"format":"wheel, ~650 g – 1.2 kg, often paprika-rubbed rind","year_recognized":2005,"animal_breed":["Serrana","Verata","Retinta"],"vegetarian":null,"desc_long":"Queso Ibores is the goat\'s-milk cheese of the Sierra de las Villuercas and the surrounding holm-oak country of eastern Cáceres, made from the raw milk of native Serrana, Verata and Retinta goats grazed across the wide dehesa landscape of Extremadura. The PDO requires the milk to be raw and lactic-set, drained gently and pressed into wheels of around a kilogram before being aged a minimum of sixty days in cool cellars. A distinguishing feature is the finish given to the rind: producers may leave the natural rind alone, or rub the wheels with sweet smoked pimentón (which turns the surface a vivid orange-red), or coat them with olive oil that draws the rind to a deep yellow-ocher. EU PDO came in 2005, with an Artesano sub-category for wheels aged at least a hundred days. Underneath any of those finishes sits a firm, fine-grained paste with a forthright goat flavour, lifted by the paprika or sealed in by the oil — a classic farmhouse cheese paired with the warm extremeño breads and ibérico cured meats of the surrounding country.","sources":[{"label":"Foods and Wines from Spain — Queso Ibores PDO","url":"https://www.foodswinesfromspain.com/content/icex-foodswines/en/food/products/cheese/queso-ibores-pdo.html"}],"pronunciation":{"ipa":"/ˈkeso iˈβoɾes/","respelling":"KEH-soh ee-BOH-ress"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.85,39.75],[-5.4,39.8],[-5.15,39.65],[-5.2,39.3],[-5.55,39.2],[-5.85,39.35],[-5.85,39.75]]]}},{"name":"Queso Los Beyos","lat":43.16,"lon":-4.95,"country":"Spain","where":"Beyos gorge, Asturias/León","hint":"Beyos gorge, Cantabrian range","desc":"Small dense cylinder from cow, sheep or goat milk; crumbly, dry, mountain-village made.","image":"queso_los_beyos.jpg","name_protections":["PGI"],"milk_types":["cow","sheep","goat"],"pasteurization":"any","style":["semi-hard","lactic-set"],"ageing_min_days":20,"format":"small cylinder, 250–500 g, 9–10 cm × 6–9 cm","year_recognized":2014,"animal_breed":null,"vegetarian":null,"desc_long":"Queso Los Beyos is the small farmhouse cheese of the Beyos gorge, the dramatic limestone cut that the river Sella carves between Asturias and León through three small municipalities recognised in the PGI. The unusual rule of the designation is that the cheese may be made from cow, sheep or goat milk — but only one of those at a time, never blended; the same village can produce three quite different cheeses depending on the day. Both raw and pasteurised milk are permitted; raw-milk wheels must age at least sixty days, while pasteurised ones can be sold from twenty. Wheels are small — a few hundred grams in a low cylinder — with a thin pale rind and a firm crumbly paste that grows drier and more concentrated as it ages. EU PGI came in 2014. Each milk gives its own version: cow Los Beyos is mild and lactic, sheep is rich and faintly piquant, goat is the sharpest and most aromatic — a kind of three-cheeses-in-one PGI that reflects the small-scale mixed-livestock dairying of the gorge.","sources":[{"label":"Foods and Wines from Spain — Queso Los Beyos PGI","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-los-beyos-pgi"}],"pronunciation":{"ipa":"/ˈkeso los ˈβejos/","respelling":"KEH-soh lohs BAY-yohs"},"region_polygon":{"type":"Polygon","coordinates":[[[-5.3,43.25],[-5.05,43.3],[-4.9,43.15],[-5.0,43.0],[-5.3,43.0],[-5.4,43.15],[-5.3,43.25]]]}},{"name":"Queso Majorero","lat":28.4,"lon":-14.0,"country":"Spain","where":"Fuerteventura, Canary Islands","hint":"Fuerteventura, Canaries","desc":"Goat\'s-milk cheese (Majorera goats) with paprika, oil or gofio cornmeal rind.","image":"queso_majorero.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"pasteurized","style":["semi-hard","pressed"],"ageing_min_days":8,"format":"wheel, 1–6 kg, 15–35 cm × 6–9 cm","year_recognized":1996,"animal_breed":["Majorera"],"vegetarian":null,"desc_long":"Queso Majorero is the goat\'s-milk cheese of Fuerteventura in the Canary Islands, made from the pasteurised milk of the native Majorera goat — a small hardy breed adapted to the volcanic dryness of the island. The PDO allows up to fifteen percent native Canarian sheep milk in cheeses destined for longer ageing. Wheels are pressed in plaited palm-leaf moulds whose pattern remains imprinted on the rind, then aged from a minimum of eight days for the fresh cheese into months for the cured. Producers traditionally finish older wheels by rubbing them with olive oil, sweet paprika or gofio — the toasted-cornmeal staple of Canarian cooking — each treatment lending its own colour and aroma. Spanish DO came in 1996 (the first Canarian and the first Spanish goat-cheese DO) and EU PDO followed. The flavour is markedly goaty in a way that reflects the dry forage of the island, balanced and intense, with a clean salty finish that gains depth as the cheese ages.","sources":[{"label":"Foods and Wines from Spain — Queso Majorero PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-majorero-pdo"}],"pronunciation":{"ipa":"/ˈkeso maxoˈɾeɾo/","respelling":"KEH-soh mah-hoh-REH-roh"},"region_polygon":{"type":"Polygon","coordinates":[[[-14.5,28.75],[-14.3,28.8],[-14.05,28.7],[-13.85,28.3],[-14.0,28.05],[-14.3,28.2],[-14.5,28.5],[-14.5,28.75]]]}},{"name":"Queso Manchego","lat":39.3,"lon":-3.4,"country":"Spain","where":"La Mancha (Castilla-La Mancha)","hint":"La Mancha plateau, central Spain","desc":"Sheep\'s-milk cheese from Manchega ewes; firm paste, distinctive zigzag rind from old esparto-grass moulds.","image":"queso_manchego.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"any","style":["semi-hard","hard","pressed"],"ageing_min_days":60,"format":"wheel, 0.4–4 kg, 22 cm max × 12 cm max, zigzag rind","year_recognized":1984,"animal_breed":["Manchega"],"vegetarian":null,"desc_long":"Queso Manchego is the great sheep\'s-milk cheese of Spain, made across the wide flat country of La Mancha (Albacete, Ciudad Real, Cuenca and Toledo) from the whole milk of Manchega ewes — a hardy native breed that lends the cheese its richness and a distinctive aromatic depth. The PDO permits either raw or pasteurised milk and recognises age classes that run from semicurado (about three weeks to three or four months) through curado (three to six months) to viejo (over a year). Wheels are cylindrical and weigh up to four kilograms, with their unmistakable zigzag rind pattern — the impression of the plaited esparto-grass baskets historically used to drain and press the curd, today often reproduced as moulded plastic. Spanish DO came in 1984 and EU PDO followed in 1996. Younger Manchego is buttery and faintly piquant; long-aged wheels turn drier, more granular, and develop deep caramel and toasted-nut notes, the classic table cheese of Spain and the indispensable partner for Tempranillo, jamón ibérico and quince paste.","sources":[{"label":"Wikipedia: Manchego","url":"https://en.wikipedia.org/wiki/Manchego"},{"label":"Consejo Regulador DOP Queso Manchego","url":"http://www.quesomanchego.es/"}],"pronunciation":{"ipa":"/ˈkeso manˈtʃeɣo/","respelling":"KEH-soh mahn-CHEH-goh"},"region_polygon":{"type":"Polygon","coordinates":[[[-4.8,40.1],[-3.5,40.2],[-2.2,40.0],[-1.3,39.5],[-1.4,38.8],[-2.2,38.4],[-3.7,38.3],[-4.8,38.6],[-4.95,39.4],[-4.8,40.1]]]}},{"name":"Queso Nata de Cantabria","lat":43.32,"lon":-4.0,"country":"Spain","where":"Cantabria","hint":"Cantabria, north coast","desc":"Soft cow\'s-milk cheese, mild and creamy with a thin natural rind; everyday table cheese.","image":"queso_nata_de_cantabria.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["soft","fresh"],"ageing_min_days":7,"format":"cylinder or block, ~400 g – 2.8 kg","year_recognized":1985,"animal_breed":["Friesian"],"vegetarian":null,"desc_long":"Queso Nata de Cantabria is the soft, fresh cow\'s-milk cheese of the green Atlantic coast of northern Spain, produced under PDO across the whole of Cantabria from the milk of Friesian cattle pastured on the well-watered hillsides above the Cantabrian Sea. The recipe is straightforward: whole milk is set with animal rennet, drained briefly, pressed for not more than a day, and salted in brine. After a minimum of just one week of ripening the cheese is ready to eat — most are sold within a fortnight to two months, when the paste is at its creamiest. Spanish DO came in 1985 and EU PDO followed in 1996. Finished wheels (or rectangular blocks) carry a soft pale rind around an ivory paste with a buttery, very gently lactic flavour — a quietly comforting young cheese with no eyes and no pungency, suited to the breakfast table with bread and honey.","sources":[{"label":"Foods and Wines from Spain — Nata de Cantabria PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-nata-de-cantabria-pdo"},{"label":"Wikipedia: Cantabrian cream cheese","url":"https://en.wikipedia.org/wiki/Cantabrian_cream_cheese"}],"pronunciation":{"ipa":"/ˈkeso ˈnata de kanˈtaβɾja/","respelling":"KEH-soh NAH-tah day kan-TAH-bryah"},"region_polygon":{"type":"Polygon","coordinates":[[[-4.9,43.45],[-4.3,43.45],[-3.6,43.5],[-3.1,43.45],[-3.15,43.2],[-3.5,43.05],[-4.3,43.05],[-4.85,43.2],[-4.9,43.45]]]}},{"name":"Queso Palmero / Queso de La Palma","lat":28.7,"lon":-17.9,"country":"Spain","where":"La Palma, Canary Islands","hint":"La Palma, Canaries","desc":"Goat\'s-milk cheese, often lightly smoked over wood from local volcanic woodland.","image":"queso_palmero.jpg","name_protections":["PDO"],"milk_types":["goat"],"pasteurization":"raw","style":["semi-hard","smoked","pressed"],"ageing_min_days":8,"format":"wheel, ~1–15 kg, 12–60 cm × 6–15 cm","year_recognized":2002,"animal_breed":["Palmera"],"vegetarian":null,"desc_long":"Queso Palmero is the goat\'s-milk cheese of the western Canary island of La Palma, produced under PDO from the raw milk of the native Palmera goat — a hardy local breed pastured on the island\'s volcanic slopes and laurel forests. The milk is coagulated with rennet drawn from kid stomachs, and the wheels are pressed and lightly salted before an optional short smoking step over local fuels: almond shells, dried prickly pear, or needles of the Canary pine, applied briefly so that the perfume lingers without overwhelming the cheese. Producers offer three age classes: fresh (eight to twenty days), semi-cured (three weeks to two months) and cured (sixty days or more). EU PDO came in 2002. The largest wheels can reach fifteen kilograms — among the largest farmstead goat cheeses in Europe. Fresh Palmero is bright and milky; the smoked and cured wheels turn drier and assertive, with a savoury core lifted by the gentle smoke note that ties the cheese unmistakably to its island.","sources":[{"label":"Foods and Wines from Spain — Queso Palmero PDO","url":"https://www.foodswinesfromspain.com/content/icex-foodswines/en/food/products/cheese/queso-palmero-pdo.html"},{"label":"Spanish Ministry of Agriculture (MAPA): DOP Queso Palmero (archived)","url":"https://web.archive.org/web/20090414185316/http://www.mapa.es/es/alimentacion/pags/Denominacion/queso_lacteo/queso_palmero.htm"},{"label":"Wikipedia: Palmero cheese","url":"https://en.wikipedia.org/wiki/Palmero_cheese"}],"pronunciation":{"ipa":"/ˈkeso palˈmeɾo/","respelling":"KEH-soh pal-MEH-roh"},"region_polygon":{"type":"Polygon","coordinates":[[[-18.0,28.85],[-17.85,28.85],[-17.7,28.65],[-17.7,28.45],[-17.85,28.4],[-17.95,28.65],[-18.0,28.85]]]}},{"name":"Queso Tetilla","lat":42.88,"lon":-8.6,"country":"Spain","where":"Galicia","hint":"Galicia","desc":"Cow\'s-milk cheese in a distinctive teat (tetilla) shape — soft paste, gentle lactic tang.","image":"queso_tetilla.jpeg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-soft"],"ageing_min_days":8,"format":"teat-shaped cone, ~500 g – 1.5 kg","year_recognized":1992,"animal_breed":["Friesian","Swiss Brown","Rubia Gallega"],"vegetarian":null,"desc_long":"Queso Tetilla is one of the iconic cheeses of Galicia, instantly recognisable by its shape — a soft cone topped with a small nipple, exactly as the name (tetilla, meaning little nipple) suggests. The PDO covers production across the whole of Galicia using whole milk from Friesian, Swiss Brown and Galician Blonde cattle, set with rennet and lightly drained into the moulds that give the cheese its characteristic silhouette. After a brief brining the cheese ripens just over a week before sale; most wheels are eaten young. Spanish DO came in 1992 and EU PDO followed in 1996. The paste is pale ivory and pleasingly elastic, with a mild butter-and-milk flavour and a faintly lactic tang — uncomplicated and friendly, with none of the assertiveness of the great mountain cheeses. Tetilla is at the centre of Galician table cooking, sliced for breakfast over bread, melted into queso fundido with quince paste, or simply sliced alongside the Albariño white wines of the same region.","sources":[{"label":"Wikipedia: Tetilla cheese","url":"https://en.wikipedia.org/wiki/Tetilla_cheese"},{"label":"Spanish Ministry of Agriculture (MAGRAMA): DOP Queso Tetilla","url":"http://www.magrama.gob.es/es/alimentacion/temas/calidad-agroalimentaria/calidad-diferenciada/dop/queso_lacteo/DOP_queso_tetilla.aspx"}],"pronunciation":{"ipa":"/ˈkeso teˈtiʎa/","respelling":"KEH-soh teh-TEE-yah"},"region_polygon":{"type":"Polygon","coordinates":[[[-9.3,43.8],[-8.5,43.8],[-7.5,43.5],[-6.85,42.85],[-7.4,42.1],[-8.4,41.95],[-8.95,42.2],[-9.3,43.1],[-9.3,43.8]]]}},{"name":"Queso Zamorano","lat":41.5,"lon":-5.75,"country":"Spain","where":"Zamora province, Castilla y León","hint":"Castilla y León — Zamora","desc":"Sheep\'s-milk cheese from Churra and Castellana ewes; firm, salty, intense.","image":"queso_zamorano.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","pressed"],"ageing_min_days":100,"format":"cylinder, up to 4 kg, 24 cm × 14 cm","year_recognized":1996,"animal_breed":["Churra","Castellana"],"vegetarian":null,"desc_long":"Queso Zamorano is the great sheep\'s-milk cheese of the province of Zamora in Castilla y León, made from the raw whole milk of two native Castilian breeds — Churra and Castellana — that have grazed the dry uplands and river valleys of the meseta for centuries. The PDO requires the milk to be set with animal rennet, the curd cut to a small grain, gently heated, pressed and salted in brine. Maturation runs a minimum of one hundred days in cool cellars, producing wheels of up to four kilograms with a hard pale-yellow to grey rind and a dense ivory paste flecked with small irregular eyes. Spanish DO came in 1993 and EU PDO followed in 1996. Zamorano shares the family resemblance of the Castilian sheep cheeses with Manchego, but the longer minimum ageing and the local breeds give it a deeper, drier and more emphatically savoury character — at home with Toro Tinta de Toro reds and the gold-skinned almonds of the region.","sources":[{"label":"Foods and Wines from Spain — Queso Zamorano PDO","url":"https://www.foodswinesfromspain.com/en/food/products/cheese/queso-zamorano-pdo"},{"label":"Consejo Regulador DOP Queso Zamorano","url":"https://quesozamorano.com/"}],"pronunciation":{"ipa":"/ˈkeso θamoˈɾano/","respelling":"KEH-soh thah-moh-RAH-noh"},"region_polygon":{"type":"Polygon","coordinates":[[[-6.8,42.2],[-6.05,42.25],[-5.2,42.1],[-5.0,41.65],[-5.2,41.4],[-5.95,41.45],[-6.55,41.65],[-6.85,41.95],[-6.8,42.2]]]}},{"name":"Quesucos de Liébana","lat":43.15,"lon":-4.65,"country":"Spain","where":"Liébana, Cantabria","hint":"Liébana valleys, Cantabria","desc":"Small cheese from cow/sheep/goat blend, sometimes lightly smoked; mountain valley tradition.","image":"quesucos_de_liébana.jpg","name_protections":["PDO"],"milk_types":["cow","sheep","goat"],"pasteurization":"any","style":["semi-soft","smoked"],"ageing_min_days":30,"format":"small cylinder or disc, 8–12 cm × 3–10 cm","year_recognized":1994,"animal_breed":["Tudanca","Pardo Alpina","Friesian","Latxa","Pyrenean goat"],"vegetarian":null,"desc_long":"Quesucos de Liébana are the small farmhouse cheeses of the Liébana valley deep in the Cantabrian mountains, recognised under a PDO that permits cow, sheep or goat milk alone or in any blend — a flexibility that mirrors the mixed-livestock husbandry of the valley. Native Tudanca, Pardo-Alpina and Friesian cattle, Latxa ewes and Pyrenean goats all contribute to the milk pool, and producers can make their cheese with either raw or pasteurised milk; raw-milk wheels age at least sixty days while pasteurised may go to market sooner. Wheels are deliberately small (the diminutive quesucos translates as little cheeses), in low cylinders or discs of a few hundred grams. A traditional variant is gently smoked over local woods, taking on a faint amber rind and a deeper, more savoury character. Spanish DO came in 1994 and EU PDO followed in 1996. The cheeses are typical small mountain table cheeses — mild, faintly grassy in their plain form and warmly smoky in the smoked version — at home with the chestnut-and-bean stews of the surrounding country.","sources":[{"label":"Foods and Wines from Spain — Quesucos de Liébana PDO","url":"https://www.foodswinesfromspain.com/content/icex-foodswines/en/food/products/cheese/quesucos-de-liebana-pdo.html"},{"label":"Wikipedia: Cantabrian cuisine","url":"https://en.wikipedia.org/wiki/Cantabrian_cuisine"}],"pronunciation":{"ipa":"/keˈsukos de ˈljeβana/","respelling":"keh-SOO-kohs day LYAY-bah-nah"},"region_polygon":{"type":"Polygon","coordinates":[[[-4.85,43.25],[-4.6,43.3],[-4.4,43.2],[-4.45,43.05],[-4.7,43.0],[-4.9,43.1],[-4.85,43.25]]]}},{"name":"Roncal","lat":42.81,"lon":-0.94,"country":"Spain","where":"Roncal valley, Navarre","hint":"Western Pyrenees, Navarre","desc":"Hard raw sheep\'s-milk Pyrenean cheese from Latxa and Rasa Aragonesa ewes; the first Spanish PDO.","image":"roncal.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"raw","style":["hard","pressed"],"ageing_min_days":120,"format":"cylinder, 2–3 kg","year_recognized":1981,"animal_breed":["Latxa","Rasa Aragonesa"],"vegetarian":false,"desc_long":"Roncal holds a special place in the catalogue of Spanish cheese: granted Denominación de Origen in 1981, it was the first Spanish cheese formally protected by an origin designation. Made in seven small villages of the Roncal valley in the western Navarrese Pyrenees, the cheese uses the raw whole milk of native Latxa and Rasa Aragonesa ewes set with animal rennet and salt, with no other ingredients. Wheels of two to three kilograms are pressed in cloth, dry-salted and aged for a minimum of four months in cool valley cellars; many wheels go to nine or ten months. EU PDO recognition followed in 1996. Roncal carries a hard pale-yellow rind and a dense ivory-to-straw paste with a clean, intensely savoury flavour that grows nuttier and more emphatically piquant with age — recognisably part of the Pyrenean sheep-cheese tradition alongside the French Ossau-Iraty across the border, and the indispensable Navarrese table cheese.","sources":[{"label":"Ibergour / Reyno Gourmet on Roncal PDO","url":"https://reynogourmet.com/en/alimentos-de-navarra/roncal-cheese/"},{"label":"EU DOOR registry: Roncal denomination (archived)","url":"https://web.archive.org/web/20121023233411/http://ec.europa.eu/agriculture/quality/door/registeredName.html?denominationId=625"},{"label":"Wikipedia: Roncal cheese","url":"https://en.wikipedia.org/wiki/Roncal_cheese"}],"pronunciation":{"ipa":"/ronˈkal/","respelling":"rohn-KAHL"},"region_polygon":{"type":"Polygon","coordinates":[[[-1.2,43.0],[-0.95,43.0],[-0.7,42.9],[-0.75,42.7],[-1.0,42.6],[-1.25,42.75],[-1.2,43.0]]]}},{"name":"Svecia","lat":59.0,"lon":16.0,"country":"Sweden","where":"Throughout Sweden","hint":"Sweden","desc":"Semi-hard cow\'s-milk cheese in large discs, sometimes flavoured with caraway or cloves.","image":"svecia.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","pressed"],"ageing_min_days":60,"format":"cylinder, 35 cm dia, ~12–15 kg","year_recognized":1997,"animal_breed":["Swedish Red and White","Swedish Holstein-Friesian"],"vegetarian":null,"desc_long":"Svecia is Sweden\'s only PGI cheese — a semi-hard pasteurised cow\'s-milk wheel made across the country from milk drawn from the two principal Swedish dairy breeds, Swedish Red and White (SRB) and Swedish Holstein-Friesian. The spec calls for pasteurisation, then rennet is added, the curd cut, washed once in warm whey, heated, and stirred a second time after salt is added. The curd is moulded into a wide flat cylinder thirty-five centimetres across and twelve to fifteen kilograms in weight, with the mould design admitting enough air to leave countless evenly distributed small irregular eyes in the finished paste. Wheels mature at least two months. EU PGI came in 1997. The cheese is uniform yellow, firm but supple, mildly tangy in the young grade and progressively sharper, saltier and more aromatic when ripened twelve months or longer. The most aged grade is sometimes dressed with caraway or cloves, anchoring Svecia in the broader Nordic taste for spiced cheese alongside the cumin Leyden tradition.","sources":[{"label":"Qualigeo: Svecia PGI","url":"https://www.qualigeo.eu/en/product/svecia-pgi/"},{"label":"Wikipedia: Svecia","url":"https://en.wikipedia.org/wiki/Svecia"}],"pronunciation":{"ipa":"/ˈsveːsia/","respelling":"SVEH-see-ah"},"region_polygon":{"type":"Polygon","coordinates":[[[11.05,58.95],[11.6,60.2],[12.2,61.5],[13.4,64.2],[16.1,67.0],[18.2,68.55],[20.2,69.05],[23.65,68.45],[23.95,66.3],[21.65,65.55],[19.55,63.4],[17.55,61.3],[17.2,60.05],[18.9,57.4],[17.05,56.05],[14.85,55.35],[12.85,55.4],[11.15,56.05],[11.0,57.85],[11.05,58.95]]]}},{"name":"Berner Alpkäse / Berner Hobelkäse","lat":46.55,"lon":7.85,"country":"Switzerland","where":"Bernese Oberland","hint":"Bernese Oberland alps","desc":"Hard Alpine cow\'s-milk cheese made on summer pastures; aged Hobelkäse is shaved in curls.","image":"berner_alpkase_berner_hobelkase.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","extra-hard","alpine","wood-fire"],"ageing_min_days":135,"format":"wheel, ~5–14 kg (Alpkäse); aged 24 mo+ (Hobelkäse)","year_recognized":2004,"animal_breed":["Simmental"],"vegetarian":null,"desc_long":"Berner Alpkäse is the summer-only alpine cheese of the Bernese Oberland, made over roughly one hundred days from late June through August on the upper pastures of the Berner Alpen. The AOP requires raw cow\'s milk — Simmentaler stock — from cattle grazing pastures with no artificial fertiliser, processed within eighteen hours of milking in a copper vat heated by wood fire. The work is entirely manual. After pressing, wheels rest one day in a saturated brine bath, then mature on wood for a minimum of four and a half months. The same wheel matured at least two years and developed into a brittle, deeply concentrated form is sold as Berner Hobelkäse — \\"planing cheese\\" — too hard to slice with a knife and traditionally shaved into thin rolls with a Hobel plane. Switzerland\'s AOC came in 2004; AOP recognition followed in 2013. Young Alpkäse has a firm aromatic paste with high-alpine herb notes; Hobelkäse is a long-aged crystalline cheese, intensely savoury, ideal with kirsch and dried Bergsteigerbirnen pears.","sources":[{"label":"Swiss AOP-IGP: Berner Alpkäse and Berner Hobelkäse","url":"https://www.aop-igp.ch/en/berner-alpkaese-aop-and-berner-hobelkaese-aop"},{"label":"Wikipedia: Berner Alpkäse","url":"https://en.wikipedia.org/wiki/Berner_Alpk%C3%A4se"}],"pronunciation":{"ipa":"/ˈbɛʁnɐ ˈalpˌkɛːzə/","respelling":"BAIR-ner AHLP-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[7.2,46.85],[7.7,46.85],[8.2,46.75],[8.3,46.5],[7.85,46.3],[7.3,46.4],[7.1,46.65],[7.2,46.85]]]}},{"name":"Bloderkäse / Werdenberger Sauerkäse","lat":47.2,"lon":9.45,"country":"Switzerland","where":"Werdenberg & Liechtenstein border, St. Gallen","hint":"St. Gallen / Liechtenstein border","desc":"Sour-curd skim-milk cheese with a very long pedigree; sharp, low-fat, eaten thinly sliced.","image":"bloderkäse.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["fresh","sour-curd","low-fat"],"ageing_min_days":21,"format":"small wheel, ~1–4 kg","year_recognized":2010,"animal_breed":null,"vegetarian":null,"desc_long":"Bloderkäse and its aged form Werdenberger Sauerkäse are the sour-curd skimmed-milk cheeses of the Werdenberg and Obertoggenburg districts in canton St. Gallen, made today by only five dairies under a single AOP that links them with their Liechtensteiner counterpart. The recipe uses raw skimmed cow\'s milk combined with buttermilk and lactic-acid cultures; the milk acidifies and coagulates without animal rennet, producing a remarkably low-fat curd. Fresh wheels are sold as Bloderkäse after twenty-one days — squeaky-textured, slightly springy, often compared to a firm mozzarella with \\"Pfupf\\" — while wheels held two further months in dry maturation become Sauerkäse: drier, darker, sharply acidic, an austere mountain cheese with a long traceable history at the table of the Toggenburg valley. Switzerland\'s AOC came in 2010; AOP recognition followed in 2013. About 15 kg of cheese comes from 100 litres of skimmed milk — a yield typical of acid-set rather than rennet-set cheeses.","sources":[{"label":"Swiss AOP-IGP: Bloder-Sauerkäse AOP","url":"https://www.aop-igp.ch/bloder-sauerkaese-aop/"}],"pronunciation":{"ipa":"/ˈbloːdɐˌkɛːzə/","respelling":"BLOH-der-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[9.2,47.3],[9.45,47.3],[9.55,47.2],[9.55,47.0],[9.3,46.95],[9.15,47.15],[9.2,47.3]]]}},{"name":"Emmentaler","lat":46.95,"lon":7.7,"country":"Switzerland","where":"Emme valley & central Switzerland","hint":"Emme valley, central Switzerland","desc":"Famously holey hard cow\'s-milk wheel; the original \'Swiss cheese\' silhouette.","image":"emmentaler.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed","eyed"],"ageing_min_days":120,"format":"wheel, ~75–120 kg","year_recognized":2000,"animal_breed":null,"vegetarian":null,"desc_long":"Emmentaler is the giant-wheeled Swiss original — the cheese that gave Emmental its name and the world its mental image of \\"Swiss cheese with holes\\". The AOP draws raw milk from the Emme valley of Berne and adjacent cantons, requiring strictly silage-free cows, a maximum twenty-kilometre haul, and processing within twenty-four hours. The recipe stretches milk to a remarkable scale — a single wheel weighs seventy-five to a hundred-twenty kilograms and uses about a thousand litres of milk. The curd is scalded around 53 °C, pressed into the wheel mould, brined, and ripened through a deliberate warm phase that wakes the propionic-acid bacteria responsible for the cheese\'s classic walnut-to-cherry-sized eyes. Wheels mature at least four months for the classic grade; Réserve runs eight to twelve months and beyond. Switzerland registered the AOC in 2000; the AOP designation replaced it in 2013. The paste is firm and ivory-yellow, the flavour mellow and faintly sweet with a clean nutty finish.","sources":[{"label":"Emmentaler AOP: specifications","url":"https://www.emmentaler.ch/en/what-is-governed-by-the-specifications"},{"label":"Swiss AOP-IGP Association: register","url":"https://www.aop-igp.ch/en/about-pdo-pgi/register-of-the-swiss-designations-of-origin-and-geographical-indications"},{"label":"Wikipedia: Emmental cheese","url":"https://en.wikipedia.org/wiki/Emmental_cheese"}],"pronunciation":{"ipa":"/ˈɛmənˌtaːlɐ/","respelling":"EM-en-tah-ler"},"region_polygon":{"type":"Polygon","coordinates":[[[7.05,47.3],[7.75,47.35],[8.2,47.3],[8.1,47.0],[7.55,46.75],[7.1,46.85],[6.95,47.1],[7.05,47.3]]]}},{"name":"Formaggio d\'alpe Ticinese","lat":46.5,"lon":8.9,"country":"Switzerland","where":"Ticino Alps","hint":"Italian Switzerland","desc":"Hard summer-only Alpine cow\'s-milk cheese from Ticino mountain dairies; pronounced character.","image":"formaggio_dalpe_ticinese.jpg","name_protections":["AOP"],"milk_types":["cow","goat"],"pasteurization":"raw","style":["semi-hard","alpine","cooked","pressed"],"ageing_min_days":45,"format":"wheel, ~3–10 kg","year_recognized":2002,"animal_breed":null,"vegetarian":null,"desc_long":"Formaggio d\'Alpe Ticinese is the summer-pasture cheese of Switzerland\'s Italian-speaking south, made between 1 June and 30 September on the high alpages of canton Ticino at altitudes of 1 500 to 2 400 metres. The AOP draws raw cow\'s milk — with up to thirty per cent goat\'s milk permitted — from cattle and goats grazing the Lepontine and Ticinese alpine flora. The cheese is made daily in copper kettles: coagulation runs twenty-five to forty-five minutes at 30–35 °C, the curd is then scalded to 41–50 °C for twenty to fifty minutes, pressed and brined for a day. Wheels of three to ten kilograms mature at least forty-five days. Switzerland\'s AOC came in 2002; AOP recognition followed in 2013. The paste is firm but supple, lightly straw-yellow with sparse small eyes; the flavour carries the high-alpine herb signature — gentian, anise, alpine clover — that distinguishes Ticinese alpages from northern Swiss ones, and the cheese reaches its best after eight to twelve months.","sources":[{"label":"Swiss AOP-IGP: Formaggio d\'Alpe Ticinese","url":"https://www.aop-igp.ch/en/about-pdo-pgi/swiss-map-1/index.php?id=287&L=1"}],"pronunciation":{"ipa":"/forˈmaddʒo ˈdalpe ti.tʃiˈneːze/","respelling":"for-MAH-joh DAHL-pay tee-chee-NAY-zay"},"region_polygon":{"type":"Polygon","coordinates":[[[8.4,46.55],[8.85,46.55],[9.2,46.35],[9.25,46.05],[8.95,45.85],[8.55,45.95],[8.4,46.25],[8.4,46.55]]]}},{"name":"Glarner Alpkäse","lat":46.99,"lon":9.07,"country":"Switzerland","where":"Canton of Glarus","hint":"Glarus Alps, eastern Switzerland","desc":"Raw cow\'s-milk Alpine cheese from summer pasture; firm, with hints of mountain herbs.","image":"glarner_alpkäse.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","alpine","washed-rind"],"ageing_min_days":60,"format":"wheel, ~5–9 kg, 28–32 cm diameter","year_recognized":2013,"animal_breed":null,"vegetarian":null,"desc_long":"Glarner Alpkäse is the summer-only alpine cheese of canton Glarus in eastern Switzerland, made between 1 May and 30 September on the canton\'s upper pastures. The AOP requires raw silage-free cow\'s milk, processed immediately after milking in copper vats heated to 44–47 °C. Wheels of five to nine kilograms — 28–32 centimetres across — are pressed, brined and matured for at least sixty days on wooden boards, with regular washing of the rind to develop a firm, slightly burnished surface. Switzerland\'s AOP came in 2013. The cheese is full-fat semi-hard with a supple ivory paste lightly eyed, and the flavour reflects the Glarus alpages closely — a clean dairy sweetness lifted by the wild thyme and alpine clover of the region. Glarner Alpkäse is the workhorse cheese of canton Glarus, particularly central to the local Schabziger heritage (an unrelated cousin) and the everyday Glarus table.","sources":[{"label":"Swiss AOP-IGP: Glarner Alpkäse","url":"https://www.aop-igp.ch/glarner-alpkaese-aop"}],"pronunciation":{"ipa":"/ˈɡlaʁnɐ ˈalpˌkɛːzə/","respelling":"GLAR-ner AHLP-kay-zuh"},"region_polygon":{"type":"Polygon","coordinates":[[[8.85,47.15],[9.1,47.15],[9.3,47.05],[9.3,46.85],[9.05,46.75],[8.85,46.85],[8.85,47.15]]]}},{"name":"Le Gruyère","lat":46.58,"lon":7.08,"country":"Switzerland","where":"Cantons Fribourg, Vaud, Neuchâtel, Jura, parts of Bern","hint":"Fribourg foothills, western Switzerland","desc":"Hard cow\'s-milk wheel cooked, pressed and aged in cellars; the keystone of Swiss fondue.","image":"le_gruyere.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed"],"ageing_min_days":150,"format":"wheel, ~25–40 kg","year_recognized":2001,"animal_breed":null,"vegetarian":null,"desc_long":"Le Gruyère is one of Switzerland\'s two great hard alpine cheeses, made in the cantons of Fribourg, Vaud, Neuchâtel, Jura and parts of Berne in a tradition that goes back to at least the twelfth century. The AOP requires raw cow\'s milk from cattle fed exclusively on grass in summer and hay in winter — silage is forbidden — and the milk must travel no more than twenty kilometres from farm to dairy and be processed within twenty-four hours. The milk is set in copper cauldrons, cut to rice-sized curds, scalded above 50 °C, then pressed into wheels of twenty-five to forty kilograms, brined for about a day, and matured in cellars for at least five months. Réserve grade goes to ten months, and well-aged wheels run eighteen months and beyond. Switzerland\'s AOC came in 2001; the AOP designation replaced it in 2013. The flavour evolves from milky-sweet to deeply savoury, brothy and faintly crystalline with age — the canonical cheese of the Swiss fondue moitié-moitié alongside Vacherin Fribourgeois.","sources":[{"label":"Le Gruyère AOP official site","url":"https://www.gruyere.com/en/le-gruyere-aop/protected-designation-of-origin-aop"},{"label":"Academy of Cheese: Le Gruyère AOP","url":"https://academyofcheese.org/le-gruyere-aop/"},{"label":"Swiss AOP-IGP Association: register","url":"https://www.aop-igp.ch/en/about-pdo-pgi/register-of-the-swiss-designations-of-origin-and-geographical-indications"},{"label":"Wikipedia: Gruyère cheese","url":"https://en.wikipedia.org/wiki/Gruyère_cheese"}],"pronunciation":{"ipa":"/lə ɡʁy.jɛʁ/","respelling":"luh groo-YAIR"},"region_polygon":{"type":"Polygon","coordinates":[[[6.4,47.3],[7.0,47.3],[7.5,47.1],[7.65,46.65],[7.2,46.35],[6.65,46.4],[6.35,46.75],[6.4,47.3]]]}},{"name":"L\'Etivaz","lat":46.42,"lon":7.1,"country":"Switzerland","where":"Pays d\'Enhaut, Vaud","hint":"Vaud pre-Alps","desc":"Alpine cow\'s-milk cheese cooked over open wood fires in copper cauldrons; summer-only.","image":"letivaz.jpeg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","alpine","cooked","pressed","wood-fire"],"ageing_min_days":150,"format":"wheel, ~15–35 kg","year_recognized":1999,"animal_breed":null,"vegetarian":null,"desc_long":"L\'Etivaz is the purest expression of Swiss alpage cheesemaking: a hard cooked-curd cheese produced only between 10 May and 10 October, only at summer-pasture huts between one thousand and two thousand metres in the Vaudois Alps. The AOP restricts production to ten municipalities — Château-d\'Oex, Rougemont, Rossinière, Ollon, Villeneuve, Ormont-Dessus, Ormont-Dessous, Corbeyrier, Leysin and Bex — and requires raw cow\'s milk from cattle fed exclusively on natural alpine grass and herbs. The cheese is set in the traditional copper cauldron and heated only over an open wood fire — a defining production detail that contributes the cheese\'s smoky, savoury underlay. Wheels of fifteen to thirty-five kilograms are matured at the cooperative cellar in L\'Etivaz village for five to thirteen months. Switzerland\'s AOC came in 1999; AOP recognition followed in 2013. Production is famously tiny — only around 17 000 wheels each summer — and the flavour is intensely concentrated: alpine herbs, hazelnut, brown butter, and a long resinous wood-smoke finish.","sources":[{"label":"Swiss AOP-IGP Association: L\'Etivaz","url":"https://www.aop-igp.ch/en/letivaz-aop"},{"label":"Wikipedia: L\'Etivaz","url":"https://en.wikipedia.org/wiki/L%27Etivaz"}],"pronunciation":{"ipa":"/le.ti.va/","respelling":"lay-tee-VAH"},"region_polygon":{"type":"Polygon","coordinates":[[[6.85,46.55],[7.2,46.55],[7.35,46.4],[7.25,46.2],[6.85,46.2],[6.7,46.35],[6.85,46.55]]]}},{"name":"Raclette du Valais","lat":46.23,"lon":7.36,"country":"Switzerland","where":"Valais","hint":"Valais valleys","desc":"Cow\'s-milk wheel made for melting; eaten scraped onto potatoes, pickles and onions.","image":"raclette_du_valais.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","washed-rind","melting"],"ageing_min_days":90,"format":"wheel, ~5 kg, 29–31 cm diameter","year_recognized":2003,"animal_breed":null,"vegetarian":null,"desc_long":"Raclette du Valais is the canton-of-Valais expression of Switzerland\'s great melting cheese tradition, made from raw cow\'s milk drawn from herds whose feed is at least seventy-five per cent local roughage and from which silage is strictly excluded. Milk is cooled to under 8 °C within two hours of milking, delivered to the dairy twice daily, and processed within twenty-four hours in copper kettles. Wheels are roughly twenty-nine to thirty-one centimetres across and five kilograms in weight, salt-rubbed or brined for a day, then matured at least three months on red-spruce planks with regular washing and turning. Switzerland\'s AOC came in 2003; AOP recognition followed in 2013. The cheese has a thin tan washed rind and a supple ivory paste; the canonical use is to set a half-wheel face-up against an open hearth and scrape the melted layer onto boiled potatoes with pickled onions and gherkins — the dish raclette, named for racler, to scrape, which the cheese gave to the rest of Switzerland.","sources":[{"label":"Swiss AOP-IGP: Walliser Raclette AOP","url":"https://www.aop-igp.ch/en/walliser-raclette-aop"},{"label":"Wikipedia: Raclette","url":"https://en.wikipedia.org/wiki/Raclette"}],"pronunciation":{"ipa":"/ʁa.klɛt dy va.lɛ/","respelling":"rah-KLET doo vah-LAY"},"region_polygon":{"type":"Polygon","coordinates":[[[6.85,46.65],[7.45,46.55],[8.15,46.45],[8.5,46.2],[7.85,45.95],[7.05,46.0],[6.85,46.3],[6.85,46.65]]]}},{"name":"Sbrinz","lat":46.85,"lon":8.34,"country":"Switzerland","where":"Lucerne, Schwyz, Obwalden, Nidwalden, Zug","hint":"Central Switzerland (Lake Lucerne)","desc":"Very hard aged cow\'s-milk grating cheese; the oldest Swiss cheese, likely the ancestor of Parmesan.","image":"sbrinz.jpg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["extra-hard","grana-style","cooked","pressed"],"ageing_min_days":540,"format":"wheel, ~45 kg","year_recognized":2002,"animal_breed":["Swiss Brown"],"vegetarian":null,"desc_long":"Sbrinz is the great extra-hard grating cheese of central Switzerland — a deeply traditional alpine cheese once carried south over the Gotthard pass into northern Italy, where it likely influenced the development of grana-family cheeses. The AOP draws raw silage-free milk almost exclusively from Swiss Brown cows in cantons Lucerne, Schwyz, Nidwalden, Obwalden, Zug, and parts of Berne and Aargau, with the farm-to-dairy haul capped at thirty kilometres and processing within twenty-four hours. Curds are scalded fiercely, pressed into 45 kg wheels, and matured for at least eighteen months; ideal eating age is twenty-four months and many wheels rest two and a half years or more. Switzerland registered the AOC in 2002; the AOP designation replaced it in 2013. The wheels are remarkably dense, deep golden, and amply crystalline; Sbrinz is sliced wafer-thin (rebibes), shaved into curls, or grated over pasta. The flavour is concentrated, lightly piquant, and brothy with marked tyrosine crunch — the closest Swiss cousin to Parmigiano Reggiano.","sources":[{"label":"Sbrinz AOP official site","url":"https://www.sbrinz.ch/en/craftsmanship"},{"label":"Swiss AOP-IGP Association: Sbrinz","url":"https://www.aop-igp.ch/en/sbrinz-aop"},{"label":"Wikipedia: Sbrinz","url":"https://en.wikipedia.org/wiki/Sbrinz"}],"pronunciation":{"ipa":"/ʃbʁɪnts/","respelling":"SHBRINTS"},"region_polygon":{"type":"Polygon","coordinates":[[[7.5,47.3],[8.2,47.3],[8.85,47.1],[8.85,46.65],[8.3,46.5],[7.65,46.55],[7.45,46.95],[7.5,47.3]]]}},{"name":"Tête de Moine","lat":47.3,"lon":7.2,"country":"Switzerland","where":"Bernese Jura","hint":"Bernese Jura mountains","desc":"Semi-hard cow\'s-milk cylinder shaved into thin rosettes with a \'girolle\' rotary scraper.","image":"tête_de_moine.png","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","alpine","washed-rind","girolle"],"ageing_min_days":75,"format":"small cylinder, ~700 g – 2 kg","year_recognized":2001,"animal_breed":null,"vegetarian":null,"desc_long":"Tête de Moine is the famously rosetted Jura cheese of the Bellelay monastery tradition, made in canton Berne and adjoining parts of Jura. The AOP requires raw cow\'s milk from silage-free cattle — grass in summer, hay in winter — processed in copper vats within twenty-four hours of milking. The curd is cut fine, scalded to 46–53 °C, pressed into small cylindrical moulds and brined; wheels then ripen at 13–14 °C and ninety per cent humidity on spruce boards for at least seventy-five days, washed regularly with brine and dry-brushed. Switzerland\'s AOC came in 2001; AOP recognition followed in 2013. The cheese is not sliced but pared into delicate rosettes with the Girolle® — a custom rotating device invented in 1982 by Nicolas Crevoisier specifically for this cheese, which uses the curl of the shavings to bring out the aromatics. The flavour is intensely savoury and faintly mushroomy, with floral, alpine-herb top notes that bloom when paired with a glass of pinot noir.","sources":[{"label":"Swiss AOP-IGP Association: Tête de Moine","url":"https://www.aop-igp.ch/en/tete-de-moine-aop"},{"label":"Wikipedia: Tête de Moine","url":"https://en.wikipedia.org/wiki/T%C3%AAte_de_Moine"}],"pronunciation":{"ipa":"/tɛt də mwan/","respelling":"TET duh MWAHN"},"region_polygon":{"type":"Polygon","coordinates":[[[6.95,47.45],[7.3,47.45],[7.45,47.3],[7.35,47.1],[6.95,47.1],[6.85,47.3],[6.95,47.45]]]}},{"name":"Vacherin Fribourgeois","lat":46.6,"lon":7.1,"country":"Switzerland","where":"Canton of Fribourg","hint":"Fribourg pre-Alps","desc":"Semi-soft cow\'s-milk cheese with subtle nutty flavor; melts into fondue moitié-moitié with Gruyère.","image":"vacherin_fribourgeois.webp","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","washed-rind","fondue"],"ageing_min_days":63,"format":"wheel, ~6–10 kg, 30–40 cm × 6–9 cm","year_recognized":2005,"animal_breed":null,"vegetarian":null,"desc_long":"Vacherin Fribourgeois is the soft-melting partner to Le Gruyère in Switzerland\'s classic fondue moitié-moitié, made exclusively in the canton of Fribourg from cow\'s milk drawn from herds fed at least seventy per cent local roughage. The AOP permits raw or thermised milk; only about two per cent of the roughly 2 500 tonnes produced each year is the raw-milk grade, though it is the version most prized by cheesemongers. Wheels run thirty to forty centimetres across and six to nine kilograms in weight, and are matured on spruce boards in high-humidity cellars for nine to twenty-four weeks. Switzerland registered the AOC in 2005; AOP recognition followed in 2013. The rind is a thin damp tan with a faint smear, the paste pale and supple, and the flavour combines floral, milky sweetness up front with a long woody-mushroom finish from the spruce ripening. The cheese melts beautifully — the structural reason the fondue moitié-moitié exists — but is also superb on its own at the end of a meal.","sources":[{"label":"Swiss AOP-IGP Association: Vacherin Fribourgeois","url":"https://www.aop-igp.ch/en/vacherin-fribourgeois-aop"},{"label":"Wikipedia: Vacherin Fribourgeois","url":"https://en.wikipedia.org/wiki/Vacherin_Fribourgeois"}],"pronunciation":{"ipa":"/vaʃ.ʁɛ̃ fʁi.buʁ.ʒwa/","respelling":"vahsh-RAN free-boor-ZHWAH"},"region_polygon":{"type":"Polygon","coordinates":[[[6.75,47.1],[7.2,47.1],[7.45,46.95],[7.4,46.6],[7.0,46.5],[6.7,46.65],[6.65,46.95],[6.75,47.1]]]}},{"name":"Vacherin Mont-d\'Or","lat":46.55,"lon":6.3,"country":"Switzerland","where":"Vaud — Jura mountains","hint":"Vaud Jura","desc":"Winter-only soft cow\'s-milk cheese in a spruce-bark girdle; eaten by the spoonful, often baked.","image":"vacherin_mont_dor.jpeg","name_protections":["AOP"],"milk_types":["cow"],"pasteurization":"any","style":["soft","washed-rind","spruce-banded","winter"],"ageing_min_days":17,"format":"round box, 350 g – 3 kg, spruce-banded","year_recognized":2003,"animal_breed":null,"vegetarian":null,"desc_long":"Vacherin Mont-d\'Or is the great seasonal cheese of the Vaud Jura — a soft, almost-runny winter cheese that is produced only between 15 August and 31 March, when the cows have come down from the alpages and the milk supply is too small for hard alpine wheels. The AOP version is the Swiss counterpart of France\'s Mont d\'Or PDO, made on the eastern slope of the Mont d\'Or massif. After pressing, each cheese is bound in a band of cambium (the live inner bark of the Norway spruce, épicéa) and brined for two to four hours; the spruce ring stays on through ripening and gives the cheese its signature resinous aroma. Wheels mature at least seventeen days at 6–16 °C with eighty-five per cent humidity, washed and turned regularly, then are packaged in a thin spruce box that doubles as a vessel for warming the cheese in the oven. Switzerland\'s AOC came in 2003; AOP recognition followed in 2013. The paste is exceptionally soft, nearly spoonable when ripe, with a flavour of warm cream, spruce sap and forest floor.","sources":[{"label":"Swiss AOP-IGP Association: Vacherin Mont-d\'Or","url":"https://www.aop-igp.ch/en/vacherin-mont-dor-aop"},{"label":"Wikipedia: Vacherin Mont-d\'Or","url":"https://en.wikipedia.org/wiki/Vacherin_Mont_d\'Or"}],"pronunciation":{"ipa":"/vaʃ.ʁɛ̃ mɔ̃ dɔʁ/","respelling":"vahsh-RAN mohn DOR"},"region_polygon":{"type":"Polygon","coordinates":[[[6.05,46.75],[6.35,46.8],[6.5,46.65],[6.4,46.4],[6.1,46.4],[5.95,46.55],[6.05,46.75]]]}},{"name":"Appenzeller","lat":47.33,"lon":9.41,"country":"Switzerland","where":"Cantons Appenzell & St. Gallen","hint":"Appenzell, eastern Switzerland","desc":"Hard cow\'s-milk cheese washed with a secret herbal brine; sharp, pungent, centuries-old recipe.","image":"appenzeller.jpeg","name_protections":["GI"],"milk_types":["cow"],"pasteurization":"raw","style":["semi-hard","alpine","washed-rind","herbal-brine"],"ageing_min_days":90,"format":"wheel, ~6.5–8 kg","year_recognized":2017,"animal_breed":["Brown Swiss"],"vegetarian":null,"desc_long":"Appenzeller is the herbal-brine washed Swiss alpine cheese of cantons Appenzell Innerrhoden, Appenzell Ausserrhoden and parts of St. Gallen and Thurgau, made from raw milk drawn from about eight hundred certified farms working with Brown Swiss cattle on a silage-free regime of grass, wildflowers, herbs and hay. The defining production secret is the herbal brine — a closely guarded mixture of herbs, roots, leaves, petals, seeds, fruit rinds and local wine yeast steeped in spirit, then diluted with salt water — that is hand-applied to the rind throughout maturation. Wheels mature at least three months for the mild classic, with stronger grades extending up to six months or more. Long subject to canton-level protection and registered as a Swiss GI in 2017, Appenzeller is one of the most internationally recognised Swiss cheeses despite never having entered the AOP register due to a producer dispute. The paste is firm, ivory-yellow, eyed; the flavour is bright, faintly fruity and notoriously punchy, the herbal wash leaving a long aromatic finish.","sources":[{"label":"Wikipedia: Appenzeller cheese","url":"https://en.wikipedia.org/wiki/Appenzeller_cheese"},{"label":"Swiss AOP-IGP Association: register","url":"https://www.aop-igp.ch/en/about-pdo-pgi/register-of-the-swiss-designations-of-origin-and-geographical-indications"}],"pronunciation":{"ipa":"/ˈapənˌtsɛlɐ/","respelling":"AHP-en-tsel-er"},"region_polygon":{"type":"Polygon","coordinates":[[[9.1,47.6],[9.5,47.65],[9.75,47.55],[9.75,47.3],[9.55,47.15],[9.2,47.2],[9.05,47.4],[9.1,47.6]]]}},{"name":"Beacon Fell traditional Lancashire cheese","lat":53.85,"lon":-2.62,"country":"United Kingdom","where":"Lancashire — Beacon Fell area","hint":"Forest of Bowland, Lancashire","desc":"Crumbly buttery cow\'s-milk cheese, layered curds; the local style for hot-pot crowns.","image":"beacon_fell_traditional_lancashire.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":30,"format":"cylinder, ~10–20 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Beacon Fell traditional Lancashire is the protected farmhouse version of one of England\'s oldest pressed cheeses, made on a small group of dairies clustered around the Forest of Bowland in the western part of the county. The PDO requires the historical method that distinguishes traditional Lancashire from its more modern counterparts: curd from two days\' production is layered together, broken up, salted and pressed lightly so the finished wheel keeps an unusual loose, almost buttery texture rather than the dense paste of a cheddar. Wheels are lightly pressed for two days, then waxed, buttered or cloth-bound, and matured for a minimum of a month — though the cheese reaches its most expressive maturity around six months. EU PDO came in 1996. Younger Beacon Fell Lancashire is clean and milky with a gentle tang; well aged it sharpens into the moist, slightly spicy, frankly characterful cheese the Lancashire farmhouse tradition has been quietly defending for generations.","sources":[{"label":"Beacon Fell traditional Lancashire cheese product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/65605b270c7ec8001195bda3/Revised_Beacon_Fell_Traditional_Lancashire_Cheese_product_specification_final_.pdf"},{"label":"DEFRA / Qualigeo PDO spec: Beacon Fell Traditional Lancashire","url":"https://www.qualigeo.eu/en/product/beacon-fell-traditional-lancashire-cheese-pdo/"},{"label":"Wikipedia: Lancashire cheese","url":"https://en.wikipedia.org/wiki/Lancashire_cheese"}],"pronunciation":{"ipa":"/ˈbiːkən fɛl ˈlæŋkəʃər/","respelling":"BEE-kuhn fell LANG-kuh-sher"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.85,53.95],[-2.55,53.95],[-2.45,53.85],[-2.5,53.7],[-2.75,53.7],[-2.9,53.8],[-2.85,53.95]]]}},{"name":"Bonchester cheese","lat":55.4,"lon":-2.62,"country":"United Kingdom","where":"Bonchester Bridge, Scottish Borders","hint":"Scottish Borders","desc":"Small soft bloomy-rind Brie-style cow\'s-milk cheese — rare Scottish PDO from Jersey-cow milk.","image":"bonchester_cheese.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","bloomy-rind"],"ageing_min_days":10,"format":"small cylinder, ~100 g – 1.5 kg","year_recognized":1996,"animal_breed":["Jersey"],"vegetarian":null,"desc_long":"Bonchester is one of the rarer protected cheeses of the United Kingdom, made on a single Roxburghshire farm at Bonchester Bridge in the Scottish Borders from the raw whole milk of a Jersey herd grazed on the surrounding Cheviot uplands. The PDO recognises a small soft Brie-style cheese: milk is warmed, set with rennet, gently cut and moulded, salted in brine and matured for around ten to sixteen days under a developing white bloom. EU PDO came in 1996. The finished disc is cylindrical with a pale Penicillium rind around a pale-yellow paste — softer and more delicate than the better-known continental washed-rinds. The flavour is mild, faintly mushroomy and gently creamy, with the buttery character that Jersey milk reliably contributes. Production is small and the cheese remains effectively a single-dairy product, which makes it one of the harder protected British cheeses to find but a notable curiosity for visitors to the Borders.","sources":[{"label":"Bonchester cheese product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd34debd3bf7f305cb60380/pfn-bonchester-cheese.pdf"},{"label":"DEFRA / Qualigeo PDO spec: Bonchester cheese","url":"https://www.qualigeo.eu/en/product/bonchester-cheese-pdo/"},{"label":"Wikipedia: Bonchester cheese","url":"https://en.wikipedia.org/wiki/Bonchester_cheese"}],"pronunciation":{"ipa":"/ˈbɒntʃəstər/","respelling":"BON-chess-ter"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.9,55.55],[-2.55,55.55],[-2.3,55.45],[-2.35,55.2],[-2.6,55.1],[-2.85,55.2],[-2.95,55.4],[-2.9,55.55]]]}},{"name":"Buxton Blue","lat":53.26,"lon":-1.91,"country":"United Kingdom","where":"Peak District, Derbyshire","hint":"Peak District","desc":"Mild cow\'s-milk blue cheese tinted copper-orange with annatto; smooth, gentle bite.","image":"buxton_blue.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["hard","blue","natural-rind"],"ageing_min_days":42,"format":"cylinder, ~7.5–8.5 kg, ~20 cm × 19–22 cm","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Buxton Blue is a cow\'s-milk blue cheese from the Derbyshire spa town of Buxton, in the Peak District of the East Midlands. The PDO covers production using pasteurised milk set with starter, blue mould culture and rennet — and uniquely among British blues, the curd is coloured with annatto, the natural orange dye drawn from the Bixa orellana seed, lifting the paste to a vivid copper colour against which the blue veining stands out sharply. After pressing, wheels are wrapped in cloth and pierced repeatedly with long needles to admit the air on which the Penicillium depends, then matured for at least six weeks. EU PDO came in 1996. Buxton Blue is one of the smaller-volume British blues — and the closest in family to Blue Stilton, with which it shares an origin in the Stilton lineage — but its colour and a gentler, more buttery flavour distinguish it on the cheese board.","sources":[{"label":"Buxton Blue product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/604b67d7e90e07154010b683/product_specification_Buxton_Blue_Cheese.pdf"},{"label":"Wikipedia: Buxton Blue","url":"https://en.wikipedia.org/wiki/Buxton_Blue"}],"pronunciation":{"ipa":"/ˈbʌkstən bluː/","respelling":"BUK-stuhn BLOO"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.0,53.4],[-1.65,53.4],[-1.55,53.15],[-1.65,52.95],[-1.95,52.95],[-2.05,53.2],[-2.0,53.4]]]}},{"name":"Dorset Blue Cheese","lat":50.78,"lon":-2.33,"country":"United Kingdom","where":"Dorset","hint":"Dorset, southern England","desc":"Cow\'s-milk blue (\'Blue Vinney\') from skim milk; firm, crumbly, sharp.","image":"dorset_blue_cheese.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","blue","natural-rind"],"ageing_min_days":75,"format":"cylinder, ~6 kg","year_recognized":1998,"animal_breed":null,"vegetarian":null,"desc_long":"Dorset Blue Cheese — known almost universally by its traditional name, Dorset Blue Vinney — is the famously firm, sharp blue cheese of southwest England, made from the skimmed milk of Dorset dairy cattle. Milk is set, drained, salted and shaped into modest cylinders of about six kilograms; after a month of initial ripening each wheel is pierced repeatedly with long fine needles to admit the air on which Penicillium roqueforti depends, and ageing continues for a total of three to five months. The PGI was secured in 1998 after a determined revival of a recipe that had been on the edge of extinction. Because the cheese is built from skim milk, the paste is drier and crumblier than richer blues; the flavour is correspondingly assertive — pungent, salt-forward, mineral, with the deep tang that the vinney mould (a Dorset dialect word for blue) provides. Dorset Blue Vinney is also the indispensable centre of a regional speciality, blue-vinney soup, often served with chunks of the local Dorset Knobs biscuit.","sources":[{"label":"Dorset Blue Cheese product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd34f848fa8f54d59e8b745/pfn-dorset-blue-vinny-cheese.pdf"},{"label":"Wikipedia: Dorset Blue Vinney","url":"https://en.wikipedia.org/wiki/Dorset_Blue_Vinney"}],"pronunciation":{"ipa":"/ˈdɔːsɪt bluː/","respelling":"DOR-set BLOO"},"region_polygon":{"type":"Polygon","coordinates":[[[-3.0,50.95],[-2.5,51.05],[-1.95,50.95],[-1.9,50.65],[-2.4,50.55],[-2.85,50.65],[-3.0,50.95]]]}},{"name":"Dovedale cheese","lat":53.1,"lon":-1.78,"country":"United Kingdom","where":"Peak District","hint":"Peak District","desc":"Soft mild cow\'s-milk blue cheese; spoonable, dairy-sweet.","image":"dovedale.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["soft","blue","natural-rind"],"ageing_min_days":28,"format":"small cylinder, ~200 g – 1 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Dovedale is a soft mild blue cow\'s-milk cheese from the Peak District, made within an eighty-kilometre radius of the Dovedale valley itself, with milk drawn from a defined zone across parts of Derbyshire, Nottinghamshire and Staffordshire. The PDO is unusual in the British cheese landscape in mandating that the wheels be dipped in brine during maturation rather than the dry-salting more common in the United Kingdom, which gives Dovedale a softer, more continental finish than its near-neighbour Buxton Blue. After moulding and brine-dipping the wheels mature at a cool, very humid temperature with regular turning; the rind stays thin and the paste turns moist, ivory-white and softly veined with blue. EU PDO came in 1996. The flavour is genuinely mild for a blue — almost buttery, with the moulds adding a quiet savoury tang rather than the sharper bite of older British blues — and the cheese spreads beautifully on a digestive biscuit or under a drizzle of local honey.","sources":[{"label":"Dovedale cheese product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/604b6924e90e07153b5675c5/product_specification_Dovedale_Cheese_.pdf"},{"label":"Wikipedia: Dovedale cheese","url":"https://en.wikipedia.org/wiki/Dovedale_cheese"}],"pronunciation":{"ipa":"/ˈdʌvdeɪl/","respelling":"DUV-dayl"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.0,53.3],[-1.6,53.3],[-1.5,53.05],[-1.65,52.85],[-1.95,52.85],[-2.05,53.1],[-2.0,53.3]]]}},{"name":"Exmoor Blue Cheese","lat":51.13,"lon":-3.65,"country":"United Kingdom","where":"Exmoor, Somerset","hint":"Exmoor moors, SW England","desc":"Soft Jersey-cow\'s-milk blue from Exmoor pastures; rich and buttery.","image":"exmoor_blue.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"raw","style":["soft","blue","natural-rind"],"ageing_min_days":21,"format":"small cylinder, ~1 kg","year_recognized":1999,"animal_breed":["Jersey"],"vegetarian":null,"desc_long":"Exmoor Blue is a small farmstead blue cheese made on a single dairy in west Somerset, using raw whole milk from a Jersey herd grazed on the lush margins of Exmoor. The PGI covers production at Willett Farm, where the milk is set with rennet, drained, salted and seeded with Penicillium roqueforti, then matured for three to six weeks with regular turning. The Jersey milk gives the paste an unusually rich yellow colour and a fat content that lifts the cheese into the moist, buttery family of blues rather than the drier crumbly British style. EU PGI came in 1999. The aroma is warm and dairy-sweet, the flavour markedly creamy, with the blue moulds adding a clean tang that lengthens through the finish — at home with the local cider and the bread of the surrounding Quantock and Brendon hills.","sources":[{"label":"Exmoor Blue Cheese product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd3621be90e07662ed92c7f/pfn-exmoor-jersey-blue.pdf"},{"label":"Qualigeo / DEFRA PGI spec: Exmoor Blue Cheese","url":"https://www.qualigeo.eu/en/product/exmoor-blue-cheese-pgi/"}],"pronunciation":{"ipa":"/ˈɛksmɔːr bluː/","respelling":"EKS-moor BLOO"},"region_polygon":{"type":"Polygon","coordinates":[[[-3.85,51.3],[-3.4,51.3],[-3.1,51.2],[-3.1,51.0],[-3.45,50.95],[-3.85,51.05],[-3.85,51.3]]]}},{"name":"Orkney Scottish Island Cheddar","lat":58.99,"lon":-2.96,"country":"United Kingdom","where":"Orkney Islands","hint":"Orkney Islands","desc":"Mature cheddar made on the Orkneys from island-grazed cow\'s milk; sharp and clean.","image":"orkney_scottish_island_cheddar.jpg","name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["hard","cheddar"],"ageing_min_days":180,"format":"block, ~5–20 kg","year_recognized":2013,"animal_breed":null,"vegetarian":null,"desc_long":"Orkney Scottish Island Cheddar is the cheddar of the Orkney archipelago off the north coast of Scotland, made from milk drawn from herds grazing the sea-thrashed pastures of the islands. The PGI specifies a distinctive dry-stir method of curd handling that differs from the traditional cheddaring practiced in southwest England, producing a wheel that is reliably tangy and clean rather than as densely close-textured as the West Country Farmhouse PDO. Ripening runs at least six months — Medium grade extends through twelve months, Mature to fifteen, and Extra Mature to about a year and a half — with each step concentrating the sharp, savoury character that long-aged cheddar develops. EU PGI came in 2013. Orkney\'s island climate — cool, damp, exposed to Atlantic winds — gives the milk an iodine-tinged minerality that surfaces clearly in the cured cheese, lifting it above mass-market British cheddars.","sources":[{"label":"Orkney Scottish Island Cheddar product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd365b48fa8f54d5ba9c0f1/pfn-orkney-scottish-island-cheddar-pgi.pdf"},{"label":"DEFRA / Orkney Cheese Company PGI spec","url":"https://www.orkneycheddar.co.uk/"},{"label":"Wikipedia: Cheddar cheese","url":"https://en.wikipedia.org/wiki/Cheddar_cheese"}],"pronunciation":{"ipa":"/ˈɔːkni ˈskɒtɪʃ ˈaɪlənd ˈtʃɛdər/","respelling":"ORK-nee SKOT-ish EYE-luhnd CHED-er"},"region_polygon":{"type":"Polygon","coordinates":[[[-3.45,59.3],[-2.55,59.3],[-2.4,58.85],[-2.85,58.75],[-3.45,58.8],[-3.45,59.3]]]}},{"name":"Single Gloucester","lat":51.86,"lon":-2.24,"country":"United Kingdom","where":"Gloucestershire","hint":"Gloucestershire","desc":"Semi-hard cow\'s-milk cheese, traditionally made on Gloucester-cattle farms; thinner and gentler than Double.","image":"single_gloucester.webp","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["semi-hard","pressed"],"ageing_min_days":21,"format":"wheel, ~3.5–5 kg","year_recognized":1996,"animal_breed":["Old Gloucester"],"vegetarian":null,"desc_long":"Single Gloucester is the older and rarer counterpart of the more familiar Double Gloucester — historically the farmhouse version made for home use from a single milking (Double Gloucester was made for sale, from a richer milk pool). The PDO requires production in Gloucestershire from cow\'s milk that, wherever possible, includes milk from the rare Old Gloucester breed that gave both cheeses their names. Wheels are pressed and aged a minimum of three weeks, though most producers go to four to six. EU PDO came in 1996. Single Gloucester is uncoloured (unlike its annatto-tinted Double cousin) and the paste sits at a slightly lower fat than Double Gloucester, giving a paler, fresher and more delicate cheese with a gentle nutty character. With fewer than a handful of working dairies still making the cheese under the spec, Single Gloucester remains one of the rarest protected British farmhouse cheeses.","sources":[{"label":"Single Gloucester product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd366d48fa8f54d5f67a7ce/pfn-single-gloucester.pdf"},{"label":"Academy of Cheese / DEFRA PDO spec: Single Gloucester","url":"https://academyofcheese.org/single-gloucester-pdo/"},{"label":"Wikipedia: Gloucester cheese","url":"https://en.wikipedia.org/wiki/Gloucester_cheese"}],"pronunciation":{"ipa":"/ˈsɪŋɡəl ˈɡlɒstər/","respelling":"SING-guhl GLOSS-ter"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.65,52.05],[-2.2,52.1],[-1.75,51.95],[-1.75,51.6],[-2.2,51.45],[-2.65,51.55],[-2.7,51.85],[-2.65,52.05]]]}},{"name":"Staffordshire Cheese","lat":52.83,"lon":-2.0,"country":"United Kingdom","where":"Staffordshire","hint":"West Midlands","desc":"Mellow semi-hard cow\'s-milk cheese revived from a long-dormant local recipe.","image":"staffordshire_cheese.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","pressed","cloth-bound"],"ageing_min_days":60,"format":"cylinder, ~8–10 kg, cloth-bound","year_recognized":2007,"animal_breed":null,"vegetarian":null,"desc_long":"Staffordshire Cheese is a pressed, cloth-bound cow\'s-milk cheese made from milk drawn from herds farmed in Staffordshire, and revived in modern form by the Staffordshire Cheese Company at Leek. The PDO spec calls for the previous day\'s milk to be cooled overnight at 0–5 °C, then warmed and pasteurised with the addition of cream from the same source before setting; the curds are pressed into cylindrical 8–10 kg wheels, bound in cloth, and aged at two grades — a younger version matured for two to four months that retains a sweet milk character, and a more developed grade ripened up to twelve months. The cheese contains 30–35 % fat overall, with 48–51 % fat in dry matter, sitting firmly in the family of pressed English farmhouse cheeses. EU PDO came in 2007. The flavour is mellow with a clean dairy sweetness when young, deepening into a savoury, slightly nutty maturity with age — closer in profile to a young cheddar than to the area\'s more famous neighbour Stilton.","sources":[{"label":"Staffordshire Cheese PDO product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/604b66eae90e07153e493fde/product_specification_Staffordshire_Cheese..pdf"},{"label":"Qualigeo: Staffordshire Cheese PDO","url":"https://www.qualigeo.eu/en/product/staffordshire-cheese-pdo/"},{"label":"Wikipedia: Cheshire cheese","url":"https://en.wikipedia.org/wiki/Cheshire_cheese"}],"pronunciation":{"ipa":"/ˈstæfədʃər tʃiːz/","respelling":"STAF-erd-sher CHEEZ"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.5,53.2],[-2.05,53.2],[-1.65,53.1],[-1.6,52.85],[-1.8,52.6],[-2.25,52.55],[-2.5,52.75],[-2.55,53.0],[-2.5,53.2]]]}},{"name":"Swaledale cheese","lat":54.39,"lon":-1.97,"country":"United Kingdom","where":"Swaledale, North Yorkshire","hint":"Yorkshire Dales","desc":"Cow\'s-milk cheese with crumbly open texture, mild and creamy; old Yorkshire monastic recipe.","image":"swaledale_cheese.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-hard","pressed","cloth-bound"],"ageing_min_days":21,"format":"cylinder/truckle, ~1–2 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Swaledale is a creamy, slightly crumbly cow\'s-milk cheese named for the dale of the same name in North Yorkshire. Historically the cheese was made from sheep or goat milk; cow\'s milk became dominant after dairy cattle reached the dales in the seventeenth century, and the modern PDO covers the cow\'s-milk version. Production calls for cattle grazed on the herb-rich grasses of Swaledale, with curds pressed, brined for around twenty-four hours and aged at least three to four weeks before sale, with cloth-bound mature versions running considerably longer. EU PDO came in 1996. The paste is moist and pale ivory with a gently flaky break and a quietly savoury, lactic flavour — buttery rather than sharp, with a subtle pasture note from the limestone-grass grazing. The cheese is closely associated with the small-scale farmhouse tradition of the upper Yorkshire dales.","sources":[{"label":"Swaledale Cheese PDO product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd367e98fa8f54d5d65563d/pfn-swaledale-cheese.pdf"},{"label":"Qualigeo: Swaledale Cheese PDO","url":"https://www.qualigeo.eu/en/product/swaledale-cheese-pdo/"},{"label":"Wikipedia: Swaledale cheese","url":"https://en.wikipedia.org/wiki/Swaledale_cheese"}],"pronunciation":{"ipa":"/ˈsweɪldeɪl/","respelling":"SWAYL-dayl"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.25,54.45],[-1.95,54.45],[-1.75,54.4],[-1.65,54.35],[-1.8,54.3],[-2.1,54.32],[-2.25,54.4],[-2.25,54.45]]]}},{"name":"Swaledale ewes\' cheese","lat":54.39,"lon":-1.97,"country":"United Kingdom","where":"Swaledale, North Yorkshire","hint":"Yorkshire Dales — sheep version","desc":"Sheep\'s-milk version of Swaledale, made when the local ewes are in milk; nuttier than the cow.","image":"swaledale_ewes_cheese.jpg","name_protections":["PDO"],"milk_types":["sheep"],"pasteurization":"pasteurized","style":["semi-hard","pressed"],"ageing_min_days":21,"format":"cylinder/truckle, ~1–2 kg","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"Swaledale Ewes\' Cheese is the sheep\'s-milk counterpart of the Yorkshire farmhouse cheese, made under a separate PDO registration from the cow\'s-milk version. It is a full-fat hard cheese in cylindrical or small truckle format, pressed and brined like the cow\'s-milk Swaledale before being matured a minimum of three to four weeks. The milk comes from sheep grazed on the herb-rich Swaledale pastures, whose mix of grasses, wildflowers and limestone-soil flora carries through into the milk. EU PDO came in 1996. The paste is firm but moist with a crumbly break, ivory-white, and the flavour is the cleaner, lactic-tinged sweetness characteristic of ewe\'s-milk cheeses, with a quiet salt-and-pasture finish. Production is small-scale and tied to the working farmhouse cheese tradition of the upper Yorkshire dales.","sources":[{"label":"Swaledale ewes\' cheese product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd367d1e90e076634d01781/pfn-swaledale-ewes-cheese.pdf"},{"label":"AnyCheese: Swaledale Ewes\' Cheese","url":"https://anycheese.com/types/swaledale-ewes-cheese/"},{"label":"Wikipedia: Swaledale cheese","url":"https://en.wikipedia.org/wiki/Swaledale_cheese"}],"pronunciation":{"ipa":"/ˈsweɪldeɪl juːz/","respelling":"SWAYL-dayl YOOZ"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.25,54.45],[-1.95,54.45],[-1.75,54.4],[-1.65,54.35],[-1.8,54.3],[-2.1,54.32],[-2.25,54.4],[-2.25,54.45]]]}},{"name":"Teviotdale Cheese","lat":55.42,"lon":-2.6,"country":"United Kingdom","where":"Scottish Borders","hint":"Scottish Borders","desc":"Semi-hard cow\'s-milk cheese with mild creamy flavor; small-scale Borders dairy tradition.","image":null,"name_protections":["PGI"],"milk_types":["cow"],"pasteurization":"raw","style":["hard","pressed","brine-washed"],"ageing_min_days":19,"format":"cylinder, white-coated","year_recognized":1998,"animal_breed":["Jersey"],"vegetarian":null,"desc_long":"Teviotdale is a hard, pressed cow\'s-milk cheese made on the borderlands between Scotland and England, in a defined zone within a ninety-kilometre radius of Peel Fell in the Cheviot Hills. The PGI spec requires Jersey cow\'s milk, which is heated to about 32 °C, set with rennet for ninety minutes, then cut and moulded into cylindrical wheels and mechanically pressed. The wheels brine for nine hours at 13 °C, dry for four days, then mature for at least a further fifteen days with daily turning, picking up a thin white coating. EU PGI came in 1998. The Jersey milk gives the paste a pronounced yellow colour and a richer fat profile than the cattle that dominate British dairy production; the salt-and-brine cycle pushes the flavour distinctly savoury. As of recent years there are no known active producers under the PGI mark, so wheels are rare even within the protected region.","sources":[{"label":"Teviotdale Cheese PGI product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd368188fa8f54d5abcdfdd/Teviotdale_cheese_product_specification.pdf"},{"label":"Wikipedia: Teviotdale cheese","url":"https://en.wikipedia.org/wiki/Teviotdale_cheese"}],"pronunciation":{"ipa":"/ˈtiːvjətdeɪl/","respelling":"TEE-vyot-dayl"},"region_polygon":{"type":"Polygon","coordinates":[[[-3.85,55.95],[-2.6,56.2],[-1.3,55.95],[-1.1,55.3],[-1.45,54.55],[-2.65,54.4],[-3.85,54.65],[-4.1,55.3],[-3.85,55.95]]]}},{"name":"West Country Farmhouse Cheddar","lat":51.28,"lon":-2.78,"country":"United Kingdom","where":"Somerset, Devon, Dorset, Cornwall","hint":"West Country","desc":"Hard cow\'s-milk cheese made on farms in the four West Country counties using traditional \'cheddaring\' curd-stacking.","image":"west_country_farmhouse_cheddar.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"any","style":["hard","cheddar","cloth-bound"],"ageing_min_days":270,"format":"cylinder, ~25 kg, cloth-bound","year_recognized":1996,"animal_breed":null,"vegetarian":null,"desc_long":"West Country Farmhouse Cheddar is the protected farmhouse expression of England\'s most exported cheese style — a hard, cloth-bound cheddar made on dairy farms within the 1955 county boundaries of Somerset, Dorset, Devon and Cornwall. The PDO requires that approximately half of each maker\'s milk come from their own herd, with cheddaring — the long, characteristic stretch-and-stack of the curds — done in the traditional way and wheels sold no younger than nine months. Milk may be raw or pasteurised, and is standardised by season to keep the fat-to-casein ratio close to 1:0.7. Wheels are typically bound in lard-rubbed cloth and matured for nine to twenty-four months. EU PDO came in 1996. Mature wheels show a dense, slightly flaky paste with the savoury, brothy depth and slight crystalline crunch that long ageing develops; the flavour is markedly more layered than mass-market block cheddar, with vivid pasture notes from the West Country grass.","sources":[{"label":"West Country Farmhouse Cheddar PDO spec (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd3693f8fa8f54d59e8b750/pfn-west-country-farmhouse-cheddar.pdf"},{"label":"Wikipedia: Cheddar cheese","url":"https://en.wikipedia.org/wiki/Cheddar_cheese"}],"pronunciation":{"ipa":"/wɛst ˈkʌntri ˈfɑːmhaʊs ˈtʃɛdər/","respelling":"WEST KUN-tree FARM-howss CHED-er"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.55,51.43],[-3.35,51.2],[-4.2,51.2],[-4.5,50.7],[-5.7,50.1],[-5.2,50.0],[-4.2,50.2],[-3.55,50.35],[-3.0,50.65],[-2.45,50.55],[-1.95,50.65],[-2.05,51.05],[-2.55,51.43]]]}},{"name":"White Stilton / Blue Stilton","lat":52.89,"lon":-0.62,"country":"United Kingdom","where":"Derbyshire, Leicestershire & Nottinghamshire","hint":"East Midlands","desc":"Cow\'s-milk cheese in white (unblued) or blue forms; ironically forbidden in Stilton village itself, by law.","image":"white_stilton_blue_stilton.jpg","name_protections":["PDO"],"milk_types":["cow"],"pasteurization":"pasteurized","style":["semi-soft","blue","natural-rind"],"ageing_min_days":63,"format":"cylinder, ~8 kg, 20 cm × 25 cm","year_recognized":1996,"animal_breed":null,"vegetarian":true,"desc_long":"Stilton is the great English blue cheese, protected under a single PDO that covers two distinct types — White Stilton (no blue mould) and Blue Stilton — both made from pasteurised cow\'s milk with vegetarian rennet in the three midland counties of Derbyshire, Leicestershire and Nottinghamshire. Blue Stilton is shaped into an iconic 8 kg cylinder and, after about five weeks of maturation, pierced with steel needles to admit oxygen and trigger Penicillium roqueforti to bloom outward through the paste in ivory-to-blue veining; the cheese is typically sold from nine weeks, with peak character around twelve. White Stilton uses the same milk and shape but is made without the blue mould or artificial colouring, salted, moulded and sold within three to four weeks — fresh, lactic, gently crumbly. The Stilton Cheese Makers Association was founded in 1936; EU PDO came in 1996. Blue Stilton is rich and creamy with a complex tang that builds gracefully, while White Stilton is milder and often combined with fruit; together they anchor the British Christmas cheeseboard and pair famously with port.","sources":[{"label":"Stilton Cheese PDO product specification (UK gov)","url":"https://assets.publishing.service.gov.uk/media/5fd3677c8fa8f54d564af06b/pfn-stilton-cheese.pdf"},{"label":"Academy of Cheese: Blue Stilton PDO","url":"https://academyofcheese.org/blue-stilton-pdo/"},{"label":"Wikipedia: Stilton cheese","url":"https://en.wikipedia.org/wiki/Stilton_cheese"}],"pronunciation":{"ipa":"/waɪt ˈstɪltən/","respelling":"WYT STIL-tuhn"},"region_polygon":{"type":"Polygon","coordinates":[[[-2.0,53.55],[-1.5,53.35],[-1.05,53.4],[-0.8,53.25],[-0.6,52.95],[-0.65,52.65],[-0.85,52.45],[-1.2,52.4],[-1.55,52.45],[-1.8,52.7],[-1.85,52.9],[-1.95,53.1],[-2.0,53.3],[-2.0,53.55]]]}}]');
